  str_skill_href_desc_name_30067 = "Deslumbrante variedad",
  str_skill_href_desc_desc_30067 = "Si está parado afuera de un <color=#00F6FF>deslumbrante variedad</color> después de usar un Chain Combo, se creará una nueva y deslumbrante matriz que abarcará el rango del Chain Combo actual. solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento. La creación de una nueva matriz deslumbrante después de alcanzar el máximo eliminará la que ha estado en el campo durante más tiempo.",
  str_skill_href_desc_name_30068 = "Deslumbrante variedad",
  str_skill_href_desc_desc_30068 = "Si está parado afuera de un <color=#00F6FF>deslumbrante variedad</color> después de usar un Chain Combo, se creará una nueva y deslumbrante matriz que abarcará el rango del Chain Combo actual. solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento. La creación de una nueva matriz deslumbrante después de alcanzar el máximo eliminará la que ha estado en el campo durante más tiempo. Al comienzo de la batalla, una deslumbrante variedad que es <color=#00F6FF>12 fichas en forma de diamante</color> se generará en la ubicación de inicio.",
  str_skill_href_desc_name_30069 = "Energía cúbica",
  str_skill_href_desc_desc_30069 = "Ganancias <color=#00F6FF>1</color> punto por ronda, hasta <color=#00F6FF>9</color> puntos.",
  str_skill_href_desc_name_30070 = "Energía cúbica",
  str_skill_href_desc_desc_30070 = "Axelia entra en la batalla con <color=#00F6FF>2</color> puntos y ganancias <color=#00F6FF>1</color> punto cada ronda, hasta <color=#00F6FF>9</color> puntos.",
  str_skill_href_desc_name_30071 = "Módulo de autoridad",
  str_skill_href_desc_desc_30071 = "El efecto de la habilidad activa se puede cambiar en el módulo de autoridad. El módulo de autoridad mantiene un registro de <color=#00F6FF>todos los objetos invocables de ciertos Thunder Aurorians que son invocados en esta batalla</color>.\nSeleccionable <color=#00F6FF>azulejos especiales</color>: Azulejos oscuros, Azulejos de prisma, Azulejos de prisma en forma de cruz.\nLos objetos invocables de los siguientes <color=#00F6FF>aurorianos</color> se pueden seleccionar: Amemori, Reinhardt, Bopper, Roy, Ciel, Nadine, y Amy.",
  str_skill_href_desc_name_30072 = "Orbe curativo",
  str_skill_href_desc_desc_30072 = "Cuando ha estado en el campo durante <color=#00F6FF>0/1/2</color> rondas, los Aurorianos que atraviesen el orbe o lo absorban usando la Habilidad Activa de Axelia recuperarán HP igual a <color=#00F6FF>40%/100%/200%</color> del ATK de Axelia.",
  str_skill_href_desc_name_30073 = "Orbe curativo",
  str_skill_href_desc_desc_30073 = "Cuando ha estado en el campo durante <color=#00F6FF>0/1/2</color> rondas, los Aurorianos que pasen a través del orbe recuperarán HP igual a <color=#00F6FF>40%/100%/250%</color> del ATK de Axelia. Si el orbe se absorbe con la habilidad activa de Axelia, la cantidad de curación aumenta a <color=#00F6FF>80%/180%/400%</color>.",
  str_skill_href_desc_name_30074 = "Bengala de serpiente",
  str_skill_href_desc_desc_30074 = "Usar nivel <color=#00F6FF>2|3|4</color> Combo de cadena para encender la bengala de serpiente correspondiente. La habilidad activa estará lista cuando <color=#00F6FF>3</color> Las bengalas de serpiente se encienden y todas las bengalas de serpiente se extinguen después de usar la habilidad activa.",
  str_skill_href_desc_name_30075 = "Puntos de conocimiento",
  str_skill_href_desc_desc_30075 = "Conseguir <color=#00F6FF>1</color> punto por cada 1 baldosa roja atravesada.",
  str_skill_href_desc_name_30076 = "Puntos de conocimiento",
  str_skill_href_desc_desc_30076 = "Conseguir <color=#00F6FF>1</color> punto por cada 1 baldosa roja atravesada. Ganar <color=#00F6FF>5</color> puntos al entrar en batalla, y <color=#00F6FF>5</color> puntos al comienzo de cada ola.",
  str_skill_href_desc_name_30077 = "Puntos de conocimiento",
  str_skill_href_desc_desc_30077 = "Conseguir <color=#00F6FF>1</color> punto por cada 1 ficha atravesada. Ganar <color=#00F6FF>5</color> puntos al entrar en batalla, y <color=#00F6FF>5</color> puntos al comienzo de cada ola.",
  str_skill_href_desc_name_30078 = "Celo",
  str_skill_href_desc_desc_30078 = "Cada Ataque Normal otorga <color=#00F6FF>5</color> puntos, hasta <color=#00F6FF>100</color> puntos.",
  str_skill_href_desc_name_30079 = "Reserva de munición",
  str_skill_href_desc_desc_30079 = "Se puede reservar 1 bala al comienzo de cada ronda. Se pueden reservar 5 balas cuando se usa Active Skill. Se puede reservar 1 bala cuando cualquier Aurorian usa su Habilidad Activa.",
  str_skill_href_desc_name_30080 = "Azulejo de prisma en forma de cruz",
  str_skill_href_desc_desc_30080 = "Al conectar mosaicos, convierte 4 mosaicos en forma de cruz alrededor de mosaicos de prisma en forma de cruz en el mismo elemento que los mosaicos de prisma en forma de cruz.",
  str_skill_href_desc_name_30081 = "Avance",
  str_skill_href_desc_desc_30081 = "Solo tiene efecto en los objetivos que se pueden tirar y prioriza los objetivos que están más cerca del centro del área.",
  str_skill_href_desc_name_30082 = "La asamblea",
  str_skill_href_desc_desc_30082 = "Ataca a otros objetivos que están dentro de 1 grupo circundante del objetivo.",
  str_skill_href_desc_name_30083 = "Sabiduría",
  str_skill_href_desc_desc_30083 = "Un objetivo sin PS Máx no puede recibir Sabiduría.",
  str_skill_href_desc_name_30084 = "Convergir",
  str_skill_href_desc_desc_30084 = "Reorganiza el color de las casillas para que las casillas azules en la columna/fila converjan alrededor de la casilla seleccionada, sin cambiar las posiciones de los enemigos, objetos invocables o casillas especiales.",
  str_skill_href_desc_name_30085 = "Onda",
  str_skill_href_desc_desc_30085 = "Se acumula hasta 99 veces. Se consumen múltiplos de 7 acumulaciones cada vez. No se consumen acumulaciones cuando la PS está al máximo.",
  str_skill_href_desc_name_30086 = "Onda",
  str_skill_href_desc_desc_30086 = "Se acumula hasta 99 veces. Se consumen múltiplos de 5 acumulaciones cada vez. No se consumen acumulaciones cuando se tiene el PS completo.",
  str_skill_href_desc_name_30087 = "Lagarto de Hierro",
  str_skill_href_desc_desc_30087 = "El Iron Lizard puede existir hasta por 2 rondas, y solo 1 puede estar en el campo a la vez.",
  str_skill_href_desc_name_30088 = "Lagarto de Hierro",
  str_skill_href_desc_desc_30088 = "Puedes tocar el lagarto de hierro para lanzar habilidades en cada ronda. El Iron Lizard puede existir hasta por 2 rondas, y solo 1 puede estar en el campo a la vez.",
  str_skill_href_desc_name_30089 = "Magnetix",
  str_skill_href_desc_desc_30089 = "Cuando se lanza, atrae a los enemigos dentro de 2 grupos circundantes más cerca en 1 mosaico y luego desaparece.",
  str_skill_href_desc_name_30090 = "Whirlpool",
  str_skill_href_desc_desc_30090 = "Después del lanzamiento, el Combo de cadena de Bopper se cambiará para enfrentar directamente al Lagarto de hierro, extendiéndose hasta el borde del campo en esta ronda.",
  str_skill_href_desc_name_30091 = "Tocar",
  str_skill_href_desc_desc_30091 = "Cuando se generan cristales bajo los pies del enemigo o cuando el enemigo pisa o se mueve sobre una casilla con cristales, provoca daño. El daño se puede activar repetidamente si se generan múltiples cristales debajo del enemigo.",
  str_skill_href_desc_name_30092 = "Movimiento",
  str_skill_href_desc_desc_30092 = "Incluye teletransportarse mediante Habilidades Activas de aliados Aurorianos, retrocesos/atraer causados por habilidades enemigas, el uso de un Vórtice Transportador y más.",
  str_skill_href_desc_name_30093 = "Casilla Oscura",
  str_skill_href_desc_desc_30093 = "The next tile at this location is guaranteed to be the same element as the current tile.",
  str_skill_href_desc_name_30094 = "Inmersión",
  str_skill_href_desc_desc_30094 = "Máximo 40 acumulaciones. Cada acumulación dura 3 rondas.",
  str_skill_href_desc_name_30095 = "Repuesto",
  str_skill_href_desc_desc_30095 = "Obtiene 3 Piezas de repuesto al comienzo de la batalla y 1 al inicio de cada ronda siguiente.",
  str_skill_href_desc_name_30096 = "Dotación sombría",
  str_skill_href_desc_desc_30096 = "Gana 1 punto al comienzo de cada ronda y 1 punto al pasar por cada Baldosa Oscura.",
  str_skill_href_desc_name_30097 = "Dotación sombría",
  str_skill_href_desc_desc_30097 = "Gana 5 puntos al entrar en batalla, 1 punto al comienzo de cada ronda y 1 punto al pasar por cada Baldosa Oscura.",
  str_skill_href_desc_name_30098 = "Dotación sombría",
  str_skill_href_desc_desc_30098 = "Gana 5 puntos al entrar en batalla, 1 punto al comienzo de cada ronda, 2 puntos al comienzo de cada ola, y 1 punto al pasar por cada Baldosa Oscura.",
  str_skill_href_desc_name_30099 = "Dotación sombría",
  str_skill_href_desc_desc_30099 = "Gana 1 punto al comienzo de cada ronda, 2 puntos al comienzo de cada ola, y 1 punto al pasar por cada Baldosa Oscura.",
  str_skill_href_desc_name_510218 = "Estrategia de Inversión",
  str_skill_href_desc_desc_510218 = "Sheol gana 1 Capital por cada 5 casillas azules o 1 casilla oscura por la que pasa.\nDespués de acumular 2/5/8 Capital, se desbloquearán en orden en Estrategia de Inversión 3 nuevos grupos de habilidades de combate correspondientes a la Habilidad Activa, Combo en Cadena y Ataque Normal, y solo se puede seleccionar 1 de las 2 opciones dentro de cada grupo cada vez. Las habilidades de combate que se pueden obtener son las siguientes:\nEnredo de Serpiente Sombra: Expande el rango de la Habilidad Activa a 13 fichas en forma de diamante.\nImpulsado por la Niebla: Aumenta el daño de la Habilidad Activa en un 50%.\nRico y Poderoso: El Combo en Cadena inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo.\nRiqueza aplastante: Por cada Oscuridad La casilla pasada mientras se conectan las casillas esta vez, aumenta el daño del Combo en Cadena una vez.\nExpansión de Capital: Los ataques se pueden lanzar en diagonal.\nGolpe de Capital: Por cada Casilla Oscura pasada mientras se conectan las casillas esta vez, aumenta el daño de los Ataques Normales en un 20%, hasta duplicar el daño.",
  str_skill_href_desc_name_513218 = "Estrategia de Inversión",
  str_skill_href_desc_desc_513218 = "Sheol gana 1 Capital por cada 5 casillas azules o 1 casilla oscura por la que pasa. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (se desbloquea en Ascensión III)Después de acumular 2/5/8 Capital, se desbloquearán en orden 3 nuevos grupos de habilidades de combate correspondientes a la Habilidad Activa, Combo en Cadena y Ataque Normal en Estrategia de Inversión, y solo se puede seleccionar 1 de las 2 opciones dentro de cada grupo cada vez. Las habilidades de combate que se pueden obtener son las siguientes:\nEnredo de Serpiente Sombra: Amplía el rango de la Habilidad Activa a 13 fichas en forma de diamante.Impulsado por la Niebla: Aumenta el daño de la Habilidad Activa en un 50%.\nRico y Poderoso: El Combo en Cadena inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo.\nRiqueza aplastante: Por cada Mosaico Oscuro atravesado al conectar mosaicos esta vez, aumenta el daño del Combo en Cadena una vez.\nExpansión de Capital: Los ataques pueden lanzarse en diagonal.\nGolpe de Capital: Por cada Oscuro La casilla por la que se pasa al conectar casillas esta vez, aumenta el daño de los Ataques Normales en un 20%, hasta duplicar el daño.",
  str_skill_href_desc_name_516218 = "Estrategia de Inversión",
  str_skill_href_desc_desc_516218 = "Sheol comienza la batalla con 5 Capitales y gana 1 Capital por cada 5 casillas azules o 1 casilla oscura por la que pasa. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (se desbloquea en Ascensión III)Después de acumular 2/5/8 Capital, se desbloquearán en orden 3 nuevos grupos de habilidades de combate correspondientes a la Habilidad Activa, Combo en Cadena y Ataque Normal en Estrategia de Inversión, y solo se puede seleccionar 1 de las 2 opciones dentro de cada grupo cada vez. Las habilidades de combate que se pueden obtener son las siguientes:\nEnredo de Serpiente Sombra: Amplía el rango de la Habilidad Activa a 13 fichas en forma de diamante.Impulsado por la Niebla: Aumenta el daño de la Habilidad Activa en un 50%.\nRico y Poderoso: El Combo en Cadena inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo.\nRiqueza aplastante: Por cada Mosaico Oscuro atravesado al conectar mosaicos esta vez, aumenta el daño del Combo en Cadena una vez.\nExpansión de Capital: Los ataques pueden lanzarse en diagonal.\nGolpe de Capital: Por cada Oscuro La casilla por la que se pasa al conectar casillas esta vez, aumenta el daño de los Ataques Normales en un 20%, hasta duplicar el daño.",
  str_skill_href_desc_name_530218 = "Estrategia de Inversión",
  str_skill_href_desc_desc_530218 = "Sheol gana 1 Capital por cada 5 casillas azules o 1 casilla oscura por la que pasa.\nDespués de acumular 2/5/8 Capital, se desbloquearán en orden en Estrategia de Inversión 3 nuevos grupos de habilidades de combate correspondientes a la Habilidad Activa, Combo en Cadena y Ataque Normal, y solo se puede seleccionar 1 de las 2 opciones dentro de cada grupo cada vez. Después de completar la primera ronda de inversión, ella puede hacer una segunda ronda de inversión para obtener una habilidad de combate que no tenía en la primera ronda de inversión. Las habilidades de combate que se pueden obtener son las siguientes:\nEnredo de Serpiente Sombra: Amplía el rango de la Habilidad Activa a 13 fichas en forma de diamante.\nImpulsado por la Niebla: Aumenta el daño de la Habilidad Activa en un 50%.\nRico y Poderoso: El Combo en Cadena inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo.\nRiqueza aplastante: Por cada ficha oscura que se atraviese al conectar fichas esta vez, aumenta el daño del Combo en cadena una vez.\nExpansión de capital: Los ataques se pueden lanzar en diagonal.\nGolpe de capital: Por cada ficha oscura que se atraviese al conectar fichas esta vez, aumenta el daño de los ataques normales en un 20%, hasta el doble del daño.",
  str_skill_href_desc_name_533218 = "Estrategia de Inversión",
  str_skill_href_desc_desc_533218 = "Sheol gana 1 Capital por cada 5 casillas azules o 1 casilla oscura por la que pasa. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos.Después de acumular 2/5/8 Capital, se desbloquearán en orden en la Estrategia de Inversión 3 nuevos grupos de habilidades de combate correspondientes a la Habilidad Activa, Combo en Cadena y Ataque Normal, y solo se puede seleccionar 1 de las 2 opciones dentro de cada grupo cada vez. Después de completar la primera ronda de inversión, puede hacer una segunda ronda de inversión para obtener una habilidad de combate que no tenía en la primera ronda de inversión. Las habilidades de combate que se pueden obtener son las siguientes:\nEnredo de Serpiente Sombra: Expande el rango de la Habilidad Activa a 13 fichas en forma de diamante.\nImpulsado por la Niebla: Aumenta el daño de la Habilidad Activa en un 50%.\nRico y Poderoso: El Combo en Cadena inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo.\nRiqueza aplastante: Por cada Oscuridad  La casilla pasada mientras se conectan las casillas esta vez, aumenta el daño del Combo en Cadena una vez.\nExpansión de Capital: Los ataques se pueden lanzar en diagonal.\nGolpe de Capital: Por cada Casilla Oscura pasada mientras se conectan las casillas esta vez, aumenta el daño de los Ataques Normales en un 20%, hasta el doble del daño.",
  str_skill_href_desc_name_536218 = "Estrategia de Inversión",
  str_skill_href_desc_desc_536218 = "Sheol comienza la batalla con 5 Capitales y gana 1 Capital por cada 5 casillas azules o 1 casilla oscura por la que pasa. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos.Después de acumular 2/5/8 Capital, se desbloquearán en orden en la Estrategia de Inversión 3 nuevos grupos de habilidades de combate correspondientes a la Habilidad Activa, Combo en Cadena y Ataque Normal, y solo se puede seleccionar 1 de las 2 opciones dentro de cada grupo cada vez. Después de completar la primera ronda de inversión, puede hacer una segunda ronda de inversión para obtener una habilidad de combate que no tenía en la primera ronda de inversión. Las habilidades de combate que se pueden obtener son las siguientes:\nEnredo de Serpiente Sombra: Expande el rango de la Habilidad Activa a 13 fichas en forma de diamante.\nImpulsado por la Niebla: Aumenta el daño de la Habilidad Activa en un 50%.\nRico y Poderoso: El Combo en Cadena inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo.\nRiqueza aplastante: Por cada Oscuridad La casilla pasada mientras se conectan las casillas esta vez, aumenta el daño del Combo en Cadena una vez.\nExpansión de Capital: Los ataques se pueden lanzar en diagonal.\nGolpe de Capital: Por cada Casilla Oscura pasada mientras se conectan las casillas esta vez, aumenta el daño de los Ataques Normales en un 20%, hasta el doble del daño.",
  str_skill_href_desc_name_30100 = "Tablero de Color",
  str_skill_href_desc_desc_30100 = "Zeta puede llenar su Tablero de Colores de la siguiente manera. Una vez que esté lleno, podrá lanzar su Habilidad Activa Secreta Razzle Dazzle.\n1. Su Habilidad Activa Variety Blitz registra los colores de las casillas seleccionadas antes de reiniciarlas.\n2. Al moverse para atacar a un objetivo, Conan, invocado por la Habilidad Activa Secreta Razzle Dazzle, registrará los colores de las casillas que atraviesa.",
  str_skill_href_desc_name_30110 = "Siguiente cola",
  str_skill_href_desc_desc_30110 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de fichas que la habilidad activa de Batia puede convertir. \nEl bloque cambiará al azar cada vez que Batia use su habilidad activa.",
  str_skill_href_desc_name_30111 = "Next Queue",
  str_skill_href_desc_desc_30111 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de fichas que la Habilidad Activa de Batia puede convertir. \nEl bloque cambiará al azar cada vez que Batia use su Habilidad Activa. \nCada ficha roja atravesada le otorga 1 Energía. Consume 5 Energías para aleatorizar el bloque. Cada intento de aleatorización costará 5 Energías adicionales hasta el próximo uso de su Habilidad Activa.",
  str_skill_href_desc_name_30112 = "Next Queue",
  str_skill_href_desc_desc_30112 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de casillas que la Habilidad Activa de Batia puede convertir. \nEl bloque cambiará al azar cada vez que Batia use su Habilidad Activa. \nLa siguiente cola comienza con 10 de Energía, y cada casilla roja atravesada le otorga 1 de Energía. Consume 5 de Energía para aleatorizar el bloque. Cada intento de aleatorización costará 5 de Energía adicional hasta el próximo uso de su Habilidad Activa.",
  str_skill_href_desc_name_30113 = "Next Queue",
  str_skill_href_desc_desc_30113 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de casillas que la Habilidad Activa de Batia puede convertir.\nEl bloque cambiará al azar cada vez que Batia use su Habilidad Activa.\nLa siguiente cola comienza con 10 de energía, y cada casilla roja atravesada le otorga 1 de energía. Consume 5 de energía para aleatorizar el bloque.",
  str_skill_href_desc_name_30114 = "Next Queue",
  str_skill_href_desc_desc_30114 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de casillas que la Habilidad Activa de Batia puede convertir.\nEl bloque cambiará al azar cada vez que Batia use su Habilidad Activa.\nCada casilla roja atravesada le otorga 1 Energía. Consume 5 Energías para aleatorizar el bloque. Cada intento de aleatorización costará 5 Energías adicionales hasta el próximo uso de su Habilidad Activa.Bloquea el bloque en la siguiente cola para evitar que se aleatorice. Mientras está bloqueado, cada aleatorización mejora el bloque actual en su lugar. Para cada mejora, la Habilidad Activa también generará una Ficha Oscura en una ubicación aleatoria.",
  str_skill_href_desc_name_30115 = "Next Queue",
  str_skill_href_desc_desc_30115 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de casillas que la Habilidad Activa de Batia puede convertir. \nCada vez que Batia libera su Habilidad Activa, aparecerá un bloque al azar. \nLa siguiente cola comienza con 10 de Energía, y cada casilla roja atravesada le otorga 1 de Energía. Consume 5 de Energía para aleatorizar el bloque. Cada intento de aleatorización costará 5 de Energía adicional hasta el próximo uso de su Habilidad Activa.Bloquea el bloque en la siguiente cola para evitar que se aleatorice. Mientras está bloqueado, cada aleatorización mejora el bloque actual en su lugar. Para cada mejora, la Habilidad Activa también generará una Ficha Oscura en una ubicación aleatoria.",
  str_skill_href_desc_name_30116 = "Next Queue",
  str_skill_href_desc_desc_30116 = "La siguiente cola muestra uno de los siete tipos de bloques que representan el rango de casillas que la Habilidad Activa de Batia puede convertir.\nEl bloque cambiará al azar cada vez que Batia use su Habilidad Activa.\nLa siguiente cola comienza con 10 de energía, y cada casilla roja atravesada le otorga 1 de energía. Consume 5 de energía para aleatorizar el bloque.Bloquea el bloque en la siguiente cola para evitar que se aleatorice. Mientras está bloqueado, cada aleatorización mejora el bloque actual en su lugar. Para cada mejora, la Habilidad Activa también generará una Ficha Oscura en una ubicación aleatoria.",
  str_skill_href_desc_name_30117 = "Marca Requiem",
  str_skill_href_desc_desc_30117 = "Gana 1 pila cada vez que un Combo en Cadena o Ataque Normal provoca un golpe de rayo en un enemigo.",
  str_skill_href_desc_name_30118 = "Pacto del Señor",
  str_skill_href_desc_desc_30118 = "Solo un objetivo en el campo puede tener el Pacto del Señor a la vez.",
  str_skill_href_desc_name_30119 = "AP",
  str_skill_href_desc_desc_30119 = "Los personajes de colaboración de Atelier Ryza 2 comparten AP. Cada personaje puede usar una Habilidad Activa una vez por ronda. Ganarán 10 AP al final de una ronda si no se usa ninguna Habilidad Activa.",
  str_skill_href_desc_name_30120 = "AP",
  str_skill_href_desc_desc_30120 = "Los personajes de colaboración de Atelier Ryza 2 comparten AP. Cada personaje puede usar una Habilidad Activa una vez por ronda. Ganarán 20 AP al entrar en batalla y 10 AP al final de una ronda si no se usa ninguna Habilidad Activa.",
  str_skill_href_desc_name_30121 = "AP",
  str_skill_href_desc_desc_30121 = "Los personajes de colaboración de Atelier Ryza 2 comparten AP. Cada personaje puede usar una Habilidad Activa una vez por ronda. Ganarán 20 AP al entrar en batalla y 10 AP al final de cada ronda.",
  str_skill_href_desc_name_30122 = "Sistema de tácticas",
  str_skill_href_desc_desc_30122 = "Obtén Puntos Tácticos a través de diversas acciones en la batalla y desencadena efectos correspondientes al alcanzar ciertas cantidades.\n10 TP - Nivel 1: Aumenta el daño final del Combo en Cadena de los personajes de la colaboración Atelier Ryza 2 en un 15%.\n40 TP - Nivel 2: Genera 1 Azulejo Oscuro en una ubicación aleatoria al comienzo de cada ronda.70 TP - Nivel 3: Los Combos en Cadena de Ryza y Patricia infligen 1 pila de Quemadura al golpear. El Combo en Cadena de Klaudia inflige 1 pila de Veneno al golpear.\n100 TP - Nivel 4: Aumenta el daño final de la Habilidad Activa de los 2 personajes de colaboración de Atelier Ryza en un 50%.\n130 TP - Nivel 5: Genera 1 ficha Oscura extra en una ubicación aleatoria al comienzo de cada ronda.",
  str_skill_href_desc_name_30123 = "Sistema de tácticas",
  str_skill_href_desc_desc_30123 = "Obtén Puntos Tácticos a través de diversas acciones en batalla y desencadena efectos correspondientes al alcanzar ciertas cantidades. El límite de nivel predeterminado es 5, que aumenta en 1 al entrar en batalla.\n10 TP - Nv. 1: Aumenta el daño final del Combo en Cadena de los personajes de la colaboración Atelier Ryza 2 en un 15%.40 TP - Nivel 2: Genera 1 Casilla Oscura en una ubicación aleatoria al inicio de cada ronda.\n70 TP - Nivel 3: Los Combos en Cadena de Ryza y Patricia infligen 1 pila de Quemado al golpear. El Combo en Cadena de Klaudia inflige 1 pila de Veneno al golpear.100 TP - Nv. 4: Aumenta el daño final de la Habilidad Activa de los personajes de colaboración de Atelier Ryza 2 en un 50%.\n130 TP - Nv. 5: Genera 1 Mosaico Oscuro extra en una ubicación aleatoria al inicio de cada ronda.\n160 TP - Nv. 6: Aumenta el ATQ básico de los personajes de colaboración de Atelier Ryza 2 en un 10%.\n200 TP - Nv. 7: Genera 1 Mosaico Oscuro extra en una ubicación aleatoria al inicio de cada ronda.",
  str_skill_href_desc_name_30124 = "Absorción",
  str_skill_href_desc_desc_30124 = "El efecto se dispara al pasar a través de los mosaicos. Se pueden activar los efectos correspondientes de los Aurorianos relevantes.",
  str_skill_href_desc_name_30125 = "Vis",
  str_skill_href_desc_desc_30125 = "El equipo gana 1 Vis por cada 2 fichas conectadas.",
  str_skill_href_desc_name_30126 = "Vis",
  str_skill_href_desc_desc_30126 = "El equipo gana 1 Vis por cada 2 casillas conectadas y obtiene 5 Vis al comienzo de cada ronda.",
  str_skill_href_desc_name_30127 = "Conexión de Casilla",
  str_skill_href_desc_desc_30127 = "Ignora el elemento de la ficha al conectarlas. Consume 1 Vis por cada ficha conectada.",
  str_skill_href_desc_name_30128 = "Estado Fuera de Equipo",
  str_skill_href_desc_desc_30128 = "Cuando Claymore no está en el equipo, no puede ser Capitán y no atacará con el equipo.",
