  str_skill_desc_510010 = "Espadas aterradoras usa las espadas para atacar objetivos dentro del área de ataque 2x.",
  str_skill_desc_29203121 = "Augean usa las cuchillas para atacar objetivos dentro del área de ataque 2 veces, infligiendo sangrado.",
  str_skill_desc_29203123 = "Augean usa las cuchillas para atacar objetivos dentro del área de ataque 2 veces, infligiendo sangrado y fatiga.",
  str_skill_desc_510011 = "Mensajero usa espadas especiales para golpear objetivos dentro del área de ataque.",
  str_skill_desc_510012 = "Levanta una barrera que puede soportar 3 ataques.",
  str_skill_desc_510013 = "Usa láser para atacar objetivos a 1 casilla de distancia.",
  str_skill_desc_510014 = "Ataca objetivos dentro del área de ataque y luego se teletransporta a cualquier lugar del campo.",
  str_skill_desc_510015 = "Usa lanza para atacar objetivos dentro del área de ataque.",
  str_skill_desc_510016 = "Usa un gran escudo para atacar objetivos dentro del área de ataque.",
  str_skill_desc_510017 = "Lanza un ataque a distancia sobre objetivos en la misma fila o columna dentro del área de ataque.",
  str_skill_desc_510018 = "Inflige daño a los objetivos en cuatro direcciones dentro de un rango de 1 casilla y derriba a los objetivos alcanzados por 1 casilla.",
  str_skill_desc_510019 = "Inflige daño en una gran área frontal.",
  str_skill_desc_510020 = "Inflige daño dentro del área de ataque.",
  str_skill_desc_510021 = "Inflige daño a 3 columnas en la parte delantera y derriba a los objetivos alcanzados.",
  str_skill_desc_510022 = "Invoca Darkflow para protección. Cada pila de Oscuridad puede cancelar 1 daño recibido.",
  str_skill_desc_510023 = "Inflige daño de fuego a los objetivos dentro del área de ataque.",
  str_skill_desc_510024 = "Dispara proyectiles para derribar objetivos en línea recta.",
  str_skill_desc_510025 = "Tocando el controlador, se disparará una flecha en la dirección de la torre de ballesta, lo que infligirá daño al objetivo alcanzado.",
  str_skill_desc_510026 = "Vani usa energía para lanzar ataques a distancia sobre objetivos dentro del área de ataque.",
  str_skill_desc_510027 = "Vani usa energía para curar a Philex.",
  str_skill_desc_510028 = "Philex usa la Defensa Armada para atacar objetivos dentro del área de ataque.",
  str_skill_desc_510029 = "Philex infunde energía en la Defensa Armada y la aplasta contra el suelo, infligiendo daño a los objetivos dentro del área de ataque y aturdiéndolos.",
  str_skill_desc_510030 = "Belicista golpea el suelo con los puños, inflige daño a los objetivos dentro del área de ataque y los aturde.",
  str_skill_desc_510031 = "Inflige daño a los objetivos dentro de 1 cúmulo circundante 1 vez cada 2 rondas.",
  str_skill_desc_510032 = "Coloca Plaga de picos en las casillas atravesados lo que inflige daño a los objetivos que pasan ahí.",
  str_skill_desc_510033 = "Inflige daño a los objetivos dentro del área de ataque y derriba a los objetivos alcanzados.",
  str_skill_desc_510034 = "Ataca a los objetivos dentro del área de ataque 1 vez.",
  str_skill_desc_510035 = "El aburrimiento acumula poder para un ataque de fuego en forma de cruz, que inflige daño a los objetivos y Quemadura. El aburrimiento no se puede interrumpir mientras se acumula poder.",
  str_skill_desc_510036 = "El aburrimiento absorbe energía dentro de 1 cúmulo circundante y con los mismos elementos que él, y ataca a los objetivos dentro del alcance (cuantas más casillas se absorban, mayor es el daño) mientras inflige Quemadura.",
  str_skill_desc_510037 = "El aburrimiento acumula poder para un ataque Trueno en forma de cruz, que inflige daño a los objetivos e inflige Parálisis. El aburrimiento no se puede interrumpir mientras se acumula poder.",
  str_skill_desc_510038 = "El aburrimiento absorbe energía dentro de 1 cúmulo circundante y con los mismos elementos que él mismo, y ataca a los objetivos dentro del alcance (cuantas más casillas se absorban, mayor es el daño) mientras inflige Parálisis.",
  str_skill_desc_500039 = "Shelt usa una cola gruesa para atacar a los objetivos dentro del rango de ataque, infligiendo daño 2 veces.",
  str_skill_desc_500040 = "Shire usa una cola gruesa para acumular picos de energía con el fin de atacar a los objetivos dentro del rango de ataque, causando daño 2 veces.",
  str_skill_desc_510039 = "Shelt usa una cola robusta para atacar a los objetivos dentro del área de ataque.",
  str_skill_desc_510040 = "Shire usa picos de energía para lanzar ataques a distancia en objetivos dentro del área de ataque.",
  str_skill_desc_510041 = "Al tocar el controlador, se disparará una flecha venenosa en la dirección de la torre de ballesta, lo que infligirá daño al objetivo alcanzado e infligirá veneno.",
  str_skill_desc_510042 = "Al tocar el controlador se disparará una flecha de parálisis en la dirección de la torre de ballesta. El Aurorian golpeado quedará inmovilizado y solo podrá moverse 1 casilla en la siguiente ronda.",
  str_skill_desc_510043 = "Un dispositivo que se carga con 1 Silo de Misiles, con dispositivo Jinete de la muerte.",
  str_skill_desc_510044 = "Tabaad usa garras para atacar objetivos dentro del área de ataque.",
  str_skill_desc_510045 = "Inflige daño a todos los objetivos una vez.",
  str_skill_desc_510046 = "Un objeto mágico fabricado por Unimet que se puede activar al pasar a través de él, lo que aumenta el ATQ de todos los Aurorians en un 10% del ATQ de Unimet.",
  str_skill_desc_510047 = "Un objeto mágico fabricado por Unimet que se puede activar al pasar a través de él, lo que aumenta el DEF de todos los Aurorians en un 10% del DEF de Unimet.",
  str_skill_desc_80001 = "Una réplica de cristal de relámpago hecha por Unimet que se puede activar al pasar a través de ella, desatando rayos que infligen el 50% del daño de Unimet a todos los objetivos enemigos.",
  str_skill_desc_80002 = "Una réplica de cristal de meteorito hecha por Unimet que se puede activar al pasar a través de ella, convocando meteoritos que infligen el 100% del daño de Unimet al objetivo enemigo con el mayor PS.",
