  str_skill_desc_5006381 = "Nozard rasga el suelo y libera Earthfire para dañar a todos los objetivos dentro del área de ataque.",
  str_skill_name_500639 = "Oscurecimiento",
  str_skill_desc_500639 = "Nozard acumula y desata el poder, causando daño a 3 columnas en el frente.",
  str_skill_name_500640 = "Aliento de fuego",
  str_skill_desc_500640 = "Nozard bate sus alas y desata una llama azul que inflige daño a todos los enemigos.",
  str_skill_desc_5006401 = "Nozard bate sus alas y desata una llama azul, infligiendo daño a todos los enemigos y conjurando una barrera de inmunidad para sí mismo.",
  str_skill_desc_49005111 = "Nozard aletea sus alas y libera llamas azules, causando daño a todos los enemigos y empujándolos hacia atrás 3 casillas, luego invoca Gloom Ghouls en ubicaciones fijas.",
  str_skill_name_505106 = "Ataque por la espalda",
