  str_skill_name_500252 = "Lanza",
  str_skill_desc_500252 = "Ataca a los objetivos dentro del área de ataque 1 vez.",
  str_skill_name_1002811 = "Eclipsites portadores",
  str_skill_desc_1002811 = "Eclipsites encargados del transporte. Derrótalos para conseguir el Nightium que están transportando.",
  str_skill_name_515121 = "Lumiwall",
  str_skill_desc_515121 = "Un objetivo en el que se transforma Phorosion se esconde en el Lumiwall más del enemigo (el Lumiwall puede ser atacado). Una ilusión para atacar al enemigo después de que se destruye el Lumiwall. Después de que se destruyen 3 Lumiwalls, todos los Lumiwalls desaparecen y aparece Phorosion.",
  str_skill_name_1003401 = "Refuerzo de combate",
  str_skill_desc_1003401 = "El Acechador se adhiere al Eclipsite dentro de 1 cúmulo circundante de sí mismo, proporcionando al Eclipsite un Escudo y mejorando su ATQ.",
  str_skill_name_1003421 = "Delirio",
  str_skill_desc_1003421 = "El Delirium Lurker se une a un Aurorian dentro de 1 grupo circundante de sí mismo, reduciendo el punto de Cordura del Aurorian continuamente.",
  str_skill_name_1003501 = "Regenerado",
