  str_skill_name_1004101 = "Ataque en ángulo",
  str_skill_desc_1004101 = "Se mueve en diagonal. Después de moverse, inflige daño a los objetivos en forma de cruz hasta el máximo de su alcance, centrado en la unidad.",
  str_skill_name_1004102 = "Asesinato en ángulo",
  str_skill_desc_1004102 = "Se mueve en diagonal. Después de moverse, inflige daño a los objetivos en forma de cruz hasta el máximo de su alcance, centrado en la unidad y reduce la DEF de los objetivos alcanzados.",
  str_skill_desc_1104102 = "Se mueve en diagonal. Después de moverse, inflige daño a los objetivos en forma de cruz en la máxima extensión de su alcance, centrado en la unidad, y reduce la DEF de los objetivos golpeados.",
  str_skill_name_1004201 = "Lado de la reina",
  str_skill_desc_1004201 = "Inflige daño equivalente a un porcentaje del PS máximo del objetivo a los objetivos en forma radial hasta el alcance máximo centrado en la unidad.",
  str_skill_name_1004202 = "Defensa incondicional",
  str_skill_desc_1004202 = "Inflige daño equivalente a un porcentaje del PS máximo del objetivo a los objetivos en forma radial al rango máximo centrado en la unidad. Si no hay objetivos en las 8 direcciones a su alrededor, gana una barrera defensiva y restaura PS a las unidades amigas.",
  str_skill_desc_1104202 = "Inflige daño igual a un porcentaje del HP máximo del objetivo a objetivos en forma radial al rango máximo centrado en la unidad. Si no hay objetivos en las 8 direcciones alrededor de la unidad, gana una barrera defensiva, reduce la cordura del jugador y restaura HP a las unidades amigas.",
  str_skill_name_1004301 = "Comando Real",
  str_skill_desc_1004301 = "Comanda peones para infligir daño masivo a los objetivos dentro de 1 cúmulo circundante.",
  str_skill_name_1004302 = "Disuasión",
  str_skill_desc_1004302 = "Derriba objetivos a su alcance, hasta quedar fuera del rango de ataque.",
  str_skill_name_1004303 = "Reino soberano",
  str_skill_desc_1004303 = "Inflige daño a todos los enemigos en el tablero.",
  str_skill_name_1006511 = "Chocar",
  str_skill_desc_1006511 = "Inflige daño a los objetivos dentro del alcance.",
  str_skill_name_1006521 = "Abismo",
  str_skill_desc_1006521 = "Detona la energía de su cuerpo, infligiendo daño a los objetivos dentro de su alcance y destruyendo la casilla en la que se encuentra.",
  str_skill_name_1007001 = "Madriguera",
  str_skill_desc_1007001 = "Cuando hay casillas rotas dentro del alcance del objetivo, Burrow emerge de una casilla rota al lado del objetivo e inflige daño, al mismo tiempo que rompe una rotas.\nCuando los Aurorians atraviesan casillas casilla rota casilla adyacente.",
  str_skill_name_1007011 = "Rompedor",
