  str_skill_desc_220091201 = "Lanza un asalto a la ubicación del objetivo en la última ronda y 1 cúmulo circundante. Rompe casillas en el rango y derrota instantáneamente a los objetivos dentro del rango.",
  str_skill_name_1007104 = "Andanada sónica",
