  str_skill_name_200024221 = "Invocar Espadas aterradoras y Spellhound",
  str_skill_name_200024231 = "Invocar Dreadblades y Vinesmark",
  str_skill_desc_200024221 = "Invoca Espadas aterradoras y Spellhounds para luchar en cada ronda.",
  str_skill_desc_200024231 = "Invoca a Dreadblades y Vinesmark a la batalla en cada ronda.",
  str_skill_name_10000021 = "Invocar Spellhound",
  str_skill_desc_10000021 = "Invoca un Spellhound para luchar en cada ronda.",
  str_skill_name_28002411 = "Opresión",
  str_skill_desc_28002411 = "Forsakin te derriba en cada ronda.",
  str_skill_name_390041101 = "Nefasto Rompedor",
