  str_skill_name_390025101 = "Guadaña Nefasta",
  str_skill_desc_390025101 = "El Fantasma ataca 1 vez e inflige daño elemental.",
  str_skill_name_390025102 = "Ley de Murphy Nefasta",
  str_skill_desc_390025102 = "El Fantasma inflige daño elemental en forma de cruz.",
  str_skill_name_390025103 = "Invocar Espejismo",
