  str_skill_desc_290120103 = "Claymore se teletransporta al centro del mapa y desata un poder aterrador para destruir casillas en forma de cruz en el centro del mapa mientras usa Darkflow para cubrir tres áreas del mapa, engullendo temporalmente a todos Lumina en estas áreas.",
  str_skill_name_290130101 = "Retirada",
