  str_skill_upgrade_desc_15010412 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15010415 = "Mejora del Combo en Cadena: Aumenta el alcance de habilidades en <color=#FFFF00> 1 grupo </color>.",
  str_skill_upgrade_desc_16003013 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16003016 = "Mejora Habilidad Activa: Incrementa la habilidad por 200%. el daño recibido por el enemigo más cercano a Sinsa se triplica.",
  str_skill_upgrade_desc_15007112 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15007115 = "Mejora de habilidad activa: después de que se extiende la habilidad activa, las fichas más lejanas se convierten en fichas rojas.",
  str_skill_upgrade_desc_16010513 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16010516 = "Mejora de habilidad activa: inflige daño 1 vez adicional por cada mosaico amarillo dentro <color=#00F6FF>2 grupos circundantes</color> de su ubicación actual.",
  str_skill_upgrade_desc_17010913 = "Mejora de la habilidad del equipamiento: Obtiene <color=#FFFF00> 1 </color> Vis por el primer ataque normal lanzado en cada ronda y aumenta el daño infligido por este ataque normal en un <color=#FFFF00> 100% </color>.",
  str_skill_upgrade_desc_17010916 = "Mejora del Combo en Cadena: 30% de probabilidad de una bonificación de daño combo en cadena de + <color=#FFFF00>50%</color>.+1% de probabilidad de activación por Vis.",
  str_skill_upgrade_desc_17011013 = "Mejora de la habilidad del equipamiento: Cuando una Habilidad Activa mata a <color=#FFFF00> 1 </color> enemigo, gana <color=#FFFF00> 2 </color> Vis.",
  str_skill_upgrade_desc_17011016 = "Mejora Habilidad Activa: Por cada 1 Vis eliminado, este daño ignora el <color=#FFFF00> 1% </color> de la DEF del objetivo.",
  str_skill_upgrade_desc_17010713 = "Mejora Habilidad Activa: Cuando se aumenta, matar a <color=#FFFF00> 1 </color> enemigo otorga <color=#FFFF00> 2 </color> Vis.",
  str_skill_upgrade_desc_17010716 = "Mejora de la habilidad del equipamiento: Al comienzo de cada ronda, por cada <color=#FFFF00> 1 </color> enemigo dentro de <color=#FFFF00> 4 casillas en forma de cruz </color>, gana <color=#FFFF00> 1 </color> Vis.",
  str_skill_upgrade_desc_17010813 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#FFFF00> 60% </color>.",
  str_skill_upgrade_desc_17010816 = "Mejora activa de habilidades: aumenta el ATK básico en <color=#FFFF00>3%</color> en la batalla actual por cada habilidad.",
  str_skill_upgrade_desc_16011213 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00>Ataque Preventivo</color>. Disponible al entrar en combate. Amplía el rango de selección de Habilidad Activa a todo el campo de batalla.",
  str_skill_upgrade_desc_16011216 = "Mejora de habilidad activa: convierte 1 o más fichas enemigas en fichas rojas.",
  str_skill_upgrade_desc_15011312 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15011315 = "Mejora Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00> 1 </color> ronda.",
  str_skill_upgrade_desc_15011412 = "Mejora Habilidad Activa: Después de usar una Habilidad Activa, los Combos en Cadena son efectivos contra todos los enemigos dentro del alcance de esta ronda.",
  str_skill_upgrade_desc_15011415 = "Mejora Habilidad Activa: puede usar Habilidad Activa una vez más después de pegarle a 1 enemigo (puede usarse una vez por ronda).",
  str_skill_upgrade_desc_14012714 = "Mejora Habilidad Activa: las casillas seleccionadas se convierte en <link=\"20001\"> <#FFAE07><u>casillas mejoradas</u></color></link> Verdes.",
  str_skill_upgrade_desc_16011713 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#FFFF00> 30% </color>.",
  str_skill_upgrade_desc_16011716 = "Mejora la Habilidad Activa: Si la Habilidad Activa estaba lista en la última ronda, el alcance del desplazamiento se convierte en <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_upgrade_desc_16011913 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16011916 = "Mejora Habilidad Activa: Después que cada onda de trueno golpea a un objetivo, el daño posterior de la onda de trueno se reduce en un <color=#00F6FF>20%</color>. Puede golpear hasta <color=#00F6FF>5</color> veces.",
  str_skill_upgrade_desc_16012212 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16012215 = "Mejora Habilidad Activa: Elimina efectos de <color=#00F6FF>casilla dañada</color> de las casillas dentro del alcance de la habilidad.",
  str_skill_upgrade_desc_16012113 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a una habilidad <color=#FFFF00>ataque preventivo</color>, haciéndola disponible al entrar en combate.",
  str_skill_upgrade_desc_16012116 = "Mejora Habilidad Activa: las primeras <color=#00F6FF>3</color> casillas en el rango de daño se convierten en <link=\"20001\"><#FFAE07><u> casillas mejoradas</u></color></link>. Por cada casilla extendida, el daño aumenta en un <color=#FFFF00>15%</color>.",
  str_skill_upgrade_desc_16011512 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a una habilidad <color=#FFFF00>ataque preventivo</color>, haciéndola disponible al entrar en combate.",
  str_skill_upgrade_desc_16011515 = "Mejora de Habilidad Activa: 1 casilla adicional dentro del rango de purificación se convierte en un <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>.",
  str_skill_upgrade_desc_13006514 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a una habilidad <color=#FFFF00>ataque preventivo</color>, haciéndola disponible al entrar en combate.",
  str_skill_upgrade_desc_16012613 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#FFFF00>120%</color>.",
  str_skill_upgrade_desc_16012616 = "Mejora de la Habilidad Activa: Puede lanzarse 1 vez más después de entrar en la Hora de Aurora (puede activarse 1 vez por oleada).",
  str_skill_upgrade_desc_16012913 = "Mejora Habilidad Activa: Cada <link=\"30022\"><#FFAE07><u>Scion</u></color></link> causa un daño de<color=#00F6FF>10%</color> adicional. Puede almacenar hasta <color=#00F6FF>12</color> Scions.",
  str_skill_upgrade_desc_16012916 = "Mejora Habilidad Activa: Gana 2 Adicionales <link=\"30023\"><#FFAE07><u>Scions</u></color></link> al inicio de cada ola.",
  str_skill_upgrade_desc_16012013 = "Mejora Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00> 1 </color> ronda.",
  str_skill_upgrade_desc_16012016 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16012312 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#FFFF00> 40% </color>.",
  str_skill_upgrade_desc_16012315 = "Mejora de Habilidad Activa: cuando golpea al objetivo por primera vez, queda aturdido durante 1 ronda.",
  str_skill_upgrade_desc_15001514 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16013113 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16013116 = "Mejora de Habilidad Activa: aumenta el valor del escudo de Habilidad Activa en un <color=#FFFF00>30%</color>.",
  str_skill_upgrade_desc_15013212 = "Mejora de la Habilidad Activa: si el daño infligido al enemigo se ha recuperado, el tiempo de enfriamiento de la Habilidad Activa se reducirá en <color=#00F6FF>1</color> ronda.",
  str_skill_upgrade_desc_15013215 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#FFFF00> 150% </color>.",
  str_skill_upgrade_desc_16013313 = "Mejora hab. activa: Cambia la hab. activa a <color=#FFFF00> Golpe preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16013316 = "Mejora del Combo en Cadena: Inflige <color=#00F6FF>30%</color> de daño de <link=\"30015\"><#FFAE07><u>Salpicadura</u></color></link> a todos los objetivos en <color=#00F6FF>4 casillas en forma de cruz</color> alrededor del enemigo.",
