  str_skill_desc_300050 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color> y derriba a los enemigos.",
  str_skill_desc_320050 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color> y derriba a los enemigos. Los enemigos derribados sufren una DEF reducida en 10%.",
  str_skill_desc_300022 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color> y un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos.",
  str_skill_desc_303022 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color> y un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos.",
  str_skill_desc_310022 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color> y un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos.",
  str_skill_desc_313022 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color> y un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos.",
  str_skill_desc_300047 = "Recupera los PS del equipo en un <color=#00F6FF>150%</color> del ATQ de Zoya. Cada casilla Azul en el campo aumenta la efectividad de curación en <color=#00F6FF>5%</color>.",
  str_skill_desc_303047 = "Recupera los PS del equipo en un <color=#00F6FF>150%</color> del ATQ de Zoya. Cada casilla Azul en el campo aumenta la efectividad de curación en <color=#00F6FF>5%</color>.",
  str_skill_desc_320047 = "Recupera los PS del equipo en un <color=#00F6FF>150%</color> del ATQ de Zoya. Cada casilla Azul en el campo aumenta la efectividad de curación en <color=#00F6FF>8%</color>.",
  str_skill_desc_323047 = "Recupera los PS del equipo en un <color=#00F6FF>150%</color> del ATQ de Zoya. Cada casilla Azul en el campo aumenta la efectividad de curación en <color=#00F6FF>8%</color>.",
  str_skill_desc_300049 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_303049 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_320049 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color> y convierte todas las casillas rojas dentro del alcance de ataque en otros elementos.",
  str_skill_desc_323049 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color> y convierte todas las casillas rojas dentro del alcance de ataque en otros elementos.",
  str_skill_desc_300051 = "Ataca en cualquier 1 dirección seleccionada. Inflige un <color=#00F6FF>240%</color> de daño al primer enemigo golpeado y a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_310051 = "Ataca en cualquier 1 dirección seleccionada. Inflige un <color=#00F6FF>240%</color> de daño al primer enemigo golpeado y a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_320051 = "Ataca en cualquier 1 dirección seleccionada. Inflige un <color=#00F6FF>240%</color> de daño al primer enemigo golpeado y a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>, e inflige <link=\"10002\"><#FFAE07><u>Quema</u></color></link> (2 pilas en el primer enemigo, 1 pila en los demás) por 2 rondas.",
  str_skill_desc_300052 = "Se teletransporta a una ubicación seleccionada dentro de una distancia de 3 casillas. Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 4 casillas en forma de cruz </color> en esa ubicación.",
  str_skill_desc_310052 = "Se teletransporta a una ubicación seleccionada dentro de una distancia de 3 casillas. Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 4 casillas en forma de cruz </color> en esa ubicación.",
  str_skill_desc_320052 = "Teletransporta a un lugar seleccionado dentro de una distancia de 3 casillas. Inflige <color=#00F6FF>{1}%</color> de daño a casillas dentro de <color=#00F6FF>1 cúmulo circundante</color> de este lugar.",
  str_skill_desc_300007 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>en forma de cruz al rango máximo</color>.",
  str_skill_desc_320007 = "Inflige un <color=#00F6FF>{1}%</color> de daño a un <color=#00F6FF>área en forma de cruz de alcance máximo</color>. Duplica las pilas de Veneno si el objetivo ha sido Envenenado. Una vez que el objetivo recibe el máximo de 5 pilas de Veneno, las Habilidades Activas infligen + <color=#00F6FF>50%</color> de daño al objetivo.",
  str_skill_desc_300008 = "Convierte 1 casilla atravesable en un <link=\"30001\"><#FFAE07><u> casilla prisma </u></color></link> roja.",
  str_skill_desc_310008 = "Convierte 1 casilla atravesable en un <link=\"30001\"><#FFAE07><u> casilla prisma </u></color></link> roja.",
  str_skill_desc_300032 = "ofertas <color=#00F6FF>100%</color> daño <color=#00F6FF>6-10</color> veces al azar a los enemigos en el campo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_310032 = "ofertas <color=#00F6FF>100%</color> daño <color=#00F6FF>6-10</color> veces al azar a los enemigos en el campo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_300035 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF> 2 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_310035 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF> 2 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_320035 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF> 2 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_300058 = "Coloca la bandera en 1 casilla seleccionada. Cuanto más cerca esté Amy de la bandera, mayor será su DEF (hasta <color=#00F6FF>100%</color>). La bandera desaparece cuando lo toca un enemigo.",
  str_skill_desc_303058 = "Coloca la bandera en 1 casilla seleccionada. Cuanto más cerca esté Amy de la bandera, mayor será su DEF (hasta <color=#00F6FF>100%</color>). La bandera desaparece cuando lo toca un enemigo.",
  str_skill_desc_310058 = "Coloca la bandera en 1 casilla seleccionada. Cuanto más cerca esté Amy de la bandera, mayor será su DEF (hasta <color=#00F6FF>100%</color>). La bandera desaparece cuando lo toca un enemigo.",
  str_skill_desc_313058 = "Coloca la bandera en 1 casilla seleccionada. Cuanto más cerca esté Amy de la bandera, mayor será su DEF (hasta <color=#00F6FF>100%</color>). La bandera desaparece cuando lo toca un enemigo.",
  str_skill_desc_300053 = "Inflige un <color=#00F6FF> 150% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color>. El daño aumenta a <color=#00F6FF> 150% </color> si solo hay 1 enemigo.",
  str_skill_desc_303053 = "Inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>. El daño aumenta a <color=#00F6FF>150%</color> si solo hay 1 enemigo. Elimina el tiempo de enfriamiento de la Habilidad Activa si se mata al objetivo con la habilidad.",
  str_skill_desc_310053 = "Inflige un <color=#00F6FF> 150% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color>. El daño aumenta a <color=#00F6FF> 150% </color> si solo hay 1 enemigo.",
  str_skill_desc_313053 = "Inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>. El daño aumenta a <color=#00F6FF>150%</color> si solo hay 1 enemigo. Elimina el tiempo de enfriamiento de la Habilidad Activa si se mata al objetivo con la habilidad.",
  str_skill_desc_320053 = "Inflige un <color=#00F6FF> 150% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color>. El daño aumenta a <color=#00F6FF> 200% </color> si solo hay 1 enemigo.",
  str_skill_desc_323053 = "Inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>. El daño aumenta a <color=#00F6FF>200%</color> si solo hay 1 enemigo. Elimina el tiempo de enfriamiento de la Habilidad Activa si se mata al objetivo con la habilidad.",
  str_skill_desc_300074 = "ofertas <color=#00F6FF>{1}%</color> daño a un <color=#00F6FF>forma cruzada al rango máximo</color> y los aggros a la unidad.",
  str_skill_desc_310074 = "ofertas <color=#00F6FF>{1}%</color> daño a un <color=#00F6FF>forma cruzada al rango máximo</color> y los aggros a la unidad.",
  str_skill_desc_320074 = "ofertas <color=#00F6FF>{1}%</color> daño a un <color=#00F6FF>forma cruzada al rango máximo</color> y los aggros a la unidad. Para cada <color=#00F6FF>1</color> azulejo agredido, el enemigo toma <color=#00F6FF>10%</color> más daños finales.",
  str_skill_desc_300017 = "Se teletransporta a una ubicación seleccionada. Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 4 casillas en forma de cruz </color> y derriba a los enemigos.",
  str_skill_desc_320017 = "Se teletransporta a una ubicación seleccionada. Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 casillas en forma radial </color> y derriba a los enemigos.",
  str_skill_desc_300040 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>2 cúmulos circundantes</color> y reinicia todas las casillas dentro del área de ataque.",
  str_skill_desc_330040 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 2 cúmulos circundantes </color> y reinicia todas las casillas que <color=#00F6FF>no sean rojas</color> dentro del área de ataque. Hay una <color=#00F6FF>posibilidad pequeña</color> de generar casillas azules.",
  str_skill_desc_300041 = "Convierte <color=#00F6FF> 4 casillas en forma de cruz </color> en azul.",
  str_skill_desc_304041 = "Convierte <color=#00F6FF> 4 casillas en forma de cruz </color> en azul y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_300021 = "Restablece todas las casillas en el campo mientras se mantiene el número de <link=\"20001\"><#FFAE07><u> casillas mejoradas </u></color></link>que se redistribuirán.",
  str_skill_desc_310021 = "Restablece todas las casillas en el campo mientras se mantiene el número de <link=\"20001\"><#FFAE07><u> casillas mejoradas </u></color></link>que se redistribuirán.",
  str_skill_desc_330021 = "Restablece todas las casillas en el campo mientras se mantiene el número de <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link> que se redistribuirán. Las casillas Verdes tienen una mayor probabilidad de generar <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_300004 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>9 casillas en forma cuadrada</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_320004 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_330004 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. Convierte <color=#00F6FF>2</color> fichas a Azul dentro del área de ataque.",
  str_skill_desc_300073 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_320073 = "Inflige daño a <color=#00F6FF>13 casillas en forma de diamante</color> centradas en 1 casilla seleccionada. Inflige <color=#00F6FF>300%</color> de daño a la casilla seleccionada, y <color=#00F6FF>225%</color> de daño a las <color=#00F6FF>4 casillas en forma de cruz</color> alrededor de la casilla seleccionada. Inflige <color=#00F6FF>150%</color> de daño a las casillas restantes.",
