  str_skill_desc_302048 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 9 casillas mejoradas en un cuadrado </color> rodeando 1 casillas mejorada seleccionada. Convierte 1 casilla enemiga a amarilla.",
  str_skill_desc_320048 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_322048 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 13 casillas en forma de diamante </color> centrado en 1 casilla seleccionada. Convierte 1 casilla enemiga en amarilla.",
  str_skill_desc_300009 = "Convierte <color=#00F6FF> 4 </color> casillas seleccionadas amarillos más cercanas a rojas.",
  str_skill_desc_302009 = "Convierte <color=#00F6FF> 4 </color> casillas seleccionadas amarillos más cercanas a rojas. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> 1 </color> en esta ronda.",
  str_skill_desc_305009 = "Convierte <color=#00F6FF> 5 </color> casillas seleccionadas amarillos más cercanas a rojas. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> 1 </color> en esta ronda.",
  str_skill_desc_330009 = "Convierte el <color=#00F6FF>4</color> casillas seleccionadas amarillas más cercanas a rojas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u> casillas seleccionadas mejoradas</u></color></link>.",
  str_skill_desc_332009 = "Convierte <color=#00F6FF>4</color> casillas amarillas seleccionadas más cercas en rojas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>. Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casilla cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_335009 = "Convierte <color=#00F6FF>5</color> casillas amarillas seleccionadas más cercas en rojas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>. Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casilla cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_300012 = "ofertas <color=#00F6FF>{1}%</color> daño a un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos. Convierte las fichas en el área de ataque a Amarillo.",
  str_skill_desc_302012 = "ofertas <color=#00F6FF>{1}%</color> daño a un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos. Convierte las fichas en el área de ataque a Amarillo.",
  str_skill_desc_300013 = "Gana <color=#00F6FF>8%</color> de PS de Noah como escudo para cada casilla azul durante 1 ronda.",
  str_skill_desc_305013 = "Gana <color=#00F6FF>10%</color> de PS de Noah como escudo para cada casilla azul durante 1 ronda.",
