  str_skill_desc_325013 = "Gana un <color=#00F6FF>10%</color> del PS de Noah como escudo por cada casilla azul durante 1 ronda. Usando la Habilidad Activa aumenta la DEF de Noah en un <color=#00F6FF> 50%</color> por 1 ronda.",
  str_skill_desc_300018 = "La Tormenta Solar explota, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF> todos</color> los enemigos en el campo y aventándolos.",
  str_skill_desc_305018 = "La Tormenta Solar explota, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF> todos</color> los enemigos en el campo y aventándolos.",
  str_skill_desc_300033 = "Inflige <color=#00F6FF> 80% </color> de daño <color=#00F6FF> 5 </color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada casilla de agua dentro de <color=#00F6FF> 1 cúmulo circundante </color> de la unidad.",
