  str_skill_desc_335010 = "Cuando se usa, el Combo en Cadena de un Aurorian de bosque se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de bosque es igual a <color=#00F6FF>85%</color> del ATQ de Louise.",
  str_skill_desc_300014 = "Inflige <color=#00F6FF>{1}% </color> más <color=#00F6FF> 10% </color> del PS actual del objetivo en daños a <color=#00F6FF> todos </color> enemigos.",
  str_skill_desc_302014 = "Inflige <color=#00F6FF>{1}% </color> más <color=#00F6FF> 10% </color> del PS actual del objetivo en daños a <color=#00F6FF> todos </color> los enemigos (matando a todos los monstruos no jefes con PS bajo <color=#00F6FF> 10% </color>)",
  str_skill_desc_320014 = "Inflige <color=#00F6FF>{1}% </color> más <color=#00F6FF> 10% </color> del PS actual del objetivo en daños a <color=#00F6FF> todos </color> los enemigos Los daños tratados por las habilidades activas aumentan con la DEF de Schwartz, hasta <color=#00F6FF> 5% </color>.",
  str_skill_desc_322014 = "Inflige <color=#00F6FF>{1}% </color> más <color=#00F6FF> 10% </color> del PS actual del objetivo en daños a <color=#00F6FF> todos </color> los enemigos (matando a todos los monstruos no jefes con bajo <color=#00F6FF> 10% </color>de PS). Los daños tratados por las habilidades activas aumentan con la DEF de Schwartz, hasta <color=#00F6FF> 5% </color>.",
  str_skill_desc_300078 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>9 casillas en forma cuadrada</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_302078 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 9 casillas en un cuadrado</color> que circundan 1 casilla seleccionada. Convierte 1 casilla enem. a una <link=\"20001\"><#FFAE07><u> casilla mejorada</u></color></link>.",
