  str_skill_desc_322078 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 13 casillas en forma de diamante</color> que circundan 1 casilla seleccionada. Convierte 1 casilla enem. a una <link=\"20001\"><#FFAE07><u> casilla mejorada</u></color></link>.",
  str_skill_desc_300076 = "Convierte <color=#00F6FF>4</color> casillas Verdes más cercanas en Azul.",
  str_skill_desc_302076 = "Convierte <color=#00F6FF> 4 </color> casillas Verdes más cercanas a Azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF>1</color> en esta ronda.",
  str_skill_desc_305076 = "Convierte <color=#00F6FF> 5 </color> casillas Verdes más cercanas a Azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF>1</color> en esta ronda.",
  str_skill_desc_330076 = "Convierte las <color=#00F6FF>4</color> casillas Verde más cercanas a Azul y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u> casillas mejoradas </u></color></link>.",
  str_skill_desc_332076 = "Convierte las <color=#00F6FF>4</color> casillas verdes más cercanas en azul (tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>). Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_335076 = "Convierte las <color=#00F6FF>5</color> casillas verdes más cercanas en azul (tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>). Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_300042 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos. Convierte las fichas en el área de ataque a Azul.",
