  str_skill_desc_303001 = "Convierte <color=#00F6FF> 4 </color> casillas rojas o amarillas más cercanas a verde. Si la habilidad está lista en la última ronda, aumenta el conteo de conversión de casillas mejoradas por <color=#00F6FF> 1 </color> en esta ronda.",
  str_skill_desc_306001 = "Convierte <color=#00F6FF> 5 </color> casillas rojas o amarillas más cercanas a verde. Si la habilidad está lista en la última ronda, aumenta el conteo de conversión de casillas mejoradas por <color=#00F6FF> 1 </color> en esta ronda.",
  str_skill_desc_330001 = "Convierte las <color=#00F6FF>4</color> casillas Rojas o Amarillas más cercanas a Verde (tiene la posibilidad de generar hasta 2 <link=\"20001\"> <#FFAE07><u> casillas mejoradas</u></color></link>).",
  str_skill_desc_333001 = "Convierte las <color=#00F6FF>4</color> casillas Rojas o Amarillas más cercanas a Verde (tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>). Si la habilidad está lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_336001 = "Convierte las <color=#00F6FF>5</color> casillas Rojas o Amarillas más cercanas a Verde (tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>). Si la habilidad está lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
