  str_skill_desc_320002 = "Convierte cualquier <color=#00F6FF>2</color> fichas seleccionadas para <link=\"20001\"><#FFAE07><u>Baldosas verdes mejoradas</u></color></link> y ofertas <color=#00F6FF>200%</color> daño en un <color=#00F6FF>forma cruzada al rango máximo</color> centrado en cada mosaico seleccionado.",
