  str_skill_desc_310005 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos en la pantalla.Cuanto menor sea el HP del enemigo, mayor será el daño (el daño aumenta hasta un 100%).",
  str_skill_desc_316005 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos en la pantalla.Cuanto menor sea el HP del enemigo, mayor será el daño (el daño aumenta hasta un 100%).",
  str_skill_desc_330005 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos en la pantalla.Cuanto menor sea el HP del enemigo, mayor será el daño (el daño aumenta hasta un 100%).",
  str_skill_desc_336005 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos en la pantalla.Cuanto menor sea el HP del enemigo, mayor será el daño (el daño aumenta hasta un 100%).",
  str_skill_desc_300006 = "Se teletransporta a una ubicación seleccionada. Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>1 columna</color> y avienta a los enemigos. Convierte las casillas en el área de ataque en Azul.",
  str_skill_desc_303006 = "Se teletransporta a una ubicación seleccionada. Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>1 columna</color> y avienta a los enemigos. Convierte las casillas en el área de ataque en Azul.",
  str_skill_desc_300025 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>3 columnas seleccionadas</color> o <color=#00F6FF>3 filas seleccionadas</color> y derriba a los enemigos. Restablece todas las casillas <color=#00F6FF>que no sean Rojas</color> dentro del área de ataque.",
  str_skill_desc_306025 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF> 3 columnas seleccionadas </color> o <color=#00F6FF> 3 filas seleccionadas </color> y derriba a los enemigos. Restablece todas las casillas <color=#00F6FF> que no sean rojas </color> dentro del área de ataque y tiene una <color=#00F6FF> pequeña posibilidad </color> de generar casillas rojas.",
  str_skill_desc_320025 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF> 3 columnas </color> o <color=#00F6FF> 3 filas seleccionadas </color> y derriba a los enemigos. El daño infligido a la fila o columna del medio será 1.5 veces el daño infligido a los dos lados. Restablece todas las casillas <color=#00F6FF> que no sean rojas </color> dentro del área de ataque.",
  str_skill_desc_326025 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>3 columnas seleccionadas</color> o <color=#00F6FF>3 filas seleccionadas</color>y avienta a los enemigos. El daño infligido a la fila o columna del medio será 1.5 veces el daño infligido a los dos lados. Restablece todas las casillas <color=#00F6FF>que no sean Rojas</color> dentro del área de ataque y tiene una <color=#00F6FF>pequeña posibilidad</color> de generar casillas Rojas.",
  str_skill_desc_300026 = "Restablece <color=#00F6FF>todas las casillas que no son Rojas</color> y tiene una <color=#00F6FF>pequeña posibilidad</color> de generar casillas Rojas. Convierte 1 o más casillas enemigas en Rojas.",
  str_skill_desc_306026 = "Restablece <color=#00F6FF>todas las casillas que no son Rojas</color> y tiene una <color=#00F6FF>pequeña posibilidad</color> de generar casillas Rojas. Convierte 1 o más casillas enemigas en Rojas.",
  str_skill_desc_300028 = "Recupera los PS del equipo en un <color=#00F6FF> 200% </color> del ATQ de Raphaela. Restablece todas las <color=#00F6FF> casillas que no son azules dentro de los 3 cúmulos circundantes </color>.",
  str_skill_desc_306028 = "Restablece todo los PS del equipo por <color=#00F6FF> 200% </color> de la ATQ de Raphaela. Restablece todas las <color=#00F6FF> casillas que no son azules dentro de los 3 cúmulos circundantes </color> y tiene una <color=#00F6FF> pequeña posibilidad </color> de generar casillas azules.",
  str_skill_desc_330028 = "Recupera los PS del equipo en un <color=#00F6FF> 200% </color> del ATQ de Raphaela. Restablece todos los <color=#00F6FF> casillas que no son azules </color>.",
