  str_skill_desc_300086 = "Recupera el PS del equipo en un<color=#00F6FF>60%</color> de la PS Max. de Uriah. Si hay algún exceso de curación, la casilla Verde más cercana se convierte en una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>.",
  str_skill_desc_304086 = "Recupera el PS del equipo en un<color=#00F6FF>70%</color> de la PS Max. de Uriah. Si hay algún exceso de curación, la casilla Verde más cercana se convierte en una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>.",
  str_skill_desc_330086 = "Recupera el PS del equipo en un <color=#00F6FF>60%</color> del PS máximo de Uriah. Si hay un exceso de curación, la casilla verde más cercana se convierte en una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>. Si se activa la <link=\"30010\"><#FFAE07><u>Hora de Aurora</u></color></link>, se puede volver a usar la Habilidad Activa.",
  str_skill_desc_334086 = "Recupera el PS del equipo en un <color=#00F6FF>70%</color> del PS máximo de Uriah. Si hay un exceso de curación, la casilla verde más cercana se convierte en una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>. Si se activa la <link=\"30010\"><#FFAE07><u>Hora de Aurora</u></color></link>, se puede volver a usar la Habilidad Activa.",
  str_skill_desc_300068 = "Se transporta a cualquier ubicación y genera 1 Pluma de Wendy en el acto. Toca Pluma de Wendy para volver a la ubicación original. Solo puede haber 1 Pluma de Wendy en el campo de batalla.",
  str_skill_desc_320068 = "Genera 1 pluma de Wendy en el campo al inicio de la batalla. Genera 1 pluma de Wendy en el lugar después de usar una Habilidad Activa. Toca la pluma de Wendy para volver a su ubicación. Sólo puede haber 1 Pluma de Wendy en el campo de batalla.",
  str_skill_desc_300082 = "Intercambia elementos entre cualquier <color=#00F6FF> 2 </color> casillas.",
  str_skill_desc_320082 = "Intercambia elementos entre cualquier <color=#00F6FF>2</color> casillas. Cualquier casilla mejorada de bosque seleccionada se convierte en <link=\"20001\"><#FFAE07> <u>casilla mejorada</u></color></link>.",
  str_skill_desc_300057 = "Teletransporta a cualquier ubicación y regenera los PS del equipo por una cantidad igual a <color=#00F6FF> 250% </color> del ATQ de Philyshy. Aumenta el factor de curación por <color=#00F6FF> 10% </color> para cada enemigo dentro de <color=#00F6FF> 2 cúmulos circundantes </color> de la ubicación de destino.",
  str_skill_desc_305057 = "Teletransporta a cualquier ubicación y regenera los PS del equipo por una cantidad igual a <color=#00F6FF> 250% </color> del ATQ de Philyshy. Aumenta el factor de curación por <color=#00F6FF> 15% </color> para cada enemigo dentro de <color=#00F6FF> 3 cúmulos circundantes </color> de la ubicación de destino.",
  str_skill_desc_320057 = "Se teletransporta a cualquier lugar y regenera el HP del equipo por una cantidad igual a <color=#00F6FF>250%</color> del ATK de Philyshy. Subsidios Philyshy un escudo igual a <color=#00F6FF>30%</color> de su HP máximo y aumenta el factor de curación en <color=#00F6FF>10%</color> para cada enemigo dentro <color=#00F6FF>2 grupos circundantes</color> de la ubicación de destino.",
  str_skill_desc_325057 = "Se teletransporta a cualquier lugar y regenera el HP del equipo por una cantidad igual a <color=#00F6FF>250%</color> del ATK de Philyshy. Subsidios Philyshy un escudo igual a <color=#00F6FF>30%</color> de su HP máximo y aumenta el factor de curación en <color=#00F6FF>15%</color> para cada enemigo dentro <color=#00F6FF>3 grupos circundantes</color> de la ubicación de destino.",
  str_skill_desc_300091 = "Cuando se lanza, cada casilla azul en el campo de batalla otorga a todos los miem. despleg. una bonificación de ATQ igual al <color=#00F6FF>0.5%</color> del ATQ de Chloe durante 2 rondas.",
  str_skill_desc_320091 = "Concede una <link=\"30006\"><#FFAE07><u>Marca de concierto</u></color></link>. Cuando se lanza, cada casilla azul en el campo de batalla y cada pila de la marca otorga a todos los miem. despleg. una bonificación de ATQ igual al <color=#00F6FF>0.5%</color> del ATQ de Chloe durante 2 rondas.",
  str_skill_desc_300079 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos dentro de <color=#00F6FF> 2 cúmulos circundantes </color> y reinicia todas las casillas dentro del área de ataque.",
  str_skill_desc_330079 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 2 cúmulos circundantes </color> y reinicia todas las casillas que <color=#00F6FF>no sean Azul</color> dentro del área de ataque. Hay una <color=#00F6FF>posibilidad pequeña</color> de generar casillas azules.",
  str_skill_desc_300085 = "Inflige un <color=#00F6FF>{1}% </color> de daño al enemigo con el <color=#00F6FF> porcentaje de PS más bajo </color>.",
  str_skill_desc_320085 = "Inflige <color=#00F6FF>{1}%</color> de daño al enemigo con el <color=#00F6FF>porcentaje de PS más bajo</color>. Elimina el tiempo de enfriamiento de la Habilidad Activa si el objetivo es eliminado con la habilidad",
  str_skill_desc_330085 = "Inflige <color=#00F6FF>{1}%</color> de daño al enemigo con el <color=#00F6FF>porcentaje de PS más bajo</color>. Otorga una <link=\"30005\"><#FFAE07><u>Marca Testigo</u></color></link>. Cada pila de la Marca de Testigo aumenta el ATQ de los Aurorians de agua en <color=#00F6FF>1%</color>. Elimina el tiempo de enfriamiento de la Habilidad Activa si el objetivo es eliminado con la habilidad",
  str_skill_desc_300089 = "Convierte cualquier <color=#00F6FF> 2 </color> casillas seleccionadas en <link=\"30001\"><#FFAE07><u> casillas de prisma </u></color></link> amarillas.",
  str_skill_desc_16008901 = "Convierte 2 fichas seleccionadas en fichas de prisma amarillo.",
  str_skill_desc_303089 = "Convierte cualquier <color=#00F6FF> 2 </color> casillas seleccionadas en <link=\"20001\"><#FFAE07><u>casillas de prisma mejoradas</u></color></link> amarillas.",
  str_skill_desc_300027 = "Se desplaza a la ubicación seleccionada e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos en el camino y en las casillas adyacentes.",
  str_skill_desc_303027 = "Se dirige a la ubicación seleccionada, inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos en el camino y en los casillas adyacentes, y luego lanza instan. un Combo en Cadena una vez en la ubicación seleccionada de acuerdo con la distancia recorrida.",
  str_skill_desc_330027 = "Se desplaza a la ubicación seleccionada, lo que inflige un <color=#00F6FF>{1}% </color> de daño y un daño adicional igual al <color=#00F6FF> 5% </color> de su PS actual a los enemigos en el camino y en las casillas adyacentes.",
  str_skill_desc_333027 = "Se desplaza a la ubicación seleccionada, lo que inflige un <color=#00F6FF>{1}% </color> de daño y un daño adicional equivalente al <color=#00F6FF> 5% </color> de su PS actual a los enemigos en el camino y en los casillas adyacentes luego lanza instan. un Combo en cadena una vez en la ubicación seleccionada de acuerdo con la distancia recorrida.",
  str_skill_desc_300060 = "Entra en el estado del mediodía, lo que aumenta el ataque de Jona en un <color=#00F6FF> 10% </color> y el daño de Combo en cadena en un <color=#00F6FF> 30% </color> durante 2 rondas.",
  str_skill_desc_303060 = "Entra en el estado del mediodía, lo que aumenta el ataque de Jona en un <color=#00F6FF> 10% </color> y el daño de Combo en cadena en un <color=#00F6FF> 30% </color> durante 2 rondas.",
  str_skill_desc_306060 = "Entra en el estado del mediodía, lo que aumenta el ataque de Jona en un <color=#00F6FF> 15% </color> y el daño de Combo en cadena en un <color=#00F6FF> 30% </color> durante 2 rondas.",
  str_skill_desc_330060 = "Entra en el estado de mediodía, lo que aumenta el ataque de Jona en un <color=#00F6FF> 10% </color> y el daño Combo en cadena en un <color=#00F6FF> 30% </color>, además de reducir el recuento de casillas de disparo de combo de Aurorians de fuego por <color=#00F6FF> 2 </color> durante 2 rondas.",
  str_skill_desc_333060 = "Entra en el estado de mediodía, lo que aumenta el ataque de Jona en un <color=#00F6FF> 10% </color> y el daño Combo en cadena en un <color=#00F6FF> 30% </color>, además de reducir el recuento de casillas de disparo de combo de Aurorians de fuego por <color=#00F6FF> 2 </color> durante 2 rondas.",
  str_skill_desc_336060 = "Entra en el estado de mediodía, lo que aumenta el ataque de Jona en un <color=#00F6FF> 15% </color> y el daño Combo en cadena en un <color=#00F6FF> 30% </color>, además de reducir el recuento de casillas de disparo de combo de Aurorians de fuego por <color=#00F6FF> 2 </color> durante 2 rondas.",
  str_skill_desc_300064 = "Entra en el estado de Sobrecarga, en el que el daño del Combo en Cadena de Wrath aumenta en <color=#00F6FF>50%</color> e inflige 2 veces daño al enemigo más cercano. Dura por 2 rondas.",
  str_skill_desc_303064 = "Entra en el estado de Sobrecarga, en el que el daño del Combo en Cadena de Wrath aumenta en <color=#00F6FF>50%</color> e inflige 2 veces daño al enemigo más cercano. Dura por 2 rondas.",
  str_skill_desc_306064 = "Entra en el estado de Sobrecarga, en el que el daño del Combo en Cadena de Wrath aumenta en <color=#00F6FF>50%</color> e inflige 2 veces daño al enemigo más cercano. Dura por 2 rondas.",
  str_skill_desc_320064 = "Entra en el estado de Sobrecarga, en el que el daño del Combo en Cadena de Wrath aumenta en <color=#00F6FF>50%</color> e inflige 2 veces daño al enemigo más cercano. Dura por 2 rondas.",
  str_skill_desc_323064 = "Entra en el estado de Sobrecarga, en el que el daño del Combo en Cadena de Wrath aumenta en <color=#00F6FF>50%</color> e inflige 2 veces daño al enemigo más cercano. Dura por 2 rondas.",
  str_skill_desc_326064 = "Entra en el estado de Sobrecarga, en el que el daño del Combo en Cadena de Wrath aumenta en <color=#00F6FF>50%</color> e inflige 2 veces daño al enemigo más cercano. Dura por 2 rondas.",
  str_skill_desc_300070 = "Inflige <color=#00F6FF> 90% </color> de daño <color=#00F6FF> 5 </color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada casilla de Fuego dentro de <color=#00F6FF> 1 cúmulo circundante </color> de la unidad.",
  str_skill_desc_302070 = "Inflige <color=#00F6FF> 90% </color> de daño <color=#00F6FF> 5 </color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada casilla de Fuego dentro de <color=#00F6FF> 1 cúmulo circundante </color> de la unidad.",
  str_skill_desc_305070 = "Inflige <color=#00F6FF>90%</color> de daño <color=#00F6FF>6</color>veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada casilla de Fuego dentro de <color=#00F6FF>12 casillas adyacentes</color>.",
  str_skill_desc_300088 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos. Convierte las fichas en el área de ataque en rojas.",
  str_skill_desc_302088 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos. Convierte las fichas en el área de ataque en rojas.",
  str_skill_desc_305088 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>forma cruzada al rango máximo</color> y derriba a los enemigos. Convierte las fichas en el área de ataque en rojas.",
  str_skill_desc_300084 = "Cuando se usa, el Combo en Cadena de un Aurorian de fuego se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de fuego es igual a <color=#00F6FF>70%</color> del ATQ de Istvan.",
  str_skill_desc_302084 = "Cuando se usa, el Combo en Cadena de un Aurorian de fuego se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de fuego es igual a <color=#00F6FF>70%</color> del ATQ de Istvan.",
  str_skill_desc_305084 = "Cuando se usa, el Combo en Cadena de un Aurorian de fuego se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de fuego es igual a <color=#00F6FF>70%</color> del ATQ de Istvan.",
  str_skill_desc_330084 = "Cuando se usa, el Combo en Cadena de un Aurorian de fuego se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de fuego es igual a <color=#00F6FF>85%</color> del ATQ de Istvan.",
  str_skill_desc_332084 = "Cuando se usa, el Combo en Cadena de un Aurorian de fuego se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de fuego es igual a <color=#00F6FF>85%</color> del ATQ de Istvan.",
  str_skill_desc_335084 = "Cuando se usa, el Combo en Cadena de un Aurorian de fuego se activará <color=#00F6FF>2</color>x en esta ronda. En el <color=#00F6FF>segundo</color> combo, el ATQ de todos los Aurorians de fuego es igual a <color=#00F6FF>85%</color> del ATQ de Istvan.",
  str_skill_desc_300090 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos y aturde a todos los enemigos en las casillas rojas.",
  str_skill_desc_302090 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos y aturde a todos los enemigos en las casillas rojas.",
  str_skill_desc_320090 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos y aturde a todos en las casillas Rojas. Los enemigos de otras casillas tienen un <color=#00F6FF>35%</color> de posibilidad de aturdimiento.",
  str_skill_desc_322090 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos y aturde a todos en las casillas Rojas. Los enemigos de otras casillas tienen un <color=#00F6FF>35%</color> de posibilidad de aturdimiento.",
  str_skill_desc_300045 = "Elige 1 casilla como objetivo, sacrifica <color=#00F6FF>15%</color> de PS actuales para infligir la misma cantidad de daño a los enemigos dentro de <color=#00F6FF>9 casillas cuadradas</color> (este daño ignora DEF) e inflige 1 pila de <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> que dura 2 rondas.",
  str_skill_desc_320045 = "Elige 1 casilla como objetivo, sacrifica el <color=#00F6FF>15%</color> de los PS actuales para infligir la misma cantidad de daño a los enemigos dentro de <color=#00F6FF>9 casillas cuadradas</color> (este daño ignora DEF) e inflige <link=\"30004\"><#FFAE07><u>1 pila</u></color></link> de Sangrado que dura 2 rondas.",
  str_skill_desc_330045 = "Elige 1 casilla como objetivo, sacrifica un <color=#00F6FF>15%</color> del PS actual para infligir una cantidad de daño igual a los enemigos dentro de <color=#00F6FF>9 casillas cuadradas</color> (este daño ignora DEF) e inflige <link=\"30004\"><#FFAE07><u>1 pila</u></color></link> de Sangrado que dura 2 rondas. El PS Máx. básico de Nails aumenta en un <color=#00F6FF>50%</color>.",
  str_skill_desc_300081 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> todos </color> los enemigos y aggros a todos los enemigos de la unidad.",
  str_skill_desc_320081 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos y los atrae hacia la unidad. El daño final aumenta en un <color=#00F6FF>10%</color> por cada casilla en la que avancen los enemigos.",
  str_skill_desc_300083 = "Selecciona 1 casilla, inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 4 casillas en forma de cruz </color> y derriba a los enemigos.",
  str_skill_desc_320083 = "Selecciona 1 casilla, lo que inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color> y derriba a los enemigos.",
  str_skill_desc_330083 = "Selecciona 1 casilla, lo que inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 cúmulo circundante </color> y derriba a los enemigos, además de reducir su DEF en proporción al porcentaje del daño repartido por 2 rondas.",
  str_skill_desc_300059 = "Se mueve a cualquier casilla dentro de <color=#00F6FF> 1 cúmulo circundante </color> alrededor de la unidad.",
  str_skill_desc_3000591 = "Se mueve a cualquier casilla dentro de <color=#00F6FF> 1 cúmulo circundante </color> alrededor de la unidad.",
  str_skill_desc_3000592 = "Se mueve a cualquier casilla dentro de <color=#00F6FF> 2 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_3000593 = "Se mueve a cualquier casilla dentro de <color=#00F6FF> 3 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_3000594 = "Se mueve a cualquier casilla dentro de <color=#00F6FF> 4 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_3000595 = "Se mueve a cualquier casilla dentro de <color=#00F6FF> 5 cúmulos circundantes </color> alrededor de la unidad.",
  str_skill_desc_300080 = "Lanza una lata a cualquier casilla seleccionada, cambiando la casilla a una casilla Amarilla. Un cristal de relámpago, cristal de meteorito, vendaje, ataque o defensa se genera al azar en la casilla.",
  str_skill_desc_320080 = "Lanza una lata a cualquier casilla seleccionada, cambiando la casilla a una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>. En la casilla se genera al azar un Cristal de Relámpago, Cristal de Meteorito, Vendaje, Ataque o Defensa.",
  str_skill_desc_300093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF> 3 cúmulos circundantes </color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF> 1 cúmulo circundante </color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque.",
  str_skill_desc_306093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF> 3 cúmulos circundantes </color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF> 1 cúmulo circundante </color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. Elimina el tiempo de enfriamiento de la Habilidad Activa si el objetivo muere con la habilidad (1x por ronda).",
  str_skill_desc_310093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF> 3 cúmulos circundantes </color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF> 1 cúmulo circundante </color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque.",
  str_skill_desc_316093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF> 3 cúmulos circundantes </color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF> 1 cúmulo circundante </color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. Elimina el tiempo de enfriamiento de la Habilidad Activa si el objetivo muere con la habilidad (1x por ronda).",
  str_skill_desc_320093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF> 3 cúmulos circundantes </color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF> 1 cúmulo circundante </color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. El daño final aumenta en un <color=#00F6FF> 15% </color> por cada enemigo asesinado. Se acumula hasta 10 veces.",
  str_skill_desc_326093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF>3 cúmulos circundantes</color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. El daño final aumenta en un <color=#00F6FF>15%</color> por cada enemigo eliminado. Se acumula hasta 10 veces. Elimina el tiempo de enfriamiento de la Habilidad Activa si se elimina al objetivo con la habilidad (1x por ronda).",
  str_skill_desc_330093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF> 3 cúmulos circundantes </color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF> 1 cúmulo circundante </color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. El daño final aumenta en un <color=#00F6FF> 15% </color> por cada enemigo asesinado. Se acumula hasta 10 veces.",
  str_skill_desc_336093 = "Se teletransporta a cualquier ubicación dentro de <color=#00F6FF>3 cúmulos circundantes</color> e inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. El daño final aumenta en un <color=#00F6FF>15%</color> por cada enemigo eliminado. Se acumula hasta 10 veces. Elimina el tiempo de enfriamiento de la Habilidad Activa si se elimina al objetivo con la habilidad (1x por ronda).",
  str_skill_desc_300097 = "Se teletransporta a cualquier lugar e inflige daño a los enemigos en forma de rectángulo entre el punto de partida y el de destino. Cuanto más pequeño sea el rectángulo, mayor será el daño infligido, hasta un <color=#00F6FF>480%</color> de daño.",
  str_skill_desc_302097 = "Se teletransporta a cualquier lugar e inflige daño a los enemigos en forma de rectángulo entre el punto de partida y el de destino. Cuanto más pequeño sea el rectángulo, mayor será el daño infligido, hasta un <color=#00F6FF>600%</color> de daño.",
  str_skill_desc_300095 = "Selecciona 1 casilla y coloca 1 mina en ella y en <color=#00F6FF> 4 casillas en forma de X </color> adyacentes. Las minas infligen un <color=#00F6FF>190%</color> de daño cada una se activan e infligen 1 pila de<link=\"10001\"><#FFAE07> <u> Veneno </u></color></link> durante 2 rondas.",
  str_skill_desc_320095 = "Selecciona 1 casilla y coloca 1 mina en ella y en las <color=#00F6FF>4 casillas adyacentes en forma de X</color>. Las minas infligen un <color=#00F6FF>190%</color> de daño cada una (el doble para la casilla elegida) cuando se activan e infligen 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas.",
  str_skill_desc_330095 = "Selecciona 1 casilla y coloca 1 mina en ella y en las <color=#00F6FF>4 casillas adyacentes en forma de X</color>. Las minas infligen un <color=#00F6FF>190%</color> de daño cada una (el doble para la casilla elegida) cuando se activan e infligen 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas.",
  str_skill_desc_300062 = "Selecciona una de las casillas más lejanas alrededor de la unidad en todas las <color=#00F6FF>8</color> direcciones y se desplaza a la ubicación seleccionada, lo que inflige un <color=#00F6FF>{1}%</color> de daño a los enemigos en el camino y en casillas adyacentes.",
  str_skill_desc_320062 = "Selecciona una de las casillas en el borde del campo de batalla y se desplaza hacia la ubicación seleccionada, lo que inflige un <color=#00F6FF>{1}% </color> de daño a los enemigos en el camino y en las casillas adyacentes.",
  str_skill_desc_300024 = "Marca 1 casilla. Cuando el número de casillas conectadas llega a <color=#00F6FF>2</color>x el número de casillas necesario para activar un Combo en cadena, lanza el Combo en cadena una vez en la ubicación marcada.",
  str_skill_desc_305024 = "Marca 1 casilla. Cuando el número de casillas conectadas llega a <color=#00F6FF>2</color>x el número de casillas necesario para activar un Combo en cadena, lanza el Combo en cadena una vez en la ubicación marcada.",
  str_skill_desc_320024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcanza <color=#00F6FF>2</color>x el número de casillas necesario para activar un Combo en cadena, lanza el Combo en cadena una vez en la ubicación marcada (aumenta el daño final de ambos Combos en cadena por <color=#00F6FF>30%</color>).",
  str_skill_desc_325024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcanza <color=#00F6FF>2</color>x el número de casillas necesario para activar un Combo en cadena, lanza el Combo en cadena una vez en la ubicación marcada (aumenta el daño final de ambos Combos en cadena por <color=#00F6FF>30%</color>).",
  str_skill_desc_330024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcanza <color=#00F6FF>1.5</color>x el número de casillas necesario para activar un Combo en cadena, lanza el Combo en cadena una vez en la ubicación marcada (aumenta el daño final de ambos Combos en cadena por <color=#00F6FF>30%</color>).",
  str_skill_desc_335024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcanza <color=#00F6FF>1.5</color>x el número de casillas necesario para activar un Combo en cadena, lanza el Combo en cadena una vez en la ubicación marcada (aumenta el daño final de ambos Combos en cadena por <color=#00F6FF>30%</color>).",
  str_skill_desc_300087 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas más cercanas a amarillas.",
  str_skill_desc_302087 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas más cercanas a amarillas. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_305087 = "Convierte las <color=#00F6FF> 5 </color> casillas rojas más cercanas a amarillas. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_330087 = "Convierte <color=#00F6FF>4</color> casillas rojas más cercanas a amarillas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u> </color></link>.",
  str_skill_desc_332087 = "Convierte <color=#00F6FF>4</color> casillas rojas cercanas en amarillas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>. Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_335087 = "Convierte <color=#00F6FF>5</color> casillas rojas cercanas en amarillas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>. Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_3020871 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas más cercanas a amarillas. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3050871 = "Convierte las <color=#00F6FF> 5 </color> casillas rojas más cercanas a amarillas. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3320871 = "Convierte <color=#00F6FF>4</color> casillas rojas cercanas en amarillas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>. Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_3350871 = "Convierte <color=#00F6FF>5</color> casillas rojas cercanas en amarillas y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>. Si la Habilidad Activa estuvo lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_300101 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>2 cúmulos circundantes</color> y reinicia todas las casillas dentro del área de ataque.",
  str_skill_desc_330101 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>2 cúmulos circundantes</color> y restablece todas las casillas <color=#00F6FF>no Amarillas</color> dentro del área de ataque. Existe una <color=#00F6FF>pequeña posibilidad</color> de generar casillas Amarillas.",
  str_skill_desc_300102 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones alrededor de la unidad y arrastra a todos los enemigos en la dirección seleccionada, en las filas y columnas adyacentes a la unidad, infligiendo un <color=#00F6FF>{1}%</color> de daño a los enemigos arrastrados.",
  str_skill_desc_300099 = "Controla una espada mágica, lo que aumenta el ATQ de la unidad en un <color=#00F6FF> 20% </color> en esta ronda. Después de esto, disminuye el ATQ y la DEF en un <color=#00F6FF> 50% </color> durante 1 ronda.",
  str_skill_desc_305099 = "Controla una espada mágica, lo que aumenta el ATQ de la unidad en un <color=#00F6FF> 25% </color> en esta ronda. Después de esto, disminuye el ATQ y la DEF en un <color=#00F6FF> 50% </color> durante 1 ronda.",
  str_skill_desc_330099 = "Controla una espada mágica, aumentando el ATQ de la unidad en un <color=#00F6FF>20%</color> en esta ronda. Después de esto, disminuye el ATQ y la DEF en un <color=#00F6FF>50%</color> durante 1 ronda. La unidad es inmune a los efectos de estado que disminuyen el ATQ y la DEF mientras controla la espada mágica para matar enemigos.",
  str_skill_desc_335099 = "Controla una espada mágica, aumentando el ATQ de la unidad en un <color=#00F6FF>25%</color> en esta ronda. Después de esto, disminuye el ATQ y la DEF en un <color=#00F6FF>50%</color> durante 1 ronda. La unidad es inmune a los efectos de estado que disminuyen el ATQ y la DEF mientras controla la espada mágica para matar enemigos.",
  str_skill_desc_300100 = "ofertas <color=#00F6FF>{1}%</color> daño a una forma de cruz al alcance máximo y empuja a los enemigos hacia atrás. Convierte las fichas del área de ataque en verdes.",
  str_skill_desc_302100 = "ofertas <color=#00F6FF>{1}%</color> daño en forma de cruz al alcance máximo y empuja a los enemigos hacia atrás. Convierte las fichas del área de ataque en verdes.",
  str_skill_desc_300098 = "Selecciona 1 enemigo dentro de <color=#00F6FF> 3 cúmulos circundantes </color> y le inflige un <color=#00F6FF>{1}% </color> de daño. Si el enemigo ocupa una sola casilla y puede ser derribado, la mueve a la posición seleccionada dentro del alcance de ataque.",
  str_skill_desc_305098 = "Selecciona 1 enemigo y le inflige un <color=#00F6FF>{1}% </color> de daño. Si el enemigo ocupa un solo casilla y puede ser derribado, la mueve a la posición seleccionada dentro del alcance de ataque.",
  str_skill_desc_330098 = "Selecciona 1 enemigo dentro de <color=#00F6FF>3 cúmulos circundantes</color> e inflige <color=#00F6FF>{1}% </color> de daño. Si el enemigo ocupa una sola casilla y puede ser derribado, lo mueve a la posición seleccionada dentro del rango de ataque. Si un objetivo que tiene una marca muere, inflige un daño equivalente al <color=#00F6FF>40%</color> del ATQ de Cuscuta a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color> (este daño ignora la DEF ).",
  str_skill_desc_335098 = "Selecciona 1 enemigo y le inflige un <color=#00F6FF>{1}%</color> de daño. Si el enemigo ocupa una sola casilla y puede ser derribado, lo mueve a la posición seleccionada, dentro del rango de ataque. Si un objetivo que tiene una marca muere, inflige un daño de <color=#00F6FF>40%</color> del ATQ de Cuscuta a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color> (este daño ignora la DEF).",
  str_skill_desc_300094 = "Registra la ubicación actual. La unidad regresa a la ubicación registrada después moverse o lanzar un Combo en Cadena Aurorian.",
  str_skill_desc_300096 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas o verdes más cercanas en azul.",
  str_skill_desc_303096 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas o verdes más cercanas en azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_306096 = "Convierte las <color=#00F6FF> 5 </color> casillas rojas o verdes más cercanas en azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_330096 = "Convierte las <color=#00F6FF>4</color> casillas Roja o Verde más cercanas a Azul y tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_333096 = "Convierte el <color=#00F6FF>4</color> casillas seleccionadas rojas o Verde más cercanas a azul (tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u> casillas seleccionadas mejoradas </u></color></link>.) Si la Habilidad Activa está lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_336096 = "Convierte el <color=#00F6FF>5</color> casillas seleccionadas rojas o Verde más cercanas a azul (tiene la posibilidad de generar hasta 2 <link=\"20001\"><#FFAE07><u> casillas seleccionadas mejoradas </u></color></link>.) Si la Habilidad Activa está lista en la ronda anterior, la conversión de casillas cuenta <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_3030961 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas o verdes más cercanas en azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3060961 = "Convierte las <color=#00F6FF> 5 </color> casillas rojas o verdes más cercanas en azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3330961 = "Convierte las <color=#00F6FF> 4 </color> casillas rojas o verdes más cercanas en azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3360961 = "Convierte las <color=#00F6FF> 5 </color> casillas rojas o verdes más cercanas en azul. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_300056 = "Inflige un <color=#00F6FF>{1}% </color> de daño a 1 enemigo dentro de <color=#00F6FF> 3 cúmulos circundantes </color>.",
  str_skill_desc_320056 = "Inflige <color=#00F6FF>{1}% </color> de daño a 1 enemigo de <color=#00F6FF> todos </color> enemigos en la pantalla.",
  str_skill_desc_300103 = "Convierte las <color=#00F6FF> 4 </color> casillas azules o verdes más cercanas a rojas.",
  str_skill_desc_303103 = "Convierte las <color=#00F6FF> 4 </color> casillas azules o verdes más cercanas en rojas. Si la Habilidad Activa estuvo lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_306103 = "Convierte las <color=#00F6FF> 5 </color> casillas azules o verdes más cercanas en rojas. Si la Habilidad Activa estuvo lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3031031 = "Convierte las <color=#00F6FF> 4 </color> casillas azules o verdes más cercanas en rojas. Si la Habilidad Activa estuvo lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_3061031 = "Convierte las <color=#00F6FF> 5 </color> casillas azules o verdes más cercanas en rojas. Si la Habilidad Activa estuvo lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF> +1 </color> en esta ronda.",
  str_skill_desc_300067 = "Disminuye el siguiente daño recibido en esta ronda en un <color=#00F6FF> 30% </color>, hasta <color=#00F6FF> 2 </color> x el PS máximo de Alice.",
  str_skill_desc_304067 = "Disminuye el siguiente daño recibido en esta ronda en un <color=#00F6FF> 40% </color>, hasta <color=#00F6FF> 2 </color> x el PS máximo de Alice.",
  str_skill_desc_320067 = "Disminuye el siguiente daño recibido en esta ronda en un <color=#00F6FF>30%</color> y recupera inmediatamente un <color=#00F6FF>10%</color> del PS perdido por el equipo al recibir daño. La reducción y el PS recuperado no pueden exceder <color=#00F6FF>2</color> x el PS máximo de Alice.",
  str_skill_desc_324067 = "Disminuye el siguiente daño recibido en esta ronda en un <color=#00F6FF>40%</color> y recupera inmediatamente un <color=#00F6FF>10%</color> del PS perdido por el equipo al recibir daño. La reducción y el PS recuperado no pueden exceder <color=#00F6FF>2</color> x el PS máximo de Alice.",
  str_skill_desc_300104 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos.",
  str_skill_desc_310104 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos.",
  str_skill_desc_320104 = "Inflige <color=#00F6FF>{1}%</color> de daño a todos los enemigos. Si el número de enemigos golpeados es 2 o menos, la habilidad se lanzará 1 vez más en esta ronda.",
  str_skill_desc_300030 = "Selecciona 1 casilla de las <color=#00F6FF> 4 casillas en forma de cruz </color> e inflige un <color=#00F6FF>{1}% </color> de daño en un área de abanico en esta dirección .(cuanto más cerca esté el enemigo, mayor será el daño. Puede infligir hasta 2.5x daño).",
  str_skill_desc_306030 = "Selecciona 1 casilla de las <color=#00F6FF> 4 casillas en forma de cruz </color> e inflige un <color=#00F6FF>{1}% </color> de daño en un área de abanico en esta dirección .(cuanto más cerca esté el enemigo, mayor será el daño. Puede infligir hasta 2.5x daño).",
  str_skill_desc_320030 = "Selecciona 1 casilla de las <color=#00F6FF> 8 casillas en forma de cruz </color> e inflige un <color=#00F6FF>{1}% </color> de daño en un área de abanico en esta dirección (cuanto más cerca esté el enemigo de Sinsa, mayor será el daño. Puede infligir hasta 2.5x daño). Si una casilla exterior es seleccionada, Sinsa avanzará 1 casilla para lanzar esta habilidad.",
  str_skill_desc_326030 = "Selecciona 1 de las <color=#00F6FF>8 casillas circundantes en forma de cruz</color> e inflige <color=#00F6FF>{1}%</color> de daño en un área en forma de abanico en esta dirección (entre más cerca esté el enemigo de Sinsa, mayor es el daño. Puede infligir hasta 3x) daño. Si se selecciona una casilla no adyacente, Sinsa avanzará 1 casilla para lanzar esta habilidad.",
  str_skill_desc_330030 = "Selecciona 1 casilla de las <color=#00F6FF> 8 casillas en forma de cruz </color> e inflige un <color=#00F6FF>{1}% </color> de daño en un área de abanico en esta dirección (cuanto más cerca esté el enemigo de Sinsa, mayor será el daño. Puede infligir hasta 2.5x daño). Si una casilla exterior es seleccionada, Sinsa avanzará 1 casilla para lanzar esta habilidad.",
  str_skill_desc_336030 = "Selecciona 1 de las <color=#00F6FF>8 casillas circundantes en forma de cruz</color> e inflige <color=#00F6FF>{1}%</color> de daño en un área en forma de abanico en esta dirección (entre más cerca esté el enemigo de Sinsa, mayor es el daño. Puede infligir hasta 3x) daño. Si se selecciona una casilla no adyacente, Sinsa avanzará 1 casilla para lanzar esta habilidad.",
  str_skill_desc_300071 = "Selecciona cualquier mosaico en un <color=#00F6FF>forma de cruz</color>, convierte esta loseta en una loseta roja mejorada y lanza Dragonscorch para tratar <color=#00F6FF>{1}%</color> daños a las baldosas en el camino. Después de llegar a la casilla seleccionada, Dragonscorch se extiende a la <color=#00F6FF>lado izquierdo y derecho</color> de esta loseta a la distancia máxima, infligiendo un 80% de daño.",
  str_skill_desc_305071 = "Selecciona cualquier mosaico en un <color=#00F6FF>forma de cruz</color>, convierte esta loseta en una loseta roja mejorada y lanza Dragonscorch para tratar <color=#00F6FF>{1}%</color> daños a las baldosas en el camino. Después de llegar a la casilla seleccionada, Dragonscorch se extiende a la <color=#00F6FF>lado izquierdo y derecho</color> de esta loseta a la distancia máxima, infligiendo un 80% de daño y convirtiendo la loseta más alejada de cada lado en una loseta roja.",
  str_skill_desc_320071 = "Selecciona cualquier mosaico en un <color=#00F6FF>forma de cruz</color>, convierte esta loseta en una loseta roja mejorada y lanza Dragonscorch para tratar <color=#00F6FF>{1}%</color> daños a las baldosas en el camino. Después de llegar a la casilla seleccionada, Dragonscorch se extiende a la <color=#00F6FF>lado izquierdo y derecho</color> de esta loseta a la distancia máxima, infligiendo un 80% de daño. Dragonscorch inflige al objetivo una marca de quemadura antes de infligir daño.",
  str_skill_desc_325071 = "Selecciona cualquier mosaico en un <color=#00F6FF>forma de cruz</color>, convierte esta loseta en una loseta roja mejorada y lanza Dragonscorch para tratar <color=#00F6FF>{1}%</color> daños a las baldosas en el camino. Después de llegar a la casilla seleccionada, Dragonscorch se extiende a la <color=#00F6FF>lado izquierdo y derecho</color> de esta loseta a la distancia máxima, infligiendo un 80% de daño y convirtiendo la loseta más alejada de cada lado en una loseta roja. Dragonscorch inflige al objetivo una marca de quemadura antes de infligir daño.",
  str_skill_desc_300105 = "Selecciona 1 casilla donde se encuentra un enemigo y le inflige un <color=#00F6FF>40%</color> de daño 20 veces al enemigo. Selecciona un nuevo objetivo después de eliminar al enemigo actual. La Habilidad Activa inflige daño 1 vez adicional por cada casilla Amarilla dentro de <color=#00F6FF>1 grupo circundante</color> de tu localización actual.",
  str_skill_desc_306105 = "Selecciona 1 casilla donde se encuentra un enemigo y le inflige un <color=#00F6FF>40%</color> de daño 20 veces al enemigo. Selecciona un nuevo objetivo después de eliminar al enemigo actual. La Habilidad Activa inflige daño 1 vez adicional por cada casilla Amarilla dentro de <color=#00F6FF>2 grupos cercanos</color> a tu localización actual.",
  str_skill_desc_330105 = "Selecciona 1 casilla donde se encuentra un enemigo y causa <color=#00F6FF>40%</color> de daño 20 veces al enemigo, con el factor de daño aumentando en <color=#00F6FF>0.8%</color> cada vez. Selecciona de nuevo un objetivo después de eliminar al enemigo actual. El objetivo final de tu ataque tiene su DEF reducida en un 10% durante 1 ronda. La Habilidad Activa causa daño 1 vez adicional por cada casilla Amarilla dentro de <color=#00F6FF>1 grupo circundante</color> de tu localización actual.",
  str_skill_desc_336105 = "Selecciona 1 casilla donde se encuentra un enemigo y le inflige un <color=#00F6FF>40%</color> de daño 20 veces, aumentando el factor de daño en <color=#00F6FF>0.8%</color> cada vez. Selecciona otro objetivo después de eliminar al enemigo actual. El objetivo final de tu ataque tiene su DEF reducida en un 10% durante 1 ronda. La Habilidad Activa inflige daño 1 vez adicional por cada casilla Amarilla dentro de <color=#00F6FF>2 grupos circundantes</color> a tu localización actual.",
  str_skill_desc_330109 = "Cuesta <color=#00F6FF>10</color> Vis y elimina el Vis restante para infligir <color=#00F6FF><color=#00F6FF>150%</color> </color> de daño a todos los enemigos en la dirección elegida y sus casillas adyacentes. El daño final aumenta en <color=#00F6FF>8%</color> por cada 1 Vis eliminado.",
  str_skill_desc_330110 = "Cuesta <color=#00F6FF> 10 </color> Vis y borra el Vis restante para infligir<color=#00F6FF>150% </color> de daño a todos los enemigos. El daño aumenta en <color=#00F6FF> 15% </color> por cada 1 Vis eliminado.",
  str_skill_desc_336110 = "Cuesta <color=#00F6FF>10</color> Vis y elimina el Vis restante para infligir <color=#00F6FF>150%</color> de daño a todos los enemigos. Por cada 1 Vis eliminado, el daño aumenta en un <color=#00F6FF>15%</color> e ignora <color=#00F6FF>1%</color> de la defensa.",
  str_skill_desc_330107 = "Cuesta <color=#00F6FF> 10 </color> Vis para ingresar a un estado aumenta en esta ronda: Los ataques normales se pueden lanzar en diagonal y aumenta el ataque normal y el daño combinado en cadena en un <color=#00F6FF> 20% </color> (se pueden acumular cuando se usan más de una vez).",
  str_skill_desc_333107 = "Cuesta <color=#00F6FF>10</color> Vis para ingresar a un estado aumentado en esta ronda: Los ataques normales se pueden lanzar en diagonal y aumenta el daño de los ataques normales y de los Combo en Cadena en <color=#00F6FF>20%</color> (se pueden acumular cuando se usa más de una vez). Gana 2 Vis por cada 1 enemigo eliminado durante el estado aumentado.",
  str_skill_desc_336107 = "Cuesta <color=#00F6FF>10</color> Vis para ingresar a un estado aumentado en esta ronda: Los ataques normales se pueden lanzar en diagonal y aumenta el daño de los ataques normales y de los Combo en Cadena en <color=#00F6FF>20%</color> (se pueden acumular cuando se usa más de una vez). Gana 2 Vis por cada 1 enemigo eliminado durante el estado aumentado.",
  str_skill_desc_330108 = "Cuesta <color=#00F6FF> 10 </color> Vis para infligir un <color=#00F6FF>{1}% </color> de daño a 1 casilla seleccionada e inflige un 50% <link=\"30015\"> <#FFAE07> <u> daño de salpicadura </u></color></link> a <color=#00F6FF> 4 casillas en forma de cruz </color> a su alrededor. Se puede lanzar varias veces en cada ronda.",
  str_skill_desc_333108 = "Cuesta <color=#00F6FF> 10 </color> Vis para infligir un <color=#00F6FF>{1}% </color> de daño a 1 casilla seleccionada e inflige un 50% <link=\"30015\"> <#FFAE07> <u> daño de salpicadura </u></color></link> a <color=#00F6FF> 4 casillas en forma de cruz </color> a su alrededor. Se puede lanzar varias veces en cada ronda.",
  str_skill_desc_336108 = "Costos <color=#00F6FF>10</color> Vis para tratar <color=#00F6FF>{1}%</color> daño a 1 mosaico seleccionado, y causa 50% <link=\"30015\"><#FFAE07><u>Chapoteo</u></color></link> daño a <color=#00F6FF>4 fichas en forma de cruz</color> alrededor. Cada lanzamiento aumenta el ATK básico en <color=#00F6FF>3%</color>. Se puede lanzar varias veces en cada ronda.",
  str_skill_desc_300112 = "Se teletransporta a cualquier mosaico dentro <color=#00F6FF>3 grupos circundantes</color>, tratar <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación de destino, y restablece todos </color>no rojo<color=#00F6FF> fichas dentro del área de ataque.",
  str_skill_desc_301112 = "Se teletransporta a cualquier casilla, infligiendo un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 2 cúmulos circundantes </color> de la ubicación del objetivo, y restablece todas las casillas <color=#00F6FF> que no sean rojas </color> dentro del área de ataque.",
  str_skill_desc_303112 = "Se teletransporta a cualquier mosaico, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación objetivo, y restablece todos </color>los mosaicos no rojos<color=#00F6FF> dentro del área de ataque. Convierte 1 o más mosaicos enemigos en mosaicos rojos.",
  str_skill_desc_320112 = "Se teletransporta a cualquier mosaico dentro <color=#00F6FF>3 grupos circundantes</color>, tratar <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación de destino, y restablece todos </color>no rojo<color=#00F6FF> fichas dentro del área de ataque.",
  str_skill_desc_321112 = "Se teletransporta a cualquier casilla, infligiendo un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 2 cúmulos circundantes </color> de la ubicación del objetivo, y restablece todas las casillas <color=#00F6FF> que no sean rojas </color> dentro del área de ataque.",
  str_skill_desc_323112 = "Se teletransporta a cualquier mosaico, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación objetivo, y restablece todos </color>los mosaicos no rojos<color=#00F6FF> dentro del área de ataque. Convierte 1 o más mosaicos enemigos en mosaicos rojos.",
  str_skill_desc_330112 = "Se teletransporta a cualquier mosaico dentro <color=#00F6FF>3 grupos circundantes</color>, trato <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación de destino, y restablece todos </color>no rojo<color=#00F6FF> fichas dentro del área de ataque. Después de activar <color=#00F6FF>Beso de Mantícora</color>, se borran las acumulaciones de Marca de Manticora del objetivo.",
  str_skill_desc_331112 = "Se teletransporta a cualquier mosaico, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación objetivo, y restablece todos </color>los mosaicos no rojos<color=#00F6FF> dentro del área de ataque. Después de activar <color=#00F6FF>El Beso de la Mánticora</color>, se borran las acumulaciones de la Marca de la Mánticora del objetivo.",
  str_skill_desc_333112 = "Se teletransporta a cualquier mosaico, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>2 grupos circundantes</color> de la ubicación objetivo, y restablece todos </color>los mosaicos no rojos<color=#00F6FF> dentro del área de ataque. Después de activar <color=#00F6FF>Beso de Mantícora</color>, las Marcas de Mantícora del objetivo se borran. Al menos 1 mosaico enemigo se convertirá en rojo.",
  str_skill_desc_300113 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones alrededor de la unidad y desplaza a todos los enemigos no jefes que ocupan una sola casilla en la dirección seleccionada, mientras infligen un <color=#00F6FF>{1}%</color> de daño a todos los enemigos en el tablero.",
  str_skill_desc_305113 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones alrededor de la unidad y desplaza a todos los enemigos no jefes que ocupan una sola casilla en la dirección seleccionada, mientras infligen un <color=#00F6FF>{1}%</color> de daño a todos los enemigos en el tablero.",
  str_skill_desc_330113 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones alrededor de la unidad y desplaza a todos los enemigos no jefes que ocupan una sola casilla en la dirección seleccionada, mientras infligen un <color=#00F6FF>{1}%</color> de daño a todos los enemigos en el tablero. Si el número de enemigos alcanzados es 2 o menos, esta habilidad se lanzará 1 vez más esta ronda.",
  str_skill_desc_335113 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones alrededor de la unidad y desplaza a todos los enemigos no jefes que ocupan una sola casilla en la dirección seleccionada, mientras infligen un <color=#00F6FF>{1}%</color> de daño a todos los enemigos en el tablero. Si el número de enemigos alcanzados es 2 o menos, esta habilidad se lanzará 1 vez más esta ronda.",
  str_skill_desc_300114 = "Se teletransporta a cualquier ubicación en forma de L desde su posición actual (1 casilla horizontal y 2 casillas en vertical o 1 casilla vertical y 2 casillas en horizontal), infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> de su ubicación objetivo.",
  str_skill_desc_302114 = "Se teletransporta a cualquier ubicación en forma de L desde su posición actual (1 casilla horizontal y 2 casillas en vertical o 1 casilla vertical y 2 casillas en horizontal), infligiendo <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>1 cúmulo circundante</color> de su ubicación objetivo. Después de usar una Habilidad Activa, los Combos en Cadena son efectivos contra a todos los enemigos dentro del alcance de esta ronda.",
  str_skill_desc_305114 = "Se teletransporta a cualquier ubicación en forma de L desde su posición actual (1 casilla horizontal y 2 casillas en vertical o 1 casilla vertical y 2 casillas en horizontal), infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> de su ubicación objetivo. Después de usar una Habilidad Activa, los Combos en Cadena son efectivos contra a todos los enemigos dentro del alcance de esta ronda. Cuando se golpea solo a 1 enemigo, esta habilidad puede lanzarse 1 vez más en esta ronda.",
  str_skill_desc_320114 = "Se teletransporta a cualquier ubicación en forma de L desde su posición actual (1 casilla horizontal y 2 casillas en vertical o 1 casilla vertical y 2 casillas en horizontal), infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> de su ubicación objetivo. Después de usar una Habilidad Activa, los Combos en Cadena aumenta en 1 cúmulo en esta ronda.",
  str_skill_desc_322114 = "Se teletransporta a cualquier ubicación en forma de L desde su posición actual (1 casilla horizontal y 2 casillas en vertical o 1 casilla vertical y 2 casillas en horizontal), infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> de su ubicación objetivo. Después de usar una Habilidad Activa, el alcance del Combo en Cadena aumenta 1 cúmulo esta ronda, y los Combos en Cadena son efectivos contra a todos los enemigos dentro del alcance.",
  str_skill_desc_325114 = "Se teletransporta a cualquier ubicación en forma de L desde su posición actual (1 casilla horizontal y 2 casillas en vertical o 1 casilla vertical y 2 casillas en horizontal), infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> de su ubicación objetivo. Después de usar una Habilidad Activa, los Combos en Cadena son efectivos contra a todos los enemigos dentro del alcance. Cuando se golpea solo a 1 enemigo, esta habilidad puede lanzarse 1 vez más en esta ronda.",
  str_skill_desc_300127 = "Selecciona 1 casilla (incluidos las casillas abisales) y coloca 1 grulla de papel sobre ella mientras la convierte en verde. Esta grulla de Papel desaparecerá tras el paso de los compañeros de equipo.",
  str_skill_desc_304127 = "Selecciona 1 casilla (incluidas las casillas abisales) y coloca 1 Grulla de Papel sobre ella, conviertendola en una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>. Cuando los compañeros de equipo pasen por la Grulla de Papel, esta desaparecerá.",
  str_skill_desc_320127 = "Selecciona 1 casilla (incluidos las casillas abisales) y coloca 1 grulla de papel sobre ella mientras la convierte en verde. Esta grulla de Papel desaparecerá tras el paso de los compañeros de equipo, y convertirá la casilla que no es Abisal debajo de ella en Verde.",
  str_skill_desc_324127 = "Selecciona 1 casilla (incluidos las casillas abisales) y coloca 1 grulla de papel sobre ella mientras la convierte en una casilla mejorada <link=\"20001\"><#FFAE07><u> verde</u></color></link>. Esta grulla de Papel desaparecerá tras el paso de los compañeros de equipo, y convertirá la casilla que no es Abisal debajo de ella en Verde.",
  str_skill_desc_300117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de su ubicación objetivo.",
  str_skill_desc_303117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de su ubicación objetivo.",
  str_skill_desc_306117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo. Si la Habilidad Activa estaba lista en la última ronda, el alcance del teletransporte en esta ronda pasa a ser <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_3061171 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo. Si la Habilidad Activa estaba lista en la última ronda, el alcance del teletransporte en esta ronda pasa a ser <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_320117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo. Inflige 1.5× de daño al grupo exterior.",
  str_skill_desc_323117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo. Inflige 1.5× de daño al grupo exterior.",
  str_skill_desc_326117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo, que inflige 1.5× de daño al grupo exterior. Si la Habilidad Activa estaba lista en la última ronda, el alcance del teletransporte en esta ronda pasa a ser <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_3261171 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo, que inflige 1.5× de daño al grupo exterior. Si la Habilidad Activa estaba lista en la última ronda, el alcance del teletransporte en esta ronda pasa a ser <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_330117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo. Inflige 1.5× de daño al grupo exterior.",
  str_skill_desc_333117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo. Inflige 1.5× de daño al grupo exterior.",
  str_skill_desc_336117 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo, que inflige 1.5× de daño al grupo exterior. Si la Habilidad Activa estaba lista en la última ronda, el alcance del teletransporte en esta ronda pasa a ser <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_3361171 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>12 casillas circundantes en forma de diamante</color>, infligiendo <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>20 casillas circundantes</color> de la ubicación objetivo, que inflige 1.5× de daño al grupo exterior. Si la Habilidad Activa estaba lista en la última ronda, el alcance del teletransporte en esta ronda pasa a ser <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_300119 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones alrededor de la unidad y lanza 3 ondas de trueno hacia adelante en un rango de 3 columnas, infligiendo <color=#00F6FF>250%</color> de daño. Después de que cada onda de trueno golpee a un objetivo, el daño de las siguientes ondas de trueno se reduce en un <color=#00F6FF>40%</color>. Puede golpear hasta <color=#00F6FF>3</color> veces.",
  str_skill_desc_306119 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones alrededor de la unidad y lanza 3 ondas de trueno hacia adelante en un rango de 3 columnas, infligiendo <color=#00F6FF>250%</color> de daño. Después de que cada onda de trueno golpee a un objetivo, el daño de las siguientes ondas de trueno se reduce en un <color=#00F6FF>20%</color>. Puede golpear hasta <color=#00F6FF>5</color> veces.",
  str_skill_desc_300122 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 17 casillas en forma de Radial </color> centrado en 1 casilla seleccionada.",
  str_skill_desc_305122 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>17 casillas en forma de radial</color> centrado en 1 casilla seleccionada. Completado <color=#00F6FF>casillas dañadas</color> efectos de las casillas en este espacio.",
  str_skill_desc_320122 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>17 casillas en forma de Radial </color> centrado en 1 casilla seleccionada. El daño en la casilla seleccionada ignora DEF.",
  str_skill_desc_325122 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>17 casillas en forma de radial</color> centrado en 1 casilla seleccionada ignora DEF. Completado <color=#00F6FF>casillas dañadas</color> efectos de las casillas en este espacio.",
  str_skill_desc_330122 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>17 casillas en forma radial</color> centradas en 1 casilla seleccionada. El daño infligido a la casilla seleccionada ignora la DEF. Cuando Bendición llega a 10 pilas, el alcance de la Habilidad Activa se convierte en el <color=#00F6FF>máximo espacio en forma radial</color>.",
  str_skill_desc_3301221 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>17 casillas en forma radial</color> centradas en 1 casilla seleccionada. El daño infligido a la casilla seleccionada ignora la DEF. Cuando Bendición llega a 10 pilas, el alcance de la Habilidad Activa se convierte en el <color=#00F6FF>máximo espacio en forma radial</color>.",
  str_skill_desc_335122 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>17 casillas en forma radial</color> centradas en 1 casilla seleccionada. El daño infligido a la casilla seleccionada ignora la DEF. Elimina los efectos de <color=#00F6FF>casilla dañada</color> de las casillas en este tramo. Cuando Bendición llega a 10 pilas, el alcance de la Habilidad Activa se convierte en el <color=#00F6FF>máximo espacio en forma radial</color>.",
  str_skill_desc_300121 = "Selecciona 1 casilla, luego, con esta casilla como centro, selecciona 1 dirección en la que extender una enredadera que se arrastra hasta el borde del campo de batalla e inflige <color=#00F6FF>360%</color>de daño dentro de este rango, mientras convierte <color=#00F6FF>2</color> casillas al frente a <link=\"20001\"><#FFAE07><u>Casillas Mejoradas</u></color></link>. Por cada casilla que atraviesa la enredadera, el daño aumenta en un <color=#00F6FF>10%</color>.",
  str_skill_desc_306121 = "Selecciona 1 casilla, luego, con esta casilla como centro, selecciona 1 dirección en la que extender una enredadera que se arrastra hasta el borde del campo de batalla e inflige <color=#00F6FF>360%</color>de daño dentro de este rango, mientras convierte <color=#00F6FF>3</color> casillas al frente a <link=\"20001\"><#FFAE07><u>Casillas Mejoradas</u></color></link>. Por cada casilla que atraviesa la enredadera, el daño aumenta en un <color=#00F6FF>15%</color>.",
  str_skill_desc_320121 = "Selecciona 1 casilla, luego, con esta casilla como centro, selecciona 1 dirección en la que extender una enredadera que se arrastra hasta el borde del campo de batalla e inflige <color=#00F6FF>360%</color> de daño dentro de este rango, mientras convierte <color=#00F6FF>2</color> casillas frontales en <link=\"20001\"><#FFAE07><u>Casillas Mejoradas</u></color></link>. Las enredaderas extienden <color=#00F6FF>3</color> casillas en forma de cruz después de infligir daño. Este efecto de extensión puede activarse solo 1 vez por cada enemigo golpeado. Por cada casilla que atraviesa la enredadera, el daño aumenta en un <color=#00F6FF>10%</color>.",
  str_skill_desc_326121 = "Selecciona 1 casilla, luego, con esta casilla como centro, selecciona 1 dirección en la que extender una enredadera que se arrastra hasta el borde del campo de batalla e inflige <color=#00F6FF>360%</color> de daño dentro de este rango, mientras convierte <color=#00F6FF>3</color> casillas frontales en <link=\"20001\"><#FFAE07><u>Casillas Mejoradas</u></color></link>. Las enredaderas extienden <color=#00F6FF>3</color> casillas en forma de cruz después de infligir daño. Este efecto de extensión puede activarse solo 1 vez por cada enemigo golpeado. Por cada casilla que atraviesa la enredadera, el daño aumenta en un <color=#00F6FF>15%</color>.",
  str_skill_desc_300065 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF> 2 cúmulos circundantes </color> o cualquier casilla Azul en el campo de batalla.",
  str_skill_desc_330065 = "Se teletransporta a cualquier casilla dentro de <color=#00F6FF>2 cúmulos circundantes</color> o cualquier casilla Azul en el campo de batalla. Puede lanzar 1 vez más después de entrar en Hora de Aurora por tiempo.",
  str_skill_desc_300115 = "Se teletransporta a una ubicación seleccionada y <link=\"30020\"><#FFAE07><u>purifica</u></color></link> casillas dentro de <color=#00F6FF>2 cúmulos circundantes</color>. Hasta <color=#00F6FF>3</color> casillas dentro del rango de purificación se convierten en <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_305115 = "Se teletransporta a una ubicación seleccionada y <link=\"30020\"><#FFAE07><u>purifica</u></color></link> casillas dentro de <color=#00F6FF>2 cúmulos circundantes</color>. Hasta <color=#00F6FF>4</color> casillas dentro del rango de purificación se convierten en <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_320115 = "Se teletransporta a una ubicación seleccionada y <link=\"30020\"><#FFAE07><u>purifica</u></color></link> casillas dentro de <color=#00F6FF>3 cúmulos circundantes</color>. Hasta <color=#00F6FF>4</color> casillas dentro del rango de purificación se convierten en <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_325115 = "Se teletransporta a una ubicación seleccionada y <link=\"30020\"><#FFAE07><u>purifica</u></color></link> casillas dentro de <color=#00F6FF>3 cúmulos circundantes</color>. Hasta <color=#00F6FF>5</color> casillas dentro del rango de purificación se convierten en <link=\"20001\"><#FFAE07><u>casillas mejoradas</u></color></link>.",
  str_skill_desc_300126 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>5 casillas en forma cruzados</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_303126 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>5 casillas en forma cruzados</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_306126 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color> centradas en 1 casilla transitable seleccionada. Puede lanzarse 1 vez más después de entrar en Hora de Aurora (puede activarse 1 vez por oleada).",
  str_skill_desc_310126 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>5 casillas en forma cruzados</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_313126 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>5 casillas en forma cruzados</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_316126 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color> centradas en 1 casilla transitable seleccionada. Puede lanzarse 1 vez más después de entrar en Hora de Aurora (puede activarse 1 vez por oleada).",
  str_skill_desc_320126 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>5 casillas en forma cruzados</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_323126 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>5 casillas en forma cruzados</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_326126 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color> centradas en 1 casilla transitable seleccionada. Puede lanzarse 1 vez más después de entrar en Hora de Aurora (puede activarse 1 vez por oleada).",
  str_skill_desc_300129 = "Consume todos los <link=\"30021\"><#FFAE07><u>Scions</u></color></link> para causar daño a 1 enemigo. Cada <link=\"30021\"><#FFAE07><u>Scion</u></color></link> causa <color=#00F6FF>40%</color> de daño.",
  str_skill_desc_303129 = "Consume todos los <link=\"30022\"><#FFAE07><u>Scions</u></color></link> para causar daño a 1 enemigo. Cada <link=\"30022\"><#FFAE07><u>Scion</u></color></link> causa <color=#00F6FF>50%</color> de daño.",
  str_skill_desc_306129 = "Consume todos los <link=\"30023\"><#FFAE07><u>Scions</u></color></link> para causar daño a 1 enemigo. Cada <link=\"30023\"><#FFAE07><u>Scion</u></color></link> causa <color=#00F6FF>50%</color> de daño.",
  str_skill_desc_300055 = "Ataca en cualquier 1 dirección seleccionada, causando <color=#00F6FF>160%</color> de daño a todos los enemigos en esta dirección y haciéndolos retroceder.",
  str_skill_desc_302055 = "Ataca en cualquier 1 dirección seleccionada, inflige <color=#00F6FF>160%</color> de daño a todos los enemigos en esta dirección y los derriba. Si tu Habilidad Activa estaba lista en la ronda anterior, el daño final de esta ronda aumenta en un <color=#00F6FF>60%</color>.",
  str_skill_desc_3020551 = "Ataca en cualquier 1 dirección seleccionada, inflige <color=#00F6FF>160%</color> de daño a todos los enemigos en esta dirección y los derriba. Si tu Habilidad Activa estaba lista en la ronda anterior, el daño final de esta ronda aumenta en un <color=#00F6FF>60%</color>.",
  str_skill_desc_305055 = "Ataca en cualquier dirección seleccionada, inflige <color=#00F6FF>160%</color> de daño a todos los enemigos en esta dirección y los derriba. Por cada <color=#00F6FF>1</color> casilla de los enemigos son derribados, el daño final aumenta en un <color=#00F6FF>5%</color>. Si tu Habilidad Activa estaba lista en la ronda anterior, el daño final de esta ronda aumenta en un <color=#00F6FF>60%</color>.",
  str_skill_desc_3050551 = "Ataca en cualquier dirección seleccionada, inflige <color=#00F6FF>160%</color> de daño a todos los enemigos en esta dirección y los derriba. Por cada <color=#00F6FF>1</color> casilla de los enemigos son derribados, el daño final aumenta en un <color=#00F6FF>5%</color>. Si tu Habilidad Activa estaba lista en la ronda anterior, el daño final de esta ronda aumenta en un <color=#00F6FF>60%</color>.",
  str_skill_desc_300120 = "Se teletransporta a una ubicación seleccionada. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 columna</color> y derriba a los enemigos. Convierte casillas en el área de ataque en verde.",
  str_skill_desc_16012001 = "Inflige una pequeña cantidad de daño en 1 columna y repele a los enemigos. Convierte las fichas dentro del área de ataque en verdes.",
  str_skill_desc_16012002 = "Derriba 1 columna de enemigos dentro de un área específica. Convierte las fichas del área de ataque en verdes.",
  str_skill_desc_303120 = "Se teletransporta a una ubicación seleccionada. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 columna</color> y derriba a los enemigos. Convierte casillas en el área de ataque en verde.",
  str_skill_desc_300123 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo a <color=#00F6FF>1 cúmulo circundante</color>. Cuando se ataca al mismo objetivo por primera vez, se inflige <link=\"10004\"><#FFAE07><u>Paralización</u></color></link> por 1 ronda. Al atacar por segunda vez, se inflige <color=#00F6FF><color=#00F6FF>Aturdimiento</color></color> por 1 ronda.",
  str_skill_desc_302123 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo a <color=#00F6FF>1 cúmulo circundante</color>. Cuando se ataca al mismo objetivo por primera vez, se inflige <link=\"10004\"><#FFAE07><u>Paralización</u></color></link> por 1 ronda. Al atacar por segunda vez, se inflige <color=#00F6FF>Aturdimiento</color> por 1 ronda.",
  str_skill_desc_305123 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo a <color=#00F6FF>1 cúmulo circundante</color>. Cuando se Ataca al mismo objetivo las 2 primeras veces, se inflige <color=#00F6FF>Aturdimiento</color> por 1 ronda cada vez.",
  str_skill_desc_320123 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo a <color=#00F6FF>1 cúmulo circundante</color>. Al golpear el mismo objetivo por primera vez, se ven afectados por <link=\"10004\"><#FFAE07><u>Paralización</u></color></link> por 1 ronda. Cuando se les golpea por segunda vez, se les aflige con <color=#00F6FF>Aturdimiento</color> por 1 ronda. El daño de la Habilidad Activa aumenta en función del número de casillas ocupadas por el objetivo.",
  str_skill_desc_322123 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo a <color=#00F6FF>1 cúmulo circundante</color>. Al golpear el mismo objetivo por primera vez, se ven afectados por <link=\"10004\"><#FFAE07><u>Paralización</u></color></link> por 1 ronda. Cuando se les golpea por segunda vez, se les aflige con <color=#00F6FF>Aturdimiento</color> por 1 ronda. El daño de la Habilidad Activa aumenta en función del número de casillas ocupadas por el objetivo.",
  str_skill_desc_325123 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo a <color=#00F6FF>1 cúmulo circundante</color>. Cuando se Atacar al mismo objetivo las 2 primeras veces, se les afecta con <color=#00F6FF>Aturdimiento</color> por 1 ronda cada vez. El daño de la Habilidad Activa aumenta en función del número de casillas ocupadas por el objetivo",
  str_skill_desc_300015 = "Selecciona una casilla atravesable en la que convocar a Gin y determinar su dirección, luego lanza 1 granada en esa dirección. Esta granada puede rebotar nuevamente a la mayor distancia posible en la dirección seleccionada por Gin. La granada inflige un <color=#00F6FF>200%</color> de daño a los enemigos que pasa por el camino.",
  str_skill_desc_330015 = "Selecciona una casilla atravesable en la que convocar a Gin y determinar su dirección, luego lanza 1 granada en esa dirección. Esta granada puede rebotar nuevamente a la mayor distancia posible en la dirección seleccionada por Gin. La granada inflige un <color=#00F6FF>200%</color> de daño a los enemigos que pasa por el camino. La ginebra puede prepararse para orientarse en direcciones diagonales.",
  str_skill_desc_300131 = "Recupera los PS del equipo en un <color=#00F6FF>220%</color> del ATQ de Novio y gana escudo en un <color=#00F6FF>90%</color> de los PS de Novio. Si hay un exceso de curación, inflige daño a enemigos dentro <color=#00F6FF>12 casillas en forma de diamante</color> igual al valor recuperado en exceso independientemente de la defensa de los enemigos.",
  str_skill_desc_306131 = "Recupera los PS del equipo en un <color=#00F6FF>220%</color> del ATQ de Novio y gana escudo en un <color=#00F6FF>120%</color> de los PS de Novio. Si hay un exceso de curación, inflige daño a enemigos dentro <color=#00F6FF>12 casillas en forma de diamante</color> igual al valor recuperado en exceso independientemente de la defensa de los enemigos.",
  str_skill_desc_320131 = "Recupera los PS del equipo en un <color=#00F6FF>220%</color> del ATQ de Novio y gana escudo en un <color=#00F6FF>90%</color> de los PS de Novio. Si hay un exceso de curación, inflige daño a enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> igual al exceso de valor recuperado independientemente de la defensa. Al entrar en Hora de Aurora, un escudo de hasta MAX PS se convertirá en PS.",
  str_skill_desc_326131 = "Recupera los PS del equipo en un <color=#00F6FF>220%</color> del ATQ de Novio y gana escudo en un <color=#00F6FF>120%</color> de los PS de Novio. Si hay un exceso de curación, inflige daño a enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> igual al exceso de valor recuperado independientemente de la defensa. Al entrar en Hora de Aurora, un escudo de hasta MAX PS se convertirá en PS.",
  str_skill_desc_300132 = "Inflige un <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si este enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido.",
  str_skill_desc_302132 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Cuando se recupera, el tiempo de enfriamiento de la Habilidad Activa también se reduce en <color=#00F6FF>1</color> ronda.",
  str_skill_desc_305132 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Cuando se recupera, el tiempo de enfriamiento de la Habilidad Activa también se reduce en <color=#00F6FF>1</color> ronda.",
  str_skill_desc_320132 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Al entrar en Hora de Aurora, los enemigos no pueden recuperar PS cuando finaliza la ronda.",
  str_skill_desc_3201321 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Al entrar en Hora de Aurora, los enemigos no pueden recuperar PS cuando finaliza la ronda.",
  str_skill_desc_322132 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Cuando se recupera, el tiempo de enfriamiento de la Habilidad Activa también se reduce en <color=#00F6FF>1</color> ronda. Al entrar en Hora de Aurora, los enemigos no pueden recuperar PS cuando finaliza la ronda.",
  str_skill_desc_3221321 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Cuando se recupera, el tiempo de enfriamiento de la Habilidad Activa también se reduce en <color=#00F6FF>1</color> ronda. Al entrar en Hora de Aurora, los enemigos no pueden recuperar PS cuando finaliza la ronda.",
  str_skill_desc_325132 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Cuando se recupera, el tiempo de enfriamiento de la Habilidad Activa también se reduce en <color=#00F6FF>1</color> ronda. Al entrar en Hora de Aurora, los enemigos no pueden recuperar PS cuando finaliza la ronda.",
  str_skill_desc_3251321 = "Inflige <color=#00F6FF>{1}%</color> de daño a 1 enemigo seleccionado. Si el enemigo sigue en pie al final de la ronda, el PS recuperado es igual al daño infligido. Cuando se recupera, el tiempo de enfriamiento de la Habilidad Activa también se reduce en <color=#00F6FF>1</color> ronda. Al entrar en Hora de Aurora, los enemigos no pueden recuperar PS cuando finaliza la ronda.",
  str_skill_desc_300133 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centradas en 1 casilla seleccionada y derriba a los enemigos.",
  str_skill_desc_302133 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centradas en 1 casilla seleccionada y derriba a los enemigos.",
  str_skill_desc_300137 = "Selecciona 1 enemigo y convierte hasta <color=#00F6FF>2</color> casillas que no sean azules a los pies del enemigo en azules.",
  str_skill_desc_310137 = "Selecciona 1 enemigo y convierte hasta <color=#00F6FF>2</color> casillas que no sean azules a los pies del enemigo en azules.",
  str_skill_desc_304137 = "Selecciona 1 enemigo y convierte hasta <color=#00F6FF>3</color> casillas que no sean azules a los pies del enemigo en azules.",
  str_skill_desc_314137 = "Selecciona 1 enemigo y convierte hasta <color=#00F6FF>3</color> casillas que no sean azules a los pies del enemigo en azules.",
  str_skill_desc_300135 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones, y luego selecciona una dirección a cada lado, atacando a los enemigos dentro <color=#00F6FF>45 grados</color> y tratar <color=#00F6FF>340%</color> daños en la zona. El daño disminuye durante este barrido a un mínimo del 30% del valor original.",
  str_skill_desc_302135 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones, y luego selecciona una dirección a cada lado, atacando a los enemigos dentro <color=#00F6FF>45 grados</color> y tratar <color=#00F6FF>340%</color> daños en la zona. El daño disminuye durante este barrido a un mínimo del 30% del valor original.",
  str_skill_desc_305135 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones, y luego selecciona una dirección a cada lado, atacando a los enemigos dentro <color=#00F6FF>45 grados</color> y tratar <color=#00F6FF>340%</color> daños en la zona. El daño disminuye durante este barrido a un mínimo del 40% del valor original.",
  str_skill_desc_320135 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones, y luego selecciona una dirección a cada lado, atacando a los enemigos dentro <color=#00F6FF>90 grados</color> y tratar <color=#00F6FF>340%</color> daños en la zona. El daño disminuye durante este barrido a un mínimo del 30% del valor original.",
  str_skill_desc_322135 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones, y luego selecciona una dirección a cada lado, atacando a los enemigos dentro <color=#00F6FF>90 grados</color> y tratar <color=#00F6FF>340%</color> daños en la zona. El daño disminuye durante este barrido a un mínimo del 30% del valor original.",
  str_skill_desc_325135 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones, y luego selecciona una dirección a cada lado, atacando a los enemigos dentro <color=#00F6FF>90 grados</color> y tratar <color=#00F6FF>340%</color> daños en la zona. El daño disminuye durante este barrido a un mínimo del 40% del valor original.",
  str_skill_desc_300134 = "Selecciona una casilla para infligir <color=#00F6FF>{1}%</color> de daño a enemigos al frente y en casillas adyacentes, haciéndolos retroceder tanto cuanto posible.",
  str_skill_desc_303134 = "Selecciona una casilla para infligir <color=#00F6FF>{1}%</color> de daño a enemigos al frente y en casillas adyacentes, haciéndolos retroceder tanto cuanto posible.",
  str_skill_desc_320134 = "Selecciona una casilla para infligir <color=#00F6FF>{1}%</color> de daño a enemigos <color=#00F6FF>al frente</color> y en casillas <color=#00F6FF>adyacentes</color>, haciéndolos retroceder tanto cuanto posible. Enemigos <color=#00F6FF>en el camino</color> recibirán <color=#00F6FF>1.3×</color> de daño.",
  str_skill_desc_323134 = "Selecciona una casilla para infligir <color=#00F6FF>{1}%</color> de daño a enemigos <color=#00F6FF>al frente</color> y en casillas <color=#00F6FF>adyacentes</color>, haciéndolos retroceder tanto cuanto posible. Enemigos <color=#00F6FF>en el camino</color> recibirán <color=#00F6FF>1.3×</color> de daño.",
  str_skill_desc_300136 = "Inflige <color=#00F6FF>{1}%</color> de daño a todos los enemigos, e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> en todos los enemigos en casillas Verdes por 2 rondas.",
  str_skill_desc_302136 = "Inflige <color=#00F6FF>{1}%</color> de daño a todos los enemigos, e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> en todos los enemigos en casillas Verdes por 2 rondas.",
  str_skill_desc_320136 = "Inflige <color=#00F6FF>{1}%</color> de daño a todos los enemigos, e inflige <link=\"10006\"><#FFAE07><u>de Retardo</u></color></link> a todos los enemigos en las casillas verdes durante 2 rondas. El enemigo será infligido con <color=#00F6FF>2 pilas</color> de Marca de Mortalidad antes de que la Habilidad Activa haga daño.",
  str_skill_desc_322136 = "Inflige <color=#00F6FF>{1}%</color> de daño a todos los enemigos, e inflige <link=\"10006\"><#FFAE07><u>Retardo</u></color></link> a todos los enemigos en las casillas verdes durante 2 rondas. El enemigo será infligido con <color=#00F6FF>2 pilas</color> de Marca de Mortalidad antes de que la Habilidad Activa haga daño.",
  str_skill_desc_325136 = "Inflige <color=#00F6FF>{1}%</color> de daño a todos los enemigos y también <link=\"10006\"><#FFAE07><u>Lento</u></color></link> a todos los enemigos en casillas Verdes por 2 rondas. El enemigo recibirá <color=#00F6FF>3 pilas</color> de Marca de Mortalidad antes de que la Habilidad Activa haga daño.",
  str_skill_passive_desc_410022 = "Aumenta el daño de la Habilidad Activa en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410051 = "Aumenta el daño de la Habilidad Activa en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410047 = "Aumenta la curación de Combo en cadena por <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410049 = "Existe una <color=#00F6FF>{1}</color> posibilidad de aumenta el daño de Combo en cadena en un <color=#00F6FF> 50% </color>.",
  str_skill_passive_desc_410050 = "Aumenta el daño de Combo en cadena en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410052 = "Las habilidades activas tienen una <color=#00F6FF>{1}</color> probabilidad de causar <link=\"10006\"><#FFAE07><u>lento</u></color></link> en enemigos durante 2 rondas.",
  str_skill_passive_desc_410074 = "Aumenta el daño de la Habilidad Activa en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410008 = "El daño de ataque normal de Tiny One aumenta en <color=#00F6FF>{1}</color> para esta ronda después de usar una Habilidad Activa.",
  str_skill_passive_desc_410007 = "Cuando se usa Combo en cadena, inflige + <color=#00F6FF>{1}</color> de daño al primer enemigo golpeado e inflige 1 pila de Veneno, dura 2 rondas.",
  str_skill_passive_desc_410032 = "Cada rayo tiene un <color=#00F6FF>15%</color> oportunidad de negociar un adicional <color=#00F6FF>{1}</color> daño.",
  str_skill_passive_desc_410053 = "Aumenta el daño de Combo en cadena en <color=#00F6FF>{1}</color> cuando la Habilidad Activa está lista.",
  str_skill_passive_desc_410058 = "Si la bandera todavía existe al final de la ronda, regenera el PS del equipo <color=#00F6FF>{1}</color> x de la DEF de Amy.",
  str_skill_passive_desc_400035 = "Después de usar esta habilidad de movimiento, Eho gana <color=#00F6FF>{1}</color> daño de ataque normal aumentado para la ronda.",
  str_skill_passive_desc_410035 = "Después de usar esta habilidad de movimiento, Eho gana <color=#00F6FF>{1}</color> daño de ataque normal aumentado para la ronda.",
  str_skill_passive_desc_420035 = "Después de usar esta habilidad de movimiento, Eho gana <color=#00F6FF>{1}</color> daño de ataque normal y daño combinado de cadena aumentados para la ronda.",
  str_skill_passive_desc_410017 = "Siempre que un Aurorian aliado derriba a un enemigo, Rabbie inflige un daño equivalente a <color=#00F6FF>{1}</color> de su ATQ a ese enemigo (este daño ignora la DEF).",
  str_skill_passive_desc_430017 = "Cuando un Aurorian aliado derriba a un enemigo, Rabbie inflige un daño equivalente a <color=#00F6FF>{1}</color> de su ATQ a ese enemigo (este daño ignora la DEF). Incrementa la DEF en un <color=#00F6FF>10%</color> por cada casilla en que el enemigo haya sido derribado.",
  str_skill_passive_desc_410040 = "Otorga 1 acumulación de Stickiness Mark al comienzo de cada ronda. Cada acumulación aumenta la posibilidad de que las habilidades de Chain Combo inflijan <link=\"10002\"> <#FFAE07><u>Quemar</u></color></link> que dura 2 rondas por <color=#00F6FF>{1}</color>. Todas las pilas se borran al comienzo de cada ola.",
  str_skill_passive_desc_420040 = "Otorga 1 acumulación de Stickiness Mark al comienzo de cada ronda. Cada acumulación aumenta la posibilidad de que las habilidades de Chain Combo inflijan <link=\"10002\"> <#FFAE07><u>Quemar</u></color></link> que dura 2 rondas por <color=#00F6FF>{1}</color>. Todas las pilas se borran al comienzo de cada ola.",
  str_skill_passive_desc_410041 = "Aumenta el ATQ de Blanc en <color=#00F6FF>{1}</color> cuando PS está lleno.",
  str_skill_passive_desc_420041 = "Aumenta el ATK de Blanc en <color=#00F6FF>{1}</color> cuando HP está por encima del 70%.",
  str_skill_passive_desc_430041 = "Aumenta el ATK de Blanc en <color=#00F6FF>{1}</color> y aumenta el ATK de otros Aurorianos de agua desplegados en <color=#00F6FF>{2}</color> del ATK de Blanc cuando HP está por encima del 70%.",
  str_skill_passive_desc_410021 = "Aumenta el daño del combo en cadena en <color=#00F6FF>{1}</color> cuando la habilidad activa no está lista.",
  str_skill_passive_desc_420021 = "Aumenta el daño del combo en cadena en <color=#00F6FF>{1}</color> y daño de Ataque Normal por <color=#00F6FF>{2}</color> cuando la habilidad activa no está lista.",
  str_skill_passive_desc_410004 = "Aumenta el PS máximo del equipo en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410073 = "Desata 1 Combo en Cadena adicional al comienzo de la línea, lo que inflige <color=#00F6FF>{1}</color> daño normal.",
  str_skill_passive_desc_430073 = "Libera 1 Combo en Cadena adicional al comienzo de la línea, lo que inflige <color=#00F6FF>{1}</color> daño normal. Aumenta el daño a un <color=#00F6FF> 100% </color>.donde los combos inicial y real se superponen.",
  str_skill_passive_desc_410061 = "Obtiene 1 pila de Marca de Negatividad cada vez que se usa una Habilidad Activa, hasta <color=#00F6FF> 3 </color> pilas. Cada pila aumenta el número de ataques de habilidades activas en 1 y reduce el daño final en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420061 = "Obtiene 1 pila de Marca de Negatividad cada vez que se usa una Habilidad Activa, hasta <color=#00F6FF> 5 </color> pilas. Cada pila aumenta el número de ataques de habilidades activas en 1, reduce el daño final en <color=#00F6FF>{1}</color>. Cada marca aumenta el daño de Combo en cadena en un <color=#00F6FF> 5% </color>.",
  str_skill_passive_desc_430061 = "Obtiene 1 pila de Marca de Negatividad cada vez que se usa una Habilidad Activa, hasta <color=#00F6FF> 5 </color> pilas. Cada pila aumenta el número de ataques de habilidades activas en 1, reduce el daño final en <color=#00F6FF>{1}</color>. Cada marca aumenta el daño de Combo en cadena en un <color=#00F6FF> 5% </color>.",
  str_skill_passive_desc_414061 = "Obtiene 1 pila de Marca de Negatividad cada vez que se usa una Habilidad Activa, hasta <color=#00F6FF> 3 </color> pilas. Cada pila aumenta el número de ataques de habilidades activas en 1 y reduce el daño final en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_424061 = "Obtiene 1 pila de Marca de Negatividad cada vez que se usa una Habilidad Activa, hasta <color=#00F6FF> 5 </color> pilas. Cada pila aumenta el número de ataques de habilidades activas en 1, reduce el daño final en <color=#00F6FF>{1}</color>. Cada marca aumenta el daño de Combo en cadena en un <color=#00F6FF> 5% </color>.",
  str_skill_passive_desc_434061 = "Obtiene 1 pila de Marca de Negatividad cada vez que se usa una Habilidad Activa, hasta <color=#00F6FF> 5 </color> pilas. Cada pila aumenta el número de ataques de habilidades activas en 1, reduce el daño final en <color=#00F6FF>{1}</color>. Cada marca aumenta el daño de Combo en cadena en un <color=#00F6FF> 5% </color>.",
  str_skill_passive_desc_410054 = "Siempre que una linterna desaparece al final de su duración, libera una luz que ilumina <color=#00F6FF> 1 cúmulo circundante </color>, lo que inflige <color=#00F6FF>{1}</color> de daño y tiene <color=#00F6FF>{2}</color> posibilidad de infligir <link=\"10005\"><#FFAE07><u>ceguera</u></color></link> a los enemigos durante 1 ronda.",
  str_skill_passive_desc_430054 = "Mientras existe una linterna, libera luz que ilumina <color=#00F6FF> 1 cúmulo circundante </color> al final de cada ronda, lo que inflige <color=#00F6FF>{1}</color> de daño y tiene <color=#00F6FF>{2}</color> posibilidad de infligir <link=\"10005\"><#FFAE07><u>ceguera</u></color></link> a los enemigos durante 1 asalto.",
  str_skill_passive_desc_410016 = "Obtiene 1 pila de carga cada vez que atraviesa una casilla amarilla, hasta 99 pilas. Cada pila aumenta el daño de la Habilidad Activa en <color=#00F6FF>{1}</color>. El uso de la Habilidad Activa borra todas las pilas.",
  str_skill_passive_desc_410046 = "Cada pila de Marca de la risa aumenta el daño de ataque normal de los Aurorians del trueno en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430046 = "Matar enemigos con Marca de la risa inflige <color=#00F6FF>1</color> pila adicional a todos los enemigos Restantes. Cada marca aumenta el daño de ataque normal de Aurorians de Trueno en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410044 = "Siempre que los combos en cadena infligen daño a todos los enemigos, los Aurorians del trueno obtienen <color=#00F6FF>{1}</color> del ATQ de Vivian como bonificación de ataque para la ronda.",
  str_skill_passive_desc_430044 = "Siempre que los combos en cadena infligen daño a todos los enemigos, los Aurorians de agua, trueno e Illumina obtienen <color=#00F6FF>{1}</color> del ATQ de Vivian como una bonificación de ATQ durante 2 rondas.",
  str_skill_passive_desc_410048 = "Aumenta el daño de Dayna contra los enemigos que ocupan una casilla amarilla en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430048 = "Aumenta el daño de Dayna contra los enemigos que ocupan un mosaico amarillo en <color=#00F6FF>{1}</color>. También otorga a los compañeros de equipo Thunder Aurorian <color=#00F6FF>50%</color> de ese bono.",
  str_skill_passive_desc_410009 = "Al comienzo de cada ronda, existe una <color=#00F6FF>{1}</color> posibilidad de infligir <link=\"10003\"><#FFAE07><u>miedo</u></color></link> en enemigos durante 1 ronda.",
  str_skill_passive_desc_420009 = "Al comienzo de cada ronda, los enemigos tienen un <color=#00F6FF>{1}</color> de posibilidades de sufrir <link=\"10003\"> <#FFAE07> <u> miedo </u></color></link> durante 1 ronda. Activa una explosión cada vez que mata a un enemigo <link=\"10003\"> <#FFAE07> <u> asustado </u></color></link>, lo que inflige <color=#00F6FF> 10% </color> de PS máx como daño a los enemigos dentro de 1 cúmulo circundante.",
  str_skill_passive_desc_410012 = "Cada golpe de Combo en Cadena otorga 1 pila de marca de juicio. Cada pila aumenta la DEF en <color=#00F6FF>{1}</color>. La marca desaparece al final de la ronda.",
  str_skill_passive_desc_420012 = "Cada golpe de Combo en Cadena otorga 1 pila de marca de juicio (2, si es una Habilidad Activa). Cada pila aumenta la DEF en <color=#00F6FF>{1}</color>. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_430012 = "Cada golpe de Combo en Cadena otorga 1 pila de marca de juicio (golpe de Habilidad Activa otorga 2 pilas). Cada pila aumenta el ATQ en un <color=#00F6FF> 3% </color> DEF en <color=#00F6FF>{1}</color>. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_410013 = "Cuando el escudo desaparece, convierte <color=#00F6FF>{1}</color> del escudo restante en PS.",
  str_skill_passive_desc_430013 = "Cuando el escudo desaparece, convierte <color=#00F6FF>{1}</color> del escudo restante en PS. Incrementa la DEF de Noah en un <color=#00F6FF> 50% </color> si ya existe un escudo.",
  str_skill_passive_desc_410018 = "Los combos en cadena infligen hasta un <color=#00F6FF>{1}</color> más de daño. Cuanto más cerca estén los enemigos, mayor será el daño. Una distancia superior a 3 casillas no ofrece bonificaciones de daño.",
  str_skill_passive_desc_420018 = "Cuanto más cerca estén los enemigos, mayor será el daño de las habilidades activas y los combos en cadena (hasta <color=#00F6FF>{1}</color>). Una distancia superior a 3 cúmulos no ofrece bonificaciones de daño.",
  str_skill_passive_desc_430018 = "Aumenta el ATK en <color=#00F6FF>5%</color> para cada enemigo dentro <color=#00F6FF>1 grupo circundante</color>. Cuanto más cerca estén los enemigos, mayor será el daño de las habilidades activas y los combos en cadena (hasta <color=#00F6FF>{1}</color>). Una distancia superior a 3 grupos no ofrece bonificaciones de daño.",
  str_skill_passive_desc_410033 = "Vice gana 1 pila de Marca de bloqueo cada vez que inflige daño. Cada pila aumenta el daño en <color=#00F6FF>{1}</color>. Todas las pilas se eliminan al final de la ronda.",
  str_skill_passive_desc_430033 = "Vice gana 1 pila de Marca de bloqueo cada vez que inflige daño. Cada pila aumenta el daño en <color=#00F6FF>{1}</color> y el daño de Combo en cadena en <color=#00F6FF>{2}</color>. Todas las pilas se eliminan al final de la ronda.",
  str_skill_passive_desc_410036 = "Otorga 1 Marca de Lobo al comienzo de cada ronda. Cuando es atacado por primera vez, consume 1 marca para infligir daño igual al <color=#00F6FF>{1}</color> del ATQ de Hydrad de regreso al objetivo (este daño ignora la DEF). Todas las marcas de lobo se eliminan al final de la ronda.",
  str_skill_passive_desc_420036 = "Otorga 1 Marca de Lobo al comienzo de cada ronda. Cuando es atacado, consume 1 marca para infligir daño igual al <color=#00F6FF>{1}</color> del ATQ de Hydrad de regreso al objetivo (este daño ignora la DEF). Las marcas de lobo <color=#00F6FF>no se eliminan al final</color> de la ronda.",
  str_skill_passive_desc_410010 = "Al activar <link=\"30010\"><#FFAE07><u>Hora de Aurora</u></color></link>, el PS del equipo se recupera inmediatamente en <color=#00F6FF>{1}</color> de PS Máx. de Louise y aumenta su DEF en un <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_420010 = "Al activar <link=\"30010\"><#FFAE07> <u>Hora de Aurora</u></color></link>, recupera inmediatamente los PS del equipo con <color=#00F6FF>{1}</color> del PS Máx de Louise y aumenta su DEF en un <color=#00F6FF>50%</color> durante 2 rondas.",
  str_skill_passive_desc_410014 = "Aumenta la DEF de Schwartz en <color=#00F6FF>{1}</color> por cada Trueno o Lumopolis Aurorian desplegado.",
  str_skill_passive_desc_430014 = "Aumenta la DEF de Schwartz por {1} cada Trueno o Lumopolis Aurorian desplegado (también aumenta el ATQ por una cantidad igual a la DEF otorgada).",
  str_skill_passive_desc_410078 = "Aumenta el daño de Robyn contra los enemigos que ocupan casillas verdes en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430078 = "Aumenta el daño de Robyn contra los enemigos que ocupan una casilla verde en <color=#00F6FF>{1}</color>. También otorga a los compañeros de equipo de Forest Aurorian <color=#00F6FF>50%</color> de ese bono.",
  str_skill_passive_desc_410076 = "Después de usar un Combo en cadena, toca <color=#00F6FF> 4 enemigos adyacentes en forma de cruz </color> e inflige <link=\"10003\"><#FFAE07><u>miedo</u></color></link> durante 1 ronda si el PS del enemigo está por debajo de <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420076 = "Después de usar un Combo en Cadena, inflige <link=\"10003\"> <#FFAE07> <u> miedo </u></color></link> a 1 enemigo con los PS más bajo (por debajo de <color=#00F6FF>{1}</color> HP) dentro de <color=#00F6FF> 4 casillas en forma de cruz </color> durante 1 ronda. Matar a un <link=\"10003\"> <#FFAE07> <u> asustado </u></color></link> enemigo tiene un <color=#00F6FF> 50% </color> de probabilidad de infligir <link=\"10003\"> <#FFAE07> <u> miedo </u></color></link> a los enemigos dentro de <color=#00F6FF> 4 casillas en forma de cruz </color>.",
  str_skill_passive_desc_410042 = "Los ataques normales ahora pueden dispararse en diagonal e infligir <color=#00F6FF>{1}</color> daño.",
  str_skill_passive_desc_420042 = "Los ataques normales ahora pueden dispararse en diagonal para infligir <color=#00F6FF>{1}</color> daño e infligir 1 marca de potencia de fuego que dura 2 rondas. El ataque normal de Barton inflige un <color=#00F6FF> 10% </color> de daño adicional a los enemigos con la marca.",
  str_skill_passive_desc_430042 = "Los ataques normales ahora pueden dispararse en diagonal para infligir <color=#00F6FF>{1}</color> daño e infligir 1 marca de porencia de fuego que dura 2 rondas. El ataque de Barton inflige un <color=#00F6FF> 10% </color> de <color=#00F6FF>daño adicional</color> a los enemigos con la marca.",
  str_skill_passive_desc_410001 = "Otorga Mirror Mark al comienzo de la batalla. Mientras exista la Marca, Nikinis ganancias <color=#00F6FF>{1}</color> aumento de DEF. La Marca desaparece una vez Nikinis pierde HP. La marca de espejo se puede actualizar <color=#00F6FF>utilizando una habilidad activa</color>.",
  str_skill_passive_desc_420001 = "Otorga Mirror Mark al comienzo de la batalla. Mientras exista la Marca, Nikinis ganancias <color=#00F6FF>{1}</color> aumento de DEF. La Marca desaparece una vez Nikinis pierde HP. La marca de espejo se puede actualizar <color=#00F6FF>usando una habilidad activa o ingresando a Aurora Time</color>.",
  str_skill_passive_desc_410011 = "Los ataques normales aplican 1 pila de marca de diente de dragón, hasta <color=#00F6FF> 4 </color> pilas. Cada pila aumenta el daño del Combo en Cadena final de Sharona en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430011 = "Los ataques normales aplican 1 pila de marca de diente de dragón, hasta <color=#00F6FF> 6 </color> pilas. Cada pila aumenta el daño de la <color=#00F6FF>Habilidad Activa </color> de Sharona y el daño final del combo en cadena en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_440011 = "Los ataques normales aplican 1 acumulación de Dragontooth Mark, hasta <color=#00F6FF>7</color> pilas Cada acumulación aumenta la capacidad de Sharona <color=#00F6FF>Habilidad activa</color> y Chain Combo daño final por <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410019 = "Victoria regenera <color=#00F6FF>{1}</color> Max PS por pila de <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> cada vez que su Combo de Cadena alcanza un enemigo afectado por <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link>.",
  str_skill_passive_desc_420019 = "Victoria regenera <color=#00F6FF>{1}</color> Max PS por pila de <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> cada vez que su Combo de Cadena alcanza un enemigo afectado por <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link>.",
  str_skill_passive_desc_430019 = "Victoria regenera PS igual a <color=#00F6FF>{1}</color> de su Max PS por pila de <link=\"10000\"><#FFAE07><u> Sangrado</u></color></link> siempre que golpea a un enemigo afectado por <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> usando un Combo en cadena. Este efecto de recuperación aumenta en un <color=#00F6FF> 50% </color> si el porcentaje de PS del enemigo es mayor que el de tu equipo.",
  str_skill_passive_desc_410023 = "Obtiene 1 pila de marca de escalofrío cuando se usa un Combo en cadena, hasta <color=#00F6FF>5</color> pilas. Cada pila aumenta el daño de la Habilidad Activa en <color=#00F6FF>{1}</color>. El uso de una Habilidad Activa inflige <link=\"10003\"><#FFAE07><u> miedo </u></color></link> a una cantidad de enemigos equivalente a la cantidad de pilas para <color=#00F6FF> 1 </color> ronda. La activación de la Habilidad Activa <color=#00F6FF> no elimina las pilas </color>.",
  str_skill_passive_desc_430023 = "Gana 1 acumulación de Shiver Mark cuando usa un Chain Combo, hasta <color=#00F6FF>5</color> pilas Cada acumulación aumenta el daño de la habilidad activa en <color=#00F6FF>{1}</color>. El uso de una habilidad activa inflige <link=\"10003\"><#FFAE07><u>Susto</u></color></link> en un número de enemigos equivalente al número de acumulaciones para <color=#00F6FF>1</color> redondo. Activando la Habilidad Activa <color=#00F6FF>no borra las pilas</color>. Si ya tiene 5 acumulaciones antes de usar un combo en cadena, además infligirá daño al enemigo más cercano.",
  str_skill_passive_desc_410002 = "Hiiro entra en posición de Duelo al comienzo de cada ronda, y el siguiente ataque normal inflige <color=#00F6FF>{1}</color> de daño al enemigo y <color=#00F6FF>{2}</color> de daño a enemigos en <color=#00F6FF> 4 casillas en un área en forma de cruz </color>.",
  str_skill_passive_desc_420002 = "Hiiro entra en posición de Duelo al comienzo de cada ronda o cuando pasa por una <link=\"20001\"><#FFAE07> <u> casilla mejorada </u></color></link>. El siguiente ataque normal inflige <color=#00F6FF>{1}</color> de daño al enemigo y <color=#00F6FF>{2}</color> de daño a enemigos en <color=#00F6FF> 4 casillas en un área en forma de cruz </color>.",
  str_skill_passive_desc_430002 = "Hiiro entra en posición de Duelo al comienzo de cada ronda o cuando pasa por una <link=\"20001\"><#FFAE07> <u> casilla mejorada </u></color></link>. El siguiente ataque normal inflige <color=#00F6FF>{1}</color> de daño al enemigo y <color=#00F6FF>{2}</color> de daño a enemigos en <color=#00F6FF> 4 casillas en un área en forma de cruz </color>. El ATQ aumenta en un <color=#00F6FF> 4% </color> en esta ronda por uso de Uno con el duelo, hasta un máximo de <color=#00F6FF> 20% </color>.",
  str_skill_passive_desc_410005 = "Mia gana 1 pila de alma al matar a un enemigo con su Habilidad Activa, hasta 5 pilas. Cada pila desata una explosión que inflige <color=#00F6FF>{1}</color> de daño ATQ.",
  str_skill_passive_desc_420005 = "Mia gana 1 pila de alma al matar a un enemigo con su Habilidad Activa, hasta 5 pilas. Cada pila desata un Explosión de alma que inflige <color=#00F6FF>{1}</color> daño ATQ y aumenta el ataque normal de Mia en un <color=#00F6FF> 3% </color> y el daño combinado de cadena en <color=#00F6FF> 5 % </color>.",
  str_skill_passive_desc_430005 = "Mia gana 1 acumulación de Alma por cada enemigo derrotado por <color=#00F6FF>aurorianos</color> en el campo con sus Habilidades Activas, hasta <color=#00F6FF>7</color> pilas Cada pila desata una explosión que inflige <color=#00F6FF>{1}</color> Daño de ATK a un solo objetivo, lo que aumenta adicionalmente el Ataque normal de Mia en <color=#00F6FF>3%</color>, y daño combinado en cadena por <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410006 = "Carleen gana + <color=#00F6FF>{1}</color> ATQ básico por cada 1 casilla de agua en la que se mueva o sobre ella durante la ronda (hasta <color=#00F6FF>{2}</color>).",
  str_skill_passive_desc_420006 = "Carleen gana + <color=#00F6FF>{1}</color> ATQ básico por cada 1 casilla de agua en la que se mueva o sobre ella durante la ronda (hasta <color=#00F6FF>{2}</color>). Los efectos se duplican después de usar una Habilidad Activa.",
  str_skill_passive_desc_430006 = "Carleen gana + <color=#00F6FF>{1}</color> ATQ por cada 1 casilla de agua en la que se mueva o sobre ella durante la ronda (hasta <color=#00F6FF>{2}</color>). Los efectos se duplican para una Habilidad Activa. Sus ataques normales obtienen Perforación en una casilla de agua e infligen un <color=#00F6FF> 40% </color> de daño al objetivo 1 casilla detrás del enemigo.",
  str_skill_passive_desc_410025 = "Agrega daño que ignora DEF igual a <color=#00F6FF>{1}</color> de ATQ a los ataques normales.",
  str_skill_passive_desc_430025 = "Los ataques normales <color=#00F6FF> ahora pueden atacar en diagonal </color>. Agrega daño que ignora DEF igual a <color=#00F6FF>{1}</color> de ATQ a los ataques normales.",
  str_skill_passive_desc_410026 = "Cada pila de <link=\"10002\"><#FFAE07><u> Quemar</u></color></link> aumenta el daño de los Aurorians de fuego en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430026 = "Al comienzo de cada ronda, aplica 1 pila de <link=\"10002\"><#FFAE07><u>Quemar</u></color></link> a los enemigos que ocupan una casilla roja durante 2 rondas. Cada pila de <link=\"10002\"><#FFAE07><u> Quemar</u></color></link> aumenta el daño de los Aurorians de fuego en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410028 = "Cada casilla azul generada en el mapa recupera PS del equipo en <color=#00F6FF>{1}</color> del PS máximo de Raphaela.",
  str_skill_passive_desc_420028 = "Cada casilla azul generada en el mapa recupera los PS del equipo en <color=#00F6FF>{1}</color> del PS de Raphaela. Cuanto menor sea los PS del equipo, mayor será la efectividad de curación, hasta una <color=#00F6FF> bonificación del 100% </color> adicional.",
  str_skill_passive_desc_410029 = "Se generará al menos 1 <link=\"20001\"><#FFAE07> <u> casilla mejorada </u></color></link> por <color=#00F6FF>{1}</color> casillas verdes que pasen por esta ronda.",
  str_skill_passive_desc_430029 = "Durante esta ronda, se generará al menos 1 <link=\"20001\"><#FFAE07> <u> casilla mejorada </u></color></link> por <color=#00F6FF>{1}</color> verde las casillas pasadas en esta ronda, y las casilla verdes se mejorarán primero.",
  str_skill_passive_desc_410038 = "Otorga 1 Tormenta Magnética por 3 rondas. El siguiente Combo en Cadena inflige <color=#00F6FF>{1}</color> daño a 1 enemigo adicional dentro del área de ataque e inflige <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link> durante 1 ronda.",
  str_skill_passive_desc_420038 = "Otorga 1 Tormenta Magnética por 3 rondas. El siguiente Combo en Cadena inflige <color=#00F6FF>{1}</color> de daño adicional a 1 enemigo dentro del área de ataque e inflige <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link> durante 1 ronda. Hay un <color=#00F6FF>50%</color> de posibilidad de atacar a otro enemigo.",
  str_skill_passive_desc_430038 = "Otorga 1 Tormenta Magnética por 3 rondas al comienzo de la batalla. El siguiente Combo en Cadena inflige <color=#00F6FF>{1}</color> daño adicional a 1 enemigo dentro del área de ataque e inflige <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link>. Tiene un <color=#00F6FF> 50% </color> probabilidad de atacar a otro enemigo.",
  str_skill_passive_desc_410077 = "Los Aurorianos que hayan usado una Habilidad Activa recibirán un bono en esta ronda, igual al <color=#00F6FF>{1}</color> del ATQ básico de Bethlehem.",
  str_skill_passive_desc_420077 = "Los Aurorianos que hayan usado una Habilidad Activa en esta ronda recibirán un bono igual a <color=#00F6FF>{1}</color> del ATQ básico de Bethlehem. Al ingresar a la Hora de Aurora, el equipo recibirá un bono en esta ronda igual a <color=#00F6FF>{2}</color> del ATQ básico de Bethlehem.",
  str_skill_passive_desc_430077 = "Los Aurorianos que hayan usado una Habilidad Activa recibirán un bono igual a <color=#00F6FF>{1}</color> del ATQ básico de Bethlehem en esta ronda. Bethlehem también obtiene un bono de ATQ básico de <color=#00F6FF>{2}</color>. Este bono de ATQ que Bethlehem obtiene dentro de la misma ronda se puede acumular. Después de entrar en la Hora de Aurora, el equipo obtiene un bono adicional en esta ronda igual a <color=#00F6FF>{2}</color> del ATQ básico de Bethlehem.",
  str_skill_passive_desc_400092 = "Cuando un enemigo marcado muere, gana PS igual al <color=#00F6FF>{1}</color> del Max PS del enemigo y <link=\"30007\"><#FFAE07> <u> efectos de recuperación </u></color></link>.",
  str_skill_passive_desc_410092 = "Cuando un enemigo marcado muere, gana PS igual al <color=#00F6FF>{1}</color> del Max PS del enemigo y <link=\"30007\"><#FFAE07> <u> efectos de recuperación </u></color></link>.",
  str_skill_passive_desc_420092 = "Cuando un enemigo marcado muere, gana PS igual al <color=#00F6FF>{1}</color> del Max PS del enemigo y <link=\"30007\"><#FFAE07> <u> efectos de recuperación </u></color></link>. Hasta 1 casilla donde se encuentra el enemigo se cambia a una <link=\"20001\"><#FFAE07> <u> casilla mejorada </u></color></link>.",
  str_skill_passive_desc_400075 = "Los ataques normales tienen una <color=#00F6FF>{1}</color> posibilidad de infligir 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> durante 2 rondas.",
  str_skill_passive_desc_410075 = "Los ataques normales tienen una <color=#00F6FF>{1}</color> posibilidad de infligir 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> durante 2 rondas.",
  str_skill_passive_desc_430075 = "Los ataques normales pueden apuntar a enemigos en <color=#00F6FF>azulejos diagonales</color> y tener un <color=#00F6FF>{1}</color> probabilidad de infligir 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas.",
  str_skill_passive_desc_400086 = "Recupera PS igual al <color=#00F6FF>{1}</color> de la DEF de Uriah cuando pasa por una casilla verde <link=\"20001\"><#FFAE07><u>mejorada</u></color></link>.",
  str_skill_passive_desc_410086 = "Recupera PS igual al <color=#00F6FF>{1}</color> de la DEF de Uriah cuando pasa por una casilla verde <link=\"20001\"><#FFAE07><u>mejorada</u></color></link>.",
  str_skill_passive_desc_400068 = "Cuando un Aurorian se teletransporta, Wendy gana 1 pila de Marca por cada cúmulo entre la ubicación inicial del Aurorian y su destino de tele transportación. Cada pila aumenta el daño del ataque normal de Wendy en <color=#00F6FF>{1}</color>. Lanzando ataques normales borra la Marca.",
  str_skill_passive_desc_410068 = "Cuando un Aurorian se teletransporta, Wendy gana 1 pila de Marca por cada cúmulo entre la ubicación inicial del Aurorian y su destino de tele transportación. Cada pila aumenta el daño del ataque normal de Wendy en <color=#00F6FF>{1}</color>. Lanzando ataques normales borra la Marca.",
  str_skill_passive_desc_430068 = "Cuando un auroriano se teletransporta, Wendy gana 1 acumulación de Marcas por cada grupo entre la ubicación inicial del Aurorian y su destino de teletransporte. Cada acumulación aumenta el daño del siguiente ataque normal de Wendy en <color=#00F6FF>{1}</color>. Wendy retiene <color=#00F6FF>30%</color> de estas acumulaciones de Marcas después de lanzar ataques normales.",
  str_skill_passive_desc_400082 = "Los combos en cadena tienen una <color=#00F6FF>{1}</color> probabilidad de infligir 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> durante 2 rondas.",
  str_skill_passive_desc_410082 = "Los combos en cadena tienen una <color=#00F6FF>{1}</color> probabilidad de infligir 1 pila de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> durante 2 rondas.",
  str_skill_passive_desc_400057 = "Al comienzo de cada ronda, el equipo recupera PS igual al <color=#00F6FF>{1}</color> del ATQ de Philyshy y al <color=#00F6FF>{2}</color> del PS perdido por el equipo.",
  str_skill_passive_desc_410057 = "Al comienzo de cada ronda, el equipo recupera PS igual al <color=#00F6FF>{1}</color> del ATQ de Philyshy y al <color=#00F6FF>{2}</color> del PS perdido por el equipo.",
  str_skill_passive_desc_430057 = "Al comienzo de cada ronda, el equipo recupera PS igual al <color=#00F6FF>{1}</color> del ATQ de Philyshy y al <color=#00F6FF>{2}</color> del PS perdido por el equipo. Por cada <color=#00F6FF> 5% </color> PS perdido por el equipo, el ATQ de Philyshy aumenta en un <color=#00F6FF> 1% </color>.",
  str_skill_passive_desc_400091 = "Cuando se usa una Habilidad Activa o un Combo en Cadena, reduce el ATQ de los enemigos en <color=#00F6FF> 1 cúmulo circundante </color> de la unidad en <color=#00F6FF>{1}</color> durante 1 ronda.",
  str_skill_passive_desc_410091 = "Cuando se usa una Habilidad Activa o un Combo en Cadena, reduce el ATQ de los enemigos en <color=#00F6FF> 1 cúmulo circundante </color> de la unidad en <color=#00F6FF>{1}</color> durante 1 ronda.",
  str_skill_passive_desc_420091 = "Cuando se usa una Habilidad Activa o un Combo en Cadena, reduce el ATQ de los enemigos en <color=#00F6FF> 1 cúmulo circundante </color> de la unidad en <color=#00F6FF>{1}</color> durante 1 ronda.",
  str_skill_passive_desc_430091 = "Cuando se usa una Habilidad Activa o un Combo en Cadena, reduce el ATQ y la DEF de los enemigos en <color=#00F6FF> 2 cúmulos circundantes </color> de la unidad en <color=#00F6FF>{1}</color> durante 1 ronda.",
  str_skill_passive_desc_400079 = "Cuando es atacado por un objetivo con mayor porcentaje de PS, convierte el <color=#00F6FF>{1}</color> del ATQ de Michenny en DEF.",
  str_skill_passive_desc_410079 = "Cuando es atacado por un objetivo con mayor porcentaje de PS, convierte el <color=#00F6FF>{1}</color> del ATQ de Michenny en DEF.",
  str_skill_passive_desc_420079 = "Cuando es atacado por un objetivo con mayor porcentaje de PS, convierte el <color=#00F6FF>{1}</color> del ATQ de Michenny en DEF. Cuando Michenny inflige daño, convierte el mismo porcentaje de la DEF de Michenny en ATQ.",
  str_skill_passive_desc_400085 = "Cuando una Habilidad Activa inflige daño a un enemigo, aumenta el daño final en un <color=#00F6FF> 10% </color> por cada <color=#00F6FF>{1}</color> PS perdido por el enemigo.",
  str_skill_passive_desc_410085 = "Cuando una Habilidad Activa inflige daño a un enemigo, aumenta el daño final en un <color=#00F6FF> 10% </color> por cada <color=#00F6FF>{1}</color> PS perdido por el enemigo.",
  str_skill_passive_desc_400089 = "Otorga 1 marca de pantano de oro al atravesar una <link=\"30001\"><#FFAE07><u> casilla prisma </u></color></link>. Cada pila de Marca de pantano de oro incrementa el daño de Combo en cadena en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410089 = "Otorga 1 marca de pantano de oro al atravesar una <link=\"30001\"><#FFAE07><u> casilla prisma </u></color></link>. Cada pila de Marca de pantano de oro incrementa el daño de Combo en cadena en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420089 = "Otorga 1 marca de pantano de oro al atravesar una <link=\"30001\"><#FFAE07><u> casilla prisma </u></color></link>. Cada pila de Marca de pantano de oro incrementa el daño de Combo en cadena en <color=#00F6FF>{1}</color> y el daño de ataque normal en <color=#00F6FF> 3% </color>.",
  str_skill_passive_desc_430089 = "Otorga 1 marca de pantano de oro al atravesar una <link=\"30001\"><#FFAE07><u> casilla prisma </u></color></link>. Cada pila de Marca de pantano de oro aumenta el daño de Combo en cadena en <color=#00F6FF>{1}</color> y el daño de ataque normal en <color=#00F6FF> 3% </color>. Cuando desencadena <link=\"30010\"><#FFAE07><u>Hora de Aurora </u></color></link>, convierte la casilla inicial en un <link=\"30001\"> <#FFAE07> <u> casilla prisma </u></color></link>.",
  str_skill_passive_desc_400027 = "Otorga 1 pila de Marca del trueno silencioso al comienzo de cada ronda. Los ataques normales consumen 1 pila de Marca del trueno silencioso para infligir un daño adicional igual a <color=#00F6FF>{1}</color> de PS actual al enemigo.",
  str_skill_passive_desc_410027 = "Otorga 1 pila de Marca del trueno silencioso al comienzo de cada ronda. Los ataques normales consumen 1 pila de Marca del trueno silencioso para infligir un daño adicional igual a <color=#00F6FF>{1}</color> de PS actual al enemigo.",
  str_skill_passive_desc_420027 = "Otorga 1 pila de Marca del trueno silencioso al comienzo de cada ronda y cuando se usa una Habilidad Activa o un Combo en Cadena. Los ataques normales consumen 1 pila de Marca del trueno silencioso para infligir un daño adicional igual a <color=#00F6FF>{1}</color> de PS actual al enemigo.",
  str_skill_passive_desc_400060 = "En el estado de mediodía, los ataques normales infligen <color=#00F6FF>{1}% </color><link=\"30015\"><#FFAE07><u>daño por salpicadura</u></color></link> a todos los objetivos en<color=#00F6FF>4 casillas en forma de cruz</color> alrededor del enemigo.",
  str_skill_passive_desc_410060 = "En el estado de mediodía, los ataques normales infligen <color=#00F6FF>{1}% </color><link=\"30015\"><#FFAE07><u>daño por salpicadura</u></color></link> a todos los objetivos en<color=#00F6FF>4 casillas en forma de cruz</color> alrededor del enemigo.",
  str_skill_passive_desc_420060 = "Cuando está en el estado del mediodía, aumenta el daño de los ataques normales en un <color=#00F6FF>20%</color> y los ataques normales infligen <color=#00F6FF>{1}</color><link=\"30015\"><#FFAE07> <u>salpicadura</u></color></link> daña a todos los objetivos en <color=#00F6FF>4 casillas en forma de cruz </color>alrededor del enemigo.",
  str_skill_passive_desc_430060 = "Cuando está en el estado del mediodía, aumenta el daño de los ataques normales en un <color=#00F6FF>20%</color> y los ataques normales infligen <color=#00F6FF>{1}</color><link=\"30015\"><#FFAE07> <u>salpicadura</u></color></link> daña a todos los objetivos en <color=#00F6FF>4 casillas en forma de cruz </color>alrededor del enemigo.",
  str_skill_passive_desc_400064 = "Puede <link=\"30008\"><#FFAE07><u>reservar munición</u></color></link>. Cada vez que un Combo en Cadena inflige daño, se consume 1 munición (se pueden consumir hasta <color=#00F6FF>3</color> munición en el estado de sobrecarga). Por cada munición consumida, el daño final aumenta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410064 = "Puede <link=\"30008\"><#FFAE07><u>reservar munición</u></color></link>. Cada vez que un Combo en Cadena inflige daño, se consume 1 munición (se pueden consumir hasta <color=#00F6FF>3</color> munición en el estado de sobrecarga). Por cada munición consumida, el daño final aumenta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430064 = "Puede <link=\"30009\"><#FFAE07><u>reservar munición</u></color></link>. Cada vez que un Combo en Cadena inflige daño, se consume 1 munición (se pueden consumir hasta <color=#00F6FF>3</color> munición en el estado de sobrecarga). Por cada munición consumida, el daño final aumenta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400070 = "Los ataques normales tienen una <color=#00F6FF>{1}</color> probabilidad de activar 1 ataque de dragón rojo que inflige un daño equivalente al <color=#00F6FF>50%</color> del daño de ataque normal de Leona.",
  str_skill_passive_desc_410070 = "Los ataques normales tienen una <color=#00F6FF>{1}</color> probabilidad de activar 1 ataque de dragón rojo que inflige un daño equivalente al <color=#00F6FF>50%</color> del daño de ataque normal de Leona.",
  str_skill_passive_desc_420070 = "Los ataques normales tienen un <color=#00F6FF>{1}</color> probabilidad de activar 1 ataque de dragón rojo que inflige un daño equivalente al <color=#00F6FF>50%</color> del daño del ataque normal de Leona e inflige 1 pila de <link=\"10002\"><#FFAE07><u>Incendio</u></color></link> durante 2 rondas.",
  str_skill_passive_desc_400088 = "Aumenta el daño del Combo en Cadena de Maggie en <color=#00F6FF>{1}</color> después de cada <color=#00F6FF> 10 </color> combos.",
  str_skill_passive_desc_410088 = "Aumenta el daño del Combo en Cadena de Maggie en <color=#00F6FF>{1}</color> después de cada <color=#00F6FF> 10 </color> combos.",
  str_skill_passive_desc_420088 = "Aumenta el daño del Combo en Cadena de Maggie en <color=#00F6FF>{1}</color> después de cada <color=#00F6FF>10</color> combos y reduce el número de casillas que activan el combo en <color=#00F6FF>1</color>.",
  str_skill_passive_desc_430088 = "Aumenta el daño del Combo en Cadena de Maggie en <color=#00F6FF>{1}</color> después de cada <color=#00F6FF>8</color> combos y reduce el número de casillas que activan el combo en <color=#00F6FF>1</color>.",
  str_skill_passive_desc_400084 = "Después de usar un Combo en Cadena, reduce el ATQ de los enemigos dentro de <color=#00F6FF>1 cúmulo circundante </color> de la unidad en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410084 = "Después de usar un Combo en Cadena, reduce el ATQ de los enemigos dentro de <color=#00F6FF>1 cúmulo circundante </color> de la unidad en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420084 = "Después de usar un Combo en Cadena, reduce el ATQ de los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> de la unidad en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400090 = "Aumenta el daño de Barbara en <color=#00F6FF>{1}</color> contra los enemigos que ocupan una casilla roja.",
  str_skill_passive_desc_410090 = "Aumenta el daño de Barbara en <color=#00F6FF>{1}</color> contra los enemigos que ocupan una casilla roja.",
  str_skill_passive_desc_430090 = "Aumenta el daño de Bárbara contra los enemigos que ocupan una casilla roja en <color=#00F6FF>{1}</color>. También otorga a los compañeros de equipo de Fire Aurorian <color=#00F6FF>50%</color> de ese bono.",
  str_skill_passive_desc_400045 = "El ATQ y la DEF de Nails aumenta a medida que disminuye su porcentaje de PS, lo que le otorga una bonificación de hasta <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410045 = "El ATQ y la DEF de Nails aumenta a medida que disminuye su porcentaje de PS, lo que le otorga una bonificación de hasta <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400081 = "Después de usar una Habilidad Activa, aumenta el ATQ de los Aurorians de fuego igual al <color=#00F6FF>{1}</color> del ATQ de Brock por cada enemigo dentro de <color=#00F6FF>1 cúmulo circundante</color> de la unidad.",
  str_skill_passive_desc_410081 = "Después de usar una Habilidad Activa, aumenta el ATQ de los Aurorians de fuego igual al <color=#00F6FF>{1}</color> del ATQ de Brock por cada enemigo dentro de <color=#00F6FF>1 cúmulo circundante</color> de la unidad.",
  str_skill_passive_desc_430081 = "Después de usar una Habilidad Activa, aumenta el ATQ de los Aurorians de fuego igual al <color=#00F6FF>{1}</color> del ATQ de Brock por cada enemigo dentro de <color=#00F6FF>2 cúmulos circundantes </color> de la unidad.",
  str_skill_passive_desc_400083 = "Las habilidades activas tienen una <color=#00F6FF>{1}</color> probabilidad de reducir el alcance de movimiento de los enemigos en un <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_410083 = "Las habilidades activas tienen una <color=#00F6FF>{1}</color> probabilidad de reducir el alcance de movimiento de los enemigos en un <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_430083 = "Las habilidades activas tienen una <color=#00F6FF>{1}</color> probabilidad de reducir el alcance de movimiento de los enemigos en un <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_400059 = "Otorga hasta <color=#00F6FF>{1}</color> pilas (s) de <link=\"30002\"><#FFAE07><u> Marca Pepi </u></color></link>. El rango de movimiento de la Habilidad Activa se convierte en un número de cúmulos alrededor de la unidad igual a las pilas de la marca. Activar la Habilidad Activa borra todas las pilas.",
  str_skill_passive_desc_410059 = "Otorga hasta <color=#00F6FF>{1}</color> pilas (s) de <link=\"30002\"><#FFAE07><u> Marca Pepi </u></color></link>. El rango de movimiento de la Habilidad Activa se convierte en un número de cúmulos alrededor de la unidad igual a las pilas de la marca. Activar la Habilidad Activa borra todas las pilas.",
  str_skill_passive_desc_420059 = "Otorga hasta <color=#00F6FF>{1}</color> pilas (s) de <link=\"30003\"><#FFAE07><u> Marca Pepi </u></color></link>. El rango de movimiento de la Habilidad Activa se convierte en un número de cúmulos alrededor de la unidad igual a las pilas de la marca. Activar la Habilidad Activa borra todas las pilas.",
  str_skill_passive_desc_400080 = "Cuando no hay enemigos dentro del alcance de Combo en Cadena, recupera los PS de los equipos igual al <color=#00F6FF>{1}</color> del ATQ de Unimet.",
  str_skill_passive_desc_410080 = "Cuando no hay enemigos dentro del alcance de Combo en Cadena, recupera los PS de los equipos igual al <color=#00F6FF>{1}</color> del ATQ de Unimet.",
  str_skill_passive_desc_400093 = "Después de lanzar un combo en cadena o una habilidad activa, si el HP del objetivo es inferior a <color=#00F6FF>{1}</color>, lanza 1 ataque más que inflige daño ignorando DEF igual a <color=#00F6FF>{2}</color> de ATK.",
  str_skill_passive_desc_410093 = "Después de lanzar un combo en cadena o una habilidad activa, si el HP del objetivo es inferior a <color=#00F6FF>{1}</color>, lanza 1 ataque más que inflige daño ignorando DEF igual a <color=#00F6FF>{2}</color> de ATK.",
  str_skill_passive_desc_430093 = "Después de activar un combo en cadena o una habilidad activa, si el HP del objetivo es inferior a <color=#00F6FF>{1}</color>, lanza 1 ataque más que inflige daño ignorando DEF igual a <color=#00F6FF>{2}</color> de ATK. Si el HP del objetivo es menor que el ATK de Migard después del ataque adicional, muere.",
  str_skill_passive_desc_400097 = "Los ataques normales se convierten en ataques de 2-combo que infligen <color=#00F6FF>{1}</color> daño básico en cada golpe.",
  str_skill_passive_desc_410097 = "Los ataques normales se convierten en ataques de 2-combo que infligen <color=#00F6FF>{1}</color> daño básico en cada golpe.",
  str_skill_passive_desc_420097 = "Los ataques normales se convierten en 2-combo que infligen <color=#00F6FF>{1}</color> daño básico en cada golpe. Cada ataque tiene un <color=#00F6FF> 20% </color> de probabilidad de infligir un <color=#00F6FF> 50% </color> de daño adicional.",
  str_skill_passive_desc_430097 = "Los ataques normales se convierten En 2-combo que infligen <color=#00F6FF>{1}</color> daño básico en cada golpe. Cada ataque tiene un <color=#00F6FF> 20% </color> de probabilidad de infligir un <color=#00F6FF> 50% </color> de daño adicional. Cada combo aumenta la probabilidad de activación en un 0,5%, hasta un 50%.",
  str_skill_passive_desc_400095 = "Cuando infliges daño a un enemigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada pila de Veneno aumenta el daño final en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410095 = "Cuando infliges daño a un enemigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada pila de Veneno aumenta el daño final en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420095 = "Cuando infliges daño a un enemigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada pila de Veneno aumenta el daño final en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430095 = "Cuando infliges daño a un enemigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada pila de Veneno aumenta el daño final en <color=#00F6FF>{1}</color>. Cuando una Habilidad Activa o un Combo en Cadena golpea a un objetivo Envenenado, la unidad recibe 1 pila adicional de Veneno.",
  str_skill_passive_desc_400062 = "Cuando un ataque normal, combo en cadena o Habilidad Activa inflige daño a solo 1 enemigo, este daño ignora <color=#00F6FF>{1}</color> de la DEF del objetivo",
  str_skill_passive_desc_410062 = "Cuando un ataque normal, combo en cadena o Habilidad Activa inflige daño a solo 1 enemigo, este daño ignora <color=#00F6FF>{1}</color> de la DEF del objetivo.",
  str_skill_passive_desc_430062 = "Cuando el ataque normal, el combo en cadena o la habilidad activa infligen daño a solo 1 enemigo, este daño ignora <color=#00F6FF>{1}</color> de la DEF del objetivo. Cuando solo hay 1 enemigo en el tablero, las Habilidades Activas de otros Aurorianos del Bosque en el equipo también obtienen un 50% de este efecto.",
  str_skill_passive_desc_400024 = "Los ataques normales infligen un daño adicional <color=#00F6FF>{1}</color> a los enemigos que ocupan casillas rojas.",
  str_skill_passive_desc_410024 = "Los ataques normales infligen un daño adicional <color=#00F6FF>{1}</color> a los enemigos que ocupan casillas rojas.",
  str_skill_passive_desc_400087 = "Cuando un Combo en cadena golpea a un objetivo, también inflige daño a <color=#00F6FF>{1}</color> objetivo(s) aleatorios (cada objetivo solo puede recibir daño una vez) dentro de <color=#00F6FF>1 cúmulo circundante</color> del objetivo. El daño disminuye en <color=#00F6FF>{2}</color>con cada golpe.",
  str_skill_passive_desc_410087 = "Cuando un Combo en cadena golpea a un objetivo, también inflige daño a <color=#00F6FF>{1}</color> objetivo(s) aleatorios (cada objetivo solo puede recibir daño una vez) dentro de <color=#00F6FF>1 cúmulo circundante</color> del objetivo. El daño disminuye en <color=#00F6FF>{2}</color>con cada golpe.",
  str_skill_passive_desc_420087 = "Cuando un Combo en cadena golpea a un objetivo, también inflige daño a <color=#00F6FF>{1}</color> objetivo(s) aleatorios (cada objetivo solo puede recibir daño una vez) dentro de <color=#00F6FF> 2 cúmulos circundantes </color>del objetivo. El daño disminuye en <color=#00F6FF>{2}</color> con cada golpe.",
  str_skill_passive_desc_400101 = "Aumenta el daño que Ansia inflige a los enemigos a lo largo del borde del campo de batalla (la bonificación de daño es mayor cuando los enemigos están en la esquina), hasta un aumento de <color=#00F6FF>{1}</color> daño final.",
  str_skill_passive_desc_410101 = "Aumenta el daño que Ansia inflige a los enemigos a lo largo del borde del campo de batalla (la bonificación de daño es mayor cuando los enemigos están en la esquina), hasta un aumento de <color=#00F6FF>{1}</color> daño final.",
  str_skill_passive_desc_400102 = "Becas 1 Tessa Marca cada vez que un Thunder Aurorian en el equipo usa su habilidad activa. Al usar la Habilidad Activa, cada marca reparte <color=#00F6FF>{1}</color> daño a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>. Activar la habilidad activa borra todas las marcas.",
  str_skill_passive_desc_410102 = "Becas 1 Tessa Marca cada vez que un Thunder Aurorian en el equipo usa su habilidad activa. Al usar la Habilidad Activa, cada marca reparte <color=#00F6FF>{1}</color> daño a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>. Activar la habilidad activa borra todas las marcas.",
  str_skill_passive_desc_420102 = "Becas 1 Tessa Marca cada vez que un Thunder Aurorian en el equipo usa su Habilidad Activa o cuando Tessa usa un combo en cadena. Al usar la Habilidad Activa, cada marca reparte <color=#00F6FF>{1}</color> daño a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>. Activar la habilidad activa borra todas las marcas.",
  str_skill_passive_desc_430102 = "Becas 1 Tessa Marca cada vez que un Thunder Aurorian en el equipo usa su Habilidad Activa o cuando Tessa usa un combo en cadena. Al usar la Habilidad Activa, cada marca reparte <color=#00F6FF>{1}</color> DEF-ignorando el daño a los enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. Activar la habilidad activa borra todas las marcas.",
  str_skill_passive_desc_400099 = "Al controlar la espada mágica, los ataques normales penetrarán a través de los enemigos e infligirán <color=#00F6FF>{1}</color> de daño al objetivo 1 casilla detrás del enemigo.",
  str_skill_passive_desc_410099 = "Al controlar la espada mágica, los ataques normales penetrarán a través de los enemigos e infligirán <color=#00F6FF>{1}</color> de daño al objetivo 1 casilla detrás del enemigo.",
  str_skill_passive_desc_400100 = "Cuando Sikare ataca a los enemigos por primera vez, cosecha el alma del objetivo e inflige un daño equivalente a <color=#00F6FF>{1}</color> de ATQ a ese enemigo (este daño ignora la DEF).",
  str_skill_passive_desc_410100 = "Cuando Sikare ataca a los enemigos por primera vez, cosecha el alma del objetivo e inflige un daño equivalente a <color=#00F6FF>{1}</color> de ATQ a ese enemigo (este daño ignora la DEF).",
  str_skill_passive_desc_430100 = "Cuando Sikare ataca a los enemigos por primera vez, cosecha el alma del objetivo e inflige un daño equivalente al <color=#00F6FF>{1}</color> de ATQ más un daño que ignora la DEF igual al <color=#00F6FF>5%</color> de PS actual a ese enemigo.",
  str_skill_passive_desc_400098 = "Cuando un Combo en Cadena golpea a un enemigo, inflige 1 pila de Marca de desmembramiento. Acumula hasta 5 veces. Cada pila de Marca incrementa el daño de Cuscuta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410098 = "Cuando un Combo en Cadena golpea a un enemigo, inflige 1 pila de Marca de desmembramiento. Acumula hasta 5 veces. Cada pila de Marca incrementa el daño de Cuscuta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420098 = "Cuando un Combo en Cadena golpea a un enemigo, inflige 1 pila de Marca de desmembramiento. Acumula hasta 5 veces. Cada pila de Marca incrementa el daño de Cuscuta en <color=#00F6FF>{1}</color>. Los ataques normales tienen un <color=#00F6FF>30%</color> de probabilidad de infligir 1 pila de Marca de Desmembramiento.",
  str_skill_passive_desc_4200981 = "Cuando un Chain Combo golpea a un enemigo, inflige 1 acumulación de Dismember Mark. Se acumula hasta 10 veces. Cada acumulación de Dismember Mark aumenta el daño de Cuscuta en <color=#00F6FF>6%</color>. Los ataques normales tienen un <color=#00F6FF>30%</color> posibilidad de infligir 1 acumulación de Dismember Mark.",
  str_skill_passive_desc_400094 = "Después de que un Combo en Cadena golpea al objetivo, reduce el ATQ del objetivo en <color=#00F6FF>{1}</color> durante 1 ronda.",
  str_skill_passive_desc_410094 = "Después de que un Combo en Cadena golpea al objetivo, reduce el ATQ del objetivo en <color=#00F6FF>{1}</color> durante 1 ronda.",
  str_skill_passive_desc_400096 = "Otorga una <link=\"30013\"><#FFAE07> <u> Marca Sariel </u></color></link>, hasta 8 pilas. Cada pila aumenta la DEF de Sariel en <color=#00F6FF>{1}</color>. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_410096 = "Otorga una <link=\"30013\"><#FFAE07> <u> Marca Sariel </u></color></link>, hasta 8 pilas. Cada pila aumenta la DEF de Sariel en <color=#00F6FF>{1}</color>. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_420096 = "Otorga una <link=\"30013\"><#FFAE07> <u> Marca Sariel </u></color></link>, hasta 8 pilas. Cada pila aumenta la DEF de Sariel en <color=#00F6FF>{1}</color>, aumentando hasta un <color=#00F6FF> 50% </color> DEF según la cantidad de PS perdida. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_400056 = "Cuando un ataque normal o una Habilidad Activa inflige daño (lo que sea mayor), convierte <color=#00F6FF>{1}</color> del daño en ATQ. Solo válido para la ronda actual.",
  str_skill_passive_desc_410056 = "Cuando un ataque normal o una Habilidad Activa inflige daño (lo que sea mayor), convierte <color=#00F6FF>{1}</color> del daño en ATQ. Solo válido para la ronda actual.",
  str_skill_passive_desc_430056 = "Cuando un ataque normal o una Habilidad Activa inflige daño (lo que sea mayor), convierte <color=#00F6FF>{1}</color> del daño en ATQ. Solo válido para la ronda actual. Cuando solo hay 1 enemigo en el campo, aumenta el ATQ de los Aurorians de agua en <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_400103 = "Cada 3 rondas, Hollow se puede activar o guardar para uso futuro. Después de convertirse en Hollow, el daño de Combo en cadena ignora la defensa e inflige un daño igual al <color=#00F6FF>{1}</color> del ATQ de Eicy, y recupera PS en la misma cantidad.",
  str_skill_passive_desc_410103 = "Cada 3 rondas, Hollow se puede activar o guardar para uso futuro. Después de convertirse en Hollow, el daño de Combo en cadena ignora la defensa e inflige un daño igual al <color=#00F6FF>{1}</color> del ATQ de Eicy, y recupera PS en la misma cantidad.",
  str_skill_passive_desc_430103 = "Otorga el estado de Vacío una vez cada 3 rondas (si no se usa, este estado se conserva). Cuando está en el estado Vacío, Combo en Cadena inflige daño igual al <color=#00F6FF>{1}</color> del ATQ de Eicy (este daño ignora la DEF) y restaura PS por la misma cantidad. Entre más bajo sea los PS del equipo, mayor será la efectividad curativa (hasta <color=#00F6FF>50%</color>).",
  str_skill_passive_desc_410067 = "Si se ha recuperado PS en esta ronda, la DEF básica de Alice aumenta en <color=#00F6FF>{1}</color> para esta ronda.",
  str_skill_passive_desc_430067 = "Si se ha recuperado PS en esta ronda, la DEF básica de Alice aumenta en <color=#00F6FF>{1}</color> para esta ronda.",
  str_skill_passive_desc_400030 = "Los ataques normales <color=#00F6FF> pueden impactar en diagonal </color>. Los ataques diagonales normales afligen al objetivo con 1 pila de Shatter, que se acumula hasta 5 veces. Cada pila reduce la DEF del objetivo en una cantidad igual a <color=#00F6FF>{1}</color> de la DEF básica de Sinsa durante 1 ronda.",
  str_skill_passive_desc_410030 = "Los ataques normales <color=#00F6FF> pueden impactar en diagonal </color>. Los ataques diagonales normales afligen al objetivo con 1 pila de Shatter, que se acumula hasta 5 veces. Cada pila reduce la DEF del objetivo en una cantidad igual a <color=#00F6FF>{1}</color> de la DEF básica de Sinsa durante 1 ronda.",
  str_skill_passive_desc_430030 = "Los ataques normales <color=#00F6FF> pueden impactar en diagonal </color>. Los ataques diagonales normales, las habilidades activas y los combos en cadena afectan al objetivo con 1 pila de destrucción, que se acumula hasta 5 veces. Cada pila reduce la DEF del objetivo en una cantidad igual a <color=#00F6FF>{1}</color> de la DEF básica de Sinsa por 1 ronda.",
  str_skill_passive_desc_410104 = "Las Habilidades Activas marcan el objetivo del ataque. Cuando las Habilidades Activas y los Combos en Cadena de Dawn atacan a enemigos marcados, la marca se consume y restaura HP igual al <color=#00F6FF>{1}</color> del daño infligido.",
  str_skill_passive_desc_430104 = "Las Habilidades Activas marcan el objetivo del ataque. Cuando las Habilidades Activas y los Combos en cadena atacan a enemigos marcados, la marca se consume y restaura PS igual al <color=#00F6FF>{1}</color> del daño infligido. Si el equipo tiene PS al máximo, el daño final de este ataque aumentará en un <color=#00F6FF>25%</color>.",
  str_skill_passive_desc_410071 = "Al comienzo de cada ronda, aplica una Marca de Quemadura al enemigo con el mayor porcentaje de PS, aumentando todo el daño que Taki inflige al objetivo en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430071 = "Al comienzo de cada ronda, aplica una marca de quemadura al enemigo con el mayor porcentaje de HP, lo que aumenta todo el daño. Taki reparte al objetivo por <color=#00F6FF>{1}</color>. Cada vez que se elimina un enemigo afectado por Burn Mark, el ATK de Taki aumenta en <color=#00F6FF>3%</color>, hasta un máximo de <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_400105 = "Cuando los ataques normales, los combos en cadena y las habilidades activas infligen daño, cada <color=#00F6FF>10</color> instancia de daño también inflige <color=#00F6FF>{1}</color> daño una vez a <color=#00F6FF>todos</color> los enemigos.",
  str_skill_passive_desc_410105 = "Cuando los ataques normales, los combos en cadena y las habilidades activas infligen daño, cada <color=#00F6FF>10</color> instancia de daño también inflige <color=#00F6FF>{1}</color> daño una vez a <color=#00F6FF>todos</color> los enemigos.",
  str_skill_passive_desc_420105 = "Cuando los ataques normales, los combos en cadena y las habilidades activas infligen daño, cada <color=#00F6FF>8</color> instancia de daño también inflige <color=#00F6FF>{1}</color> daño una vez a <color=#00F6FF>todos</color> los enemigos.",
  str_skill_passive_desc_430105 = "Cuando los ataques normales, los combos en cadena y las habilidades activas infligen daño, cada <color=#00F6FF>8</color> instancia de daño también inflige <color=#00F6FF>{1}</color> daño una vez a <color=#00F6FF>todos</color> los enemigos.",
  str_skill_passive_desc_430109 = "Gana <color=#00F6FF>5</color> Vis al comienzo de cada ronda.",
  str_skill_passive_desc_433109 = "Gana <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Obtiene <color=#00F6FF>1</color> Vis por el primer ataque normal lanzado en cada ronda y aumenta el daño infligido por este ataque normal en un <color=#00F6FF> 100%</color>.",
  str_skill_passive_desc_430110 = "Obtienes <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Ataques normales tienen un <color=#00F6FF> 30% </color> de probabilidad de lanzar 1 rayo para golpear al enemigo más lejano.",
  str_skill_passive_desc_433110 = "Obtienes <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Ataques normales tienen un <color=#00F6FF> 2 </color> Vis extra al matar a un objetivo con una Habilidad Activa. Los ataques normales tienen un <color=#00F6FF> 30% </color> de probabilidad de lanzar 1 rayo para golpear al enemigo más lejano.",
  str_skill_passive_desc_430107 = "Gana 10 Vis al comienzo la batalla. Al finalizar la ronda en un estado no aumentado, gana <color=#00F6FF>5</color> Vis (gana 1 Vis extra por cada 20% de PS perdido).",
  str_skill_passive_desc_436107 = "Obtiene 10 Vis al comienzo de la batalla. Al inicio de cada ronda, por cada 1 enemigo que exista <color=#00F6FF>en 4 casillas en forma de cruz </color> alrededor, gana <color=#00F6FF>1</color> Vis. Al finalizar la ronda en un estado no aumentado, gana <color=#00F6FF>5</color> Vis (gana 1 Vis extra por cada 20% de PS perdido).",
  str_skill_passive_desc_430108 = "Obtienes <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Ganas <color=#00F6FF>5</color> Vis adicionales al matar a un objetivo con una Habilidad Activa.",
  str_skill_passive_desc_400116 = "Todo el daño que Fleur inflige a los enemigos con menos del 40% de su PS máximo aumenta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410112 = "Smokey activa el <color=#00F6FF> Beso de Mantícora </color> <color=#00F6FF> cada vez </color> que ataca a cada enemigo con una <color=#00F6FF> Habilidad Activa o Combo en Cadena, o la primera vez que los golpea con un ataque básico en cada ronda </color>, que inflige daño adicional que ignora DEF igual a <color=#00F6FF>{1}</color> ATQ. Este efecto disminuye cuando se activa repetidamente, hasta un mínimo del <color=#00F6FF> 20% </color> de su daño inicial.",
  str_skill_passive_desc_420112 = "Smokey disparadores <color=#00F6FF>Beso de Mantícora</color> <color=#00F6FF>cada vez</color> ella ataca a un enemigo con un <color=#00F6FF>Habilidad activa o Combo en cadena, o la primera vez que los golpea con un ataque normal en cada ronda</color>, infligiendo daño adicional que ignora DEF igual a <color=#00F6FF>{1}</color> ATQ. Este efecto disminuye cuando se activa repetidamente, hasta un mínimo de <color=#00F6FF>20%</color> de su daño inicial. <color=#00F6FF>Beso de Mantícora</color> ofertas <color=#00F6FF>doble</color> daño a los enemigos en los mosaicos rojos.",
  str_skill_passive_desc_430112 = "Smokey disparadores <color=#00F6FF>Beso de Mantícora</color> <color=#00F6FF>cada vez</color> ella ataca a un enemigo con un <color=#00F6FF>Habilidad activa o Combo en cadena, o la primera vez que los golpea con un ataque normal en cada ronda</color>, infligiendo daño adicional que ignora DEF igual a <color=#00F6FF>{1}</color> ATQ. Este efecto disminuye cuando se activa repetidamente, hasta un mínimo de <color=#00F6FF>20%</color> de su daño inicial. <color=#00F6FF>Beso de Mantícora</color> ofertas <color=#00F6FF>doble</color> daño a los enemigos en los mosaicos rojos.",
  str_skill_passive_desc_400113 = "Obtiene una Marca Divina al comienzo de la batalla o al usar una Habilidad Activa. Mientras exista esta marca, la DEF de Bonacie aumenta en <color=#00F6FF>{1}</color>. Esta marca desaparece una vez que Bonacie pierde PS.",
  str_skill_passive_desc_410113 = "Obtiene una Marca Divina al comienzo de la batalla o al usar una Habilidad Activa. Mientras exista esta marca, la DEF de Bonacie aumenta en <color=#00F6FF>{1}</color>. Esta marca desaparece una vez que Bonacie pierde PS.",
  str_skill_passive_desc_420113 = "Obtiene una Marca Divina al comienzo de la batalla o al usar una Habilidad Activa. Mientras exista esta marca, la DEF de Bonacie aumenta en <color=#00F6FF>{1}</color>. Esta marca desaparece una vez que Bonacie pierde PS. Cuando existe esta marca, el daño de Combo en Cadena infligido por Aurorians de Trueno aumenta en un <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_400114 = "Cuando una Habilidad Activa inflige daño, recupera los PS del equipo en una cantidad igual al <color=#00F6FF>{1}</color> del daño infligido.",
  str_skill_passive_desc_410114 = "Cuando una Habilidad Activa inflige daño, recupera los PS del equipo en una cantidad igual al <color=#00F6FF>{1}</color> del daño infligido.",
  str_skill_passive_desc_430114 = "Cuando una Habilidad Activa inflige daño, recupera los PS del equipo en una cantidad igual a <color=#00F6FF>{1}</color> del daño infligido y aumenta el daño de Combo en Cadena infligido por los Aurorians de fuego en un <color=#00F6FF>10%</color> esta ronda.",
  str_skill_passive_desc_410127 = "Al inicio de cada ronda, si hay enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color>, lanza una daga a 1 enemigo cualquiera, infligiendo <color=#00F6FF>{1}</color> daño e inflige 1 pila de <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> por 2 rondas.",
  str_skill_passive_desc_430127 = "Al comienzo de cada ronda, si hay enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color>, lanza una daga a cualquier enemigo, lo que inflige <color=#00F6FF>{1}</color> e daño e inflige 1 pila de <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> durante 2 rondas. La daga se activará al pasar por grullas de papel.",
  str_skill_desc_3351221 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color> centradas en 1 casilla seleccionada. El daño infligido a la casilla seleccionada ignora la DEF. Elimina los efectos de <color=#00F6FF>casilla dañada</color> de las casillas en este tramo. Cuando Bendición llega a 10 pilas, el alcance de la Habilidad Activa se convierte en el <color=#00F6FF>máximo espacio en forma radial</color>.",
  str_skill_passive_desc_410117 = "Puede acumular <link=\"30016\"><#FFAE07><u>Furia</u> </color></link>. Cada pila de Furia aumenta el ATQ básico de Gram en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430117 = "Puede acumular <link=\"30017\"><#FFAE07><u>Furia</u></color></link>. Cada pila de Furia aumenta el ATQ básico de Gram en <color=#00F6FF>{1}</color>. No hay límite para la cantidad de Furia que se puede ganar con su Habilidad Activa. Este efecto se eliminará al final de cada oleada. Por cada pila despejada, Gram se recuperará por una cantidad igual al <color=#00F6FF>5%</color> de su Max PS.",
  str_skill_passive_desc_410119 = "Puede acumular <link=\"30018\"><#FFAE07><u>Corazón Intrépido</u></color></link>. Cada pila de Corazón intrépido aumenta el ATQ básico de Revy en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420119 = "Puede acumular <link=\"30018\"><#FFAE07><u>Corazón Intrépido</u></color></link>. Cada pila de Corazón intrépido aumenta el ATQ básico de Revy en <color=#00F6FF>{1}</color> y el daño de la Habilidad Activa en un <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430119 = "Puede acumular <link=\"30018\"><#FFAE07><u>Corazón Intrépido</u></color></link>. Cada pila de Corazón intrépido aumenta el ATQ básico de Revy en <color=#00F6FF>{1}</color> y el daño de la Habilidad Activa en un <color=#00F6FF>5%</color>. Los ataques normales <color=#00F6FF> pueden impactar en diagonal</color>.",
  str_skill_passive_desc_410122 = "Puede Obtener <link=\"30019\"><#FFAE07><u> Bendición</u> </color></link>. Cada pila de Bendición aumenta el daño de la Habilidad Activa de Allura en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410121 = "Siempre que pases por una <link=\"20001\"><#FFAE07><u>Casilla Mejorada</u></color></link>, obtienes 1 pila de Marca de Púas. Cada pila aumenta el daño de la cadena en <color=#00F6FF>{1}</color>. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_430121 = "Siempre que pases por una <link=\"20001\"><#FFAE07><u>Casilla Mejorada</u></color></link>, obtienes 1 pila de Marca de Púas. Cada pila aumenta el daño de Combo en Cadena y Ataque normal en <color=#00F6FF>{1}</color>. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_410065 = "Cada golpe de Combo en Cadena otorga 1 pila de marca de Snowpuff. Cada pila aumenta la DEF en <color=#00F6FF>{1}</color>. La marca desaparece al final de la ronda.",
  str_skill_passive_desc_410115 = "Siempre que atraviese una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>, obtiene 1 pila de Marca Esmeralda. Cada pila otorga <color=#00F6FF>{1}</color> del ATQ básico de Naroxel. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_430115 = "Siempre que atraviese una <link=\"20001\"><#FFAE07><u>casilla mejorada</u></color></link>, obtiene 1 pila de Marca Esmeralda. Cada pila otorga a todo tu equipo <color=#00F6FF>{1}</color> del ATQ básico de Naroxel. Retiene el 50% de las pilas al final de la ronda.",
  str_skill_passive_desc_410126 = "Invoca a <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> a la casilla seleccionada por tu Habilidad Activa. Cada vez que una unidad usa una Habilidad Activa, Frankel desata un <color=#00F6FF>Rugido</color>, infligiendo <color=#00F6FF>{1}</color> de daño a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>. Frankel también desata un <color=#00F6FF>Rugido</color> al desaparecer.",
  str_skill_passive_desc_420126 = "Invoca a <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> a la casilla seleccionada por tu Habilidad Activa. Cada vez que una unidad usa una Habilidad Activa, Frankel desata un <color=#00F6FF>Rugido</color>, infligiendo <color=#00F6FF>{1}</color> daño a los enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>. Si solo hay un enemigo dentro del alcance, desata <color=#00F6FF>Garra Desgarradora</color>, aumentando el daño en <color=#00F6FF>50%</color>. Frankel también desata un <color=#00F6FF>Rugido</color> al desaparecer.",
  str_skill_passive_desc_410129 = "Las Habilidades Activas y los Combos en Cadena infligen 1 pila de Marca Parasitaria cada vez que infligen daño. Marca Parasitaria se acumula hasta <color=#00F6FF>9</color> veces. Cada vez que un enemigo se mueve 1 casilla, cada pila de Marca Parasitaria inflige <color=#00F6FF>{1}</color> de daño.",
  str_skill_passive_desc_420129 = "Las Habilidades Activas y los Combos en Cadena infligen 1 pila de Marca Parasitaria cada vez que infligen daño. Marca Parasitaria se acumula hasta <color=#00F6FF>9</color> veces. Cada vez que un enemigo se mueve 1 casilla, cada pila de Marca Parasitaria inflige <color=#00F6FF>{1}</color> de daño. Los ataques normales y los Combos en Cadena de Luke infligen un <color=#00F6FF>30%</color> más de daño a los enemigos afectados por el mayor número de pilas de Marca Parasitaria.",
  str_skill_passive_desc_430129 = "Las Habilidades Activas y los Combos en Cadena infligen 1 pila de Marca Parasitaria cada vez que infligen daño. Marca Parasitaria se acumula hasta <color=#00F6FF>9</color> veces. Cada vez que un enemigo se mueve 1 casilla, cada pila de Marca Parasitaria inflige <color=#00F6FF>{1}</color> de daño. Este daño aumenta a <color=#00F6FF>{2}</color> para el enemigo con el mayor número de pilas en el campo de batalla. Los ataques normales y los Combos en Cadena de Luke infligen un <color=#00F6FF>30%</color> más de daño a los enemigos afectados por el mayor número de pilas de Marca Parasitaria.",
  str_skill_passive_desc_410055 = "Cuando es atacado, gana 1 pila de Marca de batalla. Puede apilarse hasta <color=#00F6FF>15</color> veces. Cada pila de Marca de batalla aumenta el ATQ en <color=#00F6FF>{1}</color>. Las pilas de Marca de Batalla disminuyen un 50% en cada ronda.",
  str_skill_passive_desc_420055 = "Cuando es atacado, gana 1 marca de batalla. Puede apilarse hasta <color=#00F6FF>15</color> veces. Cada pila de marcas de batalla aumenta el ATQ y DEF en <color=#00F6FF>{1}</color>. Las pilas de marca de batalla disminuyen un 50% cada ronda.",
  str_skill_passive_desc_430055 = "Cuando es atacado, gana 1 pila de Marca de batalla. Puede apilarse hasta <color=#00F6FF>15</color> veces. Cada pila de Marca de batalla aumenta el ATQ y la DEF en <color=#00F6FF>{1}</color>. Las pilas de Marca de Batalla disminuyen en un 50% en cada ronda. Por cada pila de Marca de batalla perdida, gana un escudo equivalente al <color=#00F6FF>12%</color> del PS máximo de Pittman.",
  str_skill_passive_desc_410120 = "Al usar Combos en Cadena y Habilidades Activas, Pompey aparecerá y atacará en lugar de Hedy. El ATQ de Pompey es igual <color=#00F6FF>{1}</color> al ATQ de Hedy.",
  str_skill_passive_desc_430120 = "Al usar Combos en Cadena y Habilidades Activas, Pompey aparecerá y atacará en lugar de Hedy. El ATQ de Pompey es igual <color=#00F6FF>{1}</color> al ATK de Hedy. Durante Hora de Aurora, el ATQ de Pompey aumenta en un <color=#00F6FF>2%</color> conexión de casilla , hasta un máximo del <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410123 = "Por cada 1 enemigo en un <color=#00F6FF>radio de 12 casillas en forma de diamante</color>, el ATQ aumenta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430123 = "Por cada 1 enemigo dentro de <color=#00F6FF>2 grupos</color>, ATQ y DEF aumentan en<color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410015 = "Por cada granada de racimo que viaja antes de que la Habilidad Activa inflija daño, el daño final aumenta en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420015 = "Por cada granada de racimo que viaja antes de que la Habilidad Activa inflija daño, el daño final aumenta en <color=#00F6FF>{1}</color>. Por cada granada de racimo que viaja antes de que Combo en Cadena inflija daño, el daño final aumenta en <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410131 = "Si el equipo no tiene PS completo antes de usar un ataque normal, el efecto de este ataque normal restaurará PS igual al <color=#00F6FF>{1}</color>ATQ de Novio.",
  str_skill_passive_desc_430131 = "Si el equipo no tiene PS completo antes de usar un ataque normal, el efecto de este ataque normal restaurará PS igual al <color=#00F6FF>{1}</color>ATQ de Novio. Si el equipo tiene PS al máximo, este ataque y su daño de Combo en cadena aumentarán en un <color=#00F6FF>10%</color>. Bono de daño aumentará <color=#00F6FF>25%</color> si ya existe un escudo.",
  str_skill_passive_desc_410132 = "Durante la Hora de Aurora, el ATQ se incrementa en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430132 = "Durante la Hora de Aurora, el ATQ se incrementa en <color=#00F6FF>{1}</color>, y desencadena el Combo en Cadena al pasar por cualquier casillas. El daño del Combo en Cadena siempre se considerará como el elemento del Bosque.",
  str_skill_passive_desc_410133 = "Cada combo aumenta el daño del Combo en Cadena en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430133 = "Cada Combo aumenta el Daño de Combo en Cadena en <color=#00F6FF>{1}</color> y el Daño de Salpicadura en <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410137 = "Cuando la Habilidad Activa inflige daño a un enemigo seleccionado, por cada <color=#00F6FF>1</color> casilla azul a los pies del enemigo, inflige <color=#00F6FF>{1}</color> del daño de ATQ de Fafnir.",
  str_skill_passive_desc_430137 = "Cuando la Habilidad Activa inflige daño a un enemigo seleccionado, por cada <color=#00F6FF>1</color> casilla azul a los pies del enemigo, inflige <color=#00F6FF>{1}</color> del daño de ATQ de Fafnir. La Habilidad Activa de otros personajes de Dragon Maid también activará este efecto de daño cuando golpee a un enemigo.",
  str_skill_passive_desc_410134 = "Kanna gana 3 cargas al usar su Habilidad Activa y 1 carga cuando cualquier Aurorian de Trueno o personaje de Dragon Maid usa sus Habilidades Activas, hasta 10 cargas. Cada carga aumenta el ATQ básico en <color=#00F6FF>{1}</color>, y se eliminará al fin de la ronda.",
  str_skill_passive_desc_430134 = "Kanna gana 3 cargas al usar su Habilidad Activa y 1 carga cuando cualquier Aurorian de Trueno o personaje de Dragon Maid usa sus Habilidades Activas, hasta 10 cargas. Cada carga aumenta el ATQ básico en <color=#00F6FF>{1}</color>, y la mitad de las cargas se eliminarán al finalizar la ronda.",
  str_skill_passive_desc_416134 = "Kanna gana 3 cargas al usar su Habilidad Activa y 1 carga cuando cualquier Aurorian de Trueno o personaje de Dragon Maid usa sus Habilidades Activas, hasta 10 cargas. Cada carga aumenta el ATQ básico en <color=#00F6FF>{1}</color>, y se eliminará al fin de la ronda. Kanna gana 2 cargas al inicio de cada ronda.",
  str_skill_passive_desc_436134 = "Kanna gana 3 cargas al usar su Habilidad Activa y 1 carga cuando cualquier Aurorian de Trueno o personaje de Dragon Maid usa sus Habilidades Activas, hasta 10 cargas. Cada carga aumenta el ATQ básico en <color=#00F6FF>{1}</color>, y la mitad de las cargas se eliminarán al finalizar la ronda. Kanna gana 2 cargas al comenzar cada ola.",
  str_skill_passive_desc_410135 = "Aumenta el daño de Combo en cadena en <color=#00F6FF>{1}</color> cuando PS está lleno.",
  str_skill_passive_desc_430135 = "Aumenta el daño de ataque Normal, Combo en cadena y Habilidad Activa en <color=#00F6FF>{1}</color> cuando PS está lleno.",
  str_skill_passive_desc_410136 = "Cuando un Combo en cadena golpea a un enemigo, se inflige 1 pila de Marca de Mortalidad. Cada pila de la marca aumenta el daño de Habilidad Activa recibido por este enemigo de todos los Aurorians en <color=#00F6FF>{1}</color>. Máximo de <color=#00F6FF>10</color> pilas y dura toda la batalla.",
  str_skill_desc_200501 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF> 8 casillas en forma de X </color>.",
