  str_skill_desc_2001153 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> y a los enemigos en una <color=#00F6FF>forma de cruz hasta el alcance máx.</color>.",
  str_skill_desc_500223 = "Vani ordena energía pura para restaurar los HP de todos.",
  str_skill_desc_540223 = "Vani ordena energía pura para restaurar los PS de todos. Además, otorga 3 pilas de escudo.",
  str_skill_desc_1002410 = "Avance Radiante",
  str_skill_desc_1002411 = "Parpadeo Sin Forma",
  str_skill_desc_1002412 = "Fiesta Sin Entidad",
  str_skill_desc_1002413 = "Cancelación Sin Entidad",
  str_skill_name_1002410 = "Se teletransporta a los bordes del Alchemy Board, lejos de su equipo, y luego inicia ataques de largo alcance.",
  str_skill_name_1002411 = "Destella sin forma hasta el borde del Alchemy Board, lejos de la ubicación de tu equipo, luego realiza ataques de largo alcance. Lanza 3 Nonentities a ubicaciones aleatorias dentro de un rango específico de donde se conectan tus Aurorians.",
  str_skill_name_1002412 = "Sin forma, lanza 9 Nontidades a ubicaciones aleatorias en todo el campo de batalla.",
  str_skill_name_1002413 = "Explota cuando los Aurorians se acercan a él. Si se deja solo, explotará después de un cierto número de rondas y generará una casilla rota en su ubicación.",
  str_skill_desc_1002414 = "Explota cuando los aurorianos se le acercan. Si se deja solo, explotará después de que haya pasado una cierta cantidad de rondas y generará 1 Área de alarma que durará 2 rondas en su ubicación.",
  str_skill_desc_280043111 = "Lanza llamas a los enemigos dentro del área de ataque, infligiendo daño y quemando a los objetivos. Las casillas dentro del área se romperán.",
  str_skill_name_29106811 = "Parpadeo Sin Forma",
  str_skill_desc_29106811 = "Destella sin forma hasta el borde del Alchemy Board, lejos de la ubicación de tu equipo, luego realiza atqs de largo alcance. Lanza 2 Nonentities a ubicaciones aleatorias dentro de un rango específico de donde se conectan tus Aurorians.",
  str_skill_name_29106812 = "Parpadeo Sin Forma",
  str_skill_desc_29106812 = "Destella sin forma hasta el borde del Alchemy Board, lejos de la ubicación de tu equipo, luego realiza atqs de largo alcance. Lanza 3 Nonentities a ubicaciones aleatorias dentro de un rango específico de donde se conectan tus Aurorians.",
  str_skill_name_29106813 = "Parpadeo Sin Forma",
  str_skill_desc_29106813 = "Desplázate sin forma hasta el borde del tablero de alquimia, lejos de la ubicación de tu equipo, y luego lleva a cabo ataques de largo alcance. Lanza 1 Nonentity y 1 Chasm a ubicaciones aleatorias dentro de un rango específico de donde se conectan tus Aurorianos.",
  str_skill_name_29106814 = "Parpadeo Sin Forma",
  str_skill_desc_29106814 = "Desplázate sin forma hasta el borde del tablero de alquimia, lejos de la ubicación de tu equipo, y luego lleva a cabo ataques de largo alcance. Lanza 2 Nonentities y 1 Chasm a ubicaciones aleatorias dentro de un rango específico de donde se conectan tus Aurorians.",
  str_skill_name_29106815 = "Fiesta Sin Entidad",
