  str_skill_name_29106816 = "Fiesta Sin Entidad",
  str_skill_desc_29106816 = "Sin forma, lanza 9 Nontidades a ubicaciones aleatorias en todo el campo de batalla.",
  str_skill_name_290140110 = "Spikeyhog - Libra feroz",
  str_skill_desc_290140110 = "Gretel golpea el suelo violentamente, infligiendo daño a los objetivos dentro de 2 grupos circundantes e invocando espinas.",
  str_skill_name_290140120 = "Spikeyhog - Ataque de choque",
  str_skill_desc_290140120 = "Gretel se mueve hacia el jugador, infligiendo daño a las unidades dentro de 2 columnas frente a ella, derribando al jugador e invocando a Spikeneedle en el camino.",
  str_skill_name_290140130 = "Bautismo de reencarnación",
  str_skill_desc_290140130 = "Gretel recicla su clon antes de volver a lanzarlo, causando daño a pantalla completa.",
  str_skill_name_1020111 = "espinos",
  str_skill_desc_1020111 = "Los puercoespines debilitados desaparecerán en la siguiente ronda y, cuando se combinen con otros puercoespines, se convertirán en Hogspikes.",
  str_skill_name_1020121 = "picos de cerdo",
  str_skill_desc_1020121 = "Puercoespines afilados que se debilitan en Hogthorns en la siguiente ronda, y cuando se combinan con otros puercoespines, se convertirán en Hogthorns nuevos.",
  str_skill_name_290150110 = "Basilisco - mazo",
  str_skill_desc_290150110 = "Gretel se mueve hacia el jugador, convocando a su clon para atacar a una corta distancia frente a ella.",
  str_skill_name_290150120 = "Basilisco - Barrido de cola",
  str_skill_desc_290150120 = "El clon de Gretel realiza un barrido de cola de gran alcance, derribando al jugador más allá de su rango de ataque.",
  str_skill_name_290150130 = "Bautismo de reencarnación",
  str_skill_desc_290150130 = "Gretel recicla su clon antes de volver a lanzarlo, lo que inflige daño a pantalla completa.",
  str_skill_name_290160110 = "Pisotón de Hierro - Rompedor",
  str_skill_desc_290160110 = "Pisotea en el lugar, inflige daño a las unidades cercanas y crea mosaicos destrozados.",
  str_skill_name_290160120 = "Pisotón de hierro - Destrozo de suelo",
  str_skill_desc_290160120 = "Muévete hacia el jugador, infligiendo daño a las unidades y creando mosaicos destrozados dentro de 1 grupo circundante. Durante el movimiento, también se crean mosaicos rotos a lo largo del camino.",
  str_skill_name_290160130 = "Bautismo de reencarnación",
  str_skill_desc_290160130 = "Llama a Ironstomp para recargarlo antes de volver a soltarlo, lo que inflige daño a pantalla completa.",
  str_skill_name_290170110 = "Kittypus - Burla",
  str_skill_desc_290170110 = "Muévete hacia el jugador y abofetea a los enemigos dentro de un rango en forma de cruz con sus tentáculos, infligiendo daño.",
  str_skill_name_290170120 = "Kittypus - Abismo",
  str_skill_desc_290170120 = "Golpea a los enemigos dentro de un rango en forma de X con sus tentáculos, causando una gran cantidad de daño.",
  str_skill_name_290170130 = "Bautismo de reencarnación",
  str_skill_desc_290170130 = "Llama a Kittypus para que se recargue antes de volver a soltarlo, lo que inflige daño a pantalla completa.",
  str_skill_name_200140110 = "Tentaclaw - Escape de lesiones",
  str_skill_desc_200140110 = "Su daño sostenido se transmite a Kittypus. Cuando un Aurorian se está moviendo, tentaclaw se enroscaría para evitar ataques.",
