  str_skill_upgrade_desc_15013915 = "Mejora activa de habilidades: seleccione cualquiera de las <color=#FFFF00>8</color> direcciones.",
  str_skill_desc_300139 = "Ataques en cualquiera de los <color=#00F6FF>4</color> direcciones y ofertas <color=#00F6FF>{1}%</color> daño a los enemigos a lo largo del camino y las casillas adyacentes. Restablece todo <color=#00F6FF>no amarillo</color> losas.",
  str_skill_desc_302139 = "Ataques en cualquiera de los <color=#00F6FF>8</color> direcciones y ofertas <color=#00F6FF>{1}%</color> daño a los enemigos a lo largo del camino y las casillas adyacentes. Restablece todo <color=#00F6FF>no amarillo</color> losas.",
  str_skill_desc_320139 = "Ataques en cualquiera de los <color=#00F6FF>4</color> direcciones y ofertas <color=#00F6FF>{1}%</color> daño a los enemigos a lo largo del camino y las casillas adyacentes mientras <link=\"10004\"><#FFAE07><u>paralizante</u></color></link> 1 enemigo aleatorio a lo largo del camino. Restablece todo <color=#00F6FF>no amarillo</color> losas.",
  str_skill_desc_322139 = "Ataques en cualquiera de los <color=#00F6FF>8</color> direcciones y ofertas <color=#00F6FF>{1}%</color> daño a los enemigos a lo largo del camino y las casillas adyacentes mientras <link=\"10004\"><#FFAE07><u>paralizante</u></color></link> 1 enemigo aleatorio a lo largo del camino. Restablece todo <color=#00F6FF>no amarillo</color> losas.",
  str_skill_desc_2001391 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 columna </color>.",
  str_skill_desc_2001392 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 columnas</color>.",
  str_skill_desc_2001393 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 columnas</color>.",
  str_skill_passive_desc_410139 = "Aumenta el daño de Erica en <color=#00F6FF>{1}</color> a los enemigos en mosaicos amarillos por cada grupo de distancia.",
  str_skill_passive_desc_430139 = "Aumenta el daño de Erica en <color=#00F6FF>{1}</color> a los enemigos en mosaicos amarillos por cada grupo de distancia y otorga a los compañeros de equipo Thunder Aurorian un 50% de esa bonificación de daño.",
  str_skill_name_300138 = "Dominio de aprendiz de ocho patas",
  str_skill_name_320138 = "Dominio de aprendiz de ocho patas",
  str_skill_name_330138 = "Dominio de aprendiz de ocho patas",
  str_skill_name_2001381 = "ruptura de araña",
  str_skill_name_2001382 = "ruptura de araña",
  str_skill_name_2001383 = "ruptura de araña",
  str_skill_passive_name_410138 = "Escudo web",
  str_skill_passive_name_416138 = "Escudo web",
  str_skill_upgrade_desc_16013813 = "Mejora hab. activa: Cambia la hab. activa a <color=#FFFF00> Golpe preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16013816 = "Mejora de habilidades de equipo: al obtener un escudo de <link=\"30025\"><#FFAE07><u>marca web</u></color></link>, gana un escudo adicional igual a <color=#00F6FF>15%</color> de HP de Siobhan si hay más de 10 acumulaciones de marca.",
  str_skill_desc_300138 = "Selecciona 1 mosaico y selecciona otro mosaico para confirmar un rango de 2 × 2 o 1 × 4 y convierte los mosaicos dentro de verde.",
  str_skill_desc_320138 = "Selecciona 1 mosaico y selecciona otro mosaico para confirmar un rango de 2 × 2 o 1 × 4 y convierte los mosaicos dentro de verde. Los dos mosaicos seleccionados se convertirán en <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link>.",
  str_skill_desc_330138 = "Selecciona 1 mosaico y selecciona otro mosaico para confirmar un rango de 2 × 2 o 1 × 4 y convierte los mosaicos dentro de verde. Los dos mosaicos seleccionados se convertirán en <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link>. Durante Aurora Time, alcanza 15 combos en cadena para reducir el tiempo de reutilización de habilidades activas en <color=#00F6FF>1</color> ronda.",
  str_skill_desc_2001381 = "ofertas <color=#00F6FF>{1}%</color> daño a los 2 enemigos más cercanos dentro <color=#00F6FF>4 grupos circundantes</color>.",
  str_skill_desc_2001382 = "ofertas <color=#00F6FF>{1}%</color> daño a los 3 enemigos más cercanos dentro <color=#00F6FF>4 círculos circundantes</color>.",
  str_skill_desc_2001383 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos dentro de <color=#00F6FF> 4 cúmulos circundantes </color>.",
  str_skill_passive_desc_410138 = "Ganancias <link=\"30025\"><#FFAE07><u>marca web</u></color></link>. Borra todas las acumulaciones antes de recibir daño y gana un escudo igual a <color=#00F6FF>{1}</color> de la DEF de Siobhan por cada acumulación eliminada.",
  str_skill_passive_desc_416138 = "Ganancias <link=\"30025\"><#FFAE07><u>marca web</u></color></link>. Borra todas las acumulaciones antes de recibir daño y gana un escudo igual a <color=#00F6FF>{1}</color> de la DEF de Siobhan por cada acumulación eliminada. Si las acumulaciones de Web Mark son más de 10, gana un escudo adicional igual a <color=#00F6FF>15%</color> de HP de Siobhan al obtener escudo de <link=\"30025\"><#FFAE07><u>marca web</u></color></link>",
  str_skill_upgrade_desc_16014113 = "Mejora hab. activa: Cambia la hab. activa a <color=#FFFF00> Golpe preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16014116 = "Mejora activa de habilidades: toca la baldosa debajo de sus pies para cambiar las direcciones de retroceso y conversión de baldosas.",
  str_skill_desc_2001411 = "ofertas <color=#00F6FF>115%</color> daño a los 2 enemigos más cercanos. Si solo hay 1 objetivo enemigo, inflige daño dos veces.",
  str_skill_desc_2001412 = "ofertas <color=#00F6FF>130%</color> daño a los 2 enemigos más cercanos. Si solo hay 1 objetivo enemigo, inflige daño dos veces.",
  str_skill_desc_2001413 = "ofertas <color=#00F6FF>150%</color> daño a los 2 enemigos más cercanos. Si solo hay 1 objetivo enemigo, inflige daño dos veces.",
  str_skill_desc_300141 = "Selecciona el <color=#00F6FF>máximo en forma de cruz</color> o <color=#00F6FF>máximo en forma de X</color> rango, trato <color=#00F6FF>{1}%</color> daño, derribando al enemigo y convirtiendo las fichas dentro de su rango de ataque en fichas azules.",
  str_skill_desc_306141 = "Selecciona el <color=#00F6FF>máximo en forma de cruz</color> o <color=#00F6FF>máximo en forma de X</color> rango, trato <color=#00F6FF>{1}%</color> daño, derribando al enemigo y convirtiendo las fichas dentro de su rango de ataque en fichas azules. Toque el mosaico debajo de sus pies para cambiar las direcciones de retroceso y conversión de mosaico.",
  str_skill_desc_320141 = "Selecciona el <color=#00F6FF>máximo en forma de cruz</color> o <color=#00F6FF>máximo en forma de X</color> rango, trato <color=#00F6FF>{1}%</color> daño, derribando al enemigo y convirtiendo las fichas dentro de su rango de ataque en fichas azules. Inflige daño una vez a los objetivos enemigos que son golpeados según el nivel de su habilidad actualmente equipada.",
  str_skill_desc_326141 = "Selecciona el <color=#00F6FF>máximo en forma de cruz</color> o <color=#00F6FF>máximo en forma de X</color> rango, trato <color=#00F6FF>{1}%</color> daño, derribando al enemigo y convirtiendo las fichas dentro de su rango de ataque en fichas azules. Toque el mosaico debajo de sus pies para cambiar las direcciones de retroceso y conversión de mosaico. Inflige daño una vez a los objetivos enemigos que son golpeados según el nivel de habilidad actual del equipo.",
  str_skill_passive_desc_410141 = "Para cada <color=#00F6FF>3</color> veces Chain Combo inflige daño a un mismo objetivo, inflige daño adicional igual a <color=#00F6FF>{1}</color> del HP actual del objetivo.",
  str_skill_passive_desc_420141 = "Para cada <color=#00F6FF>3</color> veces Chain Combo inflige daño a un mismo objetivo, inflige daño adicional igual a <color=#00F6FF>{1}</color> del HP actual del objetivo.",
  str_skill_passive_desc_430141 = "Para cada <color=#00F6FF>3</color> veces Chain Combo inflige daño a un mismo objetivo, inflige daño adicional igual a <color=#00F6FF>{1}</color> del HP actual del objetivo, no menos de <color=#00F6FF>{2}</color> del DEF básico de Ruby.",
