  str_skill_desc_2001422 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2001423 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_desc_300142 = "Elige 1 de los <color=#00F6FF>13 fichas en forma de diamante</color>, tratar <color=#00F6FF>{1}%</color> daño a la ficha seleccionada y su <color=#00F6FF>2 grupos circundantes</color> y obligando a los <color=#00F6FF>no jefe</color> enemigos dentro del alcance a moverse <color=#00F6FF>2</color> baldosas hacia la baldosa seleccionada. El daño se reduce en un 53% por grupo.",
  str_skill_desc_302142 = "Elige 1 de los <color=#00F6FF>13 fichas en forma de diamante</color>, tratar <color=#00F6FF>{1}%</color> daño a la ficha seleccionada y su <color=#00F6FF>2 grupos circundantes</color> y obligando a los enemigos dentro del alcance a moverse <color=#00F6FF>2</color> baldosas hacia la baldosa seleccionada. El daño se reduce en un 53% por grupo.",
  str_skill_desc_320142 = "Elige 1 de los <color=#00F6FF>13 fichas en forma de diamante</color>, trato <color=#00F6FF>{1}%</color> daño a la ficha seleccionada y su <color=#00F6FF>3 grupos circundantes</color> y obligando a los <color=#00F6FF>no jefe</color> enemigos dentro del alcance a moverse <color=#00F6FF>2</color> baldosas hacia la baldosa seleccionada. El daño se reduce en un 53% por grupo.",
  str_skill_desc_322142 = "Elige 1 de los <color=#00F6FF>13 fichas en forma de diamante</color>, tratar <color=#00F6FF>{1}%</color> daño a la ficha seleccionada y su <color=#00F6FF>3 grupos circundantes</color> y obligando a los enemigos dentro del alcance a moverse <color=#00F6FF>2</color> baldosas hacia la baldosa seleccionada. El daño se reduce en un 53% por grupo.",
  str_skill_passive_desc_410142 = "Para cada <color=#00F6FF>3ro</color> ataque normal, el porcentaje de HP actual del objetivo aumenta el daño de ataque normal. Si el objetivo está en su HP máximo, el daño aumenta el límite de <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420142 = "Para cada <color=#00F6FF>3ro</color> y <color=#00F6FF>5to</color> ataque normal, el porcentaje de HP actual del objetivo aumenta el daño de ataque normal. Si el objetivo está en su HP máximo, el daño aumenta el límite de <color=#00F6FF>{1}</color>.",
