  str_skill_desc_2001401 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2001402 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_desc_2001403 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_300140 = "Después de usar, Thunder Aurorians lanzará su Chain Combo <color=#00F6FF>dos veces</color> durante esta ronda. Para el <color=#00F6FF>segundo</color> lanzamiento, el ATK de todos los Thunder Aurorians es <color=#00F6FF>80%</color> de Florine.",
  str_skill_desc_306140 = "Después de usar, Thunder Aurorians lanzará su Chain Combo <color=#00F6FF>dos veces</color> durante esta ronda. Para el <color=#00F6FF>segundo</color> lanzamiento, el ATK de todos los Thunder Aurorians es <color=#00F6FF>80%</color> de Florine.",
  str_skill_desc_320140 = "Después de usar, Thunder Aurorians lanzará su Chain Combo <color=#00F6FF>dos veces</color> durante esta ronda. Para el <color=#00F6FF>segundo</color> lanzamiento, el ATK de todos los Thunder Aurorians es <color=#00F6FF>80%</color> de Florine. Al mismo tiempo, la cantidad de fichas requeridas para activar Thunder Aurorian Chain Combo es <color=#00F6FF>-1</color>.",
  str_skill_desc_326140 = "Después de usar, Thunder Aurorians lanzará su Chain Combo <color=#00F6FF>dos veces</color> durante esta ronda. Para el <color=#00F6FF>segundo</color> lanzamiento, el ATK de todos los Thunder Aurorians es <color=#00F6FF>80%</color> de Florine. Al mismo tiempo, la cantidad de fichas requeridas para activar Thunder Aurorian Chain Combo es <color=#00F6FF>-1</color>.",
  str_skill_desc_330140 = "Después de usar, Thunder Aurorians lanzará su Chain Combo <color=#00F6FF>dos veces</color> durante esta ronda. Para el <color=#00F6FF>segundo</color> lanzamiento, el ATK de todos los Thunder Aurorians es <color=#00F6FF>95%</color> de Florine. Al mismo tiempo, la cantidad de fichas requeridas para activar Thunder Aurorian Chain Combo es <color=#00F6FF>-1</color>.",
  str_skill_desc_336140 = "Después de usar, Thunder Aurorians lanzará su Chain Combo <color=#00F6FF>dos veces</color> durante esta ronda. Para el <color=#00F6FF>segundo</color> lanzamiento, el ATK de todos los Thunder Aurorians es <color=#00F6FF>95%</color> de Florine. Al mismo tiempo, la cantidad de fichas requeridas para activar Thunder Aurorian Chain Combo es <color=#00F6FF>-1</color>.",
  str_skill_passive_desc_410140 = "El daño de todos los Combos de Cadena de Aurorianos de trueno de diferentes rangos se incrementa respectivamente en <color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color>.",
  str_skill_name_200150110 = "Fantasma - Rip",
  str_skill_desc_200150110 = "Corta con sus afiladas garras a los objetivos dentro del alcance.",
  str_skill_name_290200101 = "Sombra Nobutora",
  str_skill_desc_290200101 = "Cuando el enemigo está dentro de 2 grupos circundantes, se teletransporta a una ubicación a 6 mosaicos del enemigo y deja atrás a Shadow Nobutora.",
  str_skill_name_290200102 = "Contraataque",
  str_skill_desc_290200102 = "Cuando no hay enemigos dentro de 2 grupos circundantes, realiza ataques a distancia a los enemigos dentro del alcance y estropea el orden del equipo auroriano.",
  str_skill_name_290200112 = "Contraataque",
  str_skill_desc_290200112 = "Cuando no hay enemigos dentro de 2 grupos circundantes, realiza ataques a distancia a los enemigos dentro del alcance y estropea el orden del equipo auroriano. El daño aumenta con la distancia entre Fujikumo Nobutora y los enemigos.",
  str_skill_name_290200201 = "Golpe de las sombras",
  str_skill_desc_290200201 = "Shadow Nobutora ataca a los objetivos dentro del alcance.",
  str_skill_upgrade_desc_16014313 = "Mejora hab. activa: Cambia la hab. activa a <color=#FFFF00> Golpe preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16014316 = "Mejora de habilidades de equipo: Cambios de capitán en esta ronda: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001431 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos dentro de <color=#00F6FF> 2 cúmulos circundantes </color>.",
  str_skill_desc_2001432 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos dentro de <color=#00F6FF> 3 cúmulos circundantes </color>.",
  str_skill_desc_2001433 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos dentro de <color=#00F6FF> 4 cúmulos circundantes </color>.",
  str_skill_desc_300143 = "Invoca una barrera que cubre <color=#00F6FF>2 grupos circundantes</color> alrededor de sí mismo durante 2 rondas. Al invocar o cuando termina la ronda, convierte <color=#00F6FF>3</color> fichas aleatorias no rojas dentro de la barrera a rojo y <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas las fichas rojas dentro del alcance.",
  str_skill_desc_306143 = "Invoca una barrera que cubre <color=#00F6FF>2 grupos circundantes</color> alrededor de sí mismo durante 2 rondas. Al invocar o cuando termina la ronda, convierte <color=#00F6FF>3</color> fichas aleatorias no rojas dentro de la barrera a rojo y <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas las fichas rojas dentro del alcance.",
  str_skill_desc_330143 = "Invoca una barrera que cubre <color=#00F6FF>2 grupos circundantes</color> alrededor de sí mismo durante 2 rondas. Al invocar o cuando termina la ronda, convierte <color=#00F6FF>3</color> fichas aleatorias que no sean rojas dentro de la barrera al rojo, y <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas las fichas rojas dentro del alcance. Cuando está rodeado por la barrera, la DEF de Rinne aumenta en <color=#00F6FF>50%</color>, mientras que la DEF de otros compañeros Aurorianos de fuego aumenta en <color=#00F6FF>10%</color>.",
  str_skill_desc_336143 = "Invoca una barrera que cubre <color=#00F6FF>2 grupos circundantes</color> alrededor de sí mismo durante 2 rondas. Al invocar o cuando termina la ronda, convierte <color=#00F6FF>3</color> fichas aleatorias que no sean rojas dentro de la barrera al rojo, y <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas las fichas rojas dentro del alcance. Cuando está rodeado por la barrera, la DEF de Rinne aumenta en <color=#00F6FF>50%</color>, mientras que la DEF de otros compañeros Aurorianos de fuego aumenta en <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_410143 = "Cuando Rinne se convierte en capitana, recupera HP igual a <color=#00F6FF>{1}</color> de su DEF actual. Dispara hasta <color=#00F6FF>1</color> tiempo por ronda.",
  str_skill_passive_desc_416143 = "Cuando Rinne se convierte en capitana, recupera HP igual a <color=#00F6FF>{1}</color> de su DEF actual. Dispara hasta <color=#00F6FF>1</color> tiempo por ronda. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_420143 = "Cuando Rinne se convierte en capitana, recupera HP igual a <color=#00F6FF>{1}</color> de su DEF actual. Si su HP está lleno después de activarse, el azulejo azul más cercano se convertirá en rojo. Dispara hasta <color=#00F6FF>1</color> tiempo por ronda.",
  str_skill_passive_desc_426143 = "Cuando Rinne se convierte en capitana, recupera HP igual a <color=#00F6FF>{1}</color> de su DEF actual. Si su HP está lleno después de activarse, el azulejo azul más cercano se convertirá en rojo. Dispara hasta <color=#00F6FF>1</color> tiempo por ronda. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
