  str_skill_desc_300144 = "Intercambia posiciones con el Capitán actual.",
  str_skill_desc_302144 = "Intercambia posiciones con un compañero de equipo seleccionado.",
  str_skill_desc_305144 = "Intercambia posiciones con un compañero de equipo seleccionado. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
  str_skill_desc_310144 = "Intercambia posiciones con el Capitán actual.",
  str_skill_desc_312144 = "Intercambia posiciones con un compañero de equipo seleccionado.",
  str_skill_desc_315144 = "Intercambia posiciones con un compañero de equipo seleccionado. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_410144 = "Cuando Kayano se da cuenta de que no está en la parte de atrás, se verá obligada a retirarse a la parte de atrás del equipo mientras el resto del equipo avanza 1 ficha. aurorianos <color=#00F6FF>que se han retirado</color> esta ronda recibirá una bonificación ATK igual a <color=#00F6FF>{1}</color> del ATK básico de Kayano (la bonificación más alta se obtiene cuando se activa varias veces).",
  str_skill_passive_desc_420144 = "Cuando Kayano se da cuenta de que no está en la parte de atrás, se verá obligada a retirarse a la parte de atrás del equipo mientras el resto del equipo avanza 1 ficha. aurorianos <color=#00F6FF>que se han retirado</color> esta ronda recibirá una bonificación ATK igual a <color=#00F6FF>{1}</color> del ATK básico de Kayano (la bonificación más alta se obtiene cuando se activa varias veces). Cuanto más retroceda uno, mayor será la bonificación, hasta 2.5 veces el valor básico.",
  str_skill_passive_desc_430144 = "Cuando Kayano se da cuenta de que no está en la parte de atrás, se verá obligada a retirarse a la parte de atrás del equipo mientras el resto del equipo avanza 1 ficha. aurorianos <color=#00F6FF>que se han retirado</color> esta ronda recibirá una bonificación ATK igual a <color=#00F6FF>{1}</color> del ATK básico de Kayano (la bonificación más alta se obtiene cuando se activa varias veces). Cuanto más retroceda uno, mayor será la bonificación, hasta 2.5 veces el valor básico. El Capitán actual recibe la misma bonificación de ATK que Kayano.",
  str_skill_passive_desc_415144 = "Cuando Kayano se da cuenta de que no está en la parte de atrás, se verá obligada a retirarse a la parte de atrás del equipo mientras el resto del equipo avanza 1 ficha. aurorianos <color=#00F6FF>que se han retirado</color> esta ronda recibirá una bonificación ATK igual a <color=#00F6FF>{1}</color> del ATK básico de Kayano (la bonificación más alta se obtiene cuando se activa varias veces). Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_425144 = "Cuando Kayano se da cuenta de que no está en la parte de atrás, se verá obligada a retirarse a la parte de atrás del equipo mientras el resto del equipo avanza 1 ficha. aurorianos <color=#00F6FF>que se han retirado</color> esta ronda recibirá una bonificación ATK igual a <color=#00F6FF>{1}</color> del ATK básico de Kayano (la bonificación más alta se obtiene cuando se activa varias veces). Cuanto más retroceda uno, mayor será la bonificación, hasta 2.5 veces el valor básico. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_435144 = "Cuando Kayano se da cuenta de que no está en la parte de atrás, se verá obligada a retirarse a la parte de atrás del equipo mientras el resto del equipo avanza 1 ficha. aurorianos <color=#00F6FF>que se han retirado</color> esta ronda recibirá una bonificación ATK igual a <color=#00F6FF>{1}</color> del ATK básico de Kayano (la bonificación más alta se obtiene cuando se activa varias veces). Cuanto más retroceda uno, mayor será la bonificación, hasta 2.5 veces el valor básico. El Capitán actual recibe la misma bonificación de ATK que Kayano. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
