  str_skill_name_290190110 = "Espada del Inframundo - Asalto",
  str_skill_desc_290190110 = "Carga hacia los jugadores, inflige una gran cantidad de daño y golpea al Capitán en la parte trasera del equipo. Si los jugadores no están en un área en forma de cruz y lejos, usará ataques a distancia.",
  str_skill_name_290190120 = "Espada del Inframundo - Huelga",
  str_skill_desc_290190120 = "Corta a los jugadores a su lado e inflige una gran cantidad de daño. Si los jugadores no están en un área en forma de cruz y lejos, usará ataques a distancia.",
  str_skill_desc_490190120 = "Después de correr, acuchilla a los enemigos adyacentes e inflige una gran cantidad de daño.",
  str_skill_name_290190130 = "Espada del Inframundo - Hack",
  str_skill_desc_290190130 = "Después de moverse hacia el centro del tablero de alquimia, saca su arma e inflige daño a los jugadores que no están en un área en forma de cruz y lejos.",
  str_skill_desc_490190130 = "Apunta y dispara, infligiendo daño a distancia a los enemigos fuera del alcance del ataque de corte.",
  str_skill_name_290191110 = "Nagi - Corte doble",
  str_skill_desc_290191110 = "Cuando los jugadores están a su lado, ataca con un corte horizontal y un empujón hacia adelante.",
  str_skill_name_290191120 = "Nagi - Ataque de carga",
  str_skill_desc_290191120 = "Cuando los jugadores están lejos, cargará hacia ellos para causarles daño.",
  str_skill_name_290191130 = "Nagi - Ataque en ráfaga",
  str_skill_desc_290191130 = "Ella parpadea hacia el centro del campo de batalla y causa una gran cantidad de daño a su alrededor. Si es golpeado, el Capitán será derribado a la parte de atrás del equipo.",
  str_skill_name_290210101 = "Devorar - Sano",
  str_skill_desc_290210101 = "Cuando el objetivo está dentro del alcance, los aurorianos y los fantasmas dentro de dos grupos al frente son devorados. Luego, los Aurorianos son escupidos hacia el borde del tablero y el Capitán recibe una maldición, lo que obliga al Capitán a retirarse a la parte trasera del equipo.",
  str_skill_desc_291210101 = "Cuando el objetivo está dentro del alcance, los aurorianos y los fantasmas dentro de dos grupos en la dirección de avance son devorados. Los Aurorianos reciben daño y luego son escupidos hacia el borde del tablero, y el Capitán se ve obligado a retirarse a la parte trasera del equipo.",
  str_skill_name_290210102 = "Devorar - Destruir",
  str_skill_desc_290210102 = "Cuando el objetivo está dentro del alcance, les inflige una gran cantidad de daño. El orden del equipo auroriano se confunde y los monstruos circundantes se eliminan al instante.",
  str_skill_name_290210201 = "Devorar - Ejército fantasma",
  str_skill_desc_290210201 = "Cuando el objetivo está dentro del alcance, se invoca una gran cantidad de fantasmas y se mejoran todos los fantasmas en el campo de batalla.",
  str_skill_desc_291210201 = "Cuando el objetivo está dentro del alcance, se invoca una gran cantidad de fantasmas y todos los fantasmas en el campo de batalla se mejoran y curan.",
  str_skill_name_290210301 = "Devorar - Saludable",
  str_skill_desc_290210301 = "Cuando el objetivo está dentro del alcance, los aurorianos y los fantasmas dentro de dos grupos al frente son devorados e infligen daño verdadero a los aurorianos. Cuantos más fantasmas devoraba, mayor era el daño infligido. Luego, los Aurorianos son escupidos hacia el borde del tablero y el Capitán recibe una maldición, lo que obliga al Capitán a retirarse a la parte trasera del equipo.",
  str_skill_name_290042201 = "Ruptura del Dragón Malvado",
  str_skill_desc_290042201 = "Hakudoma rasga el espacio frente a él e inflige daño a los objetivos dentro del área de ataque.",
  str_skill_name_290042211 = "Ruptura del Dragón Malvado",
  str_skill_desc_290042211 = "Hakudoma abre el espacio frente a él, infligiendo daño a los objetivos dentro del área de ataque y rompiendo algunas de las fichas en el campo de batalla.",
  str_skill_name_290042202 = "Reencarnación de Hakudoma",
  str_skill_desc_290042202 = "Para acumular fuerza para la marea alta, Hakudoma bate sus alas, lanza al objetivo al borde del tablero e invoca a Spikepest al campo de batalla.",
  str_skill_name_290042204 = "Apóstol de la marea alta",
  str_skill_desc_290042204 = "Hakudoma vuela hacia adelante, empujando todas las fichas hacia arriba durante 4 fichas y bombardea un área fija después.",
  str_skill_name_290042214 = "Apóstol de la marea alta",
  str_skill_desc_290042214 = "Hakudoma vuela y bombardea un área fija. El objetivo cae al borde del tablero independientemente de si se golpea. Cuando Hakudoma aterriza, convoca Spikepests frente a sí mismo.",
  str_skill_upgrade_desc_16014513 = "Mejora de habilidad activa: ganancia <color=#FFFF00>1</color> punto de Ninja Power al comienzo de cada ola.",
  str_skill_upgrade_desc_16014516 = "Mejora de habilidades de equipo: Cambios de capitán en esta ronda: <color=#FFFF00>+1</color>.",
  str_skill_name_2001451 = "Implacable.despiadado",
  str_skill_name_2001452 = "Implacable.despiadado",
  str_skill_name_2001453 = "Implacable.despiadado",
  str_skill_desc_2001451 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 8 casillas en forma de cruz </color>.",
  str_skill_desc_2001452 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color> y convocatoria <color=#00F6FF>1</color> katana en una casilla transitable aleatoria.",
  str_skill_desc_2001453 = "ofertas <color=#00F6FF>{1}%</color> daños en <color=#00F6FF>1 grupo circundante</color> y un <color=#00F6FF>forma cruzada al rango máximo</color> y convoca 1 katana cada uno en <color=#00F6FF>2</color> baldosas transitables al azar dentro del área afectada.",
