  str_skill_desc_300146 = "Intercambia posiciones con el Capitán actual y el Chain Combo de esta ronda inflige el doble de daño a <color=#00F6FF>4 fichas adyacentes</color>. Cuando termine la ronda, intercambie posiciones con el Aurorian al final del equipo.",
  str_skill_desc_303146 = "Intercambia posiciones con el Capitán actual y el Chain Combo de esta ronda inflige el doble de daño a <color=#00F6FF>4 fichas adyacentes</color>. Cuando termine la ronda, intercambie posiciones con el Aurorian al final del equipo.",
  str_skill_desc_320146 = "Intercambia posiciones con el Capitán actual, gana 1 pila de <link=\"30026\"><#FFAE07><u>marca heroica</u></color></link>, y aumentar el combo en cadena de esta ronda inflige 2 veces el daño a <color=#00F6FF>4 fichas adyacentes</color>. Cuando termine la ronda, intercambie posiciones con el Aurorian al final del equipo.",
  str_skill_desc_323146 = "Intercambia posiciones con el Capitán actual, gana 1 pila de <link=\"30026\"><#FFAE07><u>marca heroica</u></color></link>, y aumentar el combo en cadena de esta ronda inflige 2 veces el daño a <color=#00F6FF>4 fichas adyacentes</color>. Cuando termine la ronda, intercambie posiciones con el Aurorian al final del equipo.",
  str_skill_desc_330146 = "Intercambia posiciones con el Capitán actual, gana 1 pila de <link=\"30026\"><#FFAE07><u>marca heroica</u></color></link>, y aumentar el combo en cadena de esta ronda inflige 2 veces el daño a <color=#00F6FF>4 fichas adyacentes</color>. Cuando termine la ronda, intercambie posiciones con el Aurorian al final del equipo.",
  str_skill_desc_333146 = "Intercambia posiciones con el Capitán actual, gana 1 pila de <link=\"30026\"><#FFAE07><u>marca heroica</u></color></link>, y aumentar el combo en cadena de esta ronda inflige 2 veces el daño a <color=#00F6FF>4 fichas adyacentes</color>. Cuando termine la ronda, intercambie posiciones con el Aurorian al final del equipo.",
  str_skill_passive_name_410146 = "camino cruzado",
