  str_skill_passive_name_436146 = "camino cruzado",
  str_skill_passive_desc_410146 = "Ganancias <link=\"30026\"><#FFAE07><u>marca heroica</u></color></link>. Si Yao ya es o se convierte en Capitán en esta ronda, cada acumulación de Heroic Mark aumenta el ATK base de Yao en <color=#00F6FF>{1}</color>. Las bonificaciones y las pilas se borran al final de la ronda.",
  str_skill_passive_desc_416146 = "Ganancias <link=\"30026\"><#FFAE07><u>marca heroica</u></color></link>. Si Yao ya es o se convierte en Capitán en esta ronda, cada acumulación de Heroic Mark aumenta el ATK base de Yao en <color=#00F6FF>{1}</color>. Las bonificaciones y las pilas se borran al final de la ronda. <color=#00F6FF>+1</color> Capitán Cambia esta batalla.",
  str_skill_passive_desc_430146 = "Ganancias <link=\"30027\"><#FFAE07><u>marca heroica</u></color></link>. Si Yao ya es o se convierte en Capitán esta ronda, cada acumulación de Heroic Mark aumenta el ATK base de Yao en <color=#00F6FF>{1}</color>. Las bonificaciones y las pilas se borran al final de la ronda. Cada vez que Yao tome la posición de Capitán, gane <color=#00F6FF>1</color> pila de <link=\"30027\"><#FFAE07><u>marca heroica</u></color></link>.",
  str_skill_passive_desc_436146 = "Ganancias <link=\"30027\"><#FFAE07><u>marca heroica</u></color></link>. Si Yao ya es Capitán o cambia a esta ronda, cada acumulación de Heroic Mark aumenta el ATK base de Yao en <color=#00F6FF>{1}</color>. Las bonificaciones y las pilas se borran al final de la ronda. Cada vez que Yao tome la posición de Capitán, gane <color=#00F6FF>1</color> pila de <link=\"30027\"><#FFAE07><u>marca heroica</u></color></link>. <color=#00F6FF>+1</color> Cambio de capitán en esta batalla.",
  str_skill_upgrade_desc_15014712 = "Mejora activa de habilidades: reduce el tiempo de reutilización de habilidades en <color=#FFFF00>1</color> ronda cuando ocupa una posición de Capitán. Dispara hasta <color=#00F6FF>3</color> veces por ronda.",
  str_skill_upgrade_desc_15014715 = "Mejora de habilidades de equipo: Cambios de capitán en esta ronda: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001471 = "ofertas <color=#00F6FF>150%</color> daño 2 veces. Asigna el daño aleatoriamente a los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Cuando un objetivo recibe daño más de una vez, el daño del segundo golpe se reduce a la mitad.",
  str_skill_desc_2001472 = "Inflige <color=#00F6FF>160%</color> de daño 3 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2001473 = "Trato <color=#00F6FF>160%</color> daño 4 veces a unidades enemigas aleatorias dentro <color=#00F6FF>3 grupos circundantes</color> de este lanzador. Si un objetivo sufre daño más de una vez, el daño de la segunda vez y después se reduce a la mitad.",
  str_skill_desc_300147 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>8</color> veces a 1 mosaico aleatorio dentro <color=#00F6FF>3 grupos circundantes</color>.",
  str_skill_desc_302147 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>8</color> veces a 1 mosaico aleatorio dentro <color=#00F6FF>3 grupos circundantes</color>. Reduce el tiempo de reutilización de la habilidad en <color=#FFFF00>1</color> ronda cuando ocupa una posición de Capitán. Dispara hasta <color=#00F6FF>3</color> veces por ronda.",
  str_skill_desc_320147 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>8</color> veces a 1 mosaico aleatorio dentro <color=#00F6FF>3 grupos circundantes</color>, luego reparte un adicional <color=#00F6FF>188%</color> daño a los enemigos en el mismo mosaico y <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_desc_322147 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>8</color> veces a 1 mosaico aleatorio dentro <color=#00F6FF>3 grupos circundantes</color>, luego reparte un adicional <color=#00F6FF>188%</color> daño a los enemigos en el mismo mosaico y <color=#00F6FF>1 grupo circundante</color>. Reduce el tiempo de reutilización de la habilidad en <color=#FFFF00>1</color> ronda cuando ocupa una posición de Capitán. Dispara hasta <color=#00F6FF>3</color> veces por ronda.",
  str_skill_passive_desc_410147 = "Al comienzo de cada ronda, Momo y Anzu se convertirán en el Capitán automáticamente mientras que el resto del equipo retrocede 1 posición. Cada vez que Momo y Anzu se convierten en el Capitán, un <link=\"30030\"><#FFAE07><u>Cocina especial de Kaniya</u></color></link> se obtendrá con un <color=#00F6FF>{1}</color> oportunidad para un <color=#00F6FF>uno adicional</color>.",
  str_skill_passive_desc_415147 = "Al comienzo de cada ronda, Momo y Anzu se convertirán automáticamente en el Capitán mientras que el resto del equipo retrocede 1 posición. Cada vez que Momo y Anzu se convierten en el Capitán, un <link=\"30030\"><#FFAE07><u>Cocina especial de Kaniya</u></color></link> se obtendrá con un <color=#00F6FF>{1}</color> oportunidad para un <color=#00F6FF>uno adicional</color>. Capitán Cambia esta ronda: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_430147 = "Al comienzo de cada ronda, Momo y Anzu se convertirán en el Capitán automáticamente, mientras que el resto del equipo retrocede 1 posición. Cada vez que Momo y Anzu se conviertan en Capitán, se obtendrá una <link=\"30030\"><#FFAE07><u>Cocina especial de Kaniya</u></color></link> con un <color=#00F6FF> ¡{1}</color> probabilidad de <color=#00F6FF>obtener uno más</color>!",
  str_skill_passive_desc_435147 = "Al comienzo de cada ronda, Momo y Anzu se convertirán en el Capitán automáticamente, mientras que el resto del equipo retrocede 1 posición. Cada vez que Momo y Anzu se conviertan en Capitán, se obtendrá una <link=\"30030\"><#FFAE07><u>Cocina especial de Kaniya</u></color></link> con un <color=#00F6FF> ¡{1}</color> probabilidad de <color=#00F6FF>obtener uno más</color>! Cambios de capitán para la batalla: <color=#00F6FF>+1</color>.",
