  str_skill_desc_2301514 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo con el porcentaje de HP más bajo 2 veces. Cuando el punto de cordura está por debajo <color=#00F6FF>60|25</color>, inflige daño adicional 1|2 veces. Reduce el daño final cada vez por <color=#00F6FF>15%</color>.",
  str_skill_desc_2301515 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo con el porcentaje de HP más bajo 2 veces. Cuando el punto de cordura está por debajo <color=#00F6FF>60|25</color>, inflige daño adicional 1|2 veces. Reduce el daño final cada vez por <color=#00F6FF>10%</color>.",
  str_skill_desc_2301516 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo con el porcentaje de HP más bajo 2 veces. Cuando el punto de cordura está por debajo <color=#00F6FF>60|25</color>, inflige daño adicional 1|2 veces. Reduce el daño final cada vez por <color=#00F6FF>5%</color>.",
  str_skill_desc_2301517 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo con el porcentaje de HP más bajo 2 veces. Cuando el punto de cordura está por debajo <color=#00F6FF>60|25|0</color>, inflige daño adicional 1|2|3 veces. Reduce el daño final cada vez por <color=#00F6FF>15%</color>.",
  str_skill_desc_2301518 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo con el porcentaje de HP más bajo 2 veces. Cuando el punto de cordura está por debajo <color=#00F6FF>60|25|0</color>, inflige daño adicional 1|2|3 veces. Reduce el daño final cada vez por <color=#00F6FF>10%</color>.",
  str_skill_desc_2301519 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo con el porcentaje de HP más bajo 2 veces. Cuando el punto de cordura está por debajo <color=#00F6FF>60|25|0</color>, inflige 1|2|3 de daño adicional. Reduce el daño final cada vez por <color=#00F6FF>5%</color>.",
  str_skill_desc_300151 = "Giles se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Usos <color=#00F6FF>15</color> puntos de cordura a tratar <color=#00F6FF>{1}%</color> DAÑO a los enemigos en las 4 casillas adyacentes en un <color=#00F6FF>forma de cruz</color> alrededor de 1 ficha elegida. Inflige el doble de daño si se selecciona la ficha del lanzador.",
  str_skill_desc_3001510 = "Giles se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Usos <color=#00F6FF>15</color> puntos de cordura a tratar <color=#00F6FF>{1}%</color> DAÑO a los enemigos en las 4 casillas adyacentes en un <color=#00F6FF>forma de cruz</color> alrededor de 1 ficha elegida. Inflige el doble de daño si se selecciona la ficha del lanzador. Después de que una habilidad activa mata a un objetivo, se puede usar nuevamente para infligir 2 veces el daño final a costa de 2 puntos de cordura.",
  str_skill_desc_3001511 = "Giles se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Usos <color=#00F6FF>30</color> puntos de cordura a tratar <color=#00F6FF>{1}%</color> DAÑO a los enemigos en las 4 casillas adyacentes en un <color=#00F6FF>forma de cruz</color> alrededor de 1 ficha elegida. Inflige el doble de daño si se selecciona la ficha del lanzador. Después de que una habilidad activa mata a un objetivo, se puede usar nuevamente para infligir 2 veces el daño final a costa de 2 puntos de cordura.",
  str_skill_desc_3001512 = "Giles se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Usos <color=#00F6FF>60</color> puntos de cordura a tratar <color=#00F6FF>{1}%</color> DAÑO a los enemigos en las 4 casillas adyacentes en un <color=#00F6FF>forma de cruz</color> alrededor de 1 ficha elegida. Inflige el doble de daño si se selecciona la ficha del lanzador. Después de que una habilidad activa mata a un objetivo, se puede usar nuevamente para infligir 2 veces el daño final a costa de 2 puntos de cordura.",
  str_skill_desc_3001513 = "Giles se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Usos <color=#00F6FF>120</color> puntos de cordura a tratar <color=#00F6FF>{1}%</color> DAÑO a los enemigos en las 4 casillas adyacentes en un <color=#00F6FF>forma de cruz</color> alrededor de 1 ficha elegida. Inflige el doble de daño si se selecciona la ficha del lanzador. Después de que una habilidad activa mata a un objetivo, se puede usar nuevamente para infligir 2 veces el daño final a costa de 2 puntos de cordura.",
  str_skill_desc_3001514 = "Giles se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Usos <color=#00F6FF>240</color> puntos de cordura a tratar <color=#00F6FF>{1}%</color> DAÑO a los enemigos en las 4 casillas adyacentes en un <color=#00F6FF>forma de cruz</color> alrededor de 1 ficha elegida. Inflige el doble de daño si se selecciona la ficha del lanzador. Después de que una habilidad activa mata a un objetivo, se puede usar nuevamente para infligir 2 veces el daño final a costa de 2 puntos de cordura.",
  str_skill_passive_desc_410151 = "<color=#00F6FF>Activado después de matar a cualquier enemigo</color> en esta ronda: cada vez que Giles inflige daño, su ATK aumenta de acuerdo con el punto de cordura actual. Cuanto menor sea el punto de cordura, mayor será el daño, hasta <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413151 = "<color=#00F6FF>Activado después de matar a cualquier enemigo</color> en esta ronda: cada vez que Giles inflige daño, el DAÑO aumenta de acuerdo con la cordura actual. Cuanto menor sea la Cordura, mayor será el aumento del daño, hasta <color=#00F6FF>{1}</color>. La matanza de cualquier <color=#00F6FF>Espejismo</color> además aumenta las bonificaciones en <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_416151 = "<color=#00F6FF>Activado después de matar a cualquier enemigo</color> en esta ronda: cada vez que Giles inflige daño, el DAÑO aumenta de acuerdo con la cordura actual. Cuanto menor sea la Cordura, mayor será el aumento del daño, hasta <color=#00F6FF>{1}</color>. La matanza de cualquier <color=#00F6FF>Espejismo</color> además aumenta las bonificaciones en <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_430151 = "<color=#00F6FF>Activado después de matar a cualquier enemigo</color> en esta ronda: cada vez que Giles inflige daño, el DAÑO aumenta de acuerdo con la cordura actual. Cuanto menor sea la Cordura, mayor será el aumento del daño, hasta <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_433151 = "<color=#00F6FF>Activado después de matar a cualquier enemigo</color> en esta ronda: cada vez que Giles inflige daño, el DAÑO aumenta de acuerdo con la cordura actual. Cuanto menor sea la Cordura, mayor será el aumento del daño, hasta <color=#00F6FF>{1}</color>. La matanza de cualquier <color=#00F6FF>Espejismo</color> además aumenta las bonificaciones en <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_436151 = "<color=#00F6FF>Activado después de matar a cualquier enemigo</color> en esta ronda: cada vez que Giles inflige daño, el DAÑO aumenta de acuerdo con la cordura actual. Cuanto menor sea la Cordura, mayor será el aumento del daño, hasta <color=#00F6FF>{1}</color>. La matanza de cualquier <color=#00F6FF>Espejismo</color> además aumenta las bonificaciones en <color=#00F6FF>10%</color>.",
  str_skill_upgrade_desc_16015113 = "Mejora de habilidades de equipo: la muerte de cualquier <color=#00F6FF>Espejismo</color> además aumenta las bonificaciones en <color=#00F6FF>10%</color>.",
  str_skill_upgrade_desc_16015116 = "Mejora de combo en cadena: cuando la cordura llega a 0, activa DMG adicional <color=#00F6FF>3</color> tiempos (Válido para Ascensión III).",
