  str_skill_desc_300152 = "May se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Restaura <color=#00F6FF>25%</color> de los puntos de cordura perdidos a costa de <color=#00F6FF>20%</color> de su HP actual.",
  str_skill_desc_302152 = "May se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Restaura <color=#00F6FF>25%</color> de los puntos de cordura perdidos a costa de <color=#00F6FF>15%</color> de su HP actual.",
  str_skill_desc_305152 = "May es capaz de cambiar el <link=\"30040\"><#FFAE07><u>sistema de cordura</u></color></link> para esta batalla: más resistente a los efectos negativos del sistema de cordura. Los perjuicios también se debilitan. Restaura <color=#00F6FF>25%</color> de los puntos de cordura perdidos a costa de <color=#00F6FF>15%</color> de su HP actual.",
  str_skill_desc_2001521 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF> 8 casillas en forma de X </color>.",
  str_skill_desc_2001522 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>Forma de X al rango máximo</color>.",
  str_skill_desc_2001523 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>Forma de X al rango máximo</color>.",
  str_skill_passive_desc_410152 = "Por cada 1 punto de cordura perdido, restaura HP igual a <color=#00F6FF>{1}</color> del ATK de mayo.",
  str_skill_passive_desc_415152 = "Por cada 1 punto de cordura perdido, restaura HP igual a <color=#00F6FF>{1}</color> del ATK de mayo.",
  str_skill_passive_desc_420152 = "Por cada 1 punto de cordura perdido, restaura HP igual a <color=#00F6FF>{1}</color> del ATK de mayo. Su DEF aumenta a medida que baja la cordura, hasta <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_425152 = "Por cada 1 punto de cordura perdido, restaura HP igual a <color=#00F6FF>{1}</color> del ATK de mayo. Su DEF aumenta a medida que baja la cordura, hasta <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_430152 = "Por cada 1 punto de cordura perdido, restaura HP igual a <color=#00F6FF>{1}</color> del ATK de mayo. Cuanto menor es la cordura, mayor es la recuperación, hasta <color=#00F6FF>100%</color>. Su DEF aumenta a medida que baja la cordura, hasta <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_435152 = "Por cada 1 punto de cordura perdido, restaura HP igual a <color=#00F6FF>{1}</color> del ATK de mayo. Cuanto menor es la cordura, mayor es la recuperación, hasta <color=#00F6FF>100%</color>. Su DEF aumenta a medida que baja la cordura, hasta <color=#00F6FF>100%</color>.",
  str_skill_upgrade_desc_15015212 = "Mejora activa de habilidades: restaura <color=#00F6FF>25%</color> de puntos de cordura perdidos a costa de <color=#00F6FF>15%</color> de su HP actual.",
  str_skill_upgrade_desc_15015215 = "Cambia el sistema de cordura para esta batalla: mayor resistencia a los efectos negativos del sistema de cordura. Los perjuicios también se debilitan.",
