  str_skill_desc_20015012 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 filas </color>.",
  str_skill_desc_20015013 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>5 filas</color>.",
  str_skill_desc_22015011 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 fila </color>.",
  str_skill_desc_22015012 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 filas </color>.",
  str_skill_desc_22015013 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>5 filas</color>. Cuando la cordura cae por debajo <color=#00F6FF>75</color> puntos, la condición de activación se reduce a <color=#00F6FF>15</color>. si en el <color=#00F6FF>estado loco</color>, reduzca la condición de disparo a <color=#00F6FF>5</color>.",
  str_skill_desc_23015011 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 fila</color>. Cuanto menor sea la cordura, mayor será el aumento de DMG, hasta <color=#00F6FF>80%</color>.",
  str_skill_desc_23015012 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>3 filas</color>. Cuanto menor sea la cordura, mayor será el aumento de DMG, hasta <color=#00F6FF>80%</color>.",
  str_skill_desc_23015013 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>5 filas</color>. Cuando la cordura cae por debajo <color=#00F6FF>75</color> puntos, la condición de activación se reduce a <color=#00F6FF>15</color>. si en el <color=#00F6FF>estado loco</color>, reduzca la condición de disparo a <color=#00F6FF>5</color>. Cuanto menor sea la cordura, mayor será el aumento de DMG, hasta <color=#00F6FF>80%</color>.",
  str_skill_desc_23615011 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 fila</color>. Cuanto menor sea la cordura, mayor será el aumento de DMG, hasta <color=#00F6FF>100%</color>.",
  str_skill_desc_23615012 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>3 filas</color>. Cuanto menor sea la cordura, mayor será el aumento de DMG, hasta <color=#00F6FF>100%</color>.",
  str_skill_desc_23615013 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>5 filas</color>. Cuando la cordura cae por debajo <color=#00F6FF>75</color> puntos, la condición de activación se reduce a <color=#00F6FF>15</color>. si en el <color=#00F6FF>estado loco</color>, reduzca la condición de disparo a <color=#00F6FF>5</color>. Cuanto menor sea la cordura, mayor será el aumento de DMG, hasta <color=#00F6FF>100%</color>.",
  str_skill_desc_3001501 = "Lenore se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Elija cualquier mosaico 1 y luego seleccione otro 1 dentro <color=#00F6FF>2 grupos circundantes</color> para generar un área rectangular, dentro de la cual tratar <color=#00F6FF>333%</color> DMG a mosaicos. Cada mosaico en el rectángulo deduce <color=#00F6FF>3</color> puntos de cordura. Si un enemigo sufre daño más de una vez, el efecto posterior se reduce a <color=#00F6FF>33%</color>.",
  str_skill_desc_3031501 = "Lenore se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Elija cualquier mosaico 1 y luego seleccione otro 1 dentro <color=#00F6FF>2 grupos circundantes</color> para generar un área rectangular, dentro de la cual tratar <color=#00F6FF>333%</color> DMG a mosaicos. Cada mosaico en el rectángulo deduce <color=#00F6FF>3</color> Puntos de sensibilidad. Si una unidad enemiga sufre daño más de una vez, el efecto posterior se reduce a <color=#00F6FF>33%</color>. Cada vez que una Habilidad Activa causa DAÑO, el Max HP de Lenore es impulsado por <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_410150 = "si no en el <color=#00F6FF>estado de calma</color> al comienzo de cada ronda, reparte DMG igual a <color=#00F6FF>{1}</color> del Max HP del equipo a todos los enemigos. Cuanto menor sea la cordura, mayor será el aumento del daño, hasta <color=#00F6FF>{2}</color> del Max HP del equipo.",
  str_skill_name_290220101 = "Brecha nocturna",
  str_skill_desc_290220101 = "Lanza un poderoso ataque a todos los enemigos dentro del rango de habilidad.",
  str_skill_name_290220102 = "Odio Nocturno",
  str_skill_desc_290220102 = "Inflige daño masivo a los objetivos dentro de 2 grupos circundantes y convierte el 50% de los puntos de contusión en HP.",
  str_skill_name_290220103 = "Contraataque nocturno",
  str_skill_desc_290220103 = "Inflige un daño masivo a los objetivos dentro de los 2 grupos circundantes y convierte el 50% de los puntos de contusión en HP cada vez que un auroriano libera una habilidad activa.",
  str_skill_name_290220201 = "Garra sombría",
  str_skill_desc_290220201 = "Inflige daño a los enemigos en las cinco casillas adyacentes alrededor de la cabeza con una garra afilada.",
  str_skill_name_290220202 = "Golpe sombrío",
  str_skill_desc_290220202 = "Salta hacia el enemigo y rompe la trampa al aterrizar, infligiendo daño a los enemigos dentro de 1 grupo circundante.",
  str_skill_name_290220203 = "Barrido de cola sombrío",
  str_skill_desc_290220203 = "Cuando no haya ningún enemigo al frente, gire para enfrentar al enemigo moviendo la cola. Si hay obstáculos después de girar, lanza un Gloomy Swoop inmediatamente.",
  str_skill_name_290220204 = "Golpe sombrío",
  str_skill_desc_290220204 = "Salta alto y desciende en picado hacia el enemigo, infligiendo un daño masivo a los enemigos dentro de 1 grupo circundante al aterrizar. Todos los movimientos se concluyen después.",
  str_skill_name_29026011 = "Dreamwalker - Golpe cortante",
  str_skill_desc_29026011 = "Se mueve hacia un jugador y blande su guadaña para infligir daño a los enemigos circundantes dentro del alcance.",
  str_skill_name_29026012 = "Dreamwalker - Guadaña giratoria",
  str_skill_desc_29026012 = "Invoca una guadaña desde el borde del campo de batalla hacia él, lo que inflige daño a los enemigos dentro de un área de forma radial.",
  str_skill_name_29026021 = "Dreamwalker - Lluvia de cuchillas",
  str_skill_desc_29026021 = "Se mueve hacia un jugador, y si el jugador está dentro de su rango de ataque, balancea su antebrazo para infligir daño a los enemigos dentro de 2 casillas frente a él.\nSi no, pasa a un estado oculto, esquivando todos los ataques normales (revelado cuando se ve afectado por los efectos de control).",
  str_skill_name_29026023 = "Dreamwalker - Aullidos de sangre",
  str_skill_desc_29026023 = "Lanza habilidades en su lugar, infligiendo daño a todos los enemigos en la pantalla.",
  str_skill_name_290270101 = "Forsakin: La llamada",
  str_skill_desc_290270101 = "Forsakin convoca 2 Eclipsites en ubicaciones aleatorias en el campo para ayudarla en la batalla.",
  str_skill_name_290270102 = "Forsakin: Huelga",
  str_skill_desc_290270102 = "Forsakin repele a todos los Aurorianos y otros Eclipsites en el campo, e inflige daño a los Aurorianos.",
  str_skill_name_290270103 = "Forsakin: marchitarse",
  str_skill_desc_290270103 = "Lanza una onda de choque hacia la ubicación del Aurorian en la última ronda y 1 grupo circundante. Si algún Aurorian está en el rango de la onda de choque, sufrirá daños severos.",
  str_skill_name_290270111 = "Forsakin: Oscurecimiento",
  str_skill_desc_290270111 = "Forsakin invoca a la Región Oscura en el campo, lo que limita el movimiento de los Aurorianos.",
  str_skill_upgrade_desc_16015413 = "Mejora Chain Combo: Los tiempos del ataque Chain Combo siempre serán <color=#00F6FF>+1</color>.",
  str_skill_upgrade_desc_16015416 = "Mejora del combo en cadena: aumenta el daño del combo en cadena en un <color=#FFFF00>20 %</color>.",
  str_skill_name_200154 = "Diluvio penetrante",
  str_skill_name_203154 = "Diluvio penetrante",
  str_skill_name_206154 = "Diluvio penetrante",
  str_skill_name_300154 = "Objetivo asegurado",
  str_skill_name_3001541 = "Objetivo asegurado",
  str_skill_name_320154 = "Objetivo asegurado",
  str_skill_name_330154 = "Objetivo asegurado",
  str_skill_desc_300154 = "Selecciona y <color=#00F6FF>bloqueos en</color> 1 enemigo. Puede haber un máximo de <color=#00F6FF>1</color> objetivo siendo bloqueado al mismo tiempo. Mientras el objetivo bloqueado esté vivo, los combos en cadena de Vice: Keen Sight siempre <color=#00F6FF>apuntarán</color>. Si el enemigo seleccionado ya está fijado, trata <color=#00F6FF>100%</color> dañarlo una vez en su lugar.",
  str_skill_desc_330154 = "Selecciona y <color=#00F6FF>bloqueos en</color> 1 enemigo. Puede haber un máximo de <color=#00F6FF>1</color> objetivo siendo bloqueado al mismo tiempo. Mientras el objetivo fijo vive, los combos en cadena de Vice: Keen Sight siempre <color=#00F6FF>apuntarán</color>. Si el enemigo seleccionado ya está fijado, trata <color=#00F6FF>100%</color> dañarlo una vez en su lugar. cada pila de <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> en el objetivo aumenta el daño en <color=#00F6FF>5%</color> Adicionalmente.",
  str_skill_desc_200154 = "ofertas <color=#00F6FF>100%</color> daño una vez al objetivo más cercano por cada <color=#00F6FF>3</color> fichas consecutivas recorridas. El daño no se ve afectado por la cantidad de fichas conectadas.",
  str_skill_desc_203154 = "ofertas <color=#00F6FF>100%</color> daño una vez al objetivo más cercano por cada <color=#00F6FF>3</color> fichas consecutivas recorridas. El daño no se ve afectado por la cantidad de fichas conectadas. Los tiempos del ataque Chain Combo siempre serán <color=#00F6FF>+1</color>.",
  str_skill_desc_206154 = "ofertas <color=#00F6FF>100%</color> daño una vez al objetivo más cercano por cada <color=#00F6FF>3</color> fichas consecutivas recorridas. El daño no se ve afectado por la cantidad de fichas conectadas. Los tiempos del ataque Chain Combo siempre serán <color=#00F6FF>+1</color>.",
  str_skill_passive_name_410154 = "Insignias atemporales",
  str_skill_passive_name_420154 = "Insignias atemporales",
  str_skill_passive_desc_410154 = "Inflige <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> en el objetivo fijo. cada pila de <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> aumenta el daño Vice: Keen Sight trata al objetivo por <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420154 = "Inflige <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> en el objetivo fijo. cada pila de <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> aumenta el daño Vice: Keen Sight trata al objetivo por <color=#00F6FF>{1}</color>. Vice: Keen Sight aplica 1 acumulación adicional de Timeless Mark en el objetivo fijo por cada <color=#00F6FF>3%</color> daño que inflige a los aliados.",
