  str_skill_desc_323155 = "Consume 20 <link=\"30046\"><#FFAE07><u>energía solitaria</u></color></link> entrar <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>10</color>, Lone Energy será <color=#00F6FF>reducido a la mitad</color> (reduciendo al menos 10 puntos) y <color=#00F6FF>conservar el estado solitario</color> en la próxima ronda.",
  str_skill_desc_326155 = "Consume 20 <link=\"30047\"><#FFAE07><u>energía solitaria</u></color></link> entrar <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>10</color>, Lone Energy será <color=#00F6FF>reducido a la mitad</color> (reduciendo al menos 10 puntos) y <color=#00F6FF>conservar el estado solitario</color> en la próxima ronda.",
  str_skill_desc_2001551 = "<color=#00F6FF>Estado normal</color>: Ganancias <color=#00F6FF>3</color> Lone Energy y ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color>.\n<color=#00F6FF>estado solitario</color>: Ofertas <color=#00F6FF>170%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>.",
  str_skill_desc_2001552 = "<color=#00F6FF>Estado normal</color>: Ganancias <color=#00F6FF>4</color> Lone Energy y ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>.\n<color=#00F6FF>estado solitario</color>: Ofertas <color=#00F6FF>190%</color> daño a <color=#00F6FF>16 fichas en forma radial</color>.",
  str_skill_desc_2001553 = "<color=#00F6FF>Estado normal</color>: Ganancias <color=#00F6FF>5</color> Lone Energy y ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>16 fichas en forma radial</color>.\n<color=#00F6FF>estado solitario</color>: Ofertas <color=#00F6FF>210%</color> daño a <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_20015510 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_20015520 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_desc_20015530 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_passive_desc_410155 = "Mientras en <color=#00F6FF>estado solitario, </color> los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos que no son de destino reciben <color=#00F6FF>{1}</color> de daños normales.",
  str_skill_passive_desc_416155 = "Mientras en <color=#00F6FF>estado solitario, </color> los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos no objetivo reciben <color=#00F6FF>{1}</color> de daños normales.",
  str_skill_passive_desc_420155 = "Mientras en <color=#00F6FF>estado solitario</color>, los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos no objetivo reciben <color=#00F6FF>{1}</color> de daños normales. Mientras en <color=#00F6FF>estado solitario</color>, el primer ataque normal a cada enemigo en cada ronda será seguido de un ataque normal adicional, infligiendo <color=#00F6FF>{1}</color> de daño a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_desc_426155 = "Mientras en <color=#00F6FF>estado solitario</color>, los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos no objetivo reciben <color=#00F6FF>{1}</color> de daños normales. Mientras en <color=#00F6FF>estado solitario</color>, el primer ataque normal a cada enemigo en cada ronda será seguido de un ataque normal adicional, infligiendo <color=#00F6FF>{1}</color> de daño a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_desc_430155 = "Los ataques normales pueden <color=#00F6FF>apuntar a enemigos en un azulejo diagonal</color>. Mientras en <color=#00F6FF>estado solitario, </color> los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos no objetivo reciben <color=#00F6FF>{1}</color> de daños normales. Mientras en <color=#00F6FF>estado solitario</color>, el primer ataque normal a cada enemigo en cada ronda será seguido de un ataque normal adicional, infligiendo <color=#00F6FF>{1}</color> daño a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_desc_436155 = "Los ataques normales pueden <color=#00F6FF>apuntar a enemigos en un azulejo diagonal</color>. Mientras en <color=#00F6FF>estado solitario, </color> los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos no objetivo reciben <color=#00F6FF>{1}</color> de daños normales. Mientras en <color=#00F6FF>estado solitario</color>, el primer ataque normal a cada enemigo en cada ronda será seguido de un ataque normal adicional, infligiendo <color=#00F6FF>{1}</color> daño a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_upgrade_desc_16015513 = "Mejora activa de habilidades: ganancias <color=#00F6FF>20</color> Lone Energy al comienzo de cada batalla.",
  str_skill_upgrade_desc_16015516 = "Mejora activa de habilidades: Inmediatamente gana <color=#00F6FF>5</color> Energía solitaria después de usar la habilidad activa.",
  str_skill_passive_desc_440153 = "Los ataques normales pueden <color=#00F6FF>apuntar a enemigos en un azulejo diagonal</color>. Mientras en <color=#00F6FF>estado solitario, </color> los ataques normales infligen daño a <color=#00F6FF>1 grupo circundante</color>. Los mosaicos no objetivo reciben <color=#00F6FF>65%</color> de daños normales. Mientras en <color=#00F6FF>estado solitario</color>, el primer ataque normal a cada enemigo en cada ronda será seguido de un ataque normal adicional, infligiendo <color=#00F6FF>65%</color> de daño a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_desc_350155 = "Consume 20 <link=\"30045\"><#FFAE07><u>energía solitaria</u></color></link> para entrar en <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria será <color=#00F6FF>reducida a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>conservará el estado solitario</color> en la próxima ronda.",
  str_skill_desc_353155 = "Consume 20 <link=\"30046\"><#FFAE07><u>energía solitaria</u></color></link> para entrar en <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria será <color=#00F6FF>reducida a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>conservará el estado solitario</color> en la próxima ronda.",
  str_skill_desc_356155 = "Consume 20 <link=\"30047\"><#FFAE07><u>energía solitaria</u></color></link> para entrar en <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria será <color=#00F6FF>reducida a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>conservará el estado solitario</color> en la próxima ronda.",
  str_skill_desc_360155 = "Consume 16 <link=\"30045\"><#FFAE07><u>energía solitaria</u></color></link> para entrar en <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria será <color=#00F6FF>reducida a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>conservará el estado solitario</color> en la próxima ronda.",
  str_skill_desc_363155 = "Consume 16 <link=\"30046\"><#FFAE07><u>energía solitaria</u></color></link> para entrar en <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria será <color=#00F6FF>reducida a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>conservará el estado solitario</color> en la próxima ronda.",
  str_skill_desc_366155 = "Consume 16 <link=\"30047\"><#FFAE07><u>energía solitaria</u></color></link> para entrar en <color=#00F6FF>estado solitario</color> en la ronda actual, aumentando el alcance y el daño de Chain Combo. Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria será <color=#00F6FF>reducida a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>conservará el estado solitario</color> en la próxima ronda.",
  str_skill_upgrade_refine_desc_16015511 = "Mejora de habilidades de equipo: Mientras en estado solitario, los ataques normales infligen un <color=#00F6FF>65%</color> de daño normal a los mosaicos no objetivo.",
  str_skill_upgrade_refine_desc_16015512 = "Mejora de habilidad activa: Al final de la ronda, si la energía solitaria restante al final de la ronda no es inferior a <color=#00F6FF>8</color>, la energía solitaria se <color=#00F6FF>reducirá a la mitad</color> (reduciendo al menos 8 puntos) y <color=#00F6FF>mantendrá el estado solitario en la próxima ronda</color>.",
  str_skill_upgrade_refine_desc_16015513 = "Mejora de habilidad activa: Consume <color=#00F6FF>16</color> Energía solitaria para entrar en estado solitario.",
  str_skill_upgrade_desc_16015313 = "Mejora de habilidad activa: cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate.\nMejora de habilidad de equipo: Al entrar en combate, gana instantáneamente <color=#FFFF00>2</color> Finale. (Válido para Ascensión I)",
  str_skill_upgrade_desc_16015316 = "Mejora de habilidad activa: reduce los tiempos de enfriamiento de habilidades en <color=#FFFF00>1</color>.\nMejora de habilidades de equipo: cada vez que pasa por un mosaico oscuro, aumenta el factor de daño de Combo de Cadena en <color=#FFFF00>2%</color>. (Válido para Ascensión II)",
  str_skill_name_2001531 = "Explosión de iluminación",
  str_skill_name_2001532 = "Explosión de iluminación",
  str_skill_name_2001533 = "Explosión de iluminación",
  str_skill_name_300153 = "Final iluminado",
  str_skill_name_306153 = "Final iluminado",
  str_skill_name_320153 = "Final iluminado",
  str_skill_name_326153 = "Final iluminado",
  str_skill_name_330153 = "Final iluminado",
  str_skill_name_336153 = "Final iluminado",
  str_skill_desc_300153 = "Selecciona cualquiera <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> da la vuelta y luego entra <color=#00F6FF>estado de finalidad</color> por 2 rondas. Mientras está en el estado Finality, los ataques normales se extienden a <color=#00F6FF>azulejos diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>.",
  str_skill_desc_306153 = "Selecciona cualquiera <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> da la vuelta y luego entra <color=#00F6FF>estado de finalidad</color> por 2 rondas. Mientras está en el estado Finality, los ataques normales se extienden a <color=#00F6FF>azulejos diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>.",
  str_skill_desc_320153 = "Selecciona cualquier <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> rondas, y luego entra en <color=#00F6FF>estado de Finalidad</color> durante 2 rondas. Mientras está en el estado de Finalidad, los ataques normales se extienden a <color=#00F6FF>fichas diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>. Obtiene un adicional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Final</u></color></link> independientemente del límite mientras está en estado de Finalidad.",
  str_skill_desc_326153 = "Selecciona cualquier <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> rondas, y luego entra en <color=#00F6FF>estado de Finalidad</color> durante 2 rondas. Mientras está en el estado de Finalidad, los ataques normales se extienden a <color=#00F6FF>fichas diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>. Obtiene un adicional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Final</u></color></link> independientemente del límite mientras está en estado de Finalidad.",
  str_skill_desc_330153 = "Selecciona cualquier <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> rondas, y luego entra en <color=#00F6FF>estado de Finalidad</color> durante 2 rondas. Mientras está en el estado de Finalidad, los ataques normales se extienden a <color=#00F6FF>fichas diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>. Obtiene un adicional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Final</u></color></link> independientemente del límite mientras está en estado de Finalidad.",
  str_skill_desc_336153 = "Selecciona cualquier <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> rondas, y luego entra en <color=#00F6FF>estado de Finalidad</color> durante 2 rondas. Mientras está en el estado de Finalidad, los ataques normales se extienden a <color=#00F6FF>fichas diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>. Obtiene un adicional <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Final</u></color></link> independientemente del límite mientras está en estado de Finalidad.",
  str_skill_desc_2001531 = "ofertas <color=#00F6FF>{1}%</color> daño a los 3 enemigos más cercanos dentro <color=#00F6FF>3 grupos circundantes</color>.",
  str_skill_desc_2001532 = "ofertas <color=#00F6FF>{1}%</color> daño a los 4 enemigos más cercanos dentro <color=#00F6FF>4 círculos circundantes</color>.",
  str_skill_desc_2001533 = "Inflige un <color=#00F6FF>{1}% </color> de daño a todos los enemigos dentro de <color=#00F6FF> 4 cúmulos circundantes </color>.",
  str_skill_passive_name_410153 = "Poder de Ilumina",
