  str_skill_passive_name_436153 = "Poder de Ilumina",
  str_skill_passive_desc_410153 = "Ganancias <link=\"30043\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413153 = "Gana <link=\"30043\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Final.",
  str_skill_passive_desc_420153 = "Ganancias <link=\"300442\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede superar el límite de Final. Este Final adicional desaparece al entrar en la Hora de Aurora, o al final de la ronda.",
  str_skill_passive_desc_423153 = "Ganancias <link=\"300442\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Final. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede superar el límite de Final. Este Final adicional desaparece al entrar en la Hora de Aurora, o al final de la ronda.",
  str_skill_passive_desc_426153 = "Gana <link=\"300442\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Finales. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede exceder el límite de Finales, y aumenta el factor de daño del Combo en Cadena en <color=#00F6FF>2%</color>. Este Final adicional y el bono de Combo en Cadena desaparecen al entrar en la Hora de Aurora, o al final de la ronda.",
  str_skill_passive_desc_430153 = "Gana <link=\"300442\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. <color=#00F6FF>Trueno</color> o <color=#00F6FF>Federación Illumina</color> Los aurorianos ganan un 50% de bono Final</color> basado en su <color=#00F6FF>ATK</color>. Al pasar por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede superar el límite de Final. Este Final adicional desaparece al entrar en Tiempo Aurora, o al final de la ronda.",
  str_skill_passive_desc_433153 = "Gana <link=\"300442\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. <color=#00F6FF>Trueno</color> o <color=#00F6FF>Federación Illumina</color> Los aurorianos ganan un 50% de bonificación de Final</color> basado en su <color=#00F6FF>ATK</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Finales. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede exceder el límite de Final. Este Final adicional desaparece al entrar en Tiempo Aurora, o al final de la ronda.",
  str_skill_passive_desc_436153 = "Gana <link=\"300442\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>{1}</color>. <color=#00F6FF>Trueno</color> o <color=#00F6FF>Federación Illumina</color> Los aurorianos ganan un 50% de bonificación de Final</color> basado en su <color=#00F6FF>ATK</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Finales. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede exceder el límite de Final, y aumenta el factor de daño de Combo en Cadena en <color=#00F6FF>2%</color>. Este Final adicional y la bonificación de Combo en Cadena desaparecen al entrar en Tiempo Aurora, o al final de la ronda.",
  str_skill_upgrade_refine_desc_16015311 = "Mejora de Habilidad Activa: Gana <color=#00F6FF>6</color> Final temporales después de entrar en el estado de Finalidad.",
  str_skill_upgrade_refine_desc_16015312 = "Mejora del Combo en Cadena: Aumenta el daño en <color=#00F6FF>10%</color>.",
  str_skill_upgrade_refine_desc_16015313 = "Mejora de Habilidad Activa: Si el Combo en Cadena inflige múltiples instancias de daño al mismo mosaico después de entrar en el estado de Finalidad, cada daño final siguiente se reduce en <color=#00F6FF>15%</color>.",
  str_skill_desc_2501531 = "Inflige un <color=#00F6FF>150%</color> de daño a los 3 enemigos más cercanos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_desc_2501532 = "Ofertas <color=#00F6FF>160%</color> daño a los 4 enemigos más cercanos dentro <color=#00F6FF>4 grupos circundantes</color>.",
  str_skill_desc_2501533 = "Inflige un <color=#00F6FF>170%</color> de daño a todos los enemigos dentro de <color=#00F6FF>4 cúmulos circundantes</color>.",
  str_skill_desc_340153 = "Selecciona cualquier <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> rondas, y luego entra en <color=#00F6FF>estado de Finalidad</color> durante 2 rondas. Mientras está en el estado de Finalidad, los ataques normales se extienden a <color=#00F6FF>fichas diagonales</color>. Mientras tanto, la habilidad Chain Combo inflige la mitad adicional del daño actual al mosaico donde se encuentra el Air Raid Beacon y 4 mosaicos circundantes. Al infligir daño varias veces al mismo mosaico, cada daño final siguiente se reduce en <color=#00F6FF>20%</color>. Obtiene un adicional <color=#00F6FF>6</color> <link=\"300443\"><#FFAE07><u>Final</u></color></link> independientemente del límite mientras está en estado de Finalidad.",
  str_skill_desc_360153 = "Selecciona cualquier <color=#00F6FF>4</color> fichas y convoca una baliza de ataque aéreo que dura <color=#00F6FF>2</color> rondas, y luego entra en <color=#00F6FF>estado de Finalidad</color> durante 2 rondas. Mientras está en el estado de Finalidad, los ataques normales se extienden a <color=#00F6FF>fichas diagonales</color>. Mientras tanto, la habilidad de Combo en Cadena inflige la mitad adicional del daño actual a la ficha donde se encuentra la baliza de ataque aéreo y a 4 fichas circundantes. Cuando se inflige daño varias veces a la misma ficha, cada daño final siguiente se reduce en <color=#00F6FF>15%</color>. Gana un adicional <color=#00F6FF>6</color> <link=\"300443\"><#FFAE07><u>Final</u></color></link> sin importar el límite mientras está en estado de Finalidad.",
  str_skill_passive_desc_450153 = "Gana <link=\"300443\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>3%</color>. <color=#00F6FF>Trueno</color> o <color=#00F6FF>Federación Illumina</color> Los aurorianos ganan un 50% de bono Final</color> basado en su <color=#00F6FF>ATK</color>. Al pasar por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede superar el límite de Final. Este Final adicional desaparece al entrar en Tiempo Aurora, o al final de la ronda.",
  str_skill_passive_desc_453153 = "Gana <link=\"300443\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>3%</color>. <color=#00F6FF>Trueno</color> o <color=#00F6FF>Federación Illumina</color> Los aurorianos ganan un 50% de bono Final</color> basado en su <color=#00F6FF>ATK</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Finales. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede superar el límite de Finales. Este Final adicional desaparece al entrar en Tiempo Aurora, o al final de la ronda.",
  str_skill_passive_desc_456153 = "Gana <link=\"300443\"><#FFAE07><u>Final</u></color></link>, y cada Final aumenta el ATK en <color=#00F6FF>3%</color>. <color=#00F6FF>Trueno</color> o <color=#00F6FF>Federación Illumina</color> Los aurorianos ganan un 50% de bonificación de Final</color> basado en su <color=#00F6FF>ATK</color>. Al entrar en combate, gana instantáneamente <color=#00F6FF>2</color> Finales. Cada vez que pasa por una Casilla Oscura, gana <color=#00F6FF>1</color> Final temporal que puede exceder el límite de Final, y aumenta el factor de daño de Combo en Cadena en <color=#00F6FF>2%</color>. Este Final adicional y la bonificación de Combo en Cadena desaparecen al entrar en el Tiempo de Aurora, o al final de la ronda.",
  str_skill_name_290230101 = "Claudia: Choque de meteoritos",
  str_skill_name_290230102 = "Claudia: Choque de meteoritos",
  str_skill_name_290230103 = "Claudia: Choque de meteoritos",
  str_skill_name_290230104 = "Claudia: Choque de meteoritos",
  str_skill_name_290230201 = "Claudia: hendidura saltadora",
  str_skill_name_290230202 = "Claudia: hendidura saltadora",
  str_skill_name_290230203 = "Claudia: hendidura saltadora",
  str_skill_name_290230301 = "Claudia: Cortar",
  str_skill_name_290230401 = "Plataforma Emergente",
  str_skill_name_290240101 = "Asher: Agresión",
  str_skill_desc_290230101 = "Cuando Claudia está parado en el suelo, todas las plataformas dentro de un rango en forma de cruz alrededor del enemigo son convocadas para embestir juntas, infligiendo daño varias veces al enemigo.",
  str_skill_desc_290230102 = "Cuando Claudia está parado en una plataforma, todas las plataformas dentro de un rango en forma de cruz alrededor del enemigo son convocadas para embestir juntas. Si Claudia está dentro de este rango, el enemigo quedará aturdido.",
  str_skill_desc_290230103 = "Cuando Claudia está parado en Asher, todas las plataformas dentro de un rango en forma de cruz alrededor del enemigo son convocadas para embestir juntas. Si Asher también está dentro de este rango, el enemigo será aturdido y empujado hacia atrás.",
  str_skill_desc_290230104 = "Cuando no hay plataformas dentro de un rango en forma de cruz alrededor del enemigo, Claudia convoca 4 plataformas en ubicaciones aleatorias dentro de mosaicos de 5 × 5 en el centro del campo. Luego genera una plataforma en la posición más alejada del enemigo en el campo y se teletransporta allí.",
  str_skill_desc_290230201 = "Si el enemigo está dentro del rango de ataque, Claudia se teletransporta al lado del enemigo, infligiendo daño severo y luego retrocediendo una corta distancia. Si no hay enemigos dentro del rango de ataque, Claudia genera una plataforma dentro de mosaicos de 5 × 5 en el centro del campo y se teletransporta a la posición más alejada del enemigo en el campo.",
  str_skill_desc_290230202 = "Si el enemigo está dentro del rango de ataque, Claudia se teletransporta al lado del enemigo, infligiendo daño severo y luego retrocediendo una corta distancia. Si no hay enemigos dentro del rango de ataque, Claudia genera una plataforma dentro de mosaicos de 5 × 5 en el centro del campo y se teletransporta a la posición más alejada del enemigo en el campo.",
  str_skill_desc_290230203 = "Si el enemigo está dentro del rango de ataque, Claudia se teletransporta al lado del enemigo, infligiendo daño severo y luego retrocediendo una corta distancia. Si no hay enemigos dentro del rango de ataque, Claudia genera una plataforma dentro de mosaicos de 5 × 5 en el centro del campo y se teletransporta a la posición más alejada del enemigo en el campo.",
  str_skill_desc_290230301 = "Claudia genera una plataforma en el centro del campo y en la casilla enemiga respectivamente. Luego se teletransporta a la plataforma y se corta, infligiendo daño a pantalla completa a todos los enemigos.",
  str_skill_desc_290230401 = "Al comienzo de la ronda, Claudia convoca como máximo 10 plataformas en el borde del campo.",
  str_skill_desc_290240101 = "Asher se acerca a un enemigo dentro del rango de ataque y ataca una vez, aplastando todas las plataformas en el camino. Si no se puede atacar a ningún enemigo, Asher todavía espera en el lugar.",
  str_skill_name_290250101 = "Final de inmolación",
  str_skill_desc_290250101 = "Minos se mueve al azar en el campo durante un período de tiempo y restablece todas las fichas atravesadas. Después de moverse, Minos dispara al jugador e inflige un gran daño una vez.",
  str_skill_name_290250102 = "ataque fantasma",
  str_skill_desc_290250102 = "Si Minos pasa una ficha mejorada, se invocará un fantasma en la ficha mejorada para infligir daño único al jugador. El daño infligido por el fantasma aumenta a medida que se acumula la Marca de Minos.",
  str_skill_name_290250201 = "Fantasma de restauración",
  str_skill_desc_290250201 = "Minos absorbe todas las fichas mejoradas y debilitadas del tablero y luego inflige daño al jugador. Minos inflige daño 1 vez más por cada mosaico mejorado que absorbe. El daño infligido aumenta a medida que se acumula la marca de Minos.",
  str_skill_name_390250101 = "Infame - Ataque fantasma",
  str_skill_desc_390250101 = "Nefarious Minos elige un camino con la mayor cantidad de fichas debilitadas y mueve 5 fichas, absorbiendo fichas mejoradas y debilitadas en su camino. Cada vez que absorbe fichas debilitadas, se invocará un fantasma para infligir daño único al jugador. Si no hay ninguna ficha debilitada en el camino o en el tablero, Minos invocará 7 fichas debilitadas dentro de los 3 grupos circundantes.",
  str_skill_name_390250102 = "Nefarious - Final de inmolación",
  str_skill_desc_390250102 = "Infame: Minos se fija en el objetivo y dispara, infligiendo daño a pantalla completa.",
  str_skill_name_390310106 = "Nefasto - Dulce beso",
  str_skill_desc_390310106 = "Nefarious Barbara se mueve a la ubicación más lejana del objetivo conectando mosaicos, luego inflige daño de área grande excepto en zonas seguras y rompe mosaicos rojos fuera de las zonas seguras.",
  str_skill_name_390310107 = "Nefasto - Nota final",
  str_skill_desc_390310107 = "Nefarious Barbara se mueve a la ubicación más alejada del objetivo conectando mosaicos, luego convoca aliados en el centro del tablero, infligiendo daño a pantalla completa y derribando objetivos.",
  str_skill_name_390320102 = "Concierto nefasto de pavor",
  str_skill_name_390320103 = "Nefasta Sonata del Abismo",
  str_skill_desc_390320102 = "Nefarious Connolly se mueve al punto más lejano que aún puede alcanzar al objetivo conectando mosaicos y causa daño a todas las unidades enemigas dentro de 2 grupos circundantes. Si este movimiento no ataca a ningún objetivo, invoca tentáculos en ubicaciones aleatorias.",
  str_skill_desc_390320103 = "Nefarious Connolly se mueve a la ubicación más lejana del objetivo conectando mosaicos, luego inflige daño a todos los objetivos en la pantalla.",
  str_skill_name_390330102 = "Flor oculta infame",
  str_skill_name_390330103 = "Dominio de cristal nefasto",
  str_skill_desc_390330102 = "Nefarious Beryl se mueve al punto más lejano que aún puede alcanzar al objetivo conectando mosaicos e inflige daño a todas las unidades enemigas dentro de 16 mosaicos en forma radial. Si este movimiento no ataca a ningún objetivo, invoca cristales sanguíneos en ubicaciones aleatorias.",
  str_skill_desc_390330103 = "Nefarious Beryl se mueve a la ubicación más lejana del objetivo conectando mosaicos, luego inflige daño a todos los objetivos en la pantalla.",
