  str_skill_desc_2001561 = "<color=#00F6FF>Modo sombrilla</color>: Ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color>.\n<color=#00F6FF>Modo desarmado</color>: Ofertas <color=#00F6FF>150%</color> daño a 2 enemigos más cercanos.",
  str_skill_desc_2001562 = "<color=#00F6FF>Modo sombrilla</color>: Ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>.\n<color=#00F6FF>Modo desarmado</color>: Ofertas <color=#00F6FF>160%</color> daño a los 3 enemigos más cercanos.",
  str_skill_desc_2001563 = "<color=#00F6FF>Modo sombrilla</color>: Ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color>.\n<color=#00F6FF>Modo desarmado</color>: Ofertas <color=#00F6FF>170%</color> daño a los 4 enemigos más cercanos.",
  str_skill_desc_2001564 = "<color=#00F6FF>Modo sombrilla</color>: Ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color>.\n<color=#00F6FF>Modo desarmado</color>: Ofertas <color=#00F6FF>150%</color> daño a 2 enemigos más cercanos.",
  str_skill_desc_2001565 = "<color=#00F6FF>Modo sombrilla</color>: Ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>.\n<color=#00F6FF>Modo desarmado</color>: Ofertas <color=#00F6FF>160%</color> daño a los 3 enemigos más cercanos.",
  str_skill_desc_2001566 = "<color=#00F6FF>Modo sombrilla</color>: Ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color>.\n<color=#00F6FF>Modo desarmado</color>: Ofertas <color=#00F6FF>170%</color> daño a los 4 enemigos más cercanos.",
  str_skill_desc_300156 = "<color=#00F6FF>Modo Parasol</color>: selecciona 1 mosaico atravesable y arroja el parasol al mosaico seleccionado, lo que inflige <color=#00F6FF>80 %</color> de daño a los mosaicos a lo largo del camino, luego cambia a <color=#00F6FF>Modo desarmado</color>.\n<color=#00F6FF>Modo desarmado</color>: recupera la sombrilla, lo que inflige <color=#00F6FF>640 %</color> de daño a las casillas a lo largo del camino, luego cambia a <color=#00F6FF>Modo sombrilla</color>.\nCambia a <color=#00F6FF>Modo sombrilla</color> cada vez que se cubre o se quita la sombrilla. Cuando está cubierto por un enemigo, el tiempo de reutilización de la habilidad <color=#00F6FF>+1</color> ronda.",
