  str_skill_desc_3351570 = "Usos <color=#00F6FF>3</color> <link=\"30049\"><#FFAE07><u>Puntos de rosca</u></color></link> convocar <color=#00F6FF>maná</color> en una loseta disponible o usos <color=#00F6FF>1</color> <link=\"30049\"><#FFAE07><u>Punto de rosca</u></color></link> para mover <color=#00F6FF>maná</color>. Llévate a Manae al final de nuestra ronda. Mientras se mueve, Manae hará todo lo posible para <color=#00F6FF>mantener la posición relativa</color> con Sanae e inflige daño que ignora DEF <color=#00F6FF>igual al ATK de Manae</color> al enemigo con el que choca. Manae hereda <color=#00F6FF>70%</color> del ATK básico de Sanae. Entrar en Aurora Time otorga 1 adicional <color=#00F6FF>Muevete</color> a Manae.",
  str_skill_passive_desc_410157 = "Manae gana 1 acumulación de Thread Mark cuando inflige daño. Cada acumulación aumenta su herencia del ATK de Sanae en <color=#00F6FF>{1}</color>, hasta 30 pilas.",
  str_skill_passive_desc_420157 = "Manae gana 1 acumulación de Thread Mark cuando inflige daño. Cada acumulación aumenta su herencia del ATK de Sanae en <color=#00F6FF>{1}</color>, hasta 30 pilas. Una vez que Manae lleva 30 acumulaciones de Thread Mark o gana <color=#00F6FF>5</color> acumula en una sola ronda, ella podrá <color=#00F6FF>suelte Chain Combo simultáneamente</color> con Sanae.",
  str_skill_upgrade_desc_16015813 = "Mejora de habilidades de equipo: cuando Joker cambia por primera vez de miembro del equipo a Capitán durante la batalla, Joker gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_upgrade_desc_16015816 = "Mejora de habilidades de equipo: cuando Joker cambia entre miembro del equipo y Capitán, el Capitán cambia +1, activado una vez por ronda.",
  str_skill_desc_300158 = "Joker entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Selecciona 1 enemigo para tratar <color=#00F6FF>{1}%</color> daño a y <color=#00F6FF>doble</color> su <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> pilas. El daño de la Habilidad Activa aumenta en función del número de casillas ocupadas por el objetivo.",
  str_skill_desc_320158 = "Joker entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Selecciona 1 enemigo para tratar <color=#00F6FF>{1}%</color> daño a y <color=#00F6FF>doble</color> su <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> pilas Si la habilidad activa de Joker estaba lista en la ronda anterior, las pilas son <color=#00F6FF>triplicado</color> en cambio. El daño de la Habilidad Activa aumenta en función del número de casillas ocupadas por el objetivo.",
  str_skill_desc_3201580 = "Joker entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Selecciona 1 enemigo para tratar <color=#00F6FF>{1}%</color> daño a y <color=#00F6FF>doble</color> su <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> pilas Si la habilidad activa de Joker estaba lista en la ronda anterior, las pilas son <color=#00F6FF>triplicado</color> en cambio. El daño de la Habilidad Activa aumenta en función del número de casillas ocupadas por el objetivo.",
  str_skill_desc_2001581 = "ofertas <color=#00F6FF>{1}%</color> daño a los 3 enemigos más cercanos dentro <color=#00F6FF>4 grupos circundantes</color>, e inflige <color=#00F6FF>3 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado.",
  str_skill_desc_2001582 = "ofertas <color=#00F6FF>{1}%</color> daño a los 4 enemigos más cercanos dentro <color=#00F6FF>4 grupos circundantes</color>, e inflige <color=#00F6FF>5 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado.",
  str_skill_desc_2001583 = "ofertas <color=#00F6FF>{1}%</color> daño a todos los enemigos dentro <color=#00F6FF>4 grupos circundantes</color>, e inflige <color=#00F6FF>7 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado.",
  str_skill_passive_desc_410158 = "Con cada derrota del enemigo, <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumulaciones se distribuyen entre los enemigos restantes, otorgando hasta <color=#00F6FF>{1}</color> acumula a cada enemigo.",
  str_skill_passive_desc_413158 = "Con cada derrota del enemigo, <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumulaciones se distribuyen entre los enemigos restantes, otorgando hasta <color=#00F6FF>{1}</color> acumula a cada enemigo. Cuando Joker cambia por primera vez de miembro del equipo a Capitán durante la batalla, Joker gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_passive_desc_416158 = "Con cada derrota del enemigo, <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumulaciones se distribuyen entre los enemigos restantes, otorgando hasta <color=#00F6FF>{1}</color> acumula a cada enemigo. Cuando el Guasón cambia por primera vez de miembro del equipo a Capitán durante la batalla, el Guasón gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda. Cuando Joker cambia de rol entre el miembro del equipo y el Capitán, el Capitán cambia +1, activado una vez por ronda.",
  str_skill_passive_desc_430158 = "Con cada derrota del enemigo, <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumulaciones se distribuyen entre los enemigos restantes, otorgando hasta <color=#00F6FF>{1}</color> acumula a cada enemigo. Joker inflige <color=#00F6FF>1</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> con cada Ataque Normal.",
  str_skill_passive_desc_433158 = "Con cada derrota del enemigo, <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumulaciones se distribuyen entre los enemigos restantes, otorgando hasta <color=#00F6FF>{1}</color> acumula a cada enemigo. el bromista inflige <color=#00F6FF>1</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> con cada Ataque Normal. Cuando Joker cambia por primera vez de miembro del equipo a Capitán durante la batalla, Joker gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_passive_desc_436158 = "Con cada derrota del enemigo, <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumulaciones se distribuyen entre los enemigos restantes, otorgando hasta <color=#00F6FF>{1}</color> acumula a cada enemigo. el bromista inflige <color=#00F6FF>1</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> con cada Ataque Normal. Cuando el Guasón cambia por primera vez de miembro del equipo a Capitán durante la batalla, el Guasón gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda. Cuando Joker cambia de rol entre el miembro del equipo y el Capitán, el Capitán cambia +1, activado una vez por ronda.",
  str_skill_upgrade_desc_16015913 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16015916 = "Mejora de habilidades de equipo: cuando Queen cambia por primera vez de miembro del equipo a Capitán durante la batalla, Queen gana <color=#00F6FF>15%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_desc_300159 = "Queen entra en la batalla con ella <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>todos</color> enemigos e inflige <color=#00F6FF>6</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>.",
  str_skill_desc_320159 = "Queen entra en la batalla con ella <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>todos</color> enemigos e inflige <color=#00F6FF>6</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos de agua reciben <color=#00F6FF>12 pilas</color> en cambio.",
  str_skill_desc_2001591 = "ofertas <color=#00F6FF>{1}%</color> daño a todos los enemigos dentro <color=#00F6FF>1 grupo circundante</color>, e inflige <color=#00F6FF>2 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado. Los enemigos de agua reciben <color=#00F6FF>4 pilas</color> en cambio.",
  str_skill_desc_2001592 = "Causa <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 mosaicos en forma radial</color> e inflige <color=#00F6FF>3 acumulaciones</color> de <link=\"30052\"><#FFAE07><u>Aprovecha la debilidad</u></color></link> de cada enemigo golpeado. Los enemigos del agua reciben <color=#00F6FF>6 acumulaciones</color> en su lugar.",
  str_skill_desc_2001593 = "ofertas <color=#00F6FF>{1}%</color> daño a todos los enemigos dentro <color=#00F6FF>2 clúster circundante</color>, e inflige <color=#00F6FF>4 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado. Los enemigos de agua reciben <color=#00F6FF>8 pilas</color> en cambio.",
  str_skill_passive_desc_410159 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>{1}</color> de daño básico por golpe.",
  str_skill_passive_desc_416159 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>{1}</color> de daño básico por golpe. Cuando Queen cambia por primera vez de miembro del equipo a Capitán durante la batalla, Queen gana <color=#00F6FF>15%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_passive_desc_430159 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>{1}</color> de daño básico por golpe. Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos de agua reciben <color=#00F6FF>2 pilas</color> en cambio.",
  str_skill_passive_desc_436159 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>{1}</color> de daño básico por golpe. Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos de agua reciben <color=#00F6FF>2 pilas</color> en cambio. Cuando Queen cambia por primera vez de miembro del equipo a Capitán durante la batalla, Queen gana <color=#00F6FF>15%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_desc_300160 = "Fox entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color> e inflige <color=#00F6FF>9</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>.",
  str_skill_desc_320160 = "Fox entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>2 grupos circundantes</color> e inflige <color=#00F6FF>9</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos de fuego reciben <color=#00F6FF>18</color> pilas en su lugar.",
  str_skill_desc_2001601 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 columna</color>, e inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo. Los enemigos de fuego reciben <color=#00F6FF>3</color> pilas en su lugar.",
  str_skill_desc_2001602 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>3 columnas</color>, e inflige <color=#00F6FF>2</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo. Los enemigos de fuego reciben <color=#00F6FF>4</color> pilas en su lugar.",
  str_skill_desc_2001603 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>3 columnas</color>, e inflige <color=#00F6FF>3</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo. Los enemigos de fuego reciben <color=#00F6FF>6</color> pilas en su lugar.",
  str_skill_passive_desc_410160 = "El primer ataque normal de cada ronda trata <color=#00F6FF>{1}</color> veces daño.",
  str_skill_passive_desc_415160 = "El primer Ataque Normal de cada ronda reparte <color=#00F6FF>{1}</color> veces la cantidad de daño. Cuando Fox cambia por primera vez de miembro del equipo a Capitán durante la batalla, Fox gana <color=#00F6FF>15%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_passive_desc_430160 = "Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>, Los enemigos de fuego reciben <color=#00F6FF>2</color> pilas en su lugar. El primer ataque normal de cada ronda inflige e inflige <color=#00F6FF>{1}</color> veces el daño y <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> pilas",
  str_skill_passive_desc_435160 = "Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>, Los enemigos de fuego reciben <color=#00F6FF>2</color> pilas en su lugar. El primer ataque normal de cada ronda inflige e inflige <color=#00F6FF>{1}</color> veces el daño y <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> pilas Cuando Fox cambia por primera vez de miembro del equipo a Capitán durante la batalla, Fox gana <color=#00F6FF>15%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_upgrade_desc_15016012 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15016015 = "Mejora de habilidades de equipo: cuando Fox cambia por primera vez de miembro del equipo a Capitán durante la batalla, Fox gana <color=#00F6FF>15%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_desc_300161 = "Violet entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Causa <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados alrededor de 1 mosaico seleccionado e inflige <color=#00F6FF>9</color> montones de <link=\"30052\"><#FFAE07><u>explotar debilidad</u></color></link>.",
  str_skill_desc_320161 = "Violet entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Causa <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados alrededor de 1 mosaico seleccionado e inflige <color=#00F6FF>9</color> montones de <link=\"30052\"><#FFAE07><u>explotar debilidad</u></color></link>. Los enemigos del bosque reciben <color=#00F6FF>18</color> acumulaciones en su lugar.",
  str_skill_desc_2001611 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 columna</color>, e inflige <color=#00F6FF>2</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo. Los enemigos del bosque reciben <color=#00F6FF>4</color> pilas en su lugar.",
  str_skill_desc_2001612 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>3 columnas</color>, e inflige <color=#00F6FF>3</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo. Los enemigos del bosque reciben <color=#00F6FF>6</color> pilas en su lugar.",
  str_skill_desc_2001613 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>3 columnas</color>, e inflige <color=#00F6FF>4</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo. Los enemigos del bosque reciben <color=#00F6FF>8</color> pilas en su lugar.",
  str_skill_passive_desc_410161 = "Violet aumenta todo el daño infligido a los enemigos infligidos con el <color=#00F6FF>DÉBIL</color> estado por <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_415161 = "Violet aumenta todo el daño infligido a los enemigos infligidos con el <color=#00F6FF>DÉBIL</color> estado por <color=#00F6FF>{1}</color>. Cuando Violet cambia por primera vez de miembro del equipo a Capitán durante la batalla, Violet gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_passive_desc_430161 = "Violet aumenta todo el daño infligido a los enemigos infligidos con el <color=#00F6FF>DÉBIL</color> estado por <color=#00F6FF>{1}</color>. Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>, Los enemigos del bosque reciben <color=#00F6FF>2</color> pilas en su lugar.",
  str_skill_passive_desc_435161 = "Violet aumenta todo el daño infligido a los enemigos infligidos con el <color=#00F6FF>DÉBIL</color> estado por <color=#00F6FF>{1}</color>. Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>, Los enemigos del bosque reciben <color=#00F6FF>2</color> pilas en su lugar. Cuando Violet cambia por primera vez de miembro del equipo a Capitán durante la batalla, Violet gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_upgrade_desc_15016112 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15016115 = "Mejora de habilidades de equipo: cuando Violet cambia por primera vez de miembro del equipo a Capitán durante la batalla, Violet gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_upgrade_desc_15016212 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15016215 = "Mejora de habilidades de equipo: cuando Mona cambia por primera vez de miembro del equipo a Capitán durante la batalla, Mona gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_desc_3001621 = "Mona entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Selecciona una ficha y reparte <color=#00F6FF>{1}%</color> daño a lo largo del camino y en las casillas adyacentes, e inflige <color=#00F6FF>5</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado.",
  str_skill_desc_3201621 = "Mona entra en la batalla con su <link=\"30051\"><#FFAE07><u>Habilidad especial</u></color></link>. Selecciona una ficha y reparte <color=#00F6FF>{1}%</color> daño a lo largo del camino y en las casillas adyacentes, e inflige <color=#00F6FF>5</color> montones de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos del trueno reciben <color=#00F6FF>10 pilas</color> en cambio.",
  str_skill_desc_2001621 = "ofertas <color=#00F6FF>{1}%</color> daño a los 2 enemigos más cercanos dentro <color=#00F6FF>3 grupos circundantes</color>, e inflige <color=#00F6FF>1 pila</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado. Los enemigos del trueno reciben <color=#00F6FF>3 pilas</color> en cambio.",
  str_skill_desc_2001622 = "ofertas <color=#00F6FF>{1}%</color> daño a los 3 enemigos más cercanos dentro <color=#00F6FF>3 grupos circundantes</color>, e inflige <color=#00F6FF>2 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado. Los enemigos del trueno reciben <color=#00F6FF>4 pilas</color> en cambio.",
  str_skill_desc_2001623 = "ofertas <color=#00F6FF>{1}%</color> daño a los 4 enemigos más cercanos dentro <color=#00F6FF>3 grupos circundantes</color>, e inflige <color=#00F6FF>3 pilas</color> de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> a cada enemigo golpeado. Los enemigos del trueno reciben <color=#00F6FF>5 pilas</color> en cambio.",
  str_skill_passive_desc_410162 = "Cuando Mona inflige <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumula en los enemigos, hay un <color=#00F6FF>{1}</color> probabilidad de duplicar el efecto y una <color=#00F6FF>{2}</color> posibilidad de infligir <color=#00F6FF>DÉBIL</color> estado.",
  str_skill_passive_desc_415162 = "Cuando Mona inflige <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumula en los enemigos, hay un <color=#00F6FF>{1}</color> probabilidad de duplicar el efecto y una <color=#00F6FF>{2}</color> posibilidad de infligir <color=#00F6FF>DÉBIL</color> estado. Cuando Mona cambia por primera vez de miembro del equipo a Capitán durante la batalla, Mona gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
  str_skill_passive_desc_430162 = "Cuando Mona inflige <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumula en los enemigos, hay un <color=#00F6FF>{1}</color> probabilidad de duplicar el efecto y una <color=#00F6FF>{2}</color> posibilidad de infligir <color=#00F6FF>DÉBIL</color> estado. Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos del trueno reciben <color=#00F6FF>2 pilas</color> en cambio.",
  str_skill_passive_desc_435162 = "Cuando Mona inflige <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link> acumula en los enemigos, hay un <color=#00F6FF>{1}</color> probabilidad de duplicar el efecto y una <color=#00F6FF>{2}</color> posibilidad de infligir <color=#00F6FF>DÉBIL</color> estado. Cada ataque normal inflige <color=#00F6FF>1</color> pila de <link=\"30052\"><#FFAE07><u>Explotar la debilidad</u></color></link>. Los enemigos del trueno reciben <color=#00F6FF>2 pilas</color> en cambio. Cuando Mona cambia por primera vez de miembro del equipo a Capitán durante la batalla, Mona gana <color=#00F6FF>20%</color> aumentado el daño de ataque normal en esta ronda.",
