  str_skill_desc_2001681 = "ofertas <color=#00F6FF>{1}%</color> daño a los 2 enemigos más cercanos, luego genera un <link=\"30061\"><#FFAE07><u>Marca de lluvia solar</u></color></link> en 1 casilla aleatoria ocupada por un enemigo.",
  str_skill_desc_2001682 = "ofertas <color=#00F6FF>{1}%</color> daño a los 3 enemigos más cercanos, luego genera un <link=\"30061\"><#FFAE07><u>Marca de lluvia solar</u></color></link> en 1 casilla aleatoria ocupada por un enemigo.",
  str_skill_desc_2001683 = "ofertas <color=#00F6FF>{1}%</color> daño a los 4 enemigos más cercanos, luego genera un <link=\"30061\"><#FFAE07><u>Marca de lluvia solar</u></color></link>en 1 casilla aleatoria ocupada por un enemigo.",
  str_skill_desc_300168 = "Activa todo <link=\"30061\"><#FFAE07><u>Marcas de lluvia solar</u></color></link> en el campo y tratos <color=#00F6FF>240%</color> daño a <color=#00F6FF>5 fichas en forma de cruz</color> alrededor de ellos. Si un objetivo sufre daño más de una vez, el daño por cada golpe después del primero se reduce, hasta <color=#00F6FF>10%</color> del daño original.",
  str_skill_desc_320168 = "Activa todo <link=\"30061\"><#FFAE07><u>Marcas de lluvia solar</u></color></link> en el campo y tratos <color=#00F6FF>240%</color> daño a <color=#00F6FF>9 fichas en forma de cuadrado</color> alrededor de ellos. Si un objetivo sufre daño más de una vez, el daño por cada golpe después del primero se reduce, hasta <color=#00F6FF>10%</color> del daño original.",
  str_skill_desc_330168 = "Activa todo <link=\"30061\"><#FFAE07><u>Marcas de lluvia solar</u></color></link> en el campo y tratos <color=#00F6FF>240%</color> daño a <color=#00F6FF>9 fichas en forma de cuadrado</color> alrededor de ellos. Si un objetivo sufre daño más de una vez, el daño por cada golpe después del primero se reduce, hasta <color=#00F6FF>10%</color> del daño original. Si alguna ficha del campo está ocupada por <color=#00F6FF>3</color> marcas activadas pero ninguna Marca de Lluvia de Sol, genera 1 nueva Marca de Lluvia de Sol en esa loseta.",
  str_skill_passive_name_410168 = "Burbuja de protección",
  str_skill_passive_name_415168 = "Burbuja de protección",
