  str_skill_passive_desc_415168 = "Otorga un escudo que es <color=#00F6FF>{1}</color> de la DEF de Rainbow y dura 1 ronda al pasar por un <link=\"30061\"><#FFAE07><u>Marca de lluvia solar</u></color></link>. Genera una marca de lluvia de sol en <color=#00F6FF>1</color> Azulejo azul aleatorio al comienzo de cada ronda.",
