  str_skill_name_10071413 = "Fluctuación de cordura",
  str_skill_desc_10071413 = "Tentaclaws influirá en la cordura auroriana. Al comienzo de cada ronda, cada Tentaclaw existente reduce la Cordura en 2, y la muerte de cada Tentaclaw restaura la Cordura en 3.",
  str_skill_upgrade_desc_16016613 = "Mejora activa de habilidades: ganancias <color=#00F6FF>1</color> punto de valor del cebo al comienzo de cada ola.",
  str_skill_upgrade_desc_16016616 = "Mejora activa de habilidades: Para el <color=#00F6FF>2º/3º</color> alrededor de que existe una marca de caza, Kyllo trata <color=#00F6FF>350%/500%</color> daño.",
  str_skill_passive_name_410166 = "Mareas crecientes",
  str_skill_passive_name_430166 = "Mareas crecientes",
  str_skill_passive_desc_410166 = "Fia se desliza rápidamente sobre <color=#00F6FF>Azul</color> mosaicos, infligiendo daño a los enemigos adyacentes. Cuando <link=\"30057\"><#FFAE07><u>torneado</u></color></link>, inflige daño a <color=#00F6FF>1 grupo circundante</color>. Agrega un efecto de Humedad al objetivo que dura 1 ronda: aumenta el factor de daño del contraelemento en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430166 = "Fia se desliza rápidamente <color=#00F6FF>Azul</color> mosaicos, infligiendo daño a los enemigos adyacentes. Cuando <link=\"30057\"><#FFAE07><u>torneado</u></color></link>, inflige daño a <color=#00F6FF>1 grupo circundante</color>. Agrega un efecto de Humedad al objetivo que dura 1 ronda: aumenta el factor de daño del contraelemento en <color=#00F6FF>{1}</color>. Aumenta el efecto húmedo <color=#00F6FF>50%</color> para disparar a los enemigos.",
  str_skill_name_300166 = "La estrategia de Kyllo",
  str_skill_name_320166 = "La estrategia de Kyllo",
  str_skill_name_303166 = "La estrategia de Kyllo",
  str_skill_name_306166 = "La estrategia de Kyllo",
  str_skill_name_323166 = "La estrategia de Kyllo",
  str_skill_name_326166 = "La estrategia de Kyllo",
  str_skill_desc_300166 = "consume <color=#00F6FF>1</color> Punto de <link=\"30055\"><#FFAE07><u>Valor del cebo</u></color></link> para colocar 1 marca de caza en cualquier mosaico, o selecciona 1 marca de caza para liberar a Kyllo. Mientras la marca de caza esté activa durante <color=#00F6FF>0/1/2/3</color> ronda(s), Kyllo ataca al <color=#00F6FF>Ficha de marca de caza/5 fichas en forma de cruz/13 fichas en forma de diamante/25 fichas en forma de cuadrado</color>, tratar <color=#00F6FF>150%/200%/250%/300%</color> daño.",
  str_skill_desc_320166 = "consume <color=#00F6FF>1</color> Punto de <link=\"30055\"><#FFAE07><u>Valor del cebo</u></color></link> para colocar 1 marca de caza en cualquier mosaico, o selecciona 1 marca de caza para liberar a Kyllo. Mientras la marca de caza esté activa durante <color=#00F6FF>0/1/2/3</color> ronda(s), Kyllo ataca al <color=#00F6FF>Ficha de marca de caza/5 fichas en forma de cruz/13 fichas en forma de diamante/25 fichas en forma de cuadrado</color>, trato <color=#00F6FF>150%/200%/250%/300%</color> daño. Reduce la DEF básica del objetivo en <color=#00F6FF>5%</color> para la ronda. El efecto se puede apilar.",
