  str_skill_desc_2001302 = "El nivel de las <link=\"30062\"><#FFAE07><u>Estatuas de la Ley</u></color></link> dentro de <color=#00F6FF>12 mosaicos en forma de diamante</color> <color=#00F6FF>+1</color>.",
  str_skill_desc_2001303 = "El nivel de <link=\"30062\"><#FFAE07><u>Estatuas de la Ley</u></color></link> dentro de <color=#00F6FF>2 grupos circundantes</color> <color=#00F6FF>+1</color>.",
  str_skill_name_300130 = "¡Estar sentado!",
  str_skill_desc_300130 = "<color=#00F6FF>Destruye</color> todas las <link=\"30062\"><#FFAE07><u>Estatuas de la ley</u></color></link> dentro de 2 grupos circundantes centrados en 1 transitable seleccionado mosaico, y genera una nueva Estatua de la Ley en el mosaico seleccionado, con un nivel igual a <color=#00F6FF>la suma de los niveles de todas las Estatuas destruidas</color>. Si no se detecta una Estatua de la Ley dentro del rango, genera un Lv. 1 Estatua de la Ley en la loseta seleccionada en su lugar.",
  str_skill_passive_name_400130 = "¡Justicia servida!",
  str_skill_passive_desc_400130 = "Genera 1 Lv. 1 <link=\"30062\"><#FFAE07><u>Estatua de la Ley</u></color></link> por cada 5 fichas recorridas. Para los Estatutos de la Ley actuales, <color=#00F6FF>nivel +1</color>.",
