  str_skill_desc_2001712 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 12 casillas en forma de cruz </color>.",
  str_skill_desc_2001713 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>en forma de cruz al rango máximo</color>.",
  str_skill_desc_2201711 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>8 mosaicos en forma de cruz</color>, que se difunde para afectar 1 mosaico adicional en los lados izquierdo y derecho cuando está bloqueado .",
  str_skill_desc_2201712 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 mosaicos en forma de cruz</color>, que se difunde para afectar 1 mosaico adicional en los lados izquierdo y derecho cuando está bloqueado .",
  str_skill_desc_2201713 = "Inflige <color=#00F6FF>{1}%</color> de daño <color=#00F6FF>en forma de cruz al alcance máximo</color>, que se difunde para afectar 1 mosaico adicional en los lados izquierdo y derecho cuando obstruido.",
  str_skill_desc_3001711 = "Cuesta <color=#00F6FF>2</color> <link=\"30063\"><#FFAE07><u>puntos de activación</u></color></link> y borra los puntos restantes. Inflige <color=#00F6FF>200 %</color> de daño a <color=#00F6FF>1 grupo circundante</color> después de que finaliza el ataque combinado en cadena de esta ronda. El daño final aumenta un <color=#00F6FF>20 %</color> por cada Trigger Point eliminado.",
  str_skill_desc_3021711 = "Cuesta <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>puntos de activación</u></color></link> y borra los puntos restantes. Inflige <color=#00F6FF>200 %</color> de daño a <color=#00F6FF>1 grupo circundante</color> después de que finaliza el ataque combinado en cadena de esta ronda. El daño final aumenta un <color=#00F6FF>20 %</color> por cada Trigger Point eliminado.",
  str_skill_desc_3051711 = "Cuesta <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>puntos de activación</u></color></link> y borra los puntos restantes. Inflige <color=#00F6FF>200 %</color> de daño a <color=#00F6FF>1 grupo circundante</color> después de que finaliza el ataque combinado en cadena de esta ronda. El daño final aumenta un <color=#00F6FF>25 %</color> por cada Trigger Point eliminado.",
  str_skill_passive_desc_400171 = "Detecta 1 <color=#00F6FF>Debilidad del oponente</color> al conectar 1 mosaico verde o mosaico mejorado. Después de detectar 6 debilidades, el siguiente ataque normal inflige daño crítico aleatorio de <color=#00F6FF>120 %-{1}</color>. Restablece la acumulación de <color=#00F6FF>Debilidad del oponente</color>.",
  str_skill_passive_desc_430171 = "Detecta 1 <color=#00F6FF>Punto débil</color> al conectar 1 mosaico verde o mosaico mejorado. Después de detectar 6 puntos débiles, el siguiente ataque normal inflige daño crítico aleatorio de <color=#00F6FF>120 %-{1}</color>. Restablece la acumulación de <color=#00F6FF>Punto débil</color> y gana 1 punto de activación.",
