  str_skill_desc_2001702 = "Inflige <color=#00F6FF>{1}%</color> de daño a los mosaicos amarillos dentro de <color=#00F6FF>1 grupo circundante</color> y el área <color=#00F6FF>que se extiende en forma de cruz</color >.",
  str_skill_desc_2001703 = "Inflige <color=#00F6FF>{1}%</color> de daño a los mosaicos amarillos dentro de <color=#00F6FF>1 grupo circundante</color> y el área <color=#00F6FF>que se extiende en las 8 direcciones</color >.",
  str_skill_desc_300170 = "Selecciona 1 mosaico, luego elige una dirección a la derecha o izquierda del mosaico seleccionado. Los colores de todos los mosaicos en la dirección seleccionada cambiarán una columna en esa dirección, y todos los mosaicos en <color=#00F6FF>la misma columna que el mosaico seleccionado</color> se convertirán en mosaicos amarillos.",
  str_skill_desc_306170 = "Selecciona 1 mosaico, luego elige una dirección a la derecha o izquierda del mosaico seleccionado. Los colores de todos los mosaicos en la dirección seleccionada cambiarán una columna en esa dirección, y todos los mosaicos en <color=#00F6FF>la misma columna que el mosaico seleccionado</color> se convertirán en mosaicos amarillos.",
  str_skill_desc_320170 = "Selecciona 1 mosaico, luego elige una dirección a la derecha o izquierda del mosaico seleccionado. Los colores de todos los mosaicos en la dirección seleccionada cambiarán una columna en esa dirección, y todos los mosaicos en <color=#00F6FF>la misma columna que el mosaico seleccionado</color> se convertirán en mosaicos amarillos. Inflige <color=#00F6FF>250 %</color> de daño a la columna del mosaico seleccionado.",
  str_skill_desc_326170 = "Selecciona 1 mosaico, luego elige una dirección a la derecha o izquierda del mosaico seleccionado. Los colores de todos los mosaicos en la dirección seleccionada cambiarán una columna en esa dirección, y todos los mosaicos en <color=#00F6FF>la misma columna que el mosaico seleccionado</color> se convertirán en mosaicos amarillos. Inflige <color=#00F6FF>250 %</color> de daño a la columna del mosaico seleccionado.",
  str_skill_desc_330170 = "Selecciona 1 mosaico, luego elige una dirección a la derecha o izquierda del mosaico seleccionado. Los colores de todos los mosaicos en la dirección seleccionada cambiarán una columna en esa dirección, y todos los mosaicos en <color=#00F6FF>la misma columna que el mosaico seleccionado</color> se convertirán en mosaicos amarillos. Inflige <color=#00F6FF>250 %</color> de daño a la columna de la casilla seleccionada y, si la ficha seleccionada está al pie de un <color=#00F6FF>enemigo de una sola casilla</color>, el objetivo se verá obligado a mover 1 ficha en la dirección seleccionada.",
  str_skill_desc_336170 = "Selecciona 1 mosaico, luego elige una dirección a la derecha o izquierda del mosaico seleccionado. Los colores de todos los mosaicos en la dirección seleccionada cambiarán una columna en esa dirección, y todos los mosaicos en <color=#00F6FF>la misma columna que el mosaico seleccionado</color> se convertirán en mosaicos amarillos. Inflige <color=#00F6FF>250 %</color> de daño a la columna de la casilla seleccionada y, si la ficha seleccionada está al pie de un <color=#00F6FF>enemigo de una sola casilla</color>, el objetivo se verá obligado a mover 1 ficha en la dirección seleccionada.",
  str_skill_passive_desc_410170 = "Cuando Chain Combo inflige daño, cuanto más lejos está el objetivo, mayor es el daño infligido. El daño final aumenta en <color=#00F6FF>{1}</color> por racimo.",
  str_skill_passive_desc_420170 = "Cuando Chain Combo y Active Skill infligen daño, cuanto más lejos está el objetivo, mayor es el daño infligido. El daño final aumenta en <color=#00F6FF>{1}</color> por grupo.",
  str_skill_upgrade_desc_16017013 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16017016 = "Mejora Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00> 1 </color> ronda.",
  str_skill_name_290370121 = "Cañón principal de la torreta - Choque",
  str_skill_desc_290370121 = "Después de moverse 1 mosaico, el cañón principal dispara un ataque de choque que impacta el área con 4 mosaicos frente a él, inflige daño a los objetivos en el rango y los repele 3 mosaicos.",
  str_skill_desc_290370123 = "El cañón principal dispara un ataque de choque que impacta el área con 4 casillas frente a él, inflige daño a los objetivos en el rango y los empuja hacia atrás en 3 casillas.",
  str_skill_name_290370122 = "Cañón principal invadido - Choque",
  str_skill_desc_290370122 = "Después de moverse 2 casillas, el cañón principal dispara un ataque de choque que impacta el área con 4 casillas frente a él, infligiendo un daño masivo a los objetivos en el rango y derribándolos 3 casillas.",
  str_skill_name_290370131 = "Strafe de hombro - Izquierda",
  str_skill_desc_290370131 = "Después de moverse 1 casilla, fije a los enemigos en un área en forma de abanico y dispare múltiples tiros, infligiendo daño.",
  str_skill_desc_290370133 = "Bloquea a los enemigos en un área en forma de abanico y dispara múltiples tiros, infligiendo daño.",
  str_skill_name_290370132 = "Overrun Strafe - Izquierda",
  str_skill_desc_290370132 = "Después de mover 2 mosaicos, fije a los enemigos en un área en forma de abanico y dispare múltiples tiros, infligiendo un daño masivo.",
  str_skill_name_290370141 = "Strafe de hombro - Derecho",
  str_skill_desc_290370141 = "Después de moverse 1 casilla, fije a los enemigos en un área en forma de abanico y dispare múltiples tiros, infligiendo daño.",
  str_skill_desc_290370143 = "Bloquea a los enemigos en un área en forma de abanico y dispara múltiples tiros, infligiendo daño.",
  str_skill_name_290370142 = "Overrun Strafe - Derecha",
  str_skill_desc_290370142 = "Después de mover 2 mosaicos, fije a los enemigos en un área en forma de abanico y dispare múltiples tiros, infligiendo un daño masivo.",
  str_skill_name_290370151 = "Invadir",
  str_skill_desc_290370151 = "Entra en el estado de saturación, lo que aumenta la distancia de movimiento y el ATK.",
  str_skill_name_490370401 = "Mantenimiento de emergencia",
  str_skill_desc_490370401 = "Bloquea HP y realiza mantenimiento de emergencia. Golpea a los aurorianos hacia el borde del campo con su cañón y luego se otorga un escudo. Después de 1 ronda, recuperará HP igual al doble del valor del escudo.",
  str_skill_name_40004451 = "Contaminación",
  str_skill_desc_40004451 = "Murkmite inflige daño a los objetivos dentro del alcance y los repele.",
  str_skill_name_49004213 = "Reencarnador",
  str_skill_desc_49004213 = "Nozard carga energía para la inminente marea creciente y convoca a Thumper para que lo proteja.",
  str_skill_name_49004215 = "Marea creciente",
  str_skill_desc_49004215 = "Nozard realiza una carrera de bombardeo en un área fija del campo y bloquea las casillas dentro del alcance.",
  str_skill_name_400060101 = "Refuerzo de combate",
  str_skill_desc_400060101 = "El Lurker se une al Eclipsite dentro de 1 grupo circundante de sí mismo, proporcionando al Eclipsite un Escudo y mejorando su ATK y ACT.",
  str_skill_name_400060201 = "Regenerado mejorado",
  str_skill_desc_400060201 = "Cuando se encuentra dentro de 1 grupo circundante de Dawn, se fusiona con ella para recuperar su HP, aumenta su ATK y le otorga un escudo.",
  str_skill_desc_400071502 = "Inflige daño igual a un porcentaje del HP máximo del objetivo a los objetivos dentro de su rango de forma radial máximo. Si no hay objetivos en las 8 direcciones a su alrededor, gana una barrera defensiva.",
  str_skill_desc_400072502 = "Inflige daño igual a un porcentaje del HP máximo del objetivo a objetivos en forma radial al rango máximo centrado en la unidad. Si no hay objetivos en las 8 direcciones alrededor de la unidad, restaura HP a las unidades amigas.",
  str_skill_desc_490050302 = "Solmorph inflige daño a los objetivos dentro del área de ataque y los atrae. Convierte mosaicos dentro de 2 grupos circundantes, independientemente de si el ataque golpea a un enemigo o no, y bloquea los mosaicos dentro de 1 grupo circundante centrado en el objetivo al dar un golpe.",
  str_skill_desc_491050301 = "Solmorph desata una onda expansiva de 2 mosaicos de ancho en la ubicación del objetivo, lo que inflige daño a los objetivos a lo largo del camino. Restablece las fichas dentro del rango de ataque.",
  str_skill_desc_491050302 = "Solmorph inflige daño a los objetivos dentro del área de ataque y los atrae. Restablece mosaicos dentro de 3 grupos circundantes, independientemente de si el ataque golpea a un enemigo o no.",
  str_skill_desc_490028304 = "El Dark Summoner invoca 4 balizas y luego cura todas las balizas.",
  str_skill_desc_491028304 = "El Dark Summoner invoca 4 balizas y luego cura todas las balizas.",
  str_skill_desc_490025102 = "Invoca 1 fantasma rabioso para ayudar al fantasma. El Fantasma existente se recuperará antes de invocar uno nuevo. Aumenta permanentemente el ATK del Fantasma después de un retiro exitoso.",
  str_skill_desc_490025201 = "El Fantasma rabioso ataca 2 veces, convocando a Fantasma para que lo ayude.",
  str_skill_name_491025203 = "Recuerdo de ilusión",
  str_skill_desc_491025203 = "El Phantasm existente se recuperará antes de que se invoque uno nuevo, y los efectos de la recuperación de HP, el aumento de ATK y ACT desaparecerán. Aumenta su propio ACT sin Fantasma en el campo de batalla.",
  str_skill_name_215007811 = "Ataque Normal",
  str_skill_desc_215007811 = "Robyn ataca objetivos dentro del rango de ataque.",
  str_skill_name_215007812 = "Gota deslizante",
  str_skill_desc_215007812 = "Inflige daño a objetivos dentro de 2 grupos circundantes.",
  str_skill_name_215007813 = "Aliento deslizante",
  str_skill_desc_215007813 = "Inflige daño a los objetivos en el campo de batalla.",
  str_skill_name_214004811 = "Palpitaciones",
  str_skill_desc_214004811 = "Inflige daño a los objetivos dentro del alcance.",
  str_skill_name_214004812 = "Trueno Caprichoso",
  str_skill_desc_214004812 = "Inflige daño a los objetivos en el campo de batalla.",
  str_skill_name_212005011 = "Sangriento devorar",
  str_skill_desc_212005011 = "Inflige daño a los objetivos dentro del alcance y los repele.",
  str_skill_name_212005012 = "Desgarro masivo",
  str_skill_desc_212005012 = "Inflige daño a los objetivos dentro del alcance.",
  str_skill_name_213004911 = "Cargar",
  str_skill_desc_213004911 = "Inflige daño a los objetivos dentro del alcance.",
  str_skill_name_213004912 = "Rugido de furia",
  str_skill_desc_213004912 = "Inflige daño a los objetivos dentro de 1 grupo circundante. Coloca todas las fichas que no sean azules dentro del alcance.",
  str_skill_name_214009111 = "Salmo de apoyo",
  str_skill_desc_214009111 = "Cuando se lanza, cada ficha azul en el campo de batalla otorga a todos los miembros aliados una bonificación de ATK igual al 0.5% del ATK de Chloe para la ronda.",
  str_skill_name_214009112 = "Dolor resplandeciente",
  str_skill_desc_214009112 = "Inflige daño a los objetivos en el campo de batalla.",
  str_skill_name_214009121 = "Salmo de apoyo",
  str_skill_desc_214009121 = "Cuando se lanza, ACT de todos los miembros aliados +1, y cada mosaico azul en el campo de batalla otorga a los miembros aliados una bonificación de ATQ igual al 0,5 %.",
  str_skill_desc_490022306 = "El aburrimiento acumula poder para un ataque de fuego en forma de cruz, que inflige daño a los objetivos e inflige quemadura. El aburrimiento invoca Dreadblades para protección cuando acumula poder, y aumenta el ACT para otros Eclipsites en el campo de batalla después de una invocación exitosa.",
  str_skill_desc_490022310 = "El aburrimiento acumula poder para un ataque de trueno en forma de cruz, que inflige daño a los objetivos e inflige parálisis. El aburrimiento invoca Dreadblades para protección cuando acumula poder y aumenta el ACT para otros Eclipsites en el campo de batalla después de una invocación exitosa.",
  str_skill_desc_490064302 = "La energía del Caracalune se desborda e inflige daño a 4 columnas y filas.",
  str_skill_desc_490060103 = "Inflige daño en 7 áreas aleatorias de 2 × 2 y genera fuego dentro del alcance. Convierte todas las fichas en 1 grupo circundante de cualquier Aurorian golpeado e inflige Maldición al Capitán del equipo.",
  str_skill_desc_49006811 = "Destellos sin forma al borde del Tablero de Alquimia, lejos de la ubicación de tu equipo, luego realiza ataques a distancia. Lanza 2 Nonentities y 1 Chasm a ubicaciones aleatorias dentro de un rango específico de donde se conectan tus Aurorians.",
  str_skill_desc_49006812 = "Formless lanza 4 Nonentities a ubicaciones aleatorias en todo el campo de batalla.",
  str_skill_desc_490091202 = "Lanza un rayo impactante hacia la ubicación del objetivo en la última ronda, lo que inflige daño a los objetivos en el camino del rayo y en la ubicación del objetivo. Inflige maldición al capitán del equipo auroriano después de asestar un golpe.",
  str_skill_desc_490091203 = "Inflige daño a los objetivos dentro del alcance.",
  str_skill_desc_490006301 = "Nozard distorsiona y rasga el espacio en el frente, causando daño elemental. Cualquier golpe de Aurorian será cegado.",
  str_skill_desc_490006302 = "Nozard derriba a los aurorianos y carga energía para la tormenta inminente.",
  str_skill_desc_490006304 = "Nozard bombardea un área fija repetidamente e invoca Skill Banning Stele en cada área.",
  str_skill_desc_490006306 = "Nozard bombardea un área fija repetidamente e invoca Skill Banning Stele en cada área.",
  str_skill_desc_491006304 = "Nozard bombardea un área fija repetidamente y rompe las fichas dentro del área.",
  str_skill_desc_491006305 = "Nozard bombardea un área fija repetidamente y rompe las fichas dentro del área.",
  str_skill_desc_491006302 = "Nozard derriba a los aurorianos, convoca a Thumper al campo y carga energía para la tormenta inminente.",
  str_skill_desc_492006306 = "Nozard bombardea un área fija repetidamente y rompe las fichas dentro del área.",
  str_skill_desc_490110101 = "Maude lanza ondas de choque hacia adelante en una forma rectangular de 2 mosaicos que se desplaza al rango máximo posible, infligiendo daño a los objetivos golpeados. Si el objetivo es alcanzado, recupera HP para sí mismo.",
  str_skill_desc_490110201 = "Maude lanza ondas de choque hacia adelante en una forma rectangular de 2 mosaicos que se desplaza al rango máximo posible, infligiendo daño a los objetivos golpeados. Si se golpea el objetivo, se agota el objetivo.",
  str_skill_name_490110301 = "Cuerno de guerra de Solus",
  str_skill_desc_490110301 = "Maude aumenta ATK y ACT para Eclipsites en el campo.",
  str_skill_name_400040101 = "Cruz de la oscuridad",
  str_skill_desc_400040101 = "Cuando el Dark Summoner almacena energía, el Beacon ataca a los objetivos dentro de un área en forma de cruz.",
  str_skill_name_810410092 = "Llamada del arrecife",
  str_skill_desc_810410092 = "Invoca 2 runas especiales, que se convertirán en estelas de prohibición de habilidades después de ciertas rondas.",
  str_skill_desc_490040103 = "Schummer invoca Lightning Power para infligir daño a varias áreas en forma de cruz en el campo. Los enemigos en el centro de las áreas morirán instantáneamente.",
  str_skill_desc_490040106 = "Schummer invoca Lightning Power para infligir daño a varias áreas en forma de cruz en el campo e invoca pequeños eclipses en el campo.",
  str_skill_desc_490040108 = "Schummer controla el Coloso para desatar una explosión sónica que inflige daño a todos los objetivos. Los pequeños eclipses morirán instantáneamente. Cada muerte restaura 1% HP.",
  str_skill_desc_490067201 = "Schummer controla el Coloso para desatar una Explosión sónica, que inflige daño a todos los objetivos y convierte mosaicos específicos en el campo.",
  str_skill_desc_490067202 = "Schummer libera energía rabiosa, ataca a todos los objetivos en el tablero y convierte los colores en mosaicos específicos en el campo. Cuanto más lejos esté un objetivo de Schummer, más daño recibirá.",
  str_skill_desc_490021101 = "Umbrahulk invoca 4 guijarros al azar en el campo de batalla y convoca 1 estela de prohibición de habilidades cerca de la posición de los aurorianos al comienzo de la ronda.",
  str_skill_desc_490021102 = "Umbrahulk se aleja del jugador y convoca 4 Pebbles al lado del jugador.",
  str_skill_name_490310101 = "Fuego de apoyo",
  str_skill_desc_490310101 = "Cuando los enemigos están dentro de 2 grupos circundantes, inflige daño a los objetivos y los empuja hacia atrás en 1 mosaico.",
  str_skill_name_490310102 = "Llame para soporte",
  str_skill_desc_490310102 = "Invoca 4 nulidades cuando los enemigos están a más de 2 grupos circundantes de distancia.",
  str_skill_name_490310105 = "Barbara Ataque Normal",
  str_skill_desc_490310105 = "Se acerca a los enemigos, lanza ataques y los derriba.",
  str_skill_name_491018101 = "Nota final",
  str_skill_desc_491018101 = "Cuando los enemigos están dentro de 1 grupo circundante, la tormenta solar explota, inflige daño a los enemigos y los repele.",
  str_skill_name_491018102 = "Ataque normal de Regina",
  str_skill_desc_491018102 = "Se acerca al objetivo y ataca.",
  str_skill_name_491105101 = "Tornado de ojos rojos: menor",
  str_skill_desc_491105101 = "Si hay enemigos dentro de 2 grupos circundantes, aléjese de los enemigos y hágales daño 10 veces.",
  str_skill_name_491105102 = "Tornado de ojos rojos: Mayor",
  str_skill_desc_491105102 = "Si los enemigos están más allá de 2 grupos circundantes, fije a los enemigos y hágales daño 20 veces.",
  str_skill_name_491030101 = "Sinsa Ataque Normal",
  str_skill_desc_491030101 = "Se acerca a los enemigos y lanza ataques.",
  str_skill_name_491030102 = "Salpicadura de fuego",
  str_skill_desc_491030102 = "Inflige un gran daño en forma radial al alcance máximo.",
  str_skill_desc_490060101 = "Carga al objetivo y llévalo a una casilla adyacente, convirtiendo todas las fichas en los 3 grupos circundantes al final de la carga.",
  str_skill_upgrade_desc_16017313 = "Mejora de habilidad activa: elimina 1 acumulación de Marca mortal cada vez que una habilidad activa inflige daño.\nMejora de habilidades de equipo: el ATK básico aumenta en <color=#FFFF00>25%</color> después de borrar todas las Marcas Mortales.\n(Válido para Ascensión II)",
  str_skill_upgrade_desc_16017316 = "Mejora de habilidad activa: se puede lanzar <color=#FFFF00>1</color> más tiempo después de ingresar a Aurora Time.",
  str_skill_name_3001731 = "Veredicto rápido",
  str_skill_name_3061731 = "Veredicto rápido",
  str_skill_name_3201731 = "Veredicto rápido",
  str_skill_name_3231731 = "Veredicto rápido",
  str_skill_name_3261731 = "Veredicto rápido",
  str_skill_name_3301731 = "Veredicto rápido",
  str_skill_name_3331731 = "Veredicto rápido",
  str_skill_name_3361731 = "Veredicto rápido",
  str_skill_desc_3001731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido.",
  str_skill_desc_3061731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido. La habilidad activa se puede lanzar 1 vez más después de ingresar a Aurora Time.",
  str_skill_desc_3201731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido.",
  str_skill_desc_3231731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido. Cada vez que se inflige daño, se elimina 1 acumulación de Marca Mortal.",
  str_skill_desc_3261731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido. Cada vez que se inflige daño, se elimina 1 acumulación de Marca Mortal. La habilidad activa se puede lanzar 1 vez más después de ingresar a Aurora Time.",
  str_skill_desc_3301731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido. Cada vez que se absorbe 1 ficha mejorada, se elimina 1 acumulación de Marca Mortal.",
  str_skill_desc_3331731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido. Cada vez que se inflige daño o se absorbe 1 ficha mejorada, se elimina 1 acumulación de Marca Mortal.",
  str_skill_desc_3361731 = "Seleccione cualquier 1 mosaico, luego seleccione otro 1 mosaico dentro <color=#00F6FF>2 grupos circundantes</color> para determinar un área rectangular. <link=\"30065\"><#FFAE07><u>Absorbe</u></color></link> la <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> dentro de esta área y ofertas <color=#00F6FF>100%</color> daño a los enemigos dentro de esta área. Aumenta el daño final en <color=#00F6FF>50%</color> por cada 1 mosaico mejorado absorbido. Cada vez que se inflige daño o se absorbe 1 ficha mejorada, se elimina 1 acumulación de Marca Mortal. La habilidad activa se puede lanzar 1 vez más después de ingresar a Aurora Time.",
