  str_skill_desc_2001733 = "ofertas <color=#00F6FF>180%</color> daño a los objetivos más cercanos y más lejanos, pero el daño posterior infligido a los mismos objetivos es <color=#00F6FF>reducido a la mitad</color>. Citación <color=#00F6FF>hasta 1</color> <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> a los pies de los blancos.",
  str_skill_desc_2301731 = "ofertas <color=#00F6FF>140%</color> daño a los objetivos más cercanos y más lejanos, pero el daño posterior infligido a los mismos objetivos es <color=#00F6FF>reducido a la mitad</color>. Citación <color=#00F6FF>hasta 1</color> <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> a los pies de los blancos.",
  str_skill_desc_2301732 = "ofertas <color=#00F6FF>160%</color> daño a los objetivos más cercanos y más lejanos, pero el daño posterior infligido a los mismos objetivos es <color=#00F6FF>reducido a la mitad</color>. Citación <color=#00F6FF>hasta 1</color> <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> a los pies de los blancos.",
  str_skill_desc_2301733 = "ofertas <color=#00F6FF>180%</color> daño a los objetivos más cercanos y más lejanos, pero el daño posterior infligido a los mismos objetivos es <color=#00F6FF>reducido a la mitad</color>. Citación <color=#00F6FF>hasta 1</color> <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> a los pies de los blancos.",
  str_skill_passive_name_410173 = "Liberación omnipotente",
  str_skill_passive_name_420173 = "Liberación omnipotente",
  str_skill_passive_name_423173 = "Liberación omnipotente",
  str_skill_passive_desc_410173 = "tratos inmediatos <color=#00F6FF>{1}</color> daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> (incluido <link=\"30065\"><#FFAE07><u>absorbente</u></color></link>).",
  str_skill_passive_desc_420173 = "tratos inmediatos <color=#00F6FF>{1}</color> daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> (incluido <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> Mortal Mark se acumula y reduce <color=#00F6FF>1</color> pila por cada ficha mejorada obtenida. Minos ingresa al Estado de Minotauro cuando se han eliminado todas las Marcas, lo que aumenta su ATK básico en <color=#00F6FF>20%</color>, lo que permite que sus ataques normales golpeen mosaicos diagonales, lo que aumenta el daño de la habilidad de equipo a <color=#00F6FF>2.5</color> veces, y permitiendo que su Chain Combo inflija daño normal cuando golpea al mismo objetivo nuevamente.",
  str_skill_passive_desc_423173 = "tratos inmediatos <color=#00F6FF>{1}</color> daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> (incluido <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> Mortal Mark se acumula y reduce <color=#00F6FF>1</color> pila por cada ficha mejorada obtenida. Minos ingresa al Estado de Minotauro cuando se han eliminado todas las Marcas, lo que aumenta su ATK básico en <color=#00F6FF>25%</color>, lo que permite que sus ataques normales golpeen mosaicos diagonales, lo que aumenta el daño de la habilidad de equipo a <color=#00F6FF>2.5</color> veces, y permitiendo que su Chain Combo inflija daño normal cuando golpea al mismo objetivo nuevamente.",
