  str_skill_desc_2001721 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color>. Si está parado afuera de un <color=#00F6FF>deslumbrante variedad</color>, genera una matriz deslumbrante que abarca <color=#00F6FF>1 grupo circundante</color> en la ubicación actual.",
  str_skill_desc_2001722 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color>. Si está parado afuera de un <color=#00F6FF>deslumbrante variedad</color>, genera una matriz deslumbrante que abarca <color=#00F6FF>1 grupo circundante</color> en la ubicación actual.",
  str_skill_desc_2001723 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>. Si está parado afuera de un <color=#00F6FF>deslumbrante variedad</color>, genera una matriz deslumbrante que abarca <color=#00F6FF>12 fichas en forma de diamante</color> en la ubicación actual.",
  str_skill_desc_3001721 = "Se teletransporta a cualquier lugar dentro de un <link=\"30066\"><#FFAE07><u>deslumbrante variedad</u></color></link>. solo puede haber <color=#00F6FF>2</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_desc_3201721 = "Se teletransporta a cualquier lugar dentro de un <link=\"30066\"><#FFAE07><u>deslumbrante variedad</u></color></link> y ofertas <color=#00F6FF>{1}%</color> daño a las tejas dentro del lapso de la <color=#00F6FF>deslumbrante variedad</color>. solo puede haber <color=#00F6FF>2</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_desc_3031721 = "Se teletransporta a cualquier lugar dentro de un <link=\"30067\"><#FFAE07><u>deslumbrante variedad</u></color></link>. solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_desc_3231721 = "Se teletransporta a cualquier lugar dentro de un <link=\"30067\"><#FFAE07><u>deslumbrante variedad</u></color></link> y ofertas <color=#00F6FF>{1}%</color> daño a las tejas dentro del lapso de la <color=#00F6FF>deslumbrante variedad</color>. solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_desc_3061721 = "Se teletransporta a cualquier lugar dentro de un <link=\"30068\"><#FFAE07><u>deslumbrante variedad</u></color></link>. solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_desc_3261721 = "Se teletransporta a cualquier lugar dentro de un <link=\"30068\"><#FFAE07><u>deslumbrante variedad</u></color></link> y ofertas <color=#00F6FF>{1}%</color> daño a las tejas dentro del lapso de la <color=#00F6FF>deslumbrante variedad</color>. solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_passive_desc_410172 = "Gana un escudo igual a <color=#00F6FF>{1}</color> del DEF actual de Lilica por cada mosaico atravesado dentro de un <color=#00F6FF>deslumbrante variedad</color>.",
  str_skill_passive_desc_430172 = "Gana un escudo igual a <color=#00F6FF>{1}</color> del DEF actual de Lilica por cada mosaico atravesado dentro de un <color=#00F6FF>deslumbrante variedad</color>. Al final de la ronda, inflige daño verdadero igual al escudo restante a todas las casillas dentro del lapso de todos <color=#00F6FF>arreglos deslumbrantes</color>.",
  str_skill_upgrade_desc_16017213 = "Mejora activa de habilidades: solo puede haber <color=#00F6FF>3</color> matrices deslumbrantes en el campo en cualquier momento.",
  str_skill_upgrade_desc_16017216 = "Mejora de habilidad activa: cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate. Al comienzo de la batalla, genera una deslumbrante variedad que es <color=#00F6FF>12 fichas en forma de diamante</color> en el lugar de partida.",
  str_skill_name_29038011 = "¡Ahí tienes!",
  str_skill_desc_29038011 = "Cada vez que hay un Aurorian cerca, Astor se vuelve hacia el jugador, inflige daño a las unidades cercanas en un área en forma de diamante y las repele.",
  str_skill_name_29038012 = "¿Quieres escapar?",
  str_skill_desc_29038012 = "Cada vez que un Aurorian está dentro de un rango en forma de cruz alrededor de Astor, Astor se vuelve hacia el jugador y carga contra ellos, infligiendo daño a la unidad que tiene delante y derribándolos.",
  str_skill_upgrade_desc_14016912 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_14016915 = "Mejora de habilidad activa: la habilidad activa derriba al objetivo <color=#FFFF00>3</color> losas.",
  str_skill_name_2001691 = "Noquearlos",
  str_skill_name_2001692 = "Noquearlos",
  str_skill_name_2001693 = "Noquearlos",
  str_skill_desc_2001691 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 8 casillas en forma de cruz </color>.",
  str_skill_desc_2001692 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2001693 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_name_300169 = "Pelota voladora",
  str_skill_name_305169 = "Pelota voladora",
  str_skill_name_330169 = "Pelota voladora",
  str_skill_name_335169 = "Pelota voladora",
  str_skill_desc_300169 = "ofertas <color=#00F6FF>300%</color> daño a 1 enemigo adyacente en un <color=#00F6FF>forma de cruz</color> y lo derriba 2 fichas. Cuando <color=#00F6FF>obstruido</color> mientras es derribado, se necesita un tiempo adicional <color=#00F6FF>200%</color> daño y es <color=#00F6FF>aturdido</color> por 1 ronda.",
  str_skill_desc_305169 = "ofertas <color=#00F6FF>300%</color> daño a 1 enemigo adyacente en un <color=#00F6FF>forma de cruz</color> y lo derriba 3 fichas. Cuando <color=#00F6FF>obstruido</color> mientras es derribado, se necesita un tiempo adicional <color=#00F6FF>200%</color> daño y es <color=#00F6FF>aturdido</color> por 1 ronda.",
  str_skill_desc_330169 = "ofertas <color=#00F6FF>300%</color> daño a 1 enemigo adyacente en un <color=#00F6FF>forma de cruz</color> y lo derriba 2 fichas. Cuando <color=#00F6FF>obstruido</color> mientras es derribado, se necesita un tiempo adicional <color=#00F6FF>200%</color> daño y es <color=#00F6FF>aturdido</color> por 1 ronda. Si es bloqueado por otro enemigo, ese enemigo también recibe daño y queda aturdido.",
  str_skill_desc_335169 = "ofertas <color=#00F6FF>300%</color> daño a 1 enemigo adyacente en un <color=#00F6FF>forma de cruz</color> y lo derriba 3 fichas. Cuando <color=#00F6FF>obstruido</color> mientras es derribado, toma un tiempo adicional <color=#00F6FF>200%</color> daño y es <color=#00F6FF>aturdido</color> por 1 ronda. Si es bloqueado por otro enemigo, ese enemigo también recibe daño y queda aturdido.",
  str_skill_passive_name_410169 = "Swing de bateador",
  str_skill_passive_name_420169 = "Swing de bateador",
  str_skill_passive_desc_410169 = "Aumenta el ATK básico de Sadie en <color=#00F6FF>{1}</color>. Sadie reparte hasta <color=#00F6FF>3</color> ataques normales al conectar fichas. Después de 3 ataques, gana 1 <color=#00F6FF>Punto de choque</color> al realizar el siguiente ataque normal. Cada Crash Point aumenta el factor de daño de la habilidad activa en <color=#00F6FF>{2}</color>, y todos los Crash Points se borran después de usar la habilidad activa.",
  str_skill_passive_desc_420169 = "Aumenta el ATK básico de Sadie en <color=#00F6FF>{1}</color>. Sadie reparte hasta <color=#00F6FF>3</color> ataques normales al conectar mosaicos, y el tercer ataque normal inflige el doble de daño. Después de 3 ataques, gana 1 <color=#00F6FF>Punto de choque</color> al realizar el siguiente ataque normal. Cada Crash Point aumenta el factor de daño de la habilidad activa en <color=#00F6FF>{2}</color>, y todos los Crash Points se borran después de usar la habilidad activa.",
  str_skill_desc_1601751001 = "Casilla Prisma",
  str_skill_desc_1601751003 = "Katana",
  str_skill_desc_1601751004 = "Baliza de ataque aéreo",
  str_skill_desc_1601751005 = "Abeja mecánica",
  str_skill_desc_1601751006 = "Mina de flecha solar",
  str_skill_desc_1601751007 = "Bandera",
  str_skill_desc_1601751008 = "Linterna",
  str_skill_desc_1601751009 = "Lagarto de Hierro",
  str_skill_desc_1601751010 = "Casilla Oscura",
  str_skill_desc_160175101 = "consume <color=#00F6FF>2</color> Energía cúbica para convertir cualquier mosaico en un mosaico de prisma.",
  str_skill_desc_160175103 = "consume <color=#00F6FF>2</color> Energía cúbica para invocar 1 Katana en cualquier mosaico transitable sin una Katana existente en él.",
  str_skill_desc_160175104 = "consume <color=#00F6FF>1</color> Cubic Energy para invocar 1 Air Raid Beacon en cualquier mosaico atravesable sin un Air Raid Beacon existente en él.",
  str_skill_desc_160175105 = "consume <color=#00F6FF>1</color> Energía cúbica para invocar 1 abeja mecánica en cualquier mosaico transitable dentro de los 3 grupos circundantes sin una abeja mecánica existente en él. Pueden existir hasta 4 abejas mecánicas en el campo de batalla a la vez.",
  str_skill_desc_160175106 = "consume <color=#00F6FF>1</color> Energía cúbica para invocar 1 mina de flecha solar en cualquier mosaico transitable sin una mina de flecha solar existente en él.",
  str_skill_desc_160175107 = "consume <color=#00F6FF>3</color> Energía cúbica para invocar 1 estandarte en cualquier mosaico transitable. Puede existir hasta 1 estandarte en el campo de batalla a la vez.",
  str_skill_desc_160175108 = "consume <color=#00F6FF>4</color> Energía cúbica para invocar 1 linterna en cualquier mosaico transitable sin una linterna existente. Puede existir hasta 1 Linterna en el campo de batalla a la vez.",
  str_skill_desc_160175109 = "Consume <color=#00F6FF>2</color> Energía cúbica para convocar 1 Lagarto de Hierro en 1 casilla seleccionada transitable sin Lagarto de Hierro.",
  str_skill_desc_160175110 = "consume <color=#00F6FF>2</color> Energía cúbica para convertir cualquier mosaico en un mosaico oscuro.",
  str_skill_upgrade_desc_16017513 = "Mejora activa de habilidades: ganancias <color=#FFFF00>2</color> Energía cúbica al comienzo de la batalla.",
  str_skill_upgrade_desc_16017516 = "Mejora activa de habilidades: después de que Healing Orbs haya estado en el campo durante 0/1/2 rondas, el factor de recuperación aumenta <color=#FFFF00>40%/100%/250%</color> para los aliados que pasan por ella.\nAumenta el factor de recuperación <color=#FFFF00>80%/180%/400%</color> cuando un orbe es absorbido con la Habilidad Activa de Axelia.",
  str_skill_name_30017511 = "Pirueta celestial",
  str_skill_name_30317511 = "Pirueta celestial",
  str_skill_name_30617511 = "Pirueta celestial",
