  str_skill_passive_name_4151761 = "Refuerzo Australis",
  str_skill_passive_name_4201761 = "Refuerzo Australis",
  str_skill_passive_name_4251761 = "Refuerzo Australis",
  str_skill_passive_name_4301761 = "Refuerzo Australis",
  str_skill_passive_name_4351761 = "Refuerzo Australis",
  str_skill_desc_2001761 = "ofertas <color=#00F6FF>60%</color> Daña 2 veces a enemigos aleatorios dentro <color=#00F6FF>3 grupos circundantes</color>. Cada vez que se inflige daño, aumenta el número de <color=#00F6FF>Lanzas australianas</color> en enemigos seleccionados por 1. Cuando se inflige daño a un objetivo más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2001762 = "ofertas <color=#00F6FF>80%</color> Daña 3 veces a enemigos aleatorios dentro <color=#00F6FF>3 grupos circundantes</color>. Cada vez que se inflige daño, aumenta el número de <color=#00F6FF>Lanzas australianas</color> en enemigos seleccionados por 1. Cuando se inflige daño a un objetivo más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2001763 = "ofertas <color=#00F6FF>100%</color> Daña 4 veces a enemigos aleatorios dentro <color=#00F6FF>3 grupos circundantes</color>. Cada vez que se inflige daño, aumenta el número de <color=#00F6FF>Lanzas australianas</color> en enemigos seleccionados por 1. Cuando se inflige daño a un objetivo más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_3001761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. ofertas <color=#00F6FF>80%</color> daño por cada Lanza Australis sacada.",
  str_skill_desc_3021761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. ofertas <color=#00F6FF>80%</color> daño por cada Lanza Australis sacada.",
  str_skill_desc_3051761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. ofertas <color=#00F6FF>80%–120%</color> daño por cada Lanza Australis sacada. Cuanto menor sea el HP actual del objetivo, mayor será el factor de daño.",
  str_skill_desc_3201761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. ofertas <color=#00F6FF>80%</color> daño y recupera HP por <color=#00F6FF>10%</color> del daño infligido de esta manera por cada Lanza Australis sacada.",
  str_skill_desc_3221761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. ofertas <color=#00F6FF>80%</color> daño y recupera HP por <color=#00F6FF>10%</color> del daño infligido de esta manera por cada Lanza Australis sacada.",
  str_skill_desc_3251761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. ofertas <color=#00F6FF>80%–120%</color> daño y recupera HP por <color=#00F6FF>10%</color> del daño infligido de esta manera por cada Lanza Australis sacada. Cuanto menor sea el HP actual del objetivo, mayor será el factor de daño.",
  str_skill_desc_3301761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. ofertas <color=#00F6FF>80%</color> daño y recupera HP por <color=#00F6FF>10%–15%</color> del daño infligido de esta manera por cada Lanza Australis sacada. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3321761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. ofertas <color=#00F6FF>80%</color> daño y recupera HP por <color=#00F6FF>10%–15%</color> del daño infligido de esta manera por cada Lanza Australis extraída. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3351761 = "Saca Australis Spears de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. ofertas <color=#00F6FF>80%–120%</color> daño y recupera HP por <color=#00F6FF>10%–15% de</color> el daño infligido de esta manera por cada <color=#00F6FF>Lanza Australis</color> sacado Cuanto menor sea el HP actual del objetivo, mayor será el factor de daño. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_passive_desc_4101761 = "Cada <color=#00F6FF>{1}</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_passive_desc_4151761 = "Cada <color=#00F6FF>{1}</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_passive_desc_4201761 = "Cada <color=#00F6FF>{1}</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_passive_desc_4251761 = "Cada <color=#00F6FF>{1}</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_passive_desc_4301761 = "Cada <color=#00F6FF>{1}</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_passive_desc_4351761 = "Cada <color=#00F6FF>{1}</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_upgrade_desc_15017612 = "Mejora activa de habilidades: aumenta el rango de habilidades a <color=#FFFF00>3 grupos circundantes</color>.",
  str_skill_upgrade_desc_15017615 = "Mejora activa de habilidades: cuanto menor sea el HP del objetivo, mayor será el factor de daño, hasta <color=#00F6FF>40%</color>.",
  str_skill_name_290350103 = "Cerritus: Golpe devastador",
  str_skill_desc_290350103 = "Cerritus rompe las baldosas bajo sus pies y carga contra los aurorianos, derribándolos y destruyendo todos los guijarros a su paso e infligiendo a los aurorianos con los que choca Agotado.",
  str_skill_name_290350104 = "Cerritus: terremoto devastador",
  str_skill_desc_290350104 = "Cerritus rompe las 2 fichas que tiene delante después de moverse, inflige un daño enorme y las rompe.",
  str_skill_desc_290350203 = "Cerritus rompe las baldosas bajo sus pies y carga contra los aurorianos, derribándolos y destruyendo todos los guijarros a su paso.",
  str_skill_desc_290350204 = "Cerritus rompe las 2 fichas que tiene delante después de moverse, lo que inflige un daño enorme y las destroza. Los aurorianos obtendrán el estado Agotado después de recibir daño.",
  str_skill_name_216003811 = "¡Megashock!",
  str_skill_desc_216003811 = "Phantom Gronru inflige daño a 1 columna.",
  str_skill_name_91001641 = "Mejora",
  str_skill_desc_91001641 = "Aumenta el ACT y ATK de todos los Eclipsites, excluyéndose a sí mismo. Este efecto puede acumularse.",
  str_skill_name_290290101 = "Codicia: Oleada",
  str_skill_desc_290290101 = "Aplasta a los aurorianos vecinos e inflige un daño masivo que ignora la defensa enemiga y los repele 1 casilla. Si las 4 fichas al lado de los Aurorianos están bloqueadas, son derrotados instantáneamente.",
  str_skill_desc_290291131 = "¡Aplasta a los aurorianos vecinos y los derrota al instante!",
  str_skill_name_290290104 = "Codicia: Fractura",
  str_skill_desc_290290104 = "Si no hay Aurorianos adyacentes, viaja 1 casilla hacia la dirección de la ubicación actual de los Aurorianos y luego inflige daño de área dentro de 1 grupo circundante de su cabeza.",
  str_skill_name_290290100 = "Cuerpo de Jormungand",
  str_skill_desc_290290100 = "El cuerpo de Jormungand está protegido por una energía especial que puede anular todos los ataques. Su cuerpo tiene la capacidad de replicarse a sí mismo.",
  str_skill_name_290290102 = "Cola de Jormungand",
  str_skill_desc_290290102 = "El daño infligido a su cola se transmite a su cabeza.",
  str_skill_upgrade_desc_15018012 = "Mejora Habilidad Activa: Si la habilidad estaba lista en la última ronda, aumenta el recuento de conversión de casilla en <color=#FFFF00> 1 </color> en esta ronda.",
  str_skill_upgrade_desc_15018015 = "Mejora Habilidad Activa: Aumenta el recuento de conversión de casilla en <color=#FFFF00> 1 </color>.",
