  str_skill_desc_300180 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes.",
  str_skill_desc_303180 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_305180 = "Convierte el <color=#00F6FF>5</color> las fichas azules más cercanas a las verdes. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_3031801 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_3051801 = "Convierte el <color=#00F6FF>5</color> las fichas azules más cercanas a las verdes. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
