  str_skill_desc_3131801 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_3151801 = "Convierte el <color=#00F6FF>5</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_330180 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo, luego genera un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> bajo los pies de hasta <color=#00F6FF>3</color> enemigos marcados.",
  str_skill_desc_333180 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo, luego genera un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> bajo los pies de hasta <color=#00F6FF>3</color> enemigos marcados. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_335180 = "Convierte el <color=#00F6FF>5</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo, luego genera un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> bajo los pies de hasta <color=#00F6FF>3</color> enemigos marcados. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_3331801 = "Convierte el <color=#00F6FF>4</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo, luego genera un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> bajo los pies de hasta <color=#00F6FF>3</color> enemigos marcados. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_3351801 = "Convierte el <color=#00F6FF>5</color> las fichas azules más cercanas a las verdes. Al azar inflige un <color=#00F6FF>Marca de replanteo</color> en la mitad de los enemigos en el campo, luego genera un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> bajo los pies de hasta <color=#00F6FF>3</color> enemigos marcados. Si la Habilidad Activa estaba lista en la última ronda, convierte <color=#00F6FF>+1</color> ficha en esta ronda.",
  str_skill_desc_2001801 = "ofertas <color=#00F6FF>{1}%</color> daño al más cercano y <color=#00F6FF>pequeñísimo</color> enemigo.",
  str_skill_desc_2001802 = "ofertas <color=#00F6FF>{1}%</color> daño al más cercano y <color=#00F6FF>pequeñísimo</color> enemigo.",
  str_skill_desc_2001803 = "ofertas <color=#00F6FF>{1}%</color> daño al más cercano y <color=#00F6FF>pequeñísimo</color> enemigo.",
  str_skill_desc_2201801 = "ofertas <color=#00F6FF>{1}%</color> daño al más cercano y <color=#00F6FF>pequeñísimo</color> enemigo, luego inflige un </color>Marca de replanteo<color=#00F6FF> en eso.",
  str_skill_desc_2201802 = "ofertas <color=#00F6FF>{1}%</color> daño al más cercano y <color=#00F6FF>pequeñísimo</color> enemigo, luego inflige un </color>Marca de replanteo<color=#00F6FF> en eso.",
  str_skill_desc_2201803 = "ofertas <color=#00F6FF>{1}%</color> daño al más cercano y <color=#00F6FF>pequeñísimo</color> enemigo, luego inflige un </color>Marca de replanteo<color=#00F6FF> en eso.",
  str_skill_passive_desc_410180 = "Las habilidades activas infligen un <color=#00F6FF>Marca de replanteo</color> en los enemigos que aumenta el daño final que reciben de las habilidades Chain Combo de una sola instancia en <color=#00F6FF>{1}</color>. Dura hasta que finaliza la ronda auroriana.",
  str_skill_passive_desc_420180 = "Las Habilidades Activas y los Combos en Cadena infligen un <color=#00F6FF>Marca de replanteo</color> en los enemigos que aumenta el daño final que reciben de las habilidades Chain Combo de una sola instancia en <color=#00F6FF>{1}</color>. Dura hasta que finaliza la ronda auroriana.",
  str_skill_name_2001781 = "Buceo y Retiro",
  str_skill_name_2001782 = "Buceo y Retiro",
  str_skill_name_2001783 = "Buceo y Retiro",
  str_skill_name_20017812 = "Buceo y Retiro",
  str_skill_name_20017822 = "Buceo y Retiro",
  str_skill_name_20017832 = "Buceo y Retiro",
  str_skill_name_3001780 = "Cazar y atacar",
  str_skill_desc_2001781 = "ofertas al azar <color=#00F6FF>100%</color> daño a 3 enemigos diferentes en el campo.",
  str_skill_desc_2001782 = "ofertas al azar <color=#00F6FF>120%</color> daño a 3 enemigos diferentes en el campo.",
  str_skill_desc_2001783 = "ofertas al azar <color=#00F6FF>140%</color> daño a 3 enemigos diferentes en el campo.",
  str_skill_desc_20017812 = "ofertas al azar <color=#00F6FF>100%</color> daño a 3 enemigos diferentes en el campo. Si las fichas azules están conectadas en esta ronda, Vic invoca bestias maravillosas en lugar de que cada una ataque a su propio objetivo (puede terminar siendo el mismo objetivo).",
  str_skill_desc_20017822 = "ofertas al azar <color=#00F6FF>120%</color> daño a 3 enemigos diferentes en el campo. Si las fichas azules están conectadas en esta ronda, Vic invoca bestias maravillosas en lugar de que cada una ataque a su propio objetivo (puede terminar siendo el mismo objetivo).",
  str_skill_desc_20017832 = "ofertas al azar <color=#00F6FF>140%</color> daño a 3 enemigos diferentes en el campo. Si las fichas azules están conectadas en esta ronda, Vic invoca bestias maravillosas en lugar de que cada una ataque a su propio objetivo (puede terminar siendo el mismo objetivo).",
  str_skill_desc_3001780 = "Invoca 3 bestias maravillosas que priorizan el trato <color=#00F6FF>200%</color> daños a sus respectivos objetivos.\nLittle Furball: El enemigo con más marcas de estado.\nBica: El enemigo con el HP más bajo.\nLutumi Owl: El enemigo más lejano.",
  str_skill_passive_name_410178 = "Liberación y persecución",
  str_skill_passive_name_420178 = "Liberación y persecución",
  str_skill_passive_name_430178 = "Liberación y persecución",
  str_skill_passive_name_436178 = "Liberación y persecución",
  str_skill_passive_desc_410178 = "Si las fichas azules están conectadas en esta ronda, en lugar de realizar un ataque normal, las maravillosas bestias atacan a sus respectivos objetivos una vez por cada ficha atravesada, infligiendo <color=#00F6FF>{1}</color> daño.\nTodo el daño infligido por bestias maravillosas no se beneficia de las bonificaciones de combo en cadena.",
  str_skill_passive_desc_420178 = "Si las fichas azules están conectadas en esta ronda, en lugar de realizar un ataque normal, las maravillosas bestias atacan a sus respectivos objetivos una vez por cada ficha atravesada, infligiendo <color=#00F6FF>{1}</color> daño.\nTodo el daño infligido por bestias maravillosas no se beneficia de las bonificaciones de combo en cadena.",
  str_skill_passive_desc_430178 = "Si las fichas azules están conectadas en esta ronda, en lugar de realizar un ataque normal, las maravillosas bestias atacan a sus respectivos objetivos una vez por cada ficha atravesada, infligiendo <color=#00F6FF>{1}</color> daño.\nTodo el daño infligido por bestias maravillosas no se beneficia de las bonificaciones de combo en cadena. El daño final se incrementa en <color=#00F6FF>10%</color> si los objetivos cumplen las condiciones correspondientes.\nLittle Furball: El enemigo tiene al menos <color=#00F6FF>4</color> marcas de estado.\nBica: El enemigo tiene menos de <color=#00F6FF>30%</color> HP.\nLutumi Owl: El enemigo es al menos <color=#00F6FF>4</color> azulejos de distancia.",
  str_skill_passive_desc_436178 = "Si las fichas azules están conectadas en esta ronda, en lugar de realizar un ataque normal, las maravillosas bestias atacan a sus respectivos objetivos una vez por cada ficha atravesada, infligiendo <color=#00F6FF>{1}</color> daño.\nTodo el daño infligido por bestias maravillosas no se beneficia de las bonificaciones de combo en cadena. El daño final se incrementa en <color=#00F6FF>30%</color> si los objetivos cumplen las condiciones correspondientes.\nLittle Furball: El enemigo tiene al menos <color=#00F6FF>4</color> marcas de estado.\nBica: El enemigo tiene menos de <color=#00F6FF>30%</color> HP.\nLutumi Owl: El enemigo es al menos <color=#00F6FF>4</color> azulejos de distancia.",
  str_skill_upgrade_desc_16017813 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16017816 = "Mejora de habilidades de equipo: para todo el daño infligido por bestias maravillosas, el daño final se incrementará en <color=#00F6FF>30%</color> si los objetivos cumplen las condiciones correspondientes. (Válido para Ascensión III)",
