  str_skill_passive_desc_433182 = "ofertas <color=#00F6FF>{1}</color> daño a <color=#00F6FF>todas</color> enemigos al usar Habilidad Activa.",
  str_skill_upgrade_desc_16018213 = "Mejora de combo en cadena: durante el tiempo de aurora, el costo de activación del combo en cadena <color=#00F6FF>-6</color>.",
  str_skill_upgrade_desc_16018216 = "Mejora de combo en cadena: aumenta el rango de daño del nivel <color=#00F6FF>2|3|4</color> Combo de cadena para <color=#00F6FF>13 fichas en forma de diamante|17 fichas en forma radial|25 fichas en forma de cuadrado</color>.",
  str_skill_name_29041011 = "Unir",
  str_skill_desc_29041011 = "Yoh conjura una poderosa ilusión y atrae a los aurorianos.\nDurante este período, invoca varios proyectiles con una trayectoria fija para volar por el campo y causar un gran daño a los aurorianos al golpearlos.\nEl equipo puede moverse 5 veces a voluntad. Cada movimiento está limitado a 1 ficha.",
  str_skill_name_29041012 = "Control",
  str_skill_desc_29041012 = "Cuando hay proyectiles en el campo, Yoh los controla, dirigiéndolos hacia los aurorianos para infligir daño.\nCuando no haya proyectiles en el campo, Yoh se dividirá y se esconderá. Al recibir daño, sabrás cuál de las réplicas es realmente él.",
  str_skill_name_29041013 = "Vacío de realidad",
  str_skill_desc_29041013 = "Cuando hay proyectiles en el campo, Yoh los controla, dirigiéndolos hacia los aurorianos para infligir daño.\nCuando no haya proyectiles en el campo, Yoh se dividirá y se esconderá. Al recibir daño, sabrás cuál de las réplicas es realmente él.",
  str_skill_name_29041014 = "Discurso",
  str_skill_desc_29041014 = "Después de moverse, las réplicas de Yoh infligirán daño a los objetivos en línea recta frente a él y luego dejarán un proyectil en su ubicación original.",
  str_skill_name_29041015 = "Dispersar",
  str_skill_desc_29041015 = "Yoh y sus réplicas infligen daño a todos los objetivos en la pantalla.",
  str_skill_name_20022013 = "Chocar",
  str_skill_desc_20022013 = "\"Script\" inflige mucho daño a los objetivos en la zona de peligro por delante.",
  str_skill_name_20022022 = "Control",
  str_skill_desc_20022022 = "Cuando la ilusión no está activa, Yoh controla las \"Palabras\", lanzándolas como proyectiles para golpear directamente a los aurorianos. (Los aurorianos pueden destruir proyectiles durante este período para evitar recibir daño).",
  str_skill_name_490310106 = "Nefasto - Dulce beso",
  str_skill_desc_490310106 = "Excluyendo ciertas zonas seguras, Nefarious Barbara inflige daño de gran área y rompe los mosaicos rojos fuera de las zonas seguras.",
  str_skill_name_490310107 = "Nefasto - Nota final",
  str_skill_desc_490310107 = "Nefarious Barbara convoca a los aliados al centro del tablero, infligiendo daño a pantalla completa y derribando a los objetivos.",
  str_skill_desc_490023202 = "Vani usa energía para lanzar ataques a distancia contra objetivos dentro del área de ataque, dejando a los objetivos agotados al impactar.",
  str_skill_desc_490023212 = "Vani usa energía para lanzar ataques a distancia contra objetivos dentro del área de ataque, haciendo que los objetivos queden ciegos al impactar.",
  str_skill_desc_480043414 = "Mara Sol convoca a varios Abismos al campo. El número de Abismos está determinado por las acumulaciones de Golpe de Abismo de Mara Sol acumuladas durante la primera ola.",
  str_skill_desc_400012401 = "Invoca Chasms al campo de batalla cada ronda.",
  str_skill_upgrade_desc_16018113 = "Mejora de habilidades de equipo: gana 5 puntos de conocimiento al entrar en batalla y <color=#00F6FF>5</color> Insight Points al comienzo de cada ola.",
  str_skill_upgrade_desc_16018116 = "Mejora de habilidades de equipo: Zhong Xu gana puntos de conocimiento cada vez que pasa <color=#00F6FF>mosaicos de cualquier elemento</color>.",
  str_skill_name_2001811 = "Llamas despiadadas",
