  str_skill_passive_desc_420181 = "Obtenga una nueva habilidad activa: Consume <color=#00F6FF>{1}</color> <link=\"30075\"><#FFAE07><u>Puntos de conocimiento</u></color></link> a la fuerza 1 <color=#00F6FF>enemigo no jefe</color> para mover 1 ficha. El costo de Insight Point se multiplica cuando esta habilidad se lanza varias veces en la misma ronda (cada uso costará <color=#00F6FF>{1}</color> más puntos que el uso anterior). Zhong Xu gana 1 punto de conocimiento cada vez que pasa por 1 <color=#00F6FF>teja roja</color>.",
  str_skill_passive_desc_423181 = "Obtenga una nueva habilidad activa: Consume <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Puntos de conocimiento</u></color></link> a la fuerza 1 <color=#00F6FF>enemigo no jefe</color> para mover 1 ficha. El costo de Insight Point se multiplica cuando esta habilidad se lanza varias veces en la misma ronda (cada uso costará <color=#00F6FF>{1}</color> más puntos que el uso anterior). Zhong Xu gana 1 punto de conocimiento cada vez que pasa por 1 <color=#00F6FF>teja roja</color>.",
  str_skill_passive_desc_426181 = "Obtenga una nueva habilidad activa: Consume <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Puntos de conocimiento</u></color></link> a la fuerza 1 <color=#00F6FF>enemigo no jefe</color> para mover 1 ficha. El costo de Insight Point se multiplica cuando esta habilidad se lanza varias veces en la misma ronda (cada uso costará <color=#00F6FF>{1}</color> más puntos que el uso anterior). Zhong Xu gana 1 punto de conocimiento cada vez que pasa por 1 <color=#00F6FF>loseta</color>.",
  str_skill_passive_desc_430181 = "Obtén una nueva habilidad activa: Consume <color=#00F6FF>{1}</color> <link=\"30075\"><#FFAE07><u>Puntos de conocimiento</u></color></link> para obligar a 1 <color=#00F6FF>enemigo no jefe</color> a moverse 1 casilla, o consume 8 Puntos de conocimiento para <color=#00F6FF>mover la Llama Ancestral</color> 1 casilla. El costo de los Puntos de conocimiento se multiplica cuando esta habilidad se usa varias veces en la misma ronda (mover un <color=#00F6FF>enemigo/Llama Ancestral</color> costará <color=#00F6FF>{1}/8</color> más puntos que el uso anterior). Zhong Xu gana 1 Punto de conocimiento cada vez que pasa por 1 <color=#00F6FF>casilla roja</color>.",
  str_skill_passive_desc_433181 = "Obtén una nueva habilidad activa: Consume <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Puntos de conocimiento</u></color></link> para obligar a 1 <color=#00F6FF>enemigo no jefe</color> a moverse 1 casilla, o consume 8 Puntos de conocimiento para <color=#00F6FF>mover la Llama Ancestral</color> 1 casilla. El costo de los Puntos de conocimiento se multiplica cuando esta habilidad se usa varias veces en la misma ronda (mover un <color=#00F6FF>enemigo/Llama Ancestral</color> costará <color=#00F6FF>{1}/8</color> más puntos que el uso anterior). Zhong Xu gana 1 Punto de conocimiento cada vez que pasa por 1 <color=#00F6FF>casilla roja</color>.",
  str_skill_passive_desc_436181 = "Obtén una nueva habilidad activa: Consume <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Puntos de conocimiento</u></color></link> para obligar a 1 <color=#00F6FF>enemigo no jefe</color> a moverse 1 casilla, o consume 8 Puntos de conocimiento para <color=#00F6FF>mover la Llama Ancestral</color> 1 casilla. El costo de los Puntos de conocimiento se multiplica cuando esta habilidad se usa varias veces en la misma ronda (mover un <color=#00F6FF>enemigo/Llama Ancestral</color> costará <color=#00F6FF>{1}/8</color> más puntos que el uso anterior). Zhong Xu gana 1 Punto de conocimiento cada vez que pasa por 1 <color=#00F6FF>casilla</color>.",
  str_skill_desc_15011312 = "Golpea a todos los enemigos que no son jefes que ocupan una sola casilla en el tablero por 1 ficha a la derecha y causa daño a todos los enemigos en el campo.",
