  str_skill_desc_2201842 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>16 fichas en forma radial</color> y genera <color=#00F6FF>1</color> <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> dentro del área afectada.",
