  str_skill_desc_3001852 = "Se desbloquea después de acumular <color=#00F6FF>8</color> pilas de Kyanite Power: elige un enemigo y teletransporta a la posición más cercana dentro <color=#00F6FF>1 grupo circundante</color> alrededor del objetivo.",
  str_skill_desc_3361852 = "Se desbloquea después de acumular <color=#00F6FF>5</color> pilas de Kyanite Power: elige un enemigo y teletransporta a la posición más cercana dentro <color=#00F6FF>1 grupo circundante</color> alrededor del objetivo.",
  str_skill_passive_desc_410185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_desc_416185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color> y ganar <color=#00F6FF>1</color> pila de poder de cianita. Cada acumulación aumentará el daño en <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_420185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color>. Cuando la habilidad activa de Kya activa este efecto, su daño final aumentará en <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_426185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color> y ganar <color=#00F6FF>1</color> pila de poder de cianita. Cuando la habilidad activa de Kya activa este efecto, su daño final aumentará en <color=#00F6FF>60%</color>. Cada acumulación de Kyanite Power aumentará el daño en <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color> y ganar <color=#00F6FF>1</color> pila de poder de cianita. Cuando la habilidad activa de Kya activa este efecto, su daño final aumentará en <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_432185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color> y ganar <color=#00F6FF>1</color> pila de poder de cianita. Cuando la habilidad activa de Kya activa este efecto, su daño final aumentará en <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_436185 = "Cuando el equipo se teletransporta con una habilidad activa, reparte <color=#00F6FF>{1}</color> daño al enemigo que tiene el HP más bajo dentro <color=#00F6FF>1 grupo circundante</color> y ganar <color=#00F6FF>1</color> pila de poder de cianita. Cuando la habilidad activa de Kya activa este efecto, su daño final aumentará en <color=#00F6FF>60%</color>. Cada acumulación de Kyanite Power aumentará el daño en <color=#00F6FF>5%</color>.",
  str_skill_upgrade_desc_15018512 = "Mejora de habilidad activa: la cantidad de acumulaciones requeridas para Blink of an Eye se reduce a <color=#00F6FF>5</color>. (Válido para Ascensión III)",
  str_skill_upgrade_desc_15018515 = "Mejora de habilidades de equipo: cada activador de habilidad generará <color=#00F6FF>1</color> pila de poder de cianita. Cada acumulación de Kyanite Power aumentará el daño de la habilidad de equipo de Kya en <color=#00F6FF>5%</color>.",
  str_skill_name_28005016 = "Arrastrador",
  str_skill_desc_28005016 = "Atrae los eclipses dentro de un rango pequeño frente al mosaico Arrastrador 1 en su dirección. Cada Eclipsite solo puede verse afectado por el efecto de atracción del Dragger una vez por turno.",
  str_skill_name_400054101 = "Desarraigar",
  str_skill_desc_400054101 = "Inflige daño a todos los objetivos dentro del alcance y aplasta todas las fichas dentro del alcance, destruyendo todas las invocaciones de Bullock 8 en ellos.",
  str_skill_desc_5410100 = "Usa lanza para atacar Eclipsites dentro del rango de ataque.",
  str_skill_desc_888426101 = "Después de que el jugador use Habilidades Activas 3 veces seguidas, convoca a un Lumo Piker al campo de batalla.",
  str_skill_desc_4100002 = "Invoca Fire Dreadblades cada ronda hasta que 4 Fire Dreadblades estén en el campo de batalla.",
  str_skill_desc_4100004 = "Invoca Thunder Dreadblades cada ronda hasta que 4 Thunder Dreadblades estén en el campo de batalla.",
  str_skill_desc_4100005 = "Invoca un Enferno cada ronda hasta que haya 2 Enfernos en el campo de batalla.",
  str_skill_desc_4100006 = "Invoca un Enferno al campo de batalla cada ronda. No invocará si ya hay un Enferno en el campo de batalla.",
  str_skill_desc_5401005 = "Enferno invoca lluvia ardiente en lugares aleatorios cerca del Lumo Constructor, lo que inflige daño elemental y quema objetivos.",
  str_skill_name_290470111 = "Cazador mecánico: aniquilar",
  str_skill_desc_290470111 = "Canaliza Darkflow con su martillo gigante, lo que inflige un daño masivo a todos los objetivos en el campo. Este ataque reduce el HP de los Aurorianos dentro de la zona protegida a 1.",
  str_skill_name_290470121 = "Cazador mecánico: Hunt Down",
  str_skill_desc_290470121 = "Si su objetivo está en la zona protegida, se mueve junto a él e inflige daño cuerpo a cuerpo. Si el objetivo está fuera de la zona protegida, engancha un objetivo en la misma fila o columna y acerca el objetivo a sí mismo.",
  str_skill_desc_290470122 = "Si su objetivo está en la zona protegida, se mueve junto a él e inflige daño cuerpo a cuerpo. Si el objetivo está fuera de la zona protegida, engancha un objetivo en la misma fila o columna y acerca el objetivo a sí mismo.",
  str_skill_name_290470131 = "Cazador mecánico: desterrar",
  str_skill_desc_290470131 = "Envía ondas de energía turbulenta con su martillo gigante, que inflige daño a todos los enemigos en el campo. El jugador será empujado al borde del campo por la energía si está dentro de la zona protegida.",
  str_skill_name_290490101 = "Los cuatro caballeros: batalla en equipo",
  str_skill_desc_290490101 = "Se mueve a una casilla en diagonal desde el miembro de Los Cuatro Caballeros más cercano al objetivo (si el lanzador es el miembro más cercano de Los Cuatro Caballeros, permanecerá en la misma casilla) y luego ataca a los objetivos dentro de 1 grupo circundante.",
  str_skill_desc_290490103 = "Se mueve a una casilla en diagonal desde el miembro de Los Cuatro Caballeros más cercano al objetivo (si el lanzador es el miembro más cercano de Los Cuatro Caballeros, permanecerá en la misma casilla), y luego ataca a los objetivos dentro de 1 grupo circundante, infligiendo Fragilidad a los Aurorianos. . Cada acumulación de fragilidad reduce la DEF de los aurorianos en un 2 %.",
  str_skill_desc_290490107 = "Ataca objetivos dentro de 1 grupo circundante.",
  str_skill_name_290490102 = "Los cuatro caballeros: ataque rápido",
  str_skill_desc_290490102 = "Los Cuatro Caballeros se separaron, corrieron hacia los bordes del campo y luego atacaron al objetivo.",
  str_skill_desc_290490108 = "Ataca objetivos mientras permanece en su lugar.",
  str_skill_name_290550101 = "Demonio Hati: Llama de cobalto",
  str_skill_desc_290550101 = "Demonio Hati pierde el 15% de su HP actual y se teletransporta lo más cerca posible de un enemigo dentro de 12 mosaicos en forma de diamante, luego inflige daño a los enemigos dentro de 1 grupo circundante. Si golpea a un objetivo, recupera el 15% de su HP perdido.",
  str_skill_name_290550111 = "Demonio Hati: Llama de cobalto+",
  str_skill_desc_290550111 = "Demonio Hati pierde el 15% de su HP actual y se teletransporta lo más cerca posible de un enemigo dentro de 2 grupos circundantes, luego inflige daño a los enemigos dentro de 1 grupo circundante. Si golpea a un objetivo, recupera el 15% de su HP perdido.",
  str_skill_name_290550121 = "Demonio Hati: Llama de cobalto++",
  str_skill_desc_290550121 = "Demonio Hati pierde el 15% de su HP actual y se teletransporta lo más cerca posible de un enemigo dentro de 2 grupos circundantes, luego inflige daño a los enemigos dentro de 2 grupos circundantes. Si golpea a un objetivo, recupera el 15% de su HP perdido.",
  str_skill_name_290550102 = "Demon Hati: Llamas abisales",
  str_skill_desc_290550102 = "Demonio Hati se teletransporta junto a los Aurorianos y consume el 15% de su HP actual para infligir un daño masivo a los Aurorianos. Si golpea a un Aurorian, recupera el 15% de su HP perdido.",
