  str_skill_name_3061892 = "Carnicería torbellino",
  str_skill_name_3301892 = "Sobrecarga de combate",
  str_skill_name_3331892 = "Sobrecarga de combate",
  str_skill_desc_3001890 = "Selecciona 1 ficha de <color=#00F6FF>4 fichas en forma de cruz</color> en la ubicación actual y ofertas <color=#00F6FF>100%</color> daño a <color=#00F6FF>2 filas en forma de abanico</color> en esta dirección.",
  str_skill_desc_3001891 = "Selecciona 1 ficha de <color=#00F6FF>4 fichas en forma de cruz</color> en la ubicación actual y ofertas <color=#00F6FF>100%</color> daño a <color=#00F6FF>2 filas en forma de abanico</color> en esta dirección. Fervor aumenta el daño y el alcance, infligiendo hasta <color=#00F6FF>400%</color> daño a <color=#00F6FF>7 filas en forma de abanico</color>. Zeal se eliminará después de lanzar la habilidad.",
  str_skill_desc_3001892 = "Selecciona 1 ficha de <color=#00F6FF>4 fichas en forma de cruz</color> en la ubicación actual y ofertas <color=#00F6FF>100%</color> daño a <color=#00F6FF>2 filas en forma de abanico</color> en esta dirección. Fervor aumenta el daño y el alcance, infligiendo hasta <color=#00F6FF>400%</color> daño a <color=#00F6FF>7 filas en forma de abanico</color>. Zeal se eliminará después de lanzar la habilidad.",
  str_skill_desc_3061891 = "Selecciona 1 ficha de <color=#00F6FF>4 fichas en forma de cruz</color> en la ubicación actual y ofertas <color=#00F6FF>100%</color> daño a <color=#00F6FF>2 filas en forma de abanico</color> en esta dirección. Fervor aumenta el daño y el alcance, infligiendo hasta <color=#00F6FF>400%</color> daño a <color=#00F6FF>7 filas en forma de abanico</color>. Zeal se eliminará después de lanzar la habilidad. Si elige lanzar esta habilidad con su mosaico actual, aumentará el entusiasmo en <color=#00F6FF>35</color> puntos en lugar de infligir daño.",
  str_skill_desc_3061892 = "Selecciona 1 ficha de <color=#00F6FF>4 fichas en forma de cruz</color> en la ubicación actual y ofertas <color=#00F6FF>100%</color> daño a <color=#00F6FF>2 filas en forma de abanico</color> en esta dirección. Fervor aumenta el daño y el alcance, infligiendo hasta <color=#00F6FF>400%</color> daño a <color=#00F6FF>7 filas en forma de abanico</color>. Zeal se eliminará después de lanzar la habilidad. Si elige lanzar esta habilidad con su mosaico actual, aumentará el entusiasmo en <color=#00F6FF>35</color> puntos en lugar de infligir daño.",
  str_skill_desc_3301892 = "Todavía puede usar Ataques normales en el estado Demasiado entusiasta esta ronda. El entusiasmo se disipará al final de la ronda.",
  str_skill_desc_3331892 = "Aumenta el celo a <color=#00F6FF>100</color>. Todavía puede usar ataques normales en el estado Excesivo esta ronda. El entusiasmo se disipará al final de la ronda.",
