  str_skill_desc_2001903 = "ofertas <color=#00F6FF>160%</color> daño a los 2 enemigos más cercanos dentro <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_2001933 = "ofertas <color=#00F6FF>160%</color> daño a los 2 enemigos más cercanos dentro <color=#00F6FF>2 grupos circundantes</color>. Cada vez que los Aurorianos de Fuego lanzan Habilidades Activas, la condición de activación aumenta en <color=#00F6FF>1</color>. Además, el número de objetivos golpeados aumenta en 1, o el rango de habilidad aumenta en <color=#00F6FF>1</color> grupo.",
  str_skill_desc_3001901 = "Convierte el <color=#00F6FF>4</color> las fichas verdes más cercanas a las rojas.",
  str_skill_desc_3001902 = "Convierte los <color=#00F6FF>4</color> mosaicos verdes más cercanos en rojos. Si la habilidad activa estaba lista en la última ronda, aumenta el recuento de conversión de fichas en <color=#00F6FF>1</color> en esta ronda.",
