  str_skill_passive_name_430190 = "Guardián de la santidad",
  str_skill_passive_desc_410189 = "Los ataques normales de Leyn obtienen una bonificación de daño de hasta <color=#00F6FF>{1}</color> basado en su <link=\"30078\"><#FFAE07><u>Celo</u></color></link>, cuanto mayor sea Zeal, mayor será la bonificación de daño. Cuando llega el celo <color=#00F6FF>100</color>, entra en el estado Demasiado entusiasta y no puede usar Ataques normales.",
  str_skill_passive_desc_420189 = "Los ataques normales de Leyn obtienen una bonificación de daño de hasta <color=#00F6FF>{1}</color> basado en su <link=\"30078\"><#FFAE07><u>Celo</u></color></link>, cuanto mayor sea Zeal, mayor será la bonificación de daño. Cuando llega el celo <color=#00F6FF>100</color>, entra en el estado Demasiado entusiasta y no puede usar Ataques normales. Sin embargo, el daño final de sus Chain Combos aumenta en <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_430189 = "Los ataques normales de Leyn obtienen una bonificación de daño de hasta <color=#00F6FF>{1}</color> basado en su <link=\"30078\"><#FFAE07><u>Celo</u></color></link>, cuanto mayor sea Zeal, mayor será la bonificación de daño. Cuando llega el celo <color=#00F6FF>100</color>, entra en el estado Demasiado entusiasta y no puede usar Ataques normales. Sin embargo, el daño final de sus Chain Combos aumenta en <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_433189 = "Los ataques normales de Leyn obtienen una bonificación de daño de hasta <color=#00F6FF>{1}</color> basado en su <link=\"30078\"><#FFAE07><u>Celo</u></color></link>, cuanto mayor sea Zeal, mayor será la bonificación de daño. Cuando llega el celo <color=#00F6FF>100</color>, entra en el estado Demasiado entusiasta y no puede usar Ataques normales. Sin embargo, el daño final de sus Chain Combos aumenta en <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410190 = "<color=#00F6FF>50%</color> del daño infligido por Chain Combos se convierte en un escudo. El valor de este escudo no puede exceder <color=#00F6FF>{1}</color> del ATK de Matthieu.",
  str_skill_passive_desc_420190 = "<color=#00F6FF>50%</color> del daño infligido por Chain Combos se convierte en un escudo. El valor de este escudo no puede exceder <color=#00F6FF>{1}</color> del ATK de Matthieu. Cada vez que los Aurorianos de Fuego lanzan Habilidades Activas, obtienen un escudo igual a <color=#00F6FF>10%</color> del ATK de Matthieu.",
  str_skill_passive_desc_430190 = "<color=#00F6FF>50%</color> del daño infligido por Chain Combos se convierte en un escudo. El valor de este escudo no puede exceder <color=#00F6FF>{1}</color> del ATK de Matthieu. Cada vez que los Aurorianos de Fuego lanzan Habilidades Activas, obtienen un escudo igual a <color=#00F6FF>10%</color> del ATK de Matthieu.",
  str_skill_upgrade_desc_16018613 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16018616 = "Mejora de habilidad activa: aumenta la cantidad de fichas que puede conectar <color=#00F6FF>1</color>.",
