  str_skill_passive_desc_430186 = "Aumenta la primera instancia de daño infligido por Tina cada ronda por <color=#00F6FF>{1}</color>. Si Tina no realizó ninguna acción en la última ronda, el efecto se duplica en esta ronda.",
  str_skill_name_3001861 = "Descansa en la Luz Sagrada",
  str_skill_name_3061861 = "Descansa en la Luz Sagrada",
  str_skill_name_3201861 = "Descansa en la Luz Sagrada",
  str_skill_name_3261861 = "Descansa en la Luz Sagrada",
  str_skill_desc_3001861 = "Tina comienza a caminar dormida, ignorando los colores de los mosaicos hasta <color=#00F6FF>3</color> mosaicos consecutivos mientras <color=#00F6FF>convierte los mosaicos por los que pasa</color> a azul, luego regresa a su mosaico inicial.",
  str_skill_desc_3061861 = "Tina comienza a caminar dormida, ignorando los colores de los mosaicos hasta <color=#00F6FF>4</color> mosaicos consecutivos mientras <color=#00F6FF>convierte los mosaicos por los que pasa</color> a azul, luego regresa a su mosaico inicial.",
  str_skill_desc_3201861 = "Tina comienza a caminar dormida, ignorando los colores de los mosaicos hasta <color=#00F6FF>3</color> mosaicos consecutivos mientras <color=#00F6FF>convierte su mosaico inicial y los mosaicos por los que pasa</color> en mosaicos azules antes de volver a ella baldosa inicial. Si hay enemigos al final de su camino, puede optar por descender sobre el enemigo para infligir un <color=#00F6FF>200 %</color> de daño, antes de aterrizar en el mosaico justo delante del enemigo.",
  str_skill_desc_3261861 = "Tina comienza a caminar dormida, ignorando los colores de los mosaicos hasta <color=#00F6FF>4</color> mosaicos consecutivos mientras <color=#00F6FF>convierte su mosaico inicial y los mosaicos por los que pasa</color> en mosaicos azules antes de volver a ella baldosa inicial. Si hay enemigos al final de su camino, puede optar por descender sobre el enemigo para infligir un <color=#00F6FF>200 %</color> de daño, antes de aterrizar en el mosaico justo delante del enemigo.",
  str_skill_upgrade_desc_16018913 = "Mejora activa de habilidades: la sobrecarga de combate se convierte en una <color=#FFFF00>Ataque preventivo</color> y aumenta el Celo a <color=#00F6FF>100</color> cuando está activado. (Válido para Ascensión III)",
  str_skill_upgrade_desc_16018916 = "Mejora de habilidad activa: puede seleccionar el mosaico actual para aumentar el entusiasmo en <color=#00F6FF>35</color> en lugar de hacer daño. (Válido para Ascensión I)",
  str_skill_upgrade_desc_15019012 = "Mejora Habilidad Activa: Si la habilidad estaba lista en la última ronda, aumenta el recuento de conversión de casilla en <color=#FFFF00> 1 </color> en esta ronda.",
  str_skill_upgrade_desc_15019015 = "Mejora Habilidad Activa: Aumenta el recuento de conversión de casilla en <color=#FFFF00> 1 </color>.",
  str_skill_upgrade_refine_desc_16001111 = "Mejora de habilidades de equipo: se aplica hasta <color=#00F6FF>7</color> montones de Dragontooth Mark en los enemigos.",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Se teletransporta a una ubicación seleccionada dentro <color=#FFFF00>3 grupos circundantes</color>, ofertas <color=#FFFF00>200%</color> daño a <color=#FFFF00>1 grupo circundante</color>, y aplica 2 acumulaciones de Marca Diente de Dragón (si mata a un enemigo, las acumulaciones máximas de Marca Diente de Dragón se aplican a otros enemigos dentro del área).",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. se teletransporta a <color=#FFFF00>cualquier ubicación</color>, ofertas <color=#FFFF00>360%</color> daño a <color=#FFFF00>3 grupos circundantes</color>, y aplica 2 acumulaciones de Marca Diente de Dragón (si mata a un enemigo, las acumulaciones máximas de Marca Diente de Dragón se aplican a otros enemigos dentro del área).",
  str_skill_desc_3300111 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Se teletransporta a una ubicación seleccionada dentro <color=#FFFF00>3 grupos circundantes</color>, ofertas <color=#FFFF00>200%</color> daño a <color=#FFFF00>1 grupo circundante</color>, y aplica 2 acumulaciones de Marca Diente de Dragón (si mata a un enemigo, las acumulaciones máximas de Marca Diente de Dragón se aplican a otros enemigos dentro del área).",
  str_skill_desc_3300112 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. se teletransporta a <color=#FFFF00>cualquier ubicación</color>, ofertas <color=#FFFF00>360%</color> daño a <color=#FFFF00>3 grupos circundantes</color>, y aplica 2 acumulaciones de Marca Diente de Dragón (si mata a un enemigo, las acumulaciones máximas de Marca Diente de Dragón se aplican a otros enemigos dentro del área).",
  str_skill_upgrade_desc_16019113 = "Obtenga una nueva habilidad activa: Consume <color=#00F6FF>10%</color> del HP actual del equipo para infligir un 250% de daño a <color=#00F6FF>1 grupo circundante</color>.",
