  str_skill_desc_3001911 = "Selecciona 1 enemigo dentro <color=#00F6FF>24 fichas en forma de diamante</color>, luego se teletransporta a la casilla más cercana al objetivo y reparte <color=#00F6FF>150%</color> daño a ellos.",
  str_skill_desc_3201911 = "Selecciona 1 enemigo dentro <color=#00F6FF>24 fichas en forma de diamante</color>, luego se teletransporta a la casilla más cercana al objetivo y reparte <color=#00F6FF>150%</color> daño a ellos. Si la habilidad activa estaba lista en la última ronda, el rango de selección en esta ronda se vuelve <color=#00F6FF>4 grupos circundantes</color>.",
  str_skill_desc_32019112 = "Selecciona 1 enemigo dentro <color=#00F6FF>24 fichas en forma de diamante</color>, luego se teletransporta a la casilla más cercana al objetivo y reparte <color=#00F6FF>150%</color> daño a ellos. Si la habilidad activa estaba lista en la última ronda, el rango de selección en esta ronda se vuelve <color=#00F6FF>4 grupos circundantes</color> y el daño aumenta a <color=#00F6FF>200%</color>.",
  str_skill_desc_32019113 = "Selecciona 1 enemigo dentro <color=#00F6FF>24 fichas en forma de diamante</color>, luego se teletransporta a la casilla más cercana al objetivo y reparte <color=#00F6FF>150%</color> daño a 5 fichas en forma de cruz. Si la habilidad activa estaba lista en la última ronda, el rango de selección en esta ronda se vuelve <color=#00F6FF>4 grupos circundantes</color> y el daño aumenta a <color=#00F6FF>200%</color>.",
  str_skill_name_3001912 = "Llama siniestra",
  str_skill_name_3061912 = "Llama siniestra",
  str_skill_desc_3001912 = "consume <color=#00F6FF>10%</color> del HP actual del equipo para tratar {1}% daño a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_name_410191 = "Garras incineradoras",
  str_skill_passive_desc_410191 = "El daño de Hati aumenta a medida que disminuye el HP del equipo, hasta <color=#00F6FF>{1}</color> cuando el HP del equipo es inferior a <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_4101911 = "El daño de Hati aumenta a medida que disminuye el HP del equipo, hasta <color=#00F6FF>60%</color> cuando el HP del equipo es inferior a <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16019111 = "Mejora de habilidades de equipo: la bonificación sube a <color=#00F6FF>60%</color> cuando el HP del equipo es inferior al 30%.",
  str_skill_upgrade_refine_desc_16019112 = "Nuevo efecto de habilidad activa: si la habilidad activa estaba lista en la última ronda, el rango de selección en esta ronda se convierte en 4 grupos circundantes <color=#00F6FF>y el daño aumenta al 200%</color>.",
  str_skill_upgrade_refine_desc_16019113 = "Mejora de habilidad activa: inflige daño a <color=#00F6FF>5 fichas en forma de cruz</color> en lugar de 1 objetivo.",
  str_skill_name_2001931 = "Corrientes Radiales",
  str_skill_name_2001932 = "Corrientes Radiales",
  str_skill_name_20019333 = "Corrientes Radiales",
  str_skill_name_2201931 = "Corrientes Radiales",
  str_skill_name_2201932 = "Corrientes Radiales",
  str_skill_name_2201933 = "Corrientes Radiales",
  str_skill_name_3001931 = "a los cielos",
  str_skill_name_3051931 = "a los cielos",
  str_skill_name_3301931 = "a los cielos",
  str_skill_name_3351931 = "a los cielos",
  str_skill_name_3401931 = "A Los Cielos Variante I",
  str_skill_name_3451931 = "A Los Cielos Variante I",
  str_skill_name_3401932 = "A los cielos variante II",
  str_skill_desc_2001931 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 8 casillas en forma de cruz </color>.",
  str_skill_desc_2001932 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_20019333 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color> y a los enemigos en una <color=#00F6FF>forma de cruz hasta el alcance máx.</color>",
  str_skill_desc_2201931 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>8 fichas en forma de cruz</color>. Aumenta el daño infligido a los enemigos a lo largo de una cruz en un 30%.",
  str_skill_desc_2201932 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>. Aumenta el daño infligido a los enemigos a lo largo de una cruz en un 30%.",
  str_skill_desc_2201933 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>1 grupo circundante</color> y <color=#00F6FF>una forma de cruz al rango máximo</color>. Aumenta el daño infligido a los enemigos a lo largo de una cruz en un 30%.",
  str_skill_desc_3001931 = "Ataca en cualquier dirección seleccionada, infligiendo <color=#00F6FF>160%</color> daño a todos los enemigos en esta dirección.",
  str_skill_desc_3051931 = "Ataca en cualquier dirección seleccionada, infligiendo <color=#00F6FF>200%</color> daño a todos los enemigos en esta dirección.",
  str_skill_desc_3301931 = "Ataca en cualquier dirección seleccionada, infligiendo <color=#00F6FF>160%</color> daño a todos los enemigos en esta dirección. Cuanto más lejos está un objetivo, más daño inflige. El daño final aumenta en <color=#00F6FF>10%</color> por racimo.",
  str_skill_desc_3351931 = "Ataca en cualquier dirección seleccionada, infligiendo <color=#00F6FF>200%</color> daño a todos los enemigos en esta dirección. Cuanto más lejos está un objetivo, más daño inflige. El daño final aumenta en <color=#00F6FF>10%</color> por racimo.",
  str_skill_desc_3401931 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige un 160% de daño a todos los enemigos en una dirección seleccionada, luego cambia de posición con el <color=#FFFF00>anterior</color> miembro del equipo. Cuanto más lejos esté el objetivo, más daño infligirá. El daño final aumenta en un 10% por grupo. <color=#FFFF00>Si se selecciona un mosaico exterior, Kristen avanza 1 ficha antes de lanzar la habilidad</color>.",
  str_skill_desc_3451931 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige un 200% de daño a todos los enemigos en una dirección seleccionada, luego cambia de posición con el <color=#FFFF00>anterior</color> miembro del equipo. Cuanto más lejos esté el objetivo, más daño infligirá. El daño final aumenta en un 10% por grupo. <color=#FFFF00>Si se selecciona un mosaico exterior, Kristen avanza 1 ficha antes de lanzar la habilidad</color>.",
  str_skill_desc_3401932 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. <color=#FFFF00>sin atacar</color>, intercambia posiciones con el <color=#FFFF00>subsiguiente</color> miembro del equipo. <color=#FFFF00>Aumenta el daño de la siguiente habilidad activa en un 50 %</color>. Esta bonificación de daño no se acumula cuando se lanza más de una vez.",
  str_skill_passive_name_410193 = "Láser de corriente en chorro",
  str_skill_passive_name_430193 = "Láser de corriente en chorro",
  str_skill_passive_desc_410193 = "Los ataques normales penetrarán a través de los enemigos, infligiendo <color=#00F6FF>{1}</color> daño al objetivo 1 casilla detrás del enemigo.",
  str_skill_passive_desc_430193 = "Los ataques normales penetrarán a través de los enemigos, infligiendo <color=#00F6FF>{1}</color> daño al objetivo 1 casilla detrás del enemigo.",
  str_skill_passive_desc_4401933 = "Los ataques normales penetrarán a los enemigos, infligiendo <color=#00F6FF>60%</color> daño al objetivo 1 casilla detrás del enemigo. Los cambios de capitán para la batalla aumentan en <color=#00F6FF>1</color> cuando Kristen intercambia posiciones con un miembro del equipo. Se activa hasta 1 vez por ronda.",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige daño a todos los enemigos en 1 dirección seleccionada, luego intercambia posiciones con el <color=#FFFF00>anterior</color> miembro del equipo. Cuanto más lejos esté el objetivo, más daño infligirá. El daño final aumenta en un 10% por grupo. <color=#FFFF00>Si se selecciona un mosaico exterior, Kristen avanza 1 ficha antes de lanzar la habilidad</color>.",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. <color=#FFFF00>sin atacar</color>, intercambia posiciones con el <color=#FFFF00>subsiguiente</color> miembro del equipo. <color=#FFFF00>Aumenta el daño de la siguiente habilidad activa en un 50 %</color>. Esta bonificación de daño no se acumula cuando se lanza más de una vez.",
  str_skill_upgrade_refine_desc_15019313 = "Mejora de habilidades de equipo: los cambios de capitán para la batalla aumentan en 1 cuando Kristen intercambia posiciones con un miembro del equipo. Se activa hasta 1 vez por ronda.",
  str_skill_upgrade_desc_15019312 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15019315 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#FFFF00> 40% </color>.",
  str_skill_upgrade_refine_desc_14004811 = "Mejora de habilidades de equipo: por cada 1 mosaico amarillo a los pies del enemigo, el daño aumenta en <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_14004812 = "Mejora de habilidad activa: inflige el doble de daño al mosaico en el centro del rango de la habilidad.",
  str_skill_upgrade_refine_desc_14004813 = "Mejora de habilidad activa: si la habilidad activa estaba lista en la última ronda, el rango de selección se vuelve <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_passive_desc_4400481 = "Aumenta el daño de Dayna contra los enemigos que ocupan un mosaico amarillo en <color=#00F6FF>10%</color>. Por cada mosaico amarillo a los pies del enemigo, la bonificación de daño aumenta en <color=#00F6FF>1%</color>. También otorga a los compañeros de equipo Thunder Aurorian <color=#00F6FF>50%</color> de este bono.",
  str_skill_name_3400482 = "Trueno Caprichoso",
  str_skill_name_3420482 = "Trueno Caprichoso",
  str_skill_name_3400483 = "Trueno Caprichoso",
  str_skill_name_3420483 = "Trueno Caprichoso",
  str_skill_desc_3400482 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la casilla central seleccionada se duplica.",
  str_skill_desc_3420482 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la casilla central seleccionada se duplica. Convierte hasta 1 mosaico debajo del enemigo en amarillo.",
  str_skill_desc_3400483 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la casilla central seleccionada se duplica. Si esta habilidad activa estaba lista en la última ronda, el rango de selección se vuelve <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_3420483 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la casilla central seleccionada se duplica. Convierte hasta 1 mosaico debajo del enemigo en amarillo. Si esta habilidad activa estaba lista en la última ronda, el rango de selección se vuelve <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_upgrade_refine_desc_15009811 = "Mejora del combo en cadena: aumenta el factor de daño del combo en cadena en <color=#00F6FF>15%/20%/20%</color>.",
  str_skill_upgrade_refine_desc_15009812 = "Mejora de habilidades de equipo: Dismember Mark se acumula hasta <color=#00F6FF>10 veces</color> y cada acumulación aumenta el daño en un 6%.",
  str_skill_upgrade_refine_desc_15009813 = "Mejora de habilidad activa: aumenta el factor de daño de habilidad activa a <color=#00F6FF>500%</color>. Si el enemigo seleccionado por esta Habilidad Activa no puede ser desplazado, <color=#00F6FF>Enfriamiento de habilidad -1</color> después del lanzamiento.",
  str_skill_desc_2009811 = "ofertas <color=#00F6FF>150%</color> daño a 3 enemigos dentro <color=#00F6FF>3 grupos circundantes</color>.",
  str_skill_desc_2009821 = "ofertas <color=#00F6FF>160%</color> daño a 4 enemigos dentro <color=#00F6FF>3 grupos circundantes</color>.",
  str_skill_desc_2009831 = "ofertas <color=#00F6FF>170%</color> daño a todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>.",
  str_skill_desc_3300981 = "Selecciona 1 enemigo dentro <color=#00F6FF>3 grupos circundantes</color> y ofertas <color=#00F6FF>500%</color> dañarlo. Si el enemigo ocupa una sola casilla y puede ser derribado, lo mueve a una posición seleccionada dentro del rango de ataque. Si el enemigo no puede ser derribado, <color=#00F6FF>el enfriamiento de la habilidad se reduce en 1</color> después del lanzamiento. Si un objetivo que tiene una marca muere, inflige un daño que ignora la DEF igual a <color=#00F6FF>40%</color> del ATK de Cuscuta a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_desc_3350981 = "Selecciona 1 enemigo y trata <color=#00F6FF>500%</color> dañarlo. Si el enemigo ocupa una sola casilla y puede ser derribado, se mueve a una posición seleccionada dentro del rango de ataque. Si el enemigo no puede ser derribado, <color=#00F6FF>el enfriamiento de la habilidad se reduce en 1</color> después del lanzamiento. Si un objetivo que tiene una marca muere, inflige un daño que ignora la DEF igual a <color=#00F6FF>40%</color> del ATK de Cuscuta a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_desc_3200331 = "ofertas <color=#00F6FF>95%</color> daño <color=#00F6FF>5</color> veces a enemigos aleatorios en el campo de batalla. Lanza 1 ataque adicional por cada mosaico azul dentro <color=#00F6FF>1 grupo circundante</color> de la ubicación actual. La primera instancia de daño infligido a cada objetivo es <color=#00F6FF>duplicado</color>.",
  str_skill_desc_3250331 = "ofertas <color=#00F6FF>95%</color> daño <color=#00F6FF>6</color> veces a enemigos aleatorios en el campo de batalla. Lanza 1 ataque adicional por cada mosaico azul dentro <color=#00F6FF>12 grupos circundantes</color> de la unidad La primera instancia de daño infligido a cada objetivo es <color=#00F6FF>duplicado</color>.",
  str_skill_passive_desc_4300331 = "Vice gana 1 acumulación de Locking Mark cada vez que inflige daño. Cada acumulación aumenta el daño en <color=#00F6FF>2,5%</color> y daño combinado en cadena por <color=#00F6FF>5%</color>. Todas las pilas se eliminan al final de la ronda.",
  str_skill_passive_desc_4300332 = "Vice gana 1 acumulación de Locking Mark cada vez que inflige daño. Cada acumulación aumenta el daño en <color=#00F6FF>2,5%</color> y daño combinado en cadena por <color=#00F6FF>5%</color>, así como también aumenta el ATK básico de Vice en un 0.5%. Todas las pilas se eliminan al final de la ronda.",
  str_skill_upgrade_refine_desc_15003311 = "Mejora de habilidades de equipo: cada acumulación de marca aumenta el daño en <color=#00F6FF>2,5%</color> y daño combinado en cadena por <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_15003312 = "Mejora de habilidad activa: la primera instancia de daño infligido a cada objetivo es <color=#00F6FF>duplicado</color>.",
  str_skill_upgrade_refine_desc_15003313 = "Mejora de habilidades de equipo: cada acumulación de marca aumenta el ATK básico en <color=#00F6FF>0,5%</color>.",
  str_skill_desc_340093 = "Se teletransporta a cualquier lugar dentro <color=#00F6FF>3 grupos circundantes</color> y ofertas <color=#00F6FF>250%</color> daño a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. El daño final aumenta en <color=#00F6FF>15%</color> por cada enemigo asesinado. Se acumula hasta 10 veces. El rango de teletransporte aumenta en 1 grupo circundante por cada 5 enemigos asesinados.",
  str_skill_desc_346093 = "Se teletransporta a cualquier lugar dentro <color=#00F6FF>3 grupos circundantes</color> y ofertas <color=#00F6FF>250%</color> daño a los enemigos dentro <color=#00F6FF>1 grupo circundante</color>. El daño se duplica cuando solo hay 1 enemigo en el área de ataque. El daño final aumenta en <color=#00F6FF>15%</color> por cada enemigo asesinado. Se acumula hasta 10 veces. Elimina el tiempo de reutilización de la habilidad activa si el objetivo es derrotado con la habilidad (una vez por ronda). El rango de teletransporte aumenta en 1 grupo circundante por cada 5 enemigos asesinados.",
  str_skill_passive_desc_4300931 = "Después de lanzar un combo en cadena o una habilidad activa, si el HP del objetivo es inferior a <color=#00F6FF>30%</color>, lanza 1 ataque más que inflige daño ignorando DEF igual a <color=#00F6FF>120%</color> de ATK. Si el objetivo tiene menos HP que el ATK de Migard después de este ataque adicional, muere.",
  str_skill_passive_desc_4300932 = "Después de lanzar un combo en cadena o una habilidad activa, si el HP del objetivo es inferior a <color=#00F6FF>30%</color>, lanza 1 ataque más que inflige daño ignorando DEF igual a <color=#00F6FF>120%</color> de ATK. Si el objetivo tiene menos HP que el 250% del ATK de Migard después de este ataque adicional, muere.",
  str_skill_upgrade_refine_desc_16009311 = "Mejora de habilidades de equipo: el daño adicional del ataque aumenta a <color=#00F6FF>120%</color>.",
  str_skill_upgrade_refine_desc_16009312 = "Mejora activa de habilidades: Cada <color=#00F6FF>5 veces</color> esta habilidad activa gana una bonificación de daño, el rango de selección aumenta en <color=#00F6FF>1 grupo</color>.",
  str_skill_upgrade_refine_desc_16009313 = "Mejora de habilidades de equipo: si el HP del objetivo es inferior a <color=#00F6FF>250%</color> del ATK de Migard después del ataque adicional, muere.",
  str_skill_upgrade_refine_desc_15001811 = "Mejora de habilidades de equipo: cuanto más cerca estén los enemigos, más daño infligirán las habilidades activas y los combos en cadena (hasta <color=#00F6FF>110%</color>).",
  str_skill_upgrade_refine_desc_15001812 = "Mejora del combo en cadena: aumenta el factor de daño del combo en cadena en <color=#00F6FF>10%/15%/20%</color>.",
  str_skill_upgrade_refine_desc_15001813 = "Mejora de habilidades de equipo: el alcance del efecto aumenta a <color=#00F6FF>5 racimos</color>.",
  str_skill_passive_desc_440018 = "Aumenta el ATK en <color=#00F6FF>5%</color> para cada enemigo dentro <color=#00F6FF>1 grupo circundante</color>. Cuanto más cerca estén los enemigos, más daño infligirán las habilidades activas y los combos en cadena (hasta <color=#00F6FF>110%</color>). Las distancias más allá de 3 grupos no ofrecen bonificaciones de daño.",
  str_skill_passive_desc_450018 = "Aumenta el ATK en <color=#00F6FF>5%</color> para cada enemigo dentro <color=#00F6FF>1 grupo circundante</color>. Cuanto más cerca estén los enemigos, más daño infligirán las habilidades activas y los combos en cadena (hasta <color=#00F6FF>110%</color>). Las distancias más allá de 5 grupos no ofrecen bonificaciones de daño.",
  str_skill_desc_2400181 = "ofertas <color=#00F6FF>115%</color> daño a <color=#00F6FF>1 columna</color>.",
  str_skill_desc_2400182 = "ofertas <color=#00F6FF>125%</color> daño a <color=#00F6FF>3 columnas</color>.",
  str_skill_desc_2400183 = "ofertas <color=#00F6FF>130%</color> daño a <color=#00F6FF>5 columnas</color>.",
  str_skill_upgrade_refine_desc_16006411 = "Mejora activa de habilidades: el tiempo de reutilización de habilidades se reduce en <color=#00F6FF>2</color> al comienzo de cada batalla.",
  str_skill_upgrade_refine_desc_16006412 = "Mejora de habilidades de equipo: <color=#00F6FF>5</color> las balas se pueden reservar cuando se usa la habilidad activa. <color=#00F6FF>1</color> La bala se puede reservar cuando cualquier Aurorian usa su Habilidad Activa.",
  str_skill_upgrade_refine_desc_16006413 = "Mejora de habilidades de equipo: puede alternar manualmente si Chain Combos consume munición.",
  str_skill_passive_desc_440064 = "Poder <link=\"30079\"><#FFAE07><u>munición de reserva</u></color></link>. Cada vez que un combo en cadena inflige daño, se consume 1 munición (hasta <color=#00F6FF>3</color> La munición se puede consumir en el estado de sobrecarga). Por cada munición consumida, el daño final aumenta en <color=#00F6FF>30%</color>.",
  str_skill_desc_341064 = "Entra en el estado de sobrecarga, en el que el daño de Wrath's Chain Combo aumenta en <color=#00F6FF>50%</color> y hace daño al enemigo más cercano 2 veces. Dura 2 rondas. El enfriamiento de la habilidad se reduce en <color=#00F6FF>2</color> al comienzo de cada batalla.",
  str_skill_upgrade_refine_desc_16001911 = "Victoria se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>.\n<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. ofertas <color=#FFFF00>300%</color> daño a hasta 3 enemigos dentro del alcance. ofertas <color=#FFFF00>300%</color> Daño que ignora DEF cuando solo hay 1 enemigo en el rango. El daño final infligido a los objetivos aumenta en un 10 % por cada acumulación de sangrado que tengan. Restaura HP igual a un porcentaje del daño infligido. <color=#FFFF00>Además, pierde cordura igual al porcentaje de HP restaurado</color>.",
  str_skill_upgrade_refine_desc_16001912 = "Mejora de habilidad activa: la habilidad activa puede atacar a 1 enemigo adicional.",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige un 250 % de daño a hasta 4 enemigos dentro del alcance. Inflige un 250 % de daño que ignora la DEF cuando solo hay 1 enemigo al alcance. El daño final infligido a los objetivos aumenta en un 10 % por cada acumulación de sangrado que tengan. Restaura HP igual a un porcentaje del daño infligido. <color=#FFFF00>Además restaura Cordura igual al porcentaje de HP restaurado</color>.",
  str_skill_desc_3200192 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. ofertas <color=#FFFF00>300%</color> daño a hasta 3 enemigos dentro de 3 grupos circundantes. ofertas <color=#FFFF00>300%</color> Daño que ignora DEF cuando solo hay 1 enemigo en el rango. El daño final infligido a los objetivos aumenta en un 10 % por cada acumulación de sangrado que tengan. Restaura HP igual al 25% del daño infligido. <color=#FFFF00>Además, pierde cordura igual al porcentaje de HP restaurado</color>.",
  str_skill_desc_3200191 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige un 250 % de daño a hasta 3 enemigos dentro de 3 grupos circundantes. Inflige un 250 % de daño que ignora la DEF cuando solo hay 1 enemigo al alcance. El daño final infligido a los objetivos aumenta en un 10 % por cada acumulación de sangrado que tengan. Restaura HP igual al 25% del daño infligido. <color=#FFFF00>Además restaura Cordura igual al porcentaje de HP restaurado</color>.",
  str_skill_desc_3230192 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. ofertas <color=#FFFF00>300%</color> daño a hasta 3 enemigos dentro de 3 grupos circundantes. ofertas <color=#FFFF00>300%</color> Daño que ignora DEF cuando solo hay 1 enemigo en el rango. El daño final infligido a los objetivos aumenta en un 10 % por cada acumulación de sangrado que tengan. Restaura HP igual al 35% del daño infligido. <color=#FFFF00>Además, pierde cordura igual al porcentaje de HP restaurado</color>.",
