  str_skill_name_290510101 = "campo de perforación",
  str_skill_desc_290510101 = "El Perforador selecciona aleatoriamente un área abierta para moverse, infligiendo daño de descarga a 4 casillas adyacentes. Al final del movimiento, la habilidad genera una cierta cantidad de Campos de energía y Campos de apoyo dentro de 2 grupos circundantes.",
  str_skill_desc_290511102 = "El Perforador selecciona aleatoriamente un área abierta para moverse, infligiendo daño de descarga a 4 casillas adyacentes. Al final del movimiento, esta habilidad genera una cierta cantidad de Campos de energía y Campos de apoyo.",
  str_skill_desc_290511103 = "Al actuar, genera una cierta cantidad de Campos de energía y Campos de apoyo en el área circundante.",
  str_skill_name_290510102 = "Campo de energía del perforador",
  str_skill_desc_290510102 = "El perforador absorbe campos de energía en el campo, transformándolos en una plataforma de perforación en el lugar y causa daño en todo el campo.",
  str_skill_name_290510203 = "Campo de apoyo al perforador",
  str_skill_desc_290510203 = "El Perforador bloquea la ubicación de los Aurorianos con la Plataforma de Perforación y dirige los 5 Campos de Apoyo más cercanos al jugador para causarle daño. Cuenta regresiva de carga de energía en 2.",
  str_skill_desc_290510213 = "El Perforador bloquea la ubicación de los Aurorianos con la Plataforma de Perforación y dirige los 3 Campos de Apoyo más cercanos al jugador para causarle daño. Cuenta regresiva de carga de energía en 1.",
  str_skill_name_290510204 = "Autodestrucción de la plataforma del perforador",
  str_skill_desc_290510204 = "La Plataforma de Perforación se autodestruye al reunir toda la energía, causando un gran daño a todo el campo.",
  str_skill_name_290510123 = "En la operación",
  str_skill_desc_290510123 = "El perforador opera detrás de la plataforma. Driller y Driller Platform tienen HP independientes.",
  str_skill_desc_290511101 = "El perforador se mueve hacia el jugador e inflige daño de descarga a 4 casillas adyacentes. Al final del movimiento, la habilidad genera Campos de apoyo en 4 mosaicos adyacentes.",
  str_skill_desc_290511203 = "El perforador bloquea la ubicación del jugador con la plataforma del perforador y usa todos los campos de apoyo para causar daño al jugador. La cantidad de daño infligido al jugador aumenta con el número de campos de apoyo.",
  str_skill_desc_290512101 = "El perforador se enfoca en cavar, generando una pequeña cantidad de campos de energía y campos de apoyo a su alrededor al comienzo de la ronda.",
  str_skill_upgrade_desc_16019913 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16019916 = "Mejora de habilidades de equipo: cuando Yingel inflige daño a los objetivos que tienen una herida abierta, ella ignora <color=#00F6FF>5%</color> de su DEF por cada 1 herida abierta que tengan. (Válido para Ascensión III).",
  str_skill_name_2001991 = "hiperenfoque",
  str_skill_name_2001992 = "hiperenfoque",
  str_skill_name_2001993 = "hiperenfoque",
  str_skill_desc_2001991 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo más cercano.",
  str_skill_desc_2001992 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo más cercano.",
  str_skill_desc_2001993 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo más cercano.",
  str_skill_name_2201991 = "hiperenfoque",
