  str_skill_desc_2201992 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo que tiene el HP más alto y la mayor cantidad de heridas abiertas, o ataca al enemigo más cercano.",
  str_skill_desc_2201993 = "ofertas <color=#00F6FF>{1}%</color> daño al enemigo que tiene el HP más alto y la mayor cantidad de heridas abiertas, o ataca al enemigo más cercano.",
  str_skill_name_3001991 = "resonancia del cielo",
  str_skill_desc_3001991 = "Convierte cualquier mosaico seleccionado en amarillo <link=\"30080\"><#FFAE07><u>mosaico de prisma en forma de cruz</u></color></link>.",
  str_skill_passive_name_410199 = "Recarga especializada",
  str_skill_passive_name_420199 = "Recarga especializada",
  str_skill_passive_name_430199 = "Recarga especializada",
  str_skill_passive_name_436199 = "Recarga especializada",
  str_skill_passive_desc_410199 = "Cada <color=#00F6FF>segundo</color> Ataque normal, el multiplicador de daño de Ataque normal de Yingel aumenta a <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420199 = "Cada <color=#00F6FF>segundo</color> Ataque normal, el multiplicador de daño de Ataque normal de Yingel aumenta a <color=#00F6FF>{1}</color> e inflige 1 herida abierta, hasta 20 acumulaciones. Por cada herida abierta que tenga un objetivo, el daño final del combo en cadena de Yingel aumenta en <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430199 = "Cada <color=#00F6FF>segundo</color> Ataque normal, el multiplicador de daño de Ataque normal de Yingel aumenta a <color=#00F6FF>{1}</color> e inflige 1 herida abierta, hasta 20 acumulaciones. Por cada herida abierta que tenga un objetivo, los ataques de Yingel ignoran <color=#00F6FF>3%</color> de su DEF y el daño final de su Chain Combo aumenta en <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_436199 = "Cada <color=#00F6FF>segundo</color> Ataque normal, el multiplicador de daño de Ataque normal de Yingel aumenta a <color=#00F6FF>{1}</color> e inflige 1 herida abierta, hasta 20 acumulaciones. Por cada herida abierta que tenga un objetivo, los ataques de Yingel ignoran <color=#00F6FF>5%</color> de su DEF y el daño final de su Chain Combo aumenta en <color=#00F6FF>3%</color>.",
  str_skill_desc_1601751002 = "Azulejo de prisma en forma de cruz",
  str_skill_desc_160175102 = "consume <color=#00F6FF>3</color> Energía cúbica para convertir cualquier mosaico en un mosaico de prisma en forma de cruz.",
  str_skill_name_3400231 = "Sonata del Abismo Variante I",
  str_skill_name_3430231 = "Sonata del Abismo Variante I",
  str_skill_name_3400232 = "Sonata del Abismo Variante II",
  str_skill_name_3430232 = "Sonata del Abismo Variante II",
  str_skill_desc_3400231 = "<color=#FFFF00>Enfriamiento de habilidad -2 después de lanzar</color>. ofertas <color=#FFFF00>250%</color> daño a todos los enemigos. Esta variante no puede activar el efecto Asustar de la Habilidad de equipo.",
  str_skill_desc_3430231 = "<color=#FFFF00>Enfriamiento de habilidad -2 después de lanzar</color>. ofertas <color=#FFFF00>250%</color> daño a todos los enemigos. Esta variante no puede activar el efecto Asustar de la Habilidad de equipo.",
  str_skill_desc_3400232 = "<color=#FFFF00>Enfriamiento de habilidad +2 después de lanzar</color>. <color=#FFFF00>Inflige a todos los enemigos con <link=\"10003\"><#FFAE07><u>Asustar</u></color></link> por 1 ronda</color> y ofertas <color=#FFFF00>550%</color> daño a ellos.",
  str_skill_desc_3430232 = "<color=#FFFF00>Enfriamiento de habilidad +2 después de lanzar</color>. <color=#FFFF00>Inflige a todos los enemigos con <link=\"10003\"><#FFAE07><u>Asustar</u></color></link> por 1 ronda</color> y ofertas <color=#FFFF00>550%</color> daño a ellos.",
  str_skill_passive_desc_440023 = "Gana 1 acumulación de Shiver Mark cuando usa un Chain Combo, hasta <color=#00F6FF>5</color> pilas Cada acumulación aumenta el daño de la habilidad activa en <color=#00F6FF>20%</color>. El uso de una habilidad activa inflige <link=\"10003\"><#FFAE07><u>Asustar</u></color></link> en un número de enemigos equivalente al número de acumulaciones para <color=#00F6FF>1</color> redondo. Activar la habilidad activa <color=#00F6FF>no borra las pilas</color>. Si ya hay 5 acumulaciones presentes antes de desatar una habilidad Chain Combo, infligirá daño adicional al enemigo más cercano. Connolly inflige un 15% adicional de daño final a <link=\"10003\"><#FFAE07><u>Atemorizado</u></color></link> enemigos.",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad -2 después de lanzar</color>. ofertas <color=#FFFF00>250%</color> daño a todos los enemigos. Esta variante no puede activar el efecto Asustar de la Habilidad de equipo.",
  str_skill_upgrade_refine_desc_16002312 = "Mejora de habilidades de equipo: Connolly ofertas <color=#00F6FF>un 15% adicional de daño final</color> a los enemigos infligidos con Frighten.",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad +2 después de lanzar</color>. <color=#FFFF00>Inflige a todos los enemigos con <link=\"10003\"><#FFAE07><u>Asustar</u></color></link> por 1 ronda</color> y ofertas <color=#FFFF00>550%</color> daño a ellos.",
  str_skill_name_290520101 = "Bombardeo feroz",
  str_skill_desc_290520101 = "Se mueve hacia los aurorianos y causa mucho daño, luego se retira del objetivo.",
