  str_skill_desc_290520102 = "Inflige daño a todos los Aurorianos dentro del alcance después de moverse.",
  str_skill_name_200250101 = "Fuego de aproximación",
  str_skill_desc_200250101 = "Lanza un ataque a distancia a los objetivos dentro del alcance.",
  str_skill_name_200250102 = "Cuchillo de asalto",
  str_skill_desc_200250102 = "Lanza un ataque cuerpo a cuerpo a los objetivos dentro del alcance.",
  str_skill_name_290500122 = "Huevo de araña",
  str_skill_desc_290500122 = "Un huevo de araña puesto por la Reina Araña. Eclosiona en una cría de araña en un corto período de tiempo.",
  str_skill_name_3400901 = "Dulce beso variante I",
  str_skill_name_3420901 = "Dulce beso variante I",
