  str_skill_name_3420902 = "Dulce beso variante II",
  str_skill_desc_3400901 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. ofertas <color=#FFFF00>{1}%</color> daño a todos los enemigos <color=#FFFF00>y los aturde</color>.",
  str_skill_desc_3420901 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. ofertas <color=#FFFF00>{1}%</color> daño a todos los enemigos <color=#FFFF00>y los aturde</color>.",
  str_skill_desc_3400902 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. ofertas <color=#FFFF00>{1}%</color> daño a todos los enemigos.",
  str_skill_desc_3420902 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. ofertas <color=#FFFF00>{1}%</color> daño a todos los enemigos.",
  str_skill_passive_desc_440090 = "Aumenta el daño de Bárbara contra los enemigos que ocupan una casilla roja en <color=#00F6FF>10%</color>. Por cada mosaico rojo a los pies del enemigo, la bonificación de daño aumenta en <color=#00F6FF>1%</color>. También otorga a los compañeros de equipo de Fire Aurorian <color=#00F6FF>50%</color> de este bono.",
  str_skill_upgrade_refine_desc_15009011 = "Mejora de habilidades de equipo: por cada 1 mosaico rojo a los pies del enemigo, el daño aumenta en <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. ofertas <color=#FFFF00>600%</color> daño a todos los enemigos <color=#FFFF00>y los aturde</color>.",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. ofertas <color=#FFFF00>450%</color> daño a todos los enemigos.",
  str_skill_name_5000961 = "Enlazar",
  str_skill_desc_5000961 = "Cuando los aurorianos ingresan dentro de los 2 grupos circundantes del Spikepest, se establece automáticamente un vínculo entre ellos. El vínculo se rompe cuando los Aurorianos se alejan 4 grupos circundantes del Spikepest. Mientras está vinculado, Spikepest comparte el 50% del daño recibido por el jugador.",
  str_skill_desc_4001531 = "Lanza habilidad para derribar enemigos dentro de 3 grupos circundantes por 1 mosaico y convierte los mosaicos debajo de los enemigos en mosaicos amarillos.",
  str_skill_desc_4001751 = "Al lanzar la habilidad, cada vez que el jugador reciba daño en esta ronda, se actualizará 1 mosaico del mismo elemento que el capitán y se restaurará una pequeña cantidad de HP del equipo.",
  str_skill_name_2001921 = "Asalto de espada",
  str_skill_name_2001922 = "Asalto de espada",
  str_skill_name_2001923 = "Asalto de espada",
  str_skill_name_3001920 = "Entrada gloriosa",
  str_skill_name_3301920 = "Entrada gloriosa",
  str_skill_name_3301921 = "Entrada gloriosa",
  str_skill_name_3301922 = "Entrada gloriosa",
  str_skill_name_3301923 = "Entrada gloriosa",
  str_skill_name_3401921 = "Golpe de semental blindado",
  str_skill_desc_2001921 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2001922 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_desc_2001923 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_3001920 = "ofertas <color=#00F6FF>270%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado.",
  str_skill_desc_34019200 = "Causa <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado y genera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>losetas mejoradas</u></color></link> al azar dentro del área de efecto. Los efectos de esta habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>Más de 9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>Más de 19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>Más de 29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_34019201 = "Causa <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado y genera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>losetas mejoradas</u></color></link> al azar dentro del área de efecto. Los efectos de esta habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>Más de 9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>Más de 19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>Más de 29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_34019202 = "Causa <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado y genera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>losetas mejoradas</u></color></link> al azar dentro del área de efecto. Los efectos de esta habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>Más de 9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>Más de 19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>Más de 29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_34019203 = "Causa <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado y genera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>losetas mejoradas</u></color></link> al azar dentro del área de efecto. Los efectos de esta habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>Más de 9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>Más de 19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>Más de 29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_3301920 = "Inflige <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado. Los efectos de la habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>>9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>>19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>>29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_3301921 = "Inflige <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado. Los efectos de la habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>>9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>>19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>>29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_3301922 = "Inflige <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado. Los efectos de la habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>>9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>>19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>>29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_3301923 = "Inflige <color=#00F6FF>270 %</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado. Los efectos de la habilidad se potencian según el número de <color=#00F6FF>Espinas</color>: <color=#00F6FF>>9</color>: Expande el rango de daño a 25 mosaicos en forma de cuadrado. <color=#00F6FF>>19</color>: Enfriamiento de habilidad -1. <color=#00F6FF>>29</color>: inflige un 270 % de daño a todos los enemigos.",
  str_skill_desc_3401921 = "Costos <color=#00F6FF>5</color> Espinas: en esta ronda, los ataques normales se pueden lanzar en diagonal y el daño de ataque normal aumenta en <color=#00F6FF>20%</color> (se puede apilar cuando se usa más de una vez). Este ataque no se considera una habilidad activa.",
  str_skill_passive_name_410192 = "Sello de espinas",
  str_skill_passive_name_416192 = "Sello de espinas",
  str_skill_passive_name_430192 = "Sello de espinas",
  str_skill_passive_name_436192 = "Sello de espinas",
  str_skill_passive_desc_410192 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416192 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>{1}</color>. Ganancias <color=#00F6FF>5</color> Espinas al comienzo de cada ola.",
  str_skill_passive_desc_430192 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_436192 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>{1}</color>. Ganancias <color=#00F6FF>5</color> Espinas al comienzo de cada ola.",
  str_skill_passive_desc_440192 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_446192 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>3%</color>. Ganancias <color=#00F6FF>5</color> Espinas al comienzo de cada ola.",
  str_skill_upgrade_refine_desc_16019211 = "Mejora de habilidades de equipo: cada espina aumenta el daño del combo en cadena en <color=#00F6FF>3%</color>.",
  str_skill_upgrade_refine_desc_16019212 = "Mejora de habilidades de equipo: ganancias <color=#00F6FF>5</color> Espinas al comienzo de la batalla.",
  str_skill_upgrade_refine_desc_16019213 = "Mejora activa de habilidades: genera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> al azar dentro del área de efecto.",
  str_skill_passive_desc_440193 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>3%</color>. Ganancias <color=#00F6FF>5</color> Espinas al comienzo de la batalla.",
  str_skill_passive_desc_446193 = "Ganancias 1 <color=#00F6FF>Espina</color> por cada 1 <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link> obtenidos por el equipo (incluyendo <link=\"30065\"><#FFAE07><u>absorbido</u></color></link> losas). Cada Thorn aumenta el daño de Chain Combo en <color=#00F6FF>3%</color>. Ganancias <color=#00F6FF>5</color> Espinas al comienzo de la batalla y al comienzo de cada ola.",
  str_skill_upgrade_desc_16019213 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16019216 = "Mejora de habilidades de equipo: ganancias <color=#00F6FF>5</color> Espinas al comienzo de cada ola.",
  str_skill_name_5010152 = "Animar",
  str_skill_desc_5010152 = "Shadow Walker se mueve al área con las unidades más amigables y aplica la Marca de fuerza a todos los aliados, otorgando un mayor ATK.",
  str_skill_name_888450061 = "Arrecife Cozen",
  str_skill_desc_888450061 = "Invoca 1 Cozen que ataca a los Aurorianos cada 2 rondas.",
  str_skill_desc_888450081 = "Siphorb absorbe energía de la loseta en la que se encuentra y de las losetas que comparten el mismo elemento dentro de 1 grupo circundante, luego libera un orbe de energía que ataca a todos los enemigos. El daño aumenta con el número de fichas absorbidas. Genera un área peligrosa donde los aurorianos permanecen 2 rondas después de golpear a los aurorianos.",
  str_skill_upgrade_refine_desc_13004611 = "Mejora de habilidades de equipo: <color=#00F6FF>Dobles</color> la bonificación de daño de ataque normal Keating recibe de cada Marca de Risa.",
  str_skill_upgrade_refine_desc_13004613 = "Mejora de habilidades de equipo: cada ataque normal Keating ofertas tiene un <color=#00F6FF>35%</color> posibilidad de infligir 1 marca de risa a los enemigos.",
  str_skill_passive_desc_4400461 = "Matar enemigos con Laughter Mark inflige <color=#00F6FF>1</color> acumulación adicional de Marca de risa para todos los enemigos restantes. Cada marca aumenta el daño de ataque normal de los Thunder Aurorians en <color=#00F6FF>1,8%</color>. el bono Keating recibe es <color=#00F6FF>duplicado</color>.",
  str_skill_desc_340046 = "Reduce el enfriamiento de la habilidad en <color=#00F6FF>2</color> al comienzo de la batalla. Genera un clon en un mosaico seleccionado que atrae a los enemigos dentro de <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color> </link> en enemigos con 5 acumulaciones de Marca durante 2 rondas.",
  str_skill_desc_342046 = "Reduce el enfriamiento de la habilidad en <color=#00F6FF>2</color> al comienzo de la batalla. Genera un clon en un mosaico seleccionado que atrae a los enemigos dentro de <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color> </link> en enemigos con 4 acumulaciones de Marca durante 2 rondas e inflige <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link> en enemigos con 6 acumulaciones de Marca por 1 ronda.",
  str_skill_desc_345046 = "Reduce el enfriamiento de la habilidad en <color=#00F6FF>2</color> al comienzo de la batalla. Genera un clon en un mosaico seleccionado que atrae a <color=#00F6FF>todos</color> los enemigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link > en enemigos con 4 acumulaciones de Marca durante 2 rondas e inflige <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link> en enemigos con 6 acumulaciones de Marca durante 1 ronda .",
  str_skill_passive_desc_4400463 = "Matar enemigos con Marca de risa inflige <color=#00F6FF>+1</color> acumulación adicional a todos los enemigos restantes. Cada marca aumenta el daño de ataque normal de los Thunder Aurorians en un <color=#00F6FF>2%</color>. La bonificación que recibe Keating se <color=#00F6FF>duplica</color>. Cada ataque normal que ofrece Keating tiene un <color=#00F6FF>35%</color> de probabilidad de infligir 1 marca de risa a los enemigos.",
  str_skill_upgrade_refine_desc_16006011 = "Mejora de habilidades de equipo: aumenta el daño de salpicadura de los ataques normales infligidos en el estado del mediodía al <color=#00F6FF>60 %</color>.",
  str_skill_upgrade_refine_desc_16006012 = "Mejora de habilidades de equipo: aumenta el daño de los ataques normales infligidos en el estado del mediodía en un <color=#00F6FF>5 %</color>.",
  str_skill_upgrade_refine_desc_16006013 = "Mejora de Chain Combo: aumenta el alcance del Chain Combo en 1 grupo circundante en el estado Mediodía.",
  str_skill_passive_desc_4400601 = "En el estado Mediodía, los ataques normales infligen un <color=#00F6FF>20 %</color> de daño adicional y un <color=#00F6FF>60 %</color> <link=\"30015\"><#FFAE07><u >Daño de salpicadura</u></color></link> a todos los objetivos en <color=#00F6FF>4 mosaicos en forma de cruz</color> alrededor del enemigo.",
  str_skill_passive_desc_4400602 = "En el estado Mediodía, los ataques normales infligen un <color=#00F6FF>25 %</color> de daño adicional y un <color=#00F6FF>60 %</color> <link=\"30015\"><#FFAE07><u >Daño de salpicadura</u></color></link> a todos los objetivos en <color=#00F6FF>4 mosaicos en forma de cruz</color> alrededor del enemigo.",
  str_skill_desc_243601 = "ofertas <color=#00F6FF>155%</color> daño a 4 enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. Aumenta el alcance en 1 cúmulo circundante en el estado Mediodía.",
  str_skill_desc_243602 = "ofertas <color=#00F6FF>160%</color> daño a 4 enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Aumenta el alcance en 1 cúmulo circundante en el estado Mediodía.",
  str_skill_desc_243603 = "ofertas <color=#00F6FF>175%</color> daño a 4 enemigos dentro <color=#00F6FF>4 grupos circundantes</color>. Aumenta el alcance en 1 cúmulo circundante en el estado Mediodía.",
  str_skill_name_2002001 = "Viene la oscuridad",
  str_skill_name_2002002 = "Viene la oscuridad",
  str_skill_name_2002003 = "Viene la oscuridad",
  str_skill_name_2102001 = "Viene la oscuridad",
  str_skill_name_2102002 = "Viene la oscuridad",
  str_skill_name_2102003 = "Viene la oscuridad",
  str_skill_name_300200 = "Oda a las profundidades",
  str_skill_name_305200 = "Oda a las profundidades",
  str_skill_name_320200 = "Oda a las profundidades",
  str_skill_name_325200 = "Oda a las profundidades",
  str_skill_passive_name_410200 = "Análisis de debilidad",
  str_skill_passive_name_430200 = "Análisis de debilidad",
  str_skill_desc_2002001 = "Inflige un <color=#00F6FF>{1}% </color> de daño a 3 enemigos dentro de <color=#00F6FF> 3 cúmulos circundantes </color>.",
  str_skill_desc_2002002 = "ofertas <color=#00F6FF>{1}%</color> daño a 3 enemigos dentro <color=#00F6FF>4 grupos circundantes</color>.",
  str_skill_desc_2002003 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 3 enemigos más cercanos.",
  str_skill_desc_2102001 = "Inflige un <color=#00F6FF>{1}% </color> de daño a 3 enemigos dentro de <color=#00F6FF> 3 cúmulos circundantes </color>.",
  str_skill_desc_2102002 = "ofertas <color=#00F6FF>{1}%</color> daño a 3 enemigos dentro <color=#00F6FF>4 grupos circundantes</color>.",
  str_skill_desc_2102003 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 3 enemigos más cercanos.",
  str_skill_desc_300200 = "Selecciona hasta 2 enemigos a través de los mosaicos debajo de ellos, repartiendo <color=#00F6FF>{1}%</color> daño a ellos. Todos los enemigos en los mosaicos seleccionados y los mosaicos intermedios son <link=\"30081\"><#FFAE07><u>tirado</u></color></link> al centro de esta zona. Si solo se selecciona un enemigo, solo recibirán daño y no serán atraídos.",
  str_skill_desc_305200 = "Elige hasta 2 enemigos a través de una casilla que ocupan y les inflige <color=#00F6FF>{1}%</color> de daño. Todos los enemigos en los mosaicos seleccionados y los mosaicos intermedios son <link=\"30081\"><#FFAE07><u>atraídos</u></color></link> hacia el centro del área formada. Si solo se selecciona 1 enemigo, solo recibirán daño pero no serán atraídos. El daño final aumenta un <color=#00F6FF>10 %</color> por cada <color=#00F6FF>1</color> mosaico que se detiene a un enemigo.",
  str_skill_desc_320200 = "Elige hasta 2 enemigos a través de una casilla que ocupan y les inflige <color=#00F6FF>{1}%</color> de daño. Todos los enemigos en los mosaicos seleccionados y los mosaicos intermedios son <link=\"30081\"><#FFAE07><u>atraídos</u></color></link> hacia el centro del área formada. Si solo se selecciona 1 enemigo, Anatoli lo sustituirá como segundo objetivo y se reunirá en el centro.",
  str_skill_desc_325200 = "Elige hasta 2 enemigos a través de una casilla que ocupan y les inflige <color=#00F6FF>{1}%</color> de daño. Todos los enemigos en los mosaicos seleccionados y los mosaicos intermedios son <link=\"30081\"><#FFAE07><u>atraídos</u></color></link> hacia el centro del área formada. Si solo se selecciona 1 enemigo, Anatoli lo sustituirá como segundo objetivo y se reunirá en el centro. El daño final aumenta un <color=#00F6FF>10 %</color> por cada <color=#00F6FF>1</color> mosaico que se detiene a un enemigo.",
  str_skill_passive_desc_410200 = "Los combos en cadena de Anatoli ofrecen una ventaja adicional <color=#00F6FF>{1}</color> daño a enemigos aleatorios adyacentes al objetivo.",
  str_skill_passive_desc_430200 = "Los combos en cadena de Anatoli ofrecen un <color=#00F6FF>{1}</color> daño a enemigos aleatorios adyacentes al objetivo. <color=#00F6FF>Único objetivo</color> Combos en cadena de todos los aliados. <color=#00F6FF>7%</color> mayor daño final a <link=\"30082\"><#FFAE07><u>agrupado</u></color></link> enemigos.",
  str_skill_upgrade_desc_15020012 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15020015 = "Mejora activa de habilidades: aumenta el daño final en <color=#00F6FF>10%</color> para cada <color=#00F6FF>1</color> Los enemigos de mosaico son atraídos.",
  str_skill_name_290530101 = "marca de terror",
  str_skill_desc_290530101 = "Inflige daño al objetivo directamente y genera una marca en el mosaico en el que se encuentra el objetivo.",
  str_skill_name_290530102 = "fiebre del terror",
  str_skill_desc_290530102 = "Avanza hasta 2 mosaicos hacia el objetivo, infligiendo daño a los objetivos en el camino y dentro de 4 mosaicos en forma de cruz en el destino. Si Dread Rush no da en el blanco, Helios libera una marca de terror adicional.",
  str_skill_desc_290530312 = "Avanza hasta 2 mosaicos hacia el objetivo, infligiendo daño a los objetivos en el camino y hasta 4 mosaicos en forma de cruz en el destino.",
  str_skill_name_290530103 = "Salto de terror",
  str_skill_desc_290530103 = "Si el objetivo está dentro del alcance, Helios salta junto al objetivo, lo que le inflige un gran daño y lo derriba al aterrizar. Si Leap of Terror falla el objetivo o el objetivo no está dentro del alcance, Helios libera una marca de terror adicional.",
  str_skill_name_290530104 = "Frenesí furioso",
  str_skill_desc_290530104 = "Helios se mueve a las ubicaciones de las marcas de terror según el orden en que se generaron, luego corre cerca del objetivo, infligiendo daño a los objetivos en el camino y dentro de un cierto rango en el destino. Al mismo tiempo, Helios convierte una parte de sus moretones acumulados en HP.",
  str_skill_name_215009011 = "Ataque Normal",
  str_skill_desc_215009011 = "Ataca a los enemigos dentro del alcance una vez después de moverse.",
  str_skill_name_11150713 = "Fuente de peligro",
  str_skill_desc_11150713 = "Regresa al Área Peligrosa, recupera algo de HP y se mejora permanentemente.",
  str_skill_name_290530302 = "fiebre del terror",
  str_skill_desc_290530302 = "Avanza hasta 2 mosaicos hacia el objetivo, infligiendo daño a los objetivos en el camino y hasta 4 mosaicos en forma de cruz en el destino.",
  str_skill_desc_11150313 = "Un cristal de luz misterioso que se puede activar al pasar a través de él, invocando un rayo para atacar a todos los objetivos, incluidos los aurorianos.",
  str_skill_name_290500102 = "Presa",
  str_skill_name_290500112 = "Presa: Engendro",
  str_skill_name_290500103 = "Caza",
  str_skill_name_290500113 = "Caza+",
  str_skill_name_290500104 = "Reunión",
  str_skill_name_290500114 = "Rally+",
  str_skill_desc_290500102 = "La Reina Araña se abalanza sobre su presa, tiende una telaraña para bloquear mosaicos y daña a los aurorianos.",
  str_skill_desc_290500112 = "La Reina Araña se abalanza sobre su presa, tejiendo una telaraña para bloquear fichas y dañar a los aurorianos mientras convoca a las crías al campo de batalla.",
  str_skill_desc_290500103 = "La Reina Araña tiende una telaraña para bloquear los mosaicos alrededor de los Aurorianos, luego convoca a sus crías para que se abalancen sobre ellos y causen daño.",
  str_skill_desc_290500113 = "La Reina Araña teje una telaraña para bloquear las casillas alrededor de los Aurorianos, luego convoca a sus crías para que se abalancen sobre ellos y les hagan daño. Las fichas bloqueadas vuelven a su estado original después de 1 ronda.",
  str_skill_desc_290500104 = "La Reina Araña convoca a sus crías para atacar. Colocarán telas de araña y bloquearán una gran cantidad de fichas.",
  str_skill_desc_290500114 = "La Reina Araña convoca a sus crías para tejer telas de araña, bloqueando una gran cantidad de fichas. Las fichas bloqueadas vuelven a su estado original después de 1 ronda.",
  str_skill_name_200240102 = "Patrulla",
  str_skill_name_200240103 = "Presa",
  str_skill_name_200240104 = "Reunión",
  str_skill_desc_200240102 = "Las crías de araña patrullan su territorio y atacan a cualquier enemigo que detecten.",
  str_skill_desc_200240103 = "Las crías de araña se abalanzan sobre sus presas e intentan matarlas de un solo golpe.",
  str_skill_desc_200240104 = "Al recibir la convocatoria de Spider Queen, Spider Hatchlings se une para un ataque conjunto.",
  str_skill_name_290530204 = "Frenesí furioso",
  str_skill_desc_290530204 = "Helios se mueve a las ubicaciones de las marcas de terror según el orden en que se generaron, luego corre cerca del objetivo, infligiendo daño a los objetivos en el camino y dentro de un cierto rango en el destino. Al mismo tiempo, Helios elimina todas las Marcas de terror en el campo de batalla y convierte una parte de sus Contusiones acumuladas en HP según la cantidad de Marcas de terror eliminadas.",
  str_skill_name_290530404 = "Frenesí furioso",
  str_skill_desc_290530404 = "Helios se mueve a las ubicaciones de las marcas de terror según el orden en que se generaron, luego corre cerca del objetivo, infligiendo daño a los objetivos en el camino y dentro de un cierto rango en el destino. Al mismo tiempo, Helios convierte una parte de sus moretones acumulados en HP.",
  str_skill_upgrade_desc_16020113 = "Mejora activa de habilidades: cambios <color=#FFFF00>la invocacion</color> a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate.",
