  str_skill_upgrade_refine_desc_16020111 = "Mejora de habilidades de equipo: cuando está equipado con un escudo, aumenta la bonificación de daño básico a <color=#FFFF00>15%</color>.",
  str_skill_upgrade_refine_desc_16020112 = "Mejora de habilidad activa: aumenta el escudo obtenido de <color=#FFFF00>la invocacion</color> a <color=#FFFF00>90%</color> de HP.",
