  str_skill_desc_2002021 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_desc_2002022 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>24 fichas en forma radial</color>.",
  str_skill_desc_2002023 = "ofertas <color=#00F6FF>{1}%</color> daño en un <color=#00F6FF>forma radial al rango máximo</color> y genera 1 Hoja de Dawn en cualquiera de las fichas transitables más lejanas. Se activa hasta 1 vez por ronda.\n\n",
  str_skill_desc_3002021 = "Al comienzo de la batalla, reduce el enfriamiento de la habilidad en <color=#00F6FF>3</color>. Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>500%</color> daño. Entonces, genera Blade of Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3032021 = "Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>500%</color> daño. Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3202021 = "Al comienzo de la batalla, reduce el enfriamiento de la habilidad en <color=#00F6FF>3</color>. Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>500%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> del objetivo <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3232021 = "Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>500%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> de ellos <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3402021 = "Al comienzo de la batalla, reduce el enfriamiento de la habilidad en <color=#00F6FF>3</color>. Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>500%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> del objetivo <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido o recuperado reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3432021 = "Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>500%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> de ellos <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido o recuperado reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3402022 = "Al comienzo de la batalla, reduce el enfriamiento de la habilidad en <color=#00F6FF>3</color>. Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>650%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> del objetivo <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido o recuperado reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3432022 = "Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>650%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> de ellos <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. cada hoja de Dawn recogido o recuperado reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3402023 = "Al comienzo de la batalla, reduce el enfriamiento de la habilidad en <color=#00F6FF>3</color>. Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>650%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> del objetivo <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. Al matar al objetivo, genera 1 Blade of Dawn en la ubicación del objetivo. cada hoja de Dawn recogido o recuperado reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3432023 = "Selecciona 1 mosaico dentro <color=#00F6FF>3 grupos circundantes</color> donde un enemigo está parado y trata <color=#00F6FF>650%</color> daño, más el daño adicional que es <color=#00F6FF>4%</color> de ellos <color=#00F6FF>máximo</color> HP (afectado por contadores de elementos). Luego, genera una Hoja de Dawn en <color=#00F6FF>3</color> mosaicos transitables aleatorios dentro de 2 grupos circundantes del mosaico seleccionado. Al matar al objetivo, genera 1 Blade of Dawn en la ubicación del objetivo. cada hoja de Dawn recogido o recuperado reduce el tiempo de reutilización de la habilidad en <color=#00F6FF>1</color>.",
  str_skill_desc_3302022 = "Selecciona cualquiera <color=#00F6FF>1</color> hoja de Dawn y lo recupera.",
  str_skill_desc_3362022 = "Selecciona cualquiera <color=#00F6FF>1</color> Hoja de Dawn y lo recupera.",
  str_skill_passive_name_410202 = "Donde brilla la luz",
  str_skill_passive_name_420202 = "Donde brilla la luz",
  str_skill_passive_name_430202 = "Donde brilla la luz",
  str_skill_passive_desc_410202 = "Por cada hoja de Dawn recuperado, acumula 1 pila de Oda a la noche efímera. El siguiente Ataque Normal consume 1 acumulación de Oda a la Noche Efímera e inflige daño adicional al objetivo igual a <color=#00F6FF>{1}</color> de ellos <color=#00F6FF>actual</color> HP (el daño adicional no será inferior a <color=#00F6FF>{2}</color> y no mas que <color=#00F6FF>{3}</color> de ATK básico).",
  str_skill_passive_desc_420202 = "Por cada hoja de Dawn recuperado, acumula 1 pila de Oda a la noche efímera. El siguiente Ataque Normal consume 1 acumulación de Oda a la Noche Efímera e inflige daño adicional al objetivo igual a <color=#00F6FF>{1}</color> de ellos <color=#00F6FF>actual</color> HP (el daño adicional no será inferior a <color=#00F6FF>{2}</color> y no mas que <color=#00F6FF>{3}</color> de ATK básico).",
  str_skill_passive_desc_430202 = "Por cada hoja de Dawn recogido o recuperado, acumula 1 pila de Oda a la noche efímera. El siguiente Ataque Normal consume 1 acumulación de Oda a la Noche Efímera e inflige daño adicional al objetivo igual a <color=#00F6FF>{1}</color> de ellos <color=#00F6FF>actual</color> HP (el daño adicional no será inferior a <color=#00F6FF>{2}</color> y no mas que <color=#00F6FF>{3}</color> de ATK básico).",
  str_skill_passive_desc_440202 = "Por cada Hoja de Dawn recuperado, acumula 1 pila de Oda a la noche efímera. El siguiente Ataque Normal consume 1 acumulación de Oda a la Noche Efímera e inflige daño adicional al objetivo igual a <color=#00F6FF>4%</color> del <color=#00F6FF>actual</color> HP (el daño adicional no será inferior a <color=#00F6FF>150%</color> y no mas que <color=#00F6FF>600%</color> de ATK básico).",
  str_skill_upgrade_desc_16020213 = "Mejora activa de habilidades: cambios <color=#FFFF00>dias sin fin</color> a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16020216 = "Mejora activa de habilidades: reduce el enfriamiento de habilidades de <color=#FFFF00>Oscuridad destrozada</color> por <color=#FFFF00>1</color> ronda (válido para Ascensión III).",
  str_skill_upgrade_refine_desc_16020211 = "Mejora de habilidades de equipo: aumenta el límite de daño adicional hasta <color=#00F6FF>600%</color> de ATK.",
  str_skill_upgrade_refine_desc_16020212 = "Mejora activa de habilidades: aumenta el daño a <color=#00F6FF>650%</color>.",
  str_skill_upgrade_refine_desc_16020213 = "Mejora de habilidad activa: al matar a un objetivo, genera 1 Blade of Dawn en la ubicación del objetivo.",
  str_skill_upgrade_refine_desc_15007811 = "Mejora de habilidades de equipo: por cada 1 mosaico verde a los pies del enemigo, la bonificación de daño aumenta en <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15007812 = "Mejora de habilidad activa: inflige el doble de daño al mosaico en el centro del rango de la habilidad.",
  str_skill_upgrade_refine_desc_15007813 = "Mejora de habilidad activa: si la habilidad activa estaba lista en la última ronda, el rango de selección se vuelve <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_passive_desc_4400781 = "Aumenta el daño de Robyn contra los enemigos que ocupan una casilla verde en <color=#00F6FF>10%</color>. Por cada loseta verde a los pies del enemigo, la bonificación de daño aumenta en <color=#00F6FF>1%</color>. También otorga a los compañeros de equipo de Forest Aurorian <color=#00F6FF>50%</color> de este bono.",
  str_skill_name_3400782 = "Aliento deslizante",
  str_skill_name_3420782 = "Aliento deslizante",
  str_skill_name_3400783 = "Aliento deslizante",
  str_skill_name_3420783 = "Aliento deslizante",
  str_skill_desc_3400782 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la casilla central seleccionada se duplica.",
  str_skill_desc_3420782 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la ficha seleccionada se duplica. Convierte hasta 1 mosaico debajo del enemigo en un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link>.",
  str_skill_desc_3400783 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la casilla central seleccionada se duplica. Si esta habilidad activa estaba lista en la última ronda, el rango de selección se vuelve <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_3420783 = "ofertas <color=#00F6FF>250%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color> centrado en 1 mosaico seleccionado. El daño infligido a la ficha seleccionada se duplica. Convierte hasta 1 mosaico debajo del enemigo en un <link=\"20001\"><#FFAE07><u>azulejo mejorado</u></color></link>. Si esta habilidad activa estaba lista en la última ronda, el rango de selección se vuelve <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_upgrade_refine_desc_15007511 = "Mejora de habilidades de equipo: la posibilidad de que los ataques normales inflijan veneno aumenta a <color=#00F6FF>80%</color>.",
  str_skill_upgrade_refine_desc_15007512 = "Mejora de habilidad activa: el factor de daño de habilidad activa aumenta a <color=#00F6FF>500%</color>.",
  str_skill_upgrade_refine_desc_15007513 = "Mejora activa de habilidades: el tiempo de reutilización de habilidades se reduce en <color=#00F6FF>2</color> al comienzo de cada batalla.",
