  str_skill_desc_342075 = "Inflige un 500% de daño a los enemigos dentro <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> para 2 rondas y 2 pilas de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas.",
  str_skill_desc_345075 = "Inflige 500% de daño a <color=#00F6FF>todo</color> enemigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> para 2 rondas y 2 pilas de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas.",
  str_skill_desc_350075 = "Inflige un 500% de daño a los enemigos dentro <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> para 2 rondas y 2 pilas de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas. Enfriamiento de habilidad <color=#00F6FF>-2</color> rondas al comienzo de la batalla.",
  str_skill_desc_352075 = "Inflige un 500% de daño a los enemigos dentro <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> para 2 rondas y 2 pilas de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas. Enfriamiento de habilidad <color=#00F6FF>-2</color> rondas al comienzo de la batalla.",
  str_skill_desc_355075 = "Inflige 500% de daño a <color=#00F6FF>todo</color> enemigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> para 2 rondas y 2 pilas de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rondas. Enfriamiento de habilidad <color=#00F6FF>-2</color> rondas al comienzo de la batalla.",
