  str_skill_desc_2202043 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 objetivos más cercanos. Si solo hay 1 objetivo, el daño se incrementará en un <color=#00F6FF>50%</color>.",
  str_skill_desc_2302041 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 objetivos más cercanos. Inflige un <color=#00F6FF>30%</color> más de daño a los objetivos dentro de 3 grupos cercanos. Si solo hay 1 objetivo, el daño se incrementará en un <color=#00F6FF>50%</color>.",
  str_skill_desc_2302042 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 objetivos más cercanos. Inflige un <color=#00F6FF>30%</color> más de daño a los objetivos dentro de 3 grupos cercanos. Si solo hay 1 objetivo, el daño se incrementará en un <color=#00F6FF>50%</color>.",
  str_skill_desc_2302043 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 objetivos más cercanos. Inflige un <color=#00F6FF>30%</color> más de daño a los objetivos dentro de 3 grupos cercanos. Si solo hay 1 objetivo, el daño se incrementará en un <color=#00F6FF>50%</color>.",
  str_skill_desc_2502041 = "ofertas <color=#00F6FF>140%</color> daño a los 2 objetivos más cercanos. Inflige <color=#00F6FF>30%</color> más daño a los objetivos dentro de los 3 grupos circundantes. Si solo hay 1 objetivo, el daño se incrementará en <color=#00F6FF>sesenta y cinco%</color>.",
  str_skill_desc_2502042 = "ofertas <color=#00F6FF>155%</color> daño a los 2 objetivos más cercanos. Inflige <color=#00F6FF>30%</color> más daño a los objetivos dentro de los 3 grupos circundantes. Si solo hay 1 objetivo, el daño se incrementará en <color=#00F6FF>sesenta y cinco%</color>.",
  str_skill_desc_2502043 = "ofertas <color=#00F6FF>170%</color> daño a los 2 objetivos más cercanos. Inflige <color=#00F6FF>30%</color> más daño a los objetivos dentro de los 3 grupos circundantes. Si solo hay 1 objetivo, el daño se incrementará en <color=#00F6FF>sesenta y cinco%</color>.",
  str_skill_desc_3002041 = "Selecciona un objetivo, infligiendo la <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link> y Sabiduría igual al <color=#00F6FF>200% del ATQ de Joshua</color>. También inflige <color=#00F6FF>200%</color> de daño ignorando la DEF a objetivos que no tienen PS Máx. Seleccionar el mismo objetivo de nuevo aumentará aún más su Sabiduría. Cuando la Sabiduría del objetivo exceda sus PS actuales, recibirán daño de corte que ignora el escudo (la invencibilidad sigue teniendo efecto).",
  str_skill_desc_3032041 = "Selecciona un objetivo, infligiendo la <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link> y Sabiduría igual al <color=#00F6FF>250% del ATQ de Joshua</color>. También inflige <color=#00F6FF>250%</color> de daño ignorando DEF a objetivos que no tienen PS Máx. Seleccionar el mismo objetivo de nuevo aumentará aún más su Sabiduría. Cuando la Sabiduría del objetivo exceda su PS actual, recibirán daño de corte que ignora el Escudo (la invencibilidad sigue teniendo efecto).",
  str_skill_desc_3062041 = "Selecciona un objetivo, infligiendo la <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link> y Sabiduría igual a <color=#00F6FF>250% del ATQ de Joshua + 3% del HP Máx del objetivo</color> (no menos de <color=#00F6FF>120%</color> del ATQ de Joshua). También inflige <color=#00F6FF>370%</color> de daño ignorando la DEF a objetivos que no tienen HP Máx. Seleccionar el mismo objetivo de nuevo aumentará aún más su Sabiduría. Cuando la Sabiduría del objetivo exceda su HP actual, recibirán daño de corte que ignora el escudo (la invulnerabilidad sigue teniendo efecto).",
  str_skill_passive_desc_4102041 = "Joshua inflige <color=#00F6FF>{1}</color> de daño a los enemigos en el estado <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link>, ignora todos los escudos y convierte todo el daño infligido en puntos de Sabiduría.",
  str_skill_upgrade_refine_desc_16020411 = "Mejora de habilidades de equipo: aumenta todo el daño infligido a los objetivos en el estado de Sabiduría sagrada a <color=#00F6FF>124%</color>.",
  str_skill_upgrade_refine_desc_16020412 = "Mejora de combo en cadena: cuando solo hay 1 objetivo, aumenta el daño en <color=#00F6FF>sesenta y cinco%</color>.",
  str_skill_upgrade_refine_desc_16020413 = "Mejora de habilidad activa: refresca inmediatamente el tiempo de reutilización de la habilidad tras la muerte de un objetivo en el estado de Sabiduría sagrada.",
  str_skill_desc_3502041 = "Selecciona un objetivo, infligiendo la <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link> y Sabiduría igual a <color=#00F6FF>200% del ATQ de Joshua</color>. También inflige <color=#00F6FF>200%</color> de daño ignorando DEF a objetivos que no tienen PS Máx. Seleccionar el mismo objetivo de nuevo aumentará su Sabiduría. Cuando la Sabiduría del objetivo exceda su PS actual, recibirán daño de corte que ignora el escudo (la invencibilidad sigue teniendo efecto). Refresca inmediatamente el tiempo de reutilización de la Habilidad Activa al morir un objetivo en estado de Sabiduría Sagrada.",
  str_skill_desc_3532041 = "Selecciona un objetivo, infligiendo la <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link> y Sabiduría igual a <color=#00F6FF>250% del ATQ de Joshua</color>. También inflige <color=#00F6FF>250%</color> de daño ignorando DEF a objetivos que no tienen HP Máx. Seleccionar el mismo objetivo de nuevo aumentará su Sabiduría. Cuando la Sabiduría del objetivo exceda su HP actual, recibirán daño de corte que ignora el Escudo (la invencibilidad sigue teniendo efecto). Refresca inmediatamente el tiempo de reutilización de la Habilidad Activa al morir un objetivo en estado de Sabiduría Sagrada.",
  str_skill_desc_3562041 = "Selecciona un objetivo, infligiendo la <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link> y Sabiduría igual a <color=#00F6FF>250% del ATQ de Joshua + 3% del HP Máx del objetivo</color> (no menos de <color=#00F6FF>120%</color> del ATQ de Joshua). También inflige <color=#00F6FF>370%</color> de daño ignorando DEF a objetivos que no tienen HP Máx. Seleccionar el mismo objetivo de nuevo aumentará aún más su Sabiduría. Cuando la Sabiduría del objetivo exceda su HP actual, recibirán daño de corte que ignora el Escudo (la invencibilidad sigue teniendo efecto). Refresca inmediatamente el tiempo de reutilización de la Habilidad Activa al morir un objetivo en estado de Sabiduría Sagrada.",
  str_skill_passive_desc_4502041 = "Joshua inflige <color=#00F6FF>124%</color> de daño a enemigos bajo el estado de <link=\"30083\"><#FFAE07><u>Sabiduría Sagrada</u></color></link>, ignora todos los escudos y convierte todo el daño infligido en puntos de Sabiduría.",
