  str_skill_desc_2362052 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>16 fichas en forma radial</color>. Duración de las fichas rotas dentro del rango <color=#00F6FF>-3</color>.",
  str_skill_desc_2362053 = "ofertas <color=#00F6FF>{1}%</color> daño a <color=#00F6FF>24 fichas en forma radial</color>. Duración de las fichas rotas dentro del rango <color=#00F6FF>-4</color>.",
  str_skill_desc_3002051 = "Selecciona cualquier casilla no rota y la convierte en una casilla rota que dura 9 rondas, luego convierte <color=#00F6FF>4 casillas en forma de cruz</color> en casillas Azules.",
  str_skill_desc_3052051 = "Selecciona cualquier casilla no rota y la convierte en una casilla rota que dura 9 rondas, luego convierte <color=#00F6FF>4 casillas en forma de cruz</color> en casillas Azules.",
  str_skill_passive_name_410205 = "Saludo agradable",
  str_skill_passive_name_430205 = "Saludo agradable",
  str_skill_passive_desc_410205 = "Blanc: Pura Cordis no realiza ataques normales cuando está en una casilla azul. Cada vez que pasa por 1 casilla azul, obtiene 1 acumulación de Hospitalidad si hay enemigos dentro de <color=#00F6FF>4 casillas en forma de cruz</color>. Cada acumulación de Hospitalidad aumenta la tasa de daño del Combo en cadena en <color=#00F6FF>{1}</color> y disminuye la condición de activación del Combo en cadena en <color=#00F6FF>1</color>. Todas las acumulaciones se eliminan después de que ella usa un Combo en cadena.",
  str_skill_passive_desc_430205 = "Blanc: Pura Cordis no realiza ataques normales cuando está en una casilla azul. Cada vez que pasa por 1 casilla azul, gana 1 acumulación de Hospitalidad si hay enemigos o casillas rotas dentro de <color=#00F6FF>4 casillas en forma de cruz</color>. Cada acumulación de Hospitalidad aumenta la tasa de daño del Combo en cadena en <color=#00F6FF>{1}</color> y disminuye la condición de activación del Combo en cadena en <color=#00F6FF>1</color>. Todas las acumulaciones se eliminan después de que ella usa un Combo en cadena.",
  str_skill_upgrade_desc_15020512 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15020515 = "Mejora de Chain Combo: la duración de las fichas rotas dentro del rango de Chain Combo se reduce en <color=#FFFF00>2/3/4</color> rondas (válido para Ascensión II).",
  str_skill_passive_desc_440097 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>60%</color> del daño base de cada golpe. Cada ataque tiene un <color=#00F6FF>20%</color> oportunidad de tratar <color=#00F6FF>50%</color> daño adicional. Cada combo aumenta la probabilidad de activación en <color=#00F6FF>1%</color>, hasta 50%.",
  str_skill_name_3400971 = "Frigid Debone Variante I",
  str_skill_name_3400972 = "Frigid Debone Variante II",
  str_skill_name_3420971 = "Frigid Debone Variante I",
  str_skill_name_3420972 = "Frigid Debone Variante II",
  str_skill_desc_3400971 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Se teletransporta a cualquier ubicación e inflige daño a los enemigos en forma de rectángulo entre el punto de partida y el de destino. Cuanto menor sea el área, mayor será el daño infligido, hasta <color=#00F6FF>600%</color> daño.",
  str_skill_desc_3400972 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Se teletransporta a cualquier lugar dentro <color=#FFFF00>3 grupos circundantes</color> y hace daño a los enemigos en forma de rectángulo entre el punto de partida y el destino. Cuanto menor sea el área, mayor será el daño infligido, hasta <color=#00F6FF>360%</color> daño.",
  str_skill_desc_3420971 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Se teletransporta a cualquier ubicación e inflige daño a los enemigos en forma de rectángulo entre el punto de partida y el de destino. Cuanto menor sea el área, mayor será el daño infligido, hasta <color=#00F6FF>720%</color> daño.",
  str_skill_desc_3420972 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Se teletransporta a cualquier lugar dentro <color=#FFFF00>3 grupos circundantes</color> y hace daño a los enemigos en forma de rectángulo entre el punto de partida y el destino. Cuanto menor sea el área, mayor será el daño infligido, hasta <color=#00F6FF>480%</color> daño.",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Se teletransporta a cualquier ubicación e inflige daño a los enemigos en forma de rectángulo entre el punto de partida y el de destino. Cuanto menor sea el área, mayor será el daño infligido. El daño de la habilidad activa aumenta en <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_15009712 = "Mejora de habilidades de equipo: cada combo aumenta la posibilidad de desencadenar daño adicional en <color=#00F6FF>1%</color>, hasta 50%.",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Se teletransporta a cualquier lugar dentro <color=#FFFF00>3 grupos circundantes</color> y hace daño a los enemigos en forma de rectángulo entre el punto de partida y el destino. Cuanto menor sea el área, mayor será el daño infligido. El daño de la habilidad activa se reduce en <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_16002711 = "Mejora de habilidad activa: el factor de daño de habilidad activa aumenta a <color=#00F6FF>360%</color>.",
  str_skill_upgrade_refine_desc_16002712 = "Mejora de habilidades de equipo: ganancias <color=#00F6FF>2</color> acumulaciones de Silent Thunder Mark al lanzar Active Skill.",
  str_skill_upgrade_refine_desc_16002713 = "Mejora de habilidades de equipo: los ataques normales consumen 1 acumulación de Marca de trueno silencioso para infligir un daño adicional igual a <color=#00F6FF>2,5%</color> de HP actual a los enemigos. Este daño no será inferior a <color=#00F6FF>50%</color> del ATK de Michael.",
  str_skill_desc_3400271 = "Corre a la ubicación seleccionada, repartiendo <color=#00F6FF>360%</color> daño y daño adicional igual a <color=#00F6FF>5%</color> de su HP actual a los enemigos en el camino y en las casillas adyacentes.",
  str_skill_desc_3430271 = "Corre a la ubicación seleccionada, repartiendo <color=#00F6FF>360%</color> daño y daño extra igual a <color=#00F6FF>5%</color> de su HP actual a los enemigos en el camino y en los mosaicos adyacentes, y luego lanza instantáneamente un Chain Combo una vez en la ubicación seleccionada correspondiente a la distancia recorrida.",
  str_skill_desc_3400272 = "Corre a la ubicación seleccionada, repartiendo <color=#00F6FF>360%</color> daño y daño adicional igual a <color=#00F6FF>5%</color> de su HP actual a los enemigos en el camino y en las casillas adyacentes.",
  str_skill_desc_3430272 = "Corre a la ubicación seleccionada, repartiendo <color=#00F6FF>360%</color> daño y daño extra igual a <color=#00F6FF>5%</color> de su HP actual a los enemigos en el camino y en los mosaicos adyacentes, y luego lanza instantáneamente un Chain Combo una vez en la ubicación seleccionada correspondiente a la distancia recorrida.",
  str_skill_desc_4400271 = "Otorga 1 acumulación de Silent Thunder Mark al comienzo de cada ronda y cuando se usa un combo en cadena, y 2 acumulaciones de Silent Thunder Mark cuando se usa una habilidad activa. Los ataques normales consumen 1 acumulación de Silent Thunder Mark para infligir daño adicional igual a <color=#00F6FF>2,5%</color> de HP actual al enemigo.",
  str_skill_desc_440027 = "Otorga 1 acumulación de Silent Thunder Mark al comienzo de cada ronda y cuando se usa un combo en cadena, y 2 acumulaciones de Silent Thunder Mark cuando se usa una habilidad activa. Los ataques normales consumen 1 acumulación de Silent Thunder Mark para infligir daño adicional igual a <color=#00F6FF>2,5%</color> de HP actual al enemigo. Este daño no será inferior a <color=#00F6FF>50%</color> del ATK de Michael.",
  str_skill_name_490250101 = "Renegados: fantasma de la restauración",
  str_skill_desc_490250101 = "Abandonado: Minos absorbe las casillas mejoradas y debilitadas dentro de 2 grupos cercanos, luego inflige daño a los objetivos dentro de 1 grupo cercano. El daño de este ataque se mejora según la cantidad de casillas absorbidas.",
  str_skill_name_490250102 = "Renegados: final de inmolación",
  str_skill_desc_490250102 = "Abandonado: Minos absorbe todas las casillas mejoradas y debilitadas en el tablero, luego inflige daño a los Aurorians. Minos inflige daño 1 vez adicional por cada casilla absorbida.",
  str_skill_name_490250103 = "Renegados: Restauración Fantasma+",
  str_skill_desc_490250103 = "Abandonado: Minos absorbe las casillas mejoradas y debilitadas dentro de 2 grupos cercanos, luego inflige daño a los objetivos dentro de 1 grupo cercano. El daño de este ataque se mejora según la cantidad de casillas absorbidas.",
  str_skill_name_490250104 = "Renegados: Immolation Finale+",
  str_skill_desc_490250104 = "Abandonado: Minos absorbe todas las casillas mejoradas y debilitadas en el tablero, luego inflige daño a los Aurorians. Minos inflige daño 1 vez adicional por cada casilla absorbida.",
  str_skill_upgrade_refine_desc_16002811 = "Mejora de la habilidad del equipo: aumenta el factor de recuperación a <color=#00F6FF>1,8%</color>.",
  str_skill_upgrade_refine_desc_16002812 = "Mejora activa de habilidades: aumenta el factor de recuperación a <color=#00F6FF>250%</color>.",
  str_skill_upgrade_refine_desc_16002813 = "Mejora activa de habilidades: cuanto menor sea el HP del equipo, mayor será la efectividad de curación, hasta un adicional <color=#00F6FF>100% de bonificación</color>.",
  str_skill_passive_desc_450028 = "Cada mosaico azul generado en el mapa recupera el HP del equipo por <color=#00F6FF>1,8%</color> del HP de Rafael. Cuanto menor sea el HP del equipo, mayor será la efectividad de curación, hasta un adicional <color=#00F6FF>100% de bonificación</color>.",
  str_skill_desc_350028 = "Recupera el HP del equipo por <color=#00F6FF>250%</color> del ATK de Rafael. Restablecimientos <color=#00F6FF>todo lo que no sea azul</color> losas.",
  str_skill_desc_356028 = "Recupera el HP del equipo por <color=#00F6FF>250%</color> del ATK de Rafael. Restablecimientos <color=#00F6FF>todo lo que no sea azul</color> azulejos, y tiene un <color=#00F6FF>pequeña oportunidad</color> para generar mosaicos azules.",
  str_skill_desc_360028 = "Recupera el HP del equipo por <color=#00F6FF>250%</color> del ATK de Rafael. Restablecimientos <color=#00F6FF>todo lo que no sea azul</color> losas. Cuanto menor sea el HP del equipo, mayor será la efectividad de curación, hasta un adicional <color=#00F6FF>100% de bonificación</color>.",
  str_skill_desc_366028 = "Recupera el HP del equipo por <color=#00F6FF>250%</color> del ATK de Rafael. Restablecimientos <color=#00F6FF>todo lo que no sea azul</color> azulejos, con <color=#00F6FF>pequeña oportunidad</color> para generar mosaicos azules. Cuanto menor sea el HP del equipo, mayor será la efectividad de curación, hasta un adicional <color=#00F6FF>100% de bonificación</color>.",
  str_skill_upgrade_refine_desc_15007011 = "Mejora activa de habilidades: aumenta el factor de daño para <color=#00F6FF>100%</color>.",
  str_skill_upgrade_refine_desc_15007012 = "Mejora de habilidades de equipo: aumenta el factor de daño a <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_15007013 = "Mejora activa de habilidades: al infligir daño, hay un <color=#00F6FF>25%</color> posibilidad de infligir 1 pila de <link=\"10002\"><#FFAE07><u>Quemar</u></color></link>.",
  str_skill_desc_350070 = "ofertas <color=#00F6FF>100%</color> daño <color=#00F6FF>5</color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada ficha roja dentro <color=#00F6FF>1 grupo circundante</color> de la unidad",
  str_skill_desc_355070 = "ofertas <color=#00F6FF>100%</color> daño <color=#00F6FF>6</color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada ficha roja dentro <color=#00F6FF>12 fichas adyacentes</color>.",
  str_skill_desc_360070 = "ofertas <color=#00F6FF>100%</color> daño <color=#00F6FF>5</color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada ficha roja dentro <color=#00F6FF>1 grupo circundante</color> de la unidad Al infligir daño, hay un <color=#00F6FF>25%</color> posibilidad de infligir 1 pila de <link=\"10002\"><#FFAE07><u>Quemar</u></color></link>.",
  str_skill_desc_365070 = "ofertas <color=#00F6FF>100%</color> daño <color=#00F6FF>6</color> veces a enemigos aleatorios en el campo. Lanza 1 ataque adicional por cada ficha roja dentro <color=#00F6FF>12 fichas adyacentes</color>. Al infligir daño, hay un <color=#00F6FF>25%</color> posibilidad de infligir 1 pila de <link=\"10002\"><#FFAE07><u>Quemar</u></color></link>.",
  str_skill_passive_desc_450070 = "Los ataques normales tienen un <color=#00F6FF>75%</color> probabilidad de desencadenar 1 Ataque de dragón rojo que inflige daño igual a <color=#00F6FF>60%</color> del daño de ataque normal de Leona e inflige 1 acumulación de <link=\"10002\"><#FFAE07><u>Quemar</u></color></link> por 2 rondas.",
  str_skill_desc_400140110 = "Cuando los aurorianos comienzan a moverse, Tentaclaw se acurruca para evitar ataques y restaura HP para Mirren Gautier.",
  str_skill_upgrade_desc_16020713 = "Mejora de habilidad de equipamiento: Reduce la cantidad de acumulaciones de Ondulación necesarias para activar el efecto a 5. Reduce la cantidad de acumulaciones de Ondulación consumidas a un múltiplo de 5 acumulaciones en su lugar. (Válido para Ascensión I)",
  str_skill_upgrade_desc_16020716 = "Mejora activa de habilidades: Convierte la casilla seleccionada en azul.",
  str_skill_name_2002071 = "Agridulce",
  str_skill_name_2002072 = "Agridulce",
  str_skill_name_2002073 = "Agridulce",
  str_skill_desc_2002071 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_2002072 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2002073 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_name_3002071 = "Danza de Sueños Despiertos",
  str_skill_name_3062071 = "Danza de Sueños Despiertos",
  str_skill_name_3202071 = "Danza de Sueños Despiertos",
  str_skill_name_3262071 = "Danza de Sueños Despiertos",
  str_skill_name_3302071 = "Danza de Sueños Despiertos",
  str_skill_name_3362071 = "Danza de Sueños Despiertos",
  str_skill_desc_3002071 = "Selecciona 1 casilla y hace que todas las casillas azules en la misma columna <link=\"30084\"><#FFAE07><u>converjan</u></color></link> hacia la casilla seleccionada.",
  str_skill_desc_3062071 = "Selecciona 1 casilla y convierte esta casilla en azul, luego hace que todas las casillas azules en la misma columna <link=\"30084\"><#FFAE07><u>converjan</u></color></link> hacia la casilla seleccionada.",
  str_skill_desc_3202071 = "Selecciona 1 casilla y hace que todas las casillas azules en la misma columna <link=\"30084\"><#FFAE07><u>converjan</u></color></link> hacia la casilla seleccionada. Al tocarlo de nuevo, el efecto alternará entre <color=#00F6FF>fila/columna</color>.",
  str_skill_desc_3262071 = "Selecciona 1 casilla y convierte esta casilla en azul, luego hace que todas las casillas azules en la misma columna <link=\"30084\"><#FFAE07><u>converjan</u></color></link> hacia la casilla seleccionada. Al tocarlo de nuevo, el efecto alternará entre <color=#00F6FF>fila/columna</color>.",
  str_skill_desc_3302071 = "Selecciona 1 casilla y hace que todas las casillas azules en la misma columna <link=\"30084\"><#FFAE07><u>converjan</u></color></link> hacia la casilla seleccionada. Al tocarlo de nuevo, el efecto alternará entre <color=#00F6FF>fila/columna</color>. Gana 1 pila de Onda por cada 1 casilla azul dentro del alcance de la Habilidad Activa.",
  str_skill_desc_3362071 = "Selecciona 1 casilla y convierte esta casilla en azul, luego hace que todas las casillas azules en la misma columna <link=\"30084\"><#FFAE07><u>converjan</u></color></link> hacia la casilla seleccionada. Al tocarlo de nuevo, el efecto alternará entre <color=#00F6FF>fila/columna</color>. Obtiene 1 pila de Onda por cada 1 casilla azul dentro del alcance de la Habilidad Activa.",
  str_skill_passive_name_410207 = "Desde Dawn Hasta el Anochecer",
  str_skill_passive_desc_410207 = "Cena gana 1 acumulación de <link=\"30085\"><#FFAE07><u>Ripple</u></color></link> cuando los aurorianos del equipo lanzan una habilidad activa por primera vez en la ronda. Si Cena ya tiene 7 o más acumulaciones de Ripple cuando obtiene una acumulación, se consumen para recuperar HP igual a <color=#00F6FF>{1}</color> del Max HP de Cena.",
  str_skill_passive_name_416207 = "Desde Dawn Hasta el Anochecer",
  str_skill_passive_desc_416207 = "Cena gana 1 acumulación de <link=\"30086\"><#FFAE07><u>Onda</u></color></link> cuando los Aurorians del equipo usan una Habilidad Activa por primera vez en la ronda. Si Cena ya tiene 5 o más acumulaciones de Onda al ganar una acumulación, se consume una parte para recuperar PS igual a <color=#00F6FF>{1}</color> del PS Máx de Cena.",
  str_skill_desc_350025 = "Inflige un <color=#00F6FF>300%</color> de daño a <color=#00F6FF>3 columnas seleccionadas</color> o <color=#00F6FF>3 filas seleccionadas</color> y hace retroceder a los enemigos. El daño infligido a la fila o columna central será 1.7 veces el daño infligido a los dos lados. Reinicia todas las casillas <color=#00F6FF>no rojas</color> dentro del área de ataque.",
  str_skill_desc_356025 = "Inflige un <color=#00F6FF>300%</color> de daño a <color=#00F6FF>3 columnas seleccionadas</color> o <color=#00F6FF>3 filas seleccionadas</color> y hace retroceder a los enemigos. El daño infligido a la fila o columna central será 1.7 veces el daño infligido a los dos lados. Reinicia todas las casillas <color=#00F6FF>no rojas</color> dentro del área de ataque y tiene una <color=#00F6FF>pequeña probabilidad</color> de generar casillas rojas.",
  str_skill_desc_360025 = "Inflige un <color=#00F6FF>340%</color> de daño a <color=#00F6FF>3 columnas seleccionadas</color> o <color=#00F6FF>3 filas seleccionadas</color> y hace retroceder a los enemigos. El daño infligido a la fila o columna central será 1.7 veces el daño infligido a los dos lados. Reinicia todas las casillas <color=#00F6FF>no rojas</color> dentro del área de ataque.",
  str_skill_desc_366025 = "Inflige un <color=#00F6FF>340%</color> de daño a <color=#00F6FF>3 columnas seleccionadas</color> o <color=#00F6FF>3 filas seleccionadas</color> y hace retroceder a los enemigos. El daño infligido a la fila o columna central será 1.7 veces el daño infligido a los dos lados. Reinicia todas las casillas <color=#00F6FF>no rojas</color> dentro del área de ataque y tiene una <color=#00F6FF>pequeña probabilidad</color> de generar casillas rojas.",
  str_skill_passive_desc_440025 = "Los ataques normales <color=#00F6FF>ahora pueden atacar en diagonal</color>. Los ataques normales infligen daño adicional que ignora la DEF, equivalente al <color=#00F6FF>12%</color> del ATQ.",
  str_skill_upgrade_refine_desc_16002511 = "Mejora de habilidad de equipamiento: Aumenta el factor de daño a <color=#00F6FF>12%</color>.",
  str_skill_upgrade_refine_desc_16002512 = "Mejora activa de habilidades: Inflige <color=#00F6FF>1.7 veces</color> más daño a las filas o columnas centrales.",
  str_skill_upgrade_refine_desc_16002513 = "Mejora activa de habilidades: Aumenta el factor de daño a <color=#00F6FF>340%</color>.",
