  str_skill_upgrade_desc_16020613 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16020616 = "Mejora Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00> 1 </color> ronda.",
  str_skill_upgrade_refine_desc_15002411 = "Mejora de habilidad de equipamiento: Aumenta el factor de daño a <color=#00F6FF>65%</color>.",
  str_skill_upgrade_refine_desc_15002412 = "Mejora activa de habilidades: Aumenta el daño final de ambos Combos en Cadena en un <color=#00F6FF>35%</color>.",
  str_skill_upgrade_refine_desc_15002413 = "Mejora de combo de cadena: En las rondas en las que se lanza la Habilidad Activa, reduce la cantidad de casillas para activar el combo en <color=#00F6FF>1</color>.",
  str_skill_passive_desc_440024 = "Los ataques normales infligen un <color=#00F6FF>65%</color> de daño adicional a los enemigos que ocupan casillas Rojas.",
  str_skill_desc_340024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcance <color=#00F6FF>1.5</color> veces el número de casillas necesarias para activar un Combo en cadena, lanza el Combo en cadena una vez en la localización marcada también (aumenta el daño final de ambos Combos en cadena en <color=#00F6FF>35%</color>).",
  str_skill_desc_342024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcance <color=#00F6FF>1.5</color> veces el número de casillas necesarias para activar un Combo en cadena, lanza el Combo en cadena una vez en la localización marcada también (aumenta el daño final de ambos Combos en cadena en <color=#00F6FF>35%</color>).",
  str_skill_desc_345024 = "Marca 1 casilla. Cuando el número de casillas conectadas alcance <color=#00F6FF>1.5</color> veces el número de casillas necesarias para activar un Combo en cadena, lanza el Combo en cadena una vez en la localización marcada también (aumenta el daño final de ambos Combos en cadena en <color=#00F6FF>35%</color>).",
  str_skill_desc_240241 = "Inflige un <color=#00F6FF>140%</color> de daño a <color=#00F6FF>1 grupo cercano</color>. En las rondas en las que se lanza la Habilidad Activa, reduce en <color=#00F6FF>1</color> la cantidad de casillas necesarias para activar un COMBO.",
  str_skill_desc_240242 = "Inflige un <color=#00F6FF>145%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>. En las rondas en las que se lanza la Habilidad Activa, reduce la cantidad de casillas que activan el COMBO en <color=#00F6FF>1</color>.",
  str_skill_desc_240243 = "Inflige un <color=#00F6FF>155%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color>. En las rondas en las que se lanza la Habilidad Activa, reduce en <color=#00F6FF>1</color> la cantidad de casillas necesarias para activar un COMBO.",
  str_skill_name_290560101 = "Diosa Denuo - Espina de Vid",
  str_skill_desc_290560101 = "Se mueve hacia los Aurorians e inflige daño a los objetivos en una fila o columna adelante.",
  str_skill_name_290560102 = "Diosa Denuo - Polinización",
  str_skill_desc_290560102 = "Se mueve hacia los Aurorians y causa daño a todos los objetivos dentro de las 12 casillas circundantes en forma de diamante, mientras inflige veneno y cataliza el crecimiento de las plantas en el rango.",
  str_skill_name_290560103 = "Diosa Denuo - Explosión",
  str_skill_desc_290560103 = "Apunta a un Aurorian y causa daño a todos los objetivos dentro de 12 casillas en forma de diamante alrededor del Aurorian, mientras inflige veneno y cataliza el crecimiento de las plantas en el rango (no puede fallar).",
  str_skill_name_200260101 = "Sadesian Enchantweed - Inactivo",
  str_skill_desc_200260101 = "En su forma juvenil, la Enredadera Encantada Sadesiana es inmune a los ataques de los Aurorianos.",
  str_skill_name_200260201 = "Hierba Encantada Sadesiana - Crecimiento",
  str_skill_desc_200260201 = "En su etapa metamórfica, la Enredadera Encantada Sadesiana puede ser atacada por Aurorians, pero carece de la habilidad para contraatacar.",
  str_skill_name_200260301 = "Sadesian Enchantweed - Aguijón",
  str_skill_desc_200260301 = "Apunta a Aurorians y causa daño mientras inflige veneno.",
  str_skill_name_53310002 = "Diosa Denuo - Polinización",
  str_skill_desc_53310002 = "Cataliza el crecimiento de las plantas en 12 casillas circundantes en forma de diamante.",
  str_skill_desc_3300051 = "<color=#FFFF00>Recarga de habilidad +1 después de lanzar</color>. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos. Cuanto menor sea el porcentaje de PS del enemigo, mayor será el daño (daño incrementado hasta 100%). Aumenta el daño de impacto infligido por cada acumulación de Alma al 130%.",
  str_skill_desc_3300052 = "<color=#FFFF00>Reducción de 1 en el tiempo de reutilización de habilidades después de lanzar</color>. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos en la pantalla. Cuanto menor sea el porcentaje de PS del enemigo, mayor será el daño (daño incrementado hasta 100%). No obtiene Alma por los enemigos derrotados por Aurorians en el campo con sus Habilidades Activas.",
  str_skill_desc_3360051 = "<color=#FFFF00>Recarga de habilidad +1 después de lanzar</color>. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos. Cuanto menor sea el porcentaje de PS del enemigo, mayor será el daño (daño incrementado hasta 100%). Aumenta el daño de impacto infligido por cada acumulación de Alma al 130%.",
  str_skill_desc_3360052 = "<color=#FFFF00>Reducción de 1 en el tiempo de reutilización de habilidades después de lanzar</color>. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos en la pantalla. Cuanto menor sea el porcentaje de PS del enemigo, mayor será el daño (daño incrementado hasta 100%). No obtiene Alma por los enemigos derrotados por Aurorians en el campo con sus Habilidades Activas.",
  str_skill_passive_desc_443005 = "Mia gana 1 acumulación de Alma por cada enemigo derrotado por <color=#00F6FF>aurorianos</color> en el campo con sus Habilidades Activas, hasta <color=#00F6FF>8</color> pilas Cada pila desata una explosión que inflige <color=#00F6FF>100%</color> Daño de ATK a un solo objetivo, lo que aumenta adicionalmente el Ataque normal de Mia en <color=#00F6FF>3%</color>, y Daño combinado en cadena por <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_16000511 = "<color=#00F6FF>Nueva Variante de Habilidad Activa I</color>: <color=#FFFF00>El tiempo de reutilización de la habilidad aumenta en +1 después de lanzarla</color>. Aumenta el daño de impacto infligido por cada acumulación de Alma al 130%.",
  str_skill_upgrade_refine_desc_16000512 = "<color=#00F6FF>Nueva Variante de Habilidad Activa II</color>: <color=#FFFF00>Reducción de 1 en el tiempo de reutilización de la habilidad después de lanzarla</color>. No obtiene Alma por los enemigos derrotados por Aurorians en el campo con sus Habilidades Activas.",
  str_skill_upgrade_refine_desc_16000513 = "Mejora de habilidad de equipamiento: Aumenta el límite máximo de acumulaciones de Alma a <color=#00F6FF>8</color>.",
  str_skill_desc_8001201 = "Invoca un Geist sombrío en una casilla cercana al instante.",
  str_skill_desc_8001441 = "Invoca una gran multitud de Dretchers en el campo y otorga 30 Marcas de Energía que aumentan la ATQ.",
  str_skill_desc_800128107 = "El Dark Summoner se teletransporta a su objetivo, obtiene cierto número de escudos de conteo y acumula energía para lanzar un ataque de gran área, reduciendo significativamente su DEF en la ronda actual.",
  str_skill_desc_8001391 = "Usa su cola gruesa para atacar objetivos dentro del alcance, infligiendo daño 2 veces.",
  str_skill_desc_800141 = "Utiliza su gruesa cola para acumular Púas de Energía con el fin de atacar objetivos dentro del alcance, infligiendo daño 2 veces.",
  str_skill_desc_800139 = "Usa su fuerte cola para atacar objetivos dentro del alcance.",
  str_skill_desc_800140 = "Utiliza Picos de Energía para lanzar ataques a distancia en objetivos dentro del alcance.",
  str_skill_name_52200191 = "Despertar: Dominio",
  str_skill_desc_52200191 = "Selecciona 1 casilla y selecciona otra casilla para formar un campo de 2×2 o 1×4, y convierte las casillas dentro en casillas cromáticas.",
  str_skill_name_5220021 = "Despertar: Golpe de Trueno",
