  str_skill_name_5220024 = "Despertar: Teñir de Trueno",
  str_skill_desc_5220024 = "Selecciona 1 casilla y convierte las 6 casillas más cercanas no cromáticas y no amarillas en 3 casillas amarillas y 3 casillas cromáticas.",
  str_skill_desc_52200241 = "Selecciona 1 casilla y convierte las 6 casillas no cromáticas más cercanas en 6 casillas cromáticas.",
  str_skill_name_5220022 = "Despertar: Rompe Truenos",
  str_skill_desc_5220022 = "Selecciona 1 casilla y convierte las 4 casillas circundantes en amarillo.",
  str_skill_desc_52200221 = "Selecciona 1 casilla y convierte las 4 casillas circundantes en casillas cromáticas.",
  str_skill_name_5220023 = "Despertar: Alboroto de Trueno",
  str_skill_desc_5220023 = "Convierte 5 casillas seleccionadas en amarillas.",
  str_skill_desc_52200231 = "Convierte 5 casillas seleccionadas en casillas cromáticas.",
  str_skill_desc_5010421 = "El Servidor aplica múltiples Marcas de Penetrabilidad a objetivos dentro de 2 grupos cercanos, reduciendo la DEF de los objetivos con cada acumulación.",
  str_skill_desc_5010821 = "Invoca múltiples Sirvientes inmóviles al campo al azar.",
  str_skill_desc_5010831 = "Ataca objetivos dentro del área de efecto y aplica 10 Marcas de Penetrabilidad, reduciendo la DEF de cada objetivo con cada acumulación.",
  str_skill_desc_5010832 = "Ataca objetivos dentro del área de efecto y aplica 1 Marca de Penetrabilidad, reduciendo la DEF de cada objetivo con cada acumulación.",
  str_skill_desc_5010841 = "Ruge y aplica 20 Marcas de Penetrabilidad a los objetivos dentro del área de efecto, reduciendo la DEF de cada objetivo con cada acumulación.",
  str_skill_desc_5010842 = "Ruge y aplica 2 Marcas de Penetrabilidad a los objetivos dentro del área de efecto, reduciendo la DEF de cada objetivo con cada acumulación.",
  str_skill_desc_5010851 = "Detona la Marca de Penetrabilidad en los objetivos para infligir un daño masivo, con daño incrementado por cada acumulación.",
  str_skill_desc_5010871 = "Invoca 3 Sirvientes inmóviles al campo al azar.",
