  str_skill_desc_2002081 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 columna </color>.",
  str_skill_desc_2002082 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 columnas</color>.",
  str_skill_desc_2002083 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 columnas</color>.",
  str_skill_desc_300208 = "Invoca un <link=\"30087\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en una casilla transitable seleccionada. <color=#00F6FF>Antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> hacia sí mismo en 1 casilla.",
  str_skill_desc_305208 = "Invoca un <link=\"30087\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en una casilla transitable seleccionada. Cuando el Lagarto de Hierro es <color=#00F6FF>nuevo</color> y <color=#00F6FF>antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> hacia sí mismo en 1 casilla.",
  str_skill_desc_310208 = "Invoca un <link=\"30087\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en una casilla transitable seleccionada. <color=#00F6FF>Antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> hacia sí mismo en 1 casilla.",
  str_skill_desc_315208 = "Invoca un <link=\"30087\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en una casilla transitable seleccionada. Cuando el Lagarto de Hierro es <color=#00F6FF>nuevo</color> y <color=#00F6FF>antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> hacia sí mismo en 1 casilla.",
  str_skill_desc_320208 = "Invoca un <link=\"30088\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en un mosaico transitable seleccionado. <color=#00F6FF>Antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color> hacia sí mismo en 1 casilla. El Lagarto de Hierro obtiene la habilidad <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link>.",
  str_skill_desc_325208 = "Invoca un <link=\"30088\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en un mosaico transitable seleccionado. Cuando el Lagarto de Hierro es <color=#00F6FF>nuevo</color> y <color=#00F6FF>antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color> hacia sí mismo en 1 casilla. El Lagarto de Hierro obtiene la habilidad <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link>.",
  str_skill_desc_330208 = "Invoca un <link=\"30088\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en una casilla transitable seleccionada. <color=#00F6FF>Antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color> hacia sí mismo en 1 casilla. El Lagarto de Hierro obtiene las habilidades <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link> y <link=\"30090\"><#FFAE07><u>Remolino</u></color></link>.",
  str_skill_desc_335208 = "Invoca un <link=\"30088\"><#FFAE07><u>Lagarto de Hierro</u></color></link> en un mosaico transitable seleccionado. Cuando el Lagarto de Hierro es <color=#00F6FF>nuevo</color> y <color=#00F6FF>antes de la ronda del enemigo</color>, el Lagarto de Hierro atraerá a los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color> hacia sí mismo en 1 mosaico. El Lagarto de Hierro obtiene las habilidades <link=\"30089\"><#FFAE07><u>Magnetix</u></color></link> y <link=\"30090\"><#FFAE07><u>Remolino</u></color></link>.",
  str_skill_passive_name_410208 = "Explosión de Lagarto",
  str_skill_passive_desc_410208 = "Cuando el Lagarto de Hierro desaparece, trata <color=#00F6FF>{1}</color> daño a 2 grupos circundantes.",
  str_skill_upgrade_desc_15020812 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_15020815 = "Mejora activa de habilidades: Cuando el Lagarto de Hierro es <color=#FFFF00>generado</color>, atraerá a los enemigos dentro de <color=#00F6FF>2 grupos cercanos</color> hacia sí mismo en 1 casilla.",
  str_skill_name_1522081 = "Magnetix",
  str_skill_desc_1522081 = "Cuando se lanza, atrae a los enemigos dentro de 2 grupos circundantes más cerca en 1 mosaico y luego desaparece.",
  str_skill_name_1532081 = "Whirlpool",
  str_skill_desc_1532081 = "Después del lanzamiento, el Combo de cadena de Bopper se cambiará para enfrentar directamente al Lagarto de hierro, extendiéndose hasta el borde del campo en esta ronda.",
  str_skill_name_99039011 = "Abandonado: Golpe único",
  str_skill_name_99039012 = "Se mueve hacia los Aurorianos y ataca cuando está a 4 casillas adyacentes de los Aurorianos.",
  str_skill_desc_99039011 = "Renegado: Pistolero",
  str_skill_desc_99039012 = "Se acerca a los Aurorianos y ataca cuando está dentro de 1 grupo cercano a los Aurorianos.",
  str_skill_name_52200232 = "Despertar",
  str_skill_desc_52200232 = "Convierte 1 casilla seleccionada en una casilla cromática.",
  str_skill_name_290600103 = "Duelo: Derribo",
  str_skill_name_290600104 = "Dolor: Tornado",
  str_skill_name_290600105 = "Dolor: depósito de malicia",
  str_skill_name_290600106 = "Duelo: Nulidad",
  str_skill_desc_290600103 = "duelo Eve se teletransporta al mosaico más lejano dentro del alcance máximo de un área en forma de cruz centrada alrededor del objetivo y ataca al objetivo.",
  str_skill_desc_290600104 = "Duelo Eve inflige daño en la gran área central del campo de batalla.",
  str_skill_desc_290600105 = "La afligida Eve gana una cantidad considerable de acumulaciones de Darkflow, reduciendo la cantidad de daño que recibe según el número de acumulaciones. Cada vez que es atacada, las acumulaciones de Darkflow disminuyen.",
  str_skill_desc_290600106 = "duelo Eve se fija en el objetivo e inflige daño, luego restaura una cantidad significativa de HP en función de las acumulaciones restantes de Darkflow.",
  str_skill_name_291600103 = "duelo Eve se teletransporta a la posición más cercana al objetivo y luego lo ataca.",
  str_skill_name_291600104 = "duelo Eve inflige daño en la gran área central del campo de batalla.",
  str_skill_name_291600105 = "duelo Eve gana una cierta cantidad de acumulaciones de Darkflow, obteniendo una reducción de DAÑO basada en la cantidad de acumulaciones. Cada vez que es atacada, las acumulaciones de Darkflow disminuyen.",
  str_skill_name_291600106 = "Duelo Eve se fija en el objetivo e inflige daño, luego restaura una cantidad significativa de HP en función de las acumulaciones restantes de Darkflow.",
  str_skill_name_20060011 = "Dawn Flor",
  str_skill_desc_20060011 = "Otorga una bonificación de recuperación de HP para el duelo Eve",
  str_skill_name_200310102 = "Predicar con el Ejemplo",
  str_skill_desc_200310102 = "Desata un tajo dañino primero e inmediatamente lo sigue con una patada, infligiendo otro caso de daño menor a los enemigos y derribándolos.",
  str_skill_name_200310103 = "Aumento de Moral",
  str_skill_desc_200310103 = "Otorga a los Soldados Illumina dentro de 2 grupos circundantes ACT adicional y convierte una parte del Moretón acumulado en HP para todos los soldados en el rango y ellos mismos.",
  str_skill_name_200290103 = "Supresión con ametralladora L5",
  str_skill_desc_200290103 = "Inflige daño a los enemigos dentro de 20 mosaicos circundantes con una ametralladora.",
  str_skill_name_200290104 = "Carga de Asalto L5",
  str_skill_desc_200290104 = "Cuando los enemigos no están dentro de las 20 casillas circundantes, carga rápidamente hacia una casilla dentro de un área en forma de cruz que esté más cerca de un enemigo. Al llegar, inflige daño a los enemigos frente al destino y los empuja hacia atrás 2 mosaicos.",
  str_skill_name_200300101 = "Chorro de Llama en Forma de Abanico",
  str_skill_desc_200300101 = "Inflige daño a todos los objetivos dentro de un área en forma de abanico adelante e inflige 1 pila de Quemadura en ellos mientras genera fuego en las casillas transitables dentro del alcance.",
  str_skill_name_200340103 = "Barrido corruptor",
  str_skill_desc_200340103 = "Balancea el arma para infligir daño a los enemigos en frente.",
  str_skill_name_200340104 = "Empujón Corruptor",
  str_skill_desc_200340104 = "Empuja el arma para infligir daño a los enemigos en frente.",
  str_skill_name_200270101 = "Primeros Auxilios en el Campo de Batalla de Illumina",
  str_skill_desc_200270101 = "Restaura HP al Soldado Illumina con el HP más bajo dentro de 4 casillas en forma de cruz y convierte una parte del Bruise acumulado en HP.",
  str_skill_name_200280101 = "Llamado de Refuerzo",
  str_skill_desc_200280101 = "Invoca 1 Soldado Illumina en el campo de batalla.",
  str_skill_upgrade_desc_16020913 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16020916 = "Mejora Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00> 1 </color> ronda.",
  str_skill_name_2002091 = "Impacto de Matriz",
  str_skill_name_2002092 = "Impacto de Matriz",
  str_skill_name_2002093 = "Impacto de Matriz",
  str_skill_name_2002094 = "Impacto de Matriz",
  str_skill_desc_2002091 = "Salta hacia el enemigo más cercano con el HP más alto dentro <color=#00F6FF>12 fichas en forma de diamante</color>, luego ofertas <color=#00F6FF>150%</color> daño a <color=#00F6FF>9 fichas en forma de cuadrado</color>.",
  str_skill_desc_2002092 = "Salta hacia el enemigo más cercano con el HP más alto dentro <color=#00F6FF>12 fichas en forma de diamante</color>, luego ofertas <color=#00F6FF>160%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color>.",
  str_skill_desc_2002093 = "Salta hacia el enemigo más cercano con el HP más alto dentro <color=#00F6FF>12 fichas en forma de diamante</color>, luego ofertas <color=#00F6FF>170%</color> daño a <color=#00F6FF>17 fichas en forma radial</color>.",
  str_skill_desc_2002094 = "Salta hacia el enemigo más cercano con el HP más alto dentro de <color=#00F6FF>12 fichas en forma de diamante</color>, luego inflige <color=#00F6FF>200%</color> de daño a <color=#00F6FF>25 fichas en forma de cuadrado</color>. Durante cada conexión de fichas, cada instancia de daño infligido disminuye la condición de activación en 1.",
  str_skill_name_3002091 = "Trueno Patrullero",
  str_skill_name_3002092 = "Variante de trueno en patrulla II",
  str_skill_name_3002093 = "Variante de trueno patrullero I",
  str_skill_name_3062091 = "Trueno Patrullero",
  str_skill_name_3062092 = "Variante de trueno en patrulla II",
  str_skill_name_3062093 = "Variante de trueno patrullero I",
  str_skill_desc_3002091 = "Selecciona 1 casilla para infligir <color=#00F6FF>200%</color> de daño a 25 casillas en forma cuadrada. Si el lanzador está dentro del alcance de la habilidad, el daño final se incrementa en <color=#00F6FF>30%</color>.",
  str_skill_desc_3002092 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Selecciona 1 casilla para infligir <color=#00F6FF>100%</color> de daño a 9 casillas en forma cuadrada. Si el lanzador está dentro del alcance de la habilidad, el daño final se incrementa en <color=#00F6FF>30%</color>.",
  str_skill_desc_3002093 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige un 300% de daño a todas las casillas, y el daño final aumenta en <color=#00F6FF>30%</color>.",
  str_skill_desc_3062091 = "Selecciona 1 casilla para infligir <color=#00F6FF>200%</color> de daño a 25 casillas en forma cuadrada. Si el lanzador está dentro del alcance de la habilidad, el daño final se incrementa en <color=#00F6FF>30%</color>.",
  str_skill_desc_3062092 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Selecciona 1 casilla para infligir <color=#00F6FF>100%</color> de daño a 9 casillas en forma cuadrada. Si el lanzador está dentro del alcance de la habilidad, el daño final se incrementa en <color=#00F6FF>30%</color>.",
  str_skill_desc_3062093 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige <color=#00F6FF>300%</color> de daño a todas las casillas y el daño final aumenta en <color=#00F6FF>30%</color>.",
  str_skill_passive_name_410209 = "Furia del trueno",
  str_skill_passive_name_420209 = "Furia del trueno",
  str_skill_passive_name_430209 = "Furia del trueno",
  str_skill_passive_desc_410209 = "Los enemigos atacados por la Habilidad Activa entrarán en estado de Eco Tronador durante <color=#00F6FF>2 rondas</color>. Inflige <color=#00F6FF>{1}</color> de daño a los objetivos bajo el estado de Eco Tronador dentro de <color=#00F6FF>12 fichas en forma de diamante</color> por cada ficha que el equipo atraviese.",
  str_skill_passive_desc_420209 = "Los enemigos atacados por la Habilidad Activa entrarán en estado de Eco Tronador durante <color=#00F6FF>2 rondas</color>. Inflige <color=#00F6FF>{1}</color> de daño a los objetivos bajo el estado de Eco Tronador dentro de <color=#00F6FF>12 fichas en forma de diamante</color> por cada ficha que el equipo atraviese.",
  str_skill_passive_desc_430209 = "Los ataques normales pueden alcanzar enemigos dentro de <color=#00F6FF>8 casillas en forma de cruz</color>. Los enemigos atacados por la Habilidad Activa entrarán en estado de Eco Tronador durante <color=#00F6FF>2 rondas</color>. Inflige <color=#00F6FF>{1}</color> de daño a objetivos bajo el estado de Eco Tronador dentro de <color=#00F6FF>12 casillas en forma de diamante</color> por cada casilla que el equipo atraviese.",
  str_skill_passive_desc_440209 = "Los ataques normales pueden alcanzar enemigos dentro de <color=#00F6FF>8 casillas en forma de cruz</color>. Los enemigos atacados por la Habilidad Activa entrarán en estado de Eco Atronador durante <color=#00F6FF>2 rondas</color>. Inflige <color=#00F6FF>50%</color> de daño a objetivos bajo el estado de Eco Atronador dentro de <color=#00F6FF>12 casillas en forma de diamante</color> por cada casilla que el equipo atraviese.",
  str_skill_upgrade_refine_desc_16020911 = "Mejora de habilidades de equipo: Aumenta el factor de daño a <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>Nueva variante de habilidad activa I</color>: <color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Inflige <color=#00F6FF>300%</color> de daño a todos los mosaicos y el daño final aumenta en <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>Nueva variante de habilidad activa II</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Selecciona 1 casilla para infligir <color=#00F6FF>100%</color> de daño a 9 casillas en forma cuadrada. Si el lanzador está posicionado dentro del alcance de la habilidad, el daño final aumenta en un 30%.",
  str_skill_desc_320116 = "Fleur inflige un <color=#00F6FF>{1}% </color> de daño a 1 enemigo seleccionado y marca al objetivo, y es capaz de dañar a los objetivos marcados 1 vez más cuando usa combos en cadena en esta ronda. Si la Habilidad Activa está lista en la última ronda, el daño final de esta ronda aumenta en un <color=#00F6FF> 35% </color>.",
  str_skill_desc_323116 = "Fleur inflige un <color=#00F6FF>{1}% </color> de daño a 1 enemigo seleccionado y marca al objetivo, y es capaz de dañar a los objetivos marcados 1 vez más cuando usa combos en cadena en esta ronda. Si la Habilidad Activa está lista en la última ronda, el daño final de esta ronda aumenta en un <color=#00F6FF> 35% </color>.",
  str_skill_upgrade_desc_16011113 = "Mejora de habilidades de equipo: el rango de generación de cristales aumenta a 1/2/3 <color=#00F6FF>grupos circundantes</color>.",
  str_skill_upgrade_desc_16011116 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_desc_300111 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos. Cuanto menos enemigos haya, mayor será el daño infligido, hasta 2 veces el original.",
  str_skill_desc_303111 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos. Cuanto menos enemigos haya, mayor será el daño infligido, hasta 2 veces el original.",
  str_skill_desc_320111 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos. Cuantos menos enemigos haya, mayor será el daño infligido, hasta 2 veces el original. Marca la posición actual <color=#00F6FF>después de usar Habilidades Activas</color> y al <color=#00F6FF>entrar en Hora de Aurora</color>. Si la Habilidad de Equipo genera cristales en esta ronda, se activará una vez en la posición marcada.",
  str_skill_desc_323111 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>todos</color> los enemigos. Cuantos menos enemigos haya, mayor será el daño infligido, hasta 2 veces el original. Marca la posición actual <color=#00F6FF>después de usar Habilidades Activas</color> y al <color=#00F6FF>entrar en Hora de Aurora</color>. Si la Habilidad de Equipo genera cristales en esta ronda, se activará una vez en la posición marcada.",
  str_skill_passive_name_416111 = "Toque de Cristal",
  str_skill_passive_name_436111 = "Toque de Cristal",
  str_skill_passive_desc_410111 = "Antes de que el enemigo actúe, si Beryl ha lanzado un Combo en Cadena esta ronda, se generan cristales dentro de su <color=#00F6FF>alcance de Combo en Cadena</color> y permanecerán allí durante 1 ronda. Cuando los enemigos <link=\"30091\"><#FFAE07><u>tocan</u></color></link> sus cristales, reciben <color=#00F6FF>{1}</color> de daño que ignora DEF (afectado por contadores de elementos).",
  str_skill_passive_desc_430111 = "Antes de que el enemigo actúe, si Beryl ha lanzado un Combo en Cadena esta ronda, se generan cristales dentro de su <color=#00F6FF>rango de Combo en Cadena</color> y permanecerán allí durante 1 ronda. Cuando los enemigos <link=\"30091\"><#FFAE07><u>tocan</u></color></link> sus cristales, reciben un daño <color=#00F6FF>{1}</color> que ignora la DEF (afectado por contadores de elementos). Este daño aumenta en un <color=#00F6FF>10%</color> por cada casilla conectada, hasta un máximo de 20 casillas.",
  str_skill_passive_desc_416111 = "Antes de que el enemigo actúe, si Beryl ha lanzado un Combo en Cadena esta ronda, se generan cristales dentro de <color=#00F6FF>1/2/3 cúmulos circundantes</color> y permanecerán allí durante 1 ronda. Cuando los enemigos <link=\"30091\"><#FFAE07><u>tocan</u></color></link> sus cristales, reciben <color=#00F6FF>{1}</color> de daño que ignora DEF (afectado por contadores de elementos).",
  str_skill_passive_desc_436111 = "Antes de que el enemigo actúe, si Beryl ha lanzado un Combo en Cadena esta ronda, se generan cristales dentro de <color=#00F6FF>1/2/3 cúmulos circundantes</color> y permanecerán allí durante 1 ronda. Cuando los enemigos <link=\"30091\"><#FFAE07><u>tocan</u></color></link> sus cristales, reciben un daño que ignora DEF de <color=#00F6FF>{1}</color> (afectado por contadores de elementos). Este daño aumenta en <color=#00F6FF>10%</color> por cada casilla conectada, hasta un máximo de 20 casillas.",
  str_skill_desc_2001161 = "Inflige un <color=#00F6FF>{1}% </color> de daño a 2 enemigos más cercano y <color=#00F6FF> 30% </color> <link=\"30015\"><#FFAE07> <u>salpica</u></color></link> daño a <color=#00F6FF> 4 casillas en forma de cruz </color> a su alrededor.",
  str_skill_desc_2001162 = "Inflige un <color=#00F6FF>{1}% </color> de daño a 2 enemigos más cercano y <color=#00F6FF> 30% </color> <link=\"30015\"><#FFAE07> <u>salpica</u></color></link> daño a <color=#00F6FF> 4 casillas en forma de cruz </color> a su alrededor.",
  str_skill_desc_2001163 = "Inflige un <color=#00F6FF>{1}% </color> de daño a 2 enemigos más cercano y <color=#00F6FF> 30% </color> <link=\"30015\"><#FFAE07> <u>salpica</u></color></link> daño a <color=#00F6FF> 4 casillas en forma de cruz </color> a su alrededor.",
  str_skill_desc_2061161 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos y <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>daño de salpicadura</u></color></link> a <color=#00F6FF>4 casillas en un área en forma de cruz</color> alrededor de ellos. Este ataque ignora toda la DEF si el objetivo está marcado.",
  str_skill_desc_2061162 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos y <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>daño de salpicadura</u></color></link> a <color=#00F6FF>4 casillas en un área en forma de cruz</color> alrededor de ellos. Este ataque ignora toda la DEF si el objetivo está marcado.",
  str_skill_desc_2061163 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos y <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>daño de salpicadura</u></color></link> a <color=#00F6FF>4 casillas en un área en forma de cruz</color> alrededor de ellos. Este ataque ignora toda la DEF si el objetivo está marcado.",
  str_skill_desc_2201161 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos y <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>daño de salpicadura</u></color></link> a <color=#00F6FF>4 casillas en un área en forma de cruz</color> alrededor de ellos. Este ataque ignora el 40% de DEF si el objetivo está marcado.",
  str_skill_desc_2201162 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos y <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>daño de salpicadura</u></color></link> a <color=#00F6FF>4 casillas en un área en forma de cruz</color> alrededor de ellos. Este ataque ignora el 40% de DEF si el objetivo está marcado.",
  str_skill_desc_2201163 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos y <color=#00F6FF>30%</color> <link=\"30015\"><#FFAE07><u>daño de salpicadura</u></color></link> a <color=#00F6FF>4 casillas en un área en forma de cruz</color> alrededor de ellos. Este ataque ignora el 40% de DEF si el objetivo está marcado.",
  str_skill_name_2201161 = "Puño de Hierro",
  str_skill_name_2201162 = "Puño de Hierro",
  str_skill_name_2201163 = "Puño de Hierro",
  str_skill_desc_300116 = "Selecciona 1 enemigo e inflige <color=#00F6FF>{1}%</color> de daño dejando una marca. Los Combos en Cadena de Fleur infligen daño a los objetivos marcados 1 vez adicional en esta ronda.",
  str_skill_desc_303116 = "Selecciona 1 enemigo e inflige <color=#00F6FF>{1}%</color> de daño mientras deja una marca. Los Combos en Cadena de Fleur infligen daño a los objetivos marcados 1 vez adicional en esta ronda. Fleur puede lanzar su Habilidad Activa nuevamente después de <color=#00F6FF>entrar en Hora de Aurora</color> o cuando <color=#00F6FF>un objetivo marcado es derrotado</color>.",
  str_skill_passive_name_400116 = "Personal de mantenimiento",
  str_skill_passive_name_410116 = "Personal de mantenimiento",
  str_skill_passive_name_430116 = "Personal de mantenimiento",
  str_skill_passive_desc_410116 = "Todo el daño que Fleur inflige a los enemigos con menos del 50% de su PS máximo aumenta en <color=#00F6FF>{1}</color> (si el objetivo no tiene un valor de PS máximo, este aumento de daño se aplica de inmediato).",
  str_skill_passive_desc_430116 = "Todo el daño que Fleur inflige a enemigos con menos del 50% de su PS máximo aumenta en <color=#00F6FF>{1}</color> (si el objetivo no tiene un valor de PS máximo, este aumento de daño se aplica de inmediato). Otorga un bono adicional de <color=#00F6FF>{2}</color> al atacar objetivos marcados.",
  str_skill_upgrade_desc_16011613 = "Mejora de Combo en Cadena: Al atacar objetivos marcados, los ataques de Combo en Cadena ignoran completamente la DEF. (Válido para Ascensión II.)",
  str_skill_upgrade_desc_16011616 = "Mejora de habilidad activa: Se puede lanzar de nuevo después de ingresar a Aurora Time o cuando se derrota a un objetivo marcado.",
