  str_skill_passive_name_415210 = "Lamentaciones de los moribundos",
  str_skill_desc_20021011 = "Inflige <color=#00F6FF>130%</color> de daño 2 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002102 = "Inflige <color=#00F6FF>135%</color> de daño 3 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002103 = "ofertas <color=#00F6FF>140%</color> daño 4 veces, asignado aleatoriamente a los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_3002101 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>.",
  str_skill_desc_3102101 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>.",
  str_skill_desc_3202101 = "Selecciona 1 de las <color=#00F6FF>4</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige adicionalmente <color=#00F6FF>120%</color> de daño una vez a todos los enemigos dentro de <color=#00F6FF>12 casillas en forma de diamante</color> centrado en la posición del equipo.",
  str_skill_desc_3302101 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad de Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño reducido a la mitad</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige adicionalmente <color=#00F6FF>120%</color> de daño una vez a todos los enemigos dentro de <color=#00F6FF>12 casillas en forma de diamante</color> centrado en la posición del equipo.",
  str_skill_desc_3022101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>.",
  str_skill_desc_3122101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>.",
  str_skill_desc_3222101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>12 casillas en forma de diamante</color> desde la posición del equipo.",
  str_skill_desc_3322101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño reducido a la mitad</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>12 casillas en forma de diamante</color> centrado en la posición del equipo.",
  str_skill_desc_3152101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>.",
  str_skill_desc_3252101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>12 casillas en forma de diamante</color> desde la posición del equipo.",
  str_skill_desc_3352101 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>{1}%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño reducido a la mitad</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>12 casillas en forma de diamante</color> centrado en la posición del equipo.",
  str_skill_passive_desc_410210 = "Cada Ataque Normal y Combo en Cadena de Joselyne inflige 1 pila de Voluntad Persistente a los enemigos golpeados, hasta <color=#00F6FF>6</color> acumulaciones. Su Habilidad Activa también inflige <color=#00F6FF>{1}</color> de daño ATK al enemigo <color=#00F6FF>1 casilla adelante</color> varias veces según la cantidad de pilas de Voluntad Persistente en el objetivo. Las pilas se reinician después.",
  str_skill_passive_desc_415210 = "Cada Ataque normal y Combo en cadena de Joselyne inflige 1 pila de Voluntad persistente a los enemigos golpeados, hasta <color=#00F6FF>8</color> acumulaciones. Su Habilidad Activa también inflige <color=#00F6FF>{1}</color> de daño ATK al enemigo <color=#00F6FF>1 casilla adelante</color> varias veces según la cantidad de pilas de Voluntad persistente en el objetivo. Las pilas se reinician después.",
  str_skill_upgrade_desc_15021012 = "Mejora de habilidad activa: Selecciona cualquiera de las <color=#FFFF00>8</color> direcciones y se dirige hacia ella.",
  str_skill_upgrade_desc_15021015 = "Mejora de habilidades de equipo: Aumenta el límite máximo de acumulaciones de Voluntad Persistente a <color=#FFFF00>8</color>.",
  str_skill_name_200330110 = "Manipulación psiónica",
  str_skill_desc_200330110 = "Dreadweaver se aleja de la ubicación del equipo del jugador. Una vez que el movimiento del equipo termina, Dreadweaver cambiará inmediatamente la ubicación del equipo, afectando la posición de los Combos en Cadena lanzados por su equipo.",
  str_skill_name_200330121 = "Sacrificio de Sangre",
  str_skill_desc_200330121 = "Dreadweaver quema su HP restante hasta dejarlo en 1 punto, infligiendo daño verdadero que ignora la defensa al jugador. La cantidad de HP quemado determina directamente el daño final. Esta habilidad solo se puede lanzar una vez.",
  str_skill_upgrade_refine_desc_15021011 = "Mejora de habilidades de equipo: Aumenta el factor de daño a <color=#00F6FF>36%</color>.",
  str_skill_upgrade_refine_desc_15021012 = "Mejora de habilidad activa: Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige 120% de daño una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_upgrade_refine_desc_15021013 = "Mejora de habilidad activa: Las habilidades activas y las habilidades de equipamiento infligen daño completo en los mosaicos que atraviesan.",
  str_skill_passive_desc_440210 = "Cada Ataque Normal y Chain Combo de Joselyne inflige 1 acumulación de Voluntad Persistente a los enemigos golpeados, hasta <color=#00F6FF>8</color> acumulaciones. Su Habilidad Activa también inflige <color=#00F6FF>36%</color> de daño ATK al enemigo <color=#00F6FF>1 casilla adelante</color> varias veces según la cantidad de acumulaciones de Voluntad Persistente en el objetivo. Las acumulaciones se reinician después.",
  str_skill_passive_desc_445210 = "Cada Ataque Normal y Chain Combo de Joselyne inflige 1 acumulación de Voluntad Persistente a los enemigos golpeados, hasta <color=#00F6FF>8</color> acumulaciones. Su Habilidad Activa también inflige <color=#00F6FF>36%</color> de daño ATK al enemigo <color=#00F6FF>1 casilla adelante</color> varias veces según la cantidad de acumulaciones de Voluntad Persistente en el objetivo. Las acumulaciones se reinician después.",
  str_skill_desc_34021011 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>80%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño reducido a la mitad</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_34221011 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>80%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño reducido a la mitad</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_34521011 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>80%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño reducido a la mitad</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_34021012 = "Selecciona 1 de <color=#00F6FF>4</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>80%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, infligiendo <color=#00F6FF>daño completo</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_34221012 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>80%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, causando <color=#00F6FF>daño completo</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_34521012 = "Selecciona 1 de <color=#00F6FF>8</color> direcciones y carga, deteniéndose al encontrar obstáculos. Inflige <color=#00F6FF>80%</color> de daño una vez al enemigo <color=#00F6FF>1 casilla adelante</color>. Este daño, junto con el provocado por la Habilidad del Equipo, puede atravesar 1 casilla, causando <color=#00F6FF>daño completo</color> en la casilla atravesada. Por cada 4 acumulaciones de Voluntad Persistente en el objetivo, inflige <color=#00F6FF>120%</color> de daño adicional una vez a todos los enemigos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
