  str_skill_name_290610102 = "Aceleración Potenciada",
  str_skill_desc_290610102 = "Avanza rápidamente si no hay enemigos al frente.",
  str_skill_name_290610103 = "Bombardeo integral",
  str_skill_desc_290610103 = "Inflige daño a los aurorianos alrededor del mecha y los empuja hacia atrás. La habilidad también causa daño en las paredes.",
  str_skill_name_290610104 = "Chorros de Llama",
  str_skill_desc_290610104 = "Lanza un asalto formidable, infligiendo un enorme daño a los Aurorianos en frente y a las paredes.",
  str_skill_name_290610105 = "Mecánico Corrupto",
  str_skill_desc_290610105 = "Repara sus componentes cuando está paralizado y, una vez completada la reparación, se desplegará nuevamente para el asedio.",
  str_skill_name_280240101 = "Empuje Disipador",
  str_skill_desc_280240101 = "Asesta fuertes golpes a los enemigos frente a la Puerta del Bastión y los paraliza.",
  str_skill_name_290570101 = "Mudbundle: Chapoteando",
  str_skill_name_290570102 = "Mudbundle: Manantial",
  str_skill_name_290570103 = "Mudbundle: Sifonando",
  str_skill_desc_290570101 = "Mudbundle se hunde en el barro y emerge en la ubicación más cercana a los Aurorianos, infligiendo daño a las unidades dentro de 2 grupos circundantes y generando ciénagas en el campo.",
  str_skill_desc_290570102 = "Mudbundle se hunde en el barro y emerge en la ubicación más cercana a los Aurorianos, infligiendo daño a las unidades dentro de 2 columnas al frente y generando pantanos en el campo.",
  str_skill_desc_290570103 = "Absorbe todos los mosaicos en el campo y los reinicia, infligiendo daño a los aurorianos y moviéndolos a un cenagal aleatorio.",
  str_skill_desc_290570104 = "Mara Sol invoca a 2 Tejedores del Terror al campo de batalla.",
  str_skill_upgrade_desc_16021213 = "Mejora de habilidad activa: cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate.\nConvierte 2 azulejos no verdes aleatorios dentro del área rectangular determinada de la Habilidad Activa en azulejos verdes.",
  str_skill_upgrade_desc_16021216 = "Mejora de habilidad activa: El rango de selección del segundo mosaico se expande a <color=#00F6FF>4 grupos circundantes</color>.",
  str_skill_desc_3002121 = "Selecciona cualquier casilla, luego selecciona otra casilla dentro de <color=#00F6FF>3 grupos circundantes</color> para determinar un área rectangular. Las 2 casillas seleccionadas se convierten en casillas verdes, y si el equipo está dentro del área determinada, restaura HP igual a <color=#00F6FF>250%</color> del ATK de Antony.",
  str_skill_desc_3032121 = "Selecciona cualquier mosaico, luego selecciona otro mosaico dentro de <color=#00F6FF>3 grupos circundantes</color> para determinar un área rectangular. Los 2 mosaicos seleccionados se convierten en mosaicos verdes, luego convierte 2 mosaicos no verdes aleatorios dentro del área determinada en mosaicos verdes. Si el equipo está dentro del área determinada, restaura los PS equivalentes al <color=#00F6FF>250%</color> de la ATQ de Antony.",
  str_skill_desc_3062121 = "Selecciona cualquier mosaico, luego selecciona otro mosaico dentro de <color=#00F6FF>4 grupos circundantes</color> para determinar un área rectangular. Los 2 mosaicos seleccionados se convierten en mosaicos verdes, luego convierte 2 mosaicos no verdes aleatorios dentro del área determinada en mosaicos verdes. Si el equipo está dentro del área determinada, restaura los PS equivalentes al <color=#00F6FF>250%</color> de la ATQ de Antony.",
  str_skill_desc_3202121 = "Selecciona cualquier 1 mosaico, luego selecciona otro 1 mosaico dentro de <color=#00F6FF>3 grupos circundantes</color> para determinar un área rectangular. Los 2 mosaicos seleccionados se convierten en <link=\"20001\"><#FFAE07><u>mosaicos verdes mejorados</u></color></link>, y si el equipo está dentro del área determinada, restaura HP igual a <color=#00F6FF>250%</color> del ATK de Antony.",
  str_skill_desc_3232121 = "Selecciona cualquier mosaico, luego selecciona otro mosaico dentro de <color=#00F6FF>3 grupos circundantes</color> para determinar un área rectangular. Los 2 mosaicos seleccionados se convierten en <link=\"20001\"><#FFAE07><u>mosaicos verdes mejorados</u></color></link>, luego convierte 2 mosaicos no verdes aleatorios dentro del área determinada en mosaicos verdes. Si el equipo está dentro del área determinada, restaura HP igual a <color=#00F6FF>250%</color> del ATK de Antony.",
  str_skill_desc_3262121 = "Selecciona cualquier mosaico, luego selecciona otro mosaico dentro de <color=#00F6FF>4 grupos circundantes</color> para determinar un área rectangular. Los 2 mosaicos seleccionados se convierten en <link=\"20001\"><#FFAE07><u>mosaicos verdes mejorados</u></color></link>, luego convierte 2 mosaicos no verdes aleatorios dentro del área determinada en mosaicos verdes. Si el equipo está dentro del área determinada, restaura HP igual a <color=#00F6FF>250%</color> del ATK de Antony.",
  str_skill_desc_2002121 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 1 columna </color>.",
  str_skill_desc_2002122 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 columnas</color>.",
  str_skill_desc_2002123 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 3 columnas</color>.",
  str_skill_passive_desc_410212 = "Cuando los miembros del equipo atraviesan 1 casilla sobre casillas Verdes conectadas o <link=\"30092\"><#FFAE07><u>se mueven</u></color></link> 1 casilla por cualquier medio, restauran PS igual al <color=#00F6FF>{1}</color> del ATQ de Antony.",
  str_skill_passive_desc_430212 = "Cuando los miembros del equipo atraviesan 1 casilla sobre casillas Verdes conectadas o <link=\"30092\"><#FFAE07><u>se mueven</u></color></link> 1 casilla por cualquier medio, restauran PS igual al <color=#00F6FF>{1}</color> del ATQ de Antony. Cuanto menor sea la salud del equipo, mayor será el efecto de recuperación, hasta un <color=#00F6FF>100%</color>.",
  str_skill_name_3002121 = "Atención Urgente",
