  str_skill_name_30621103 = "Tormenta de granizo invernal",
  str_skill_name_30621104 = "Siempreverde Ventisca Blanca",
  str_skill_name_30321101 = "Tormenta de granizo invernal",
  str_skill_name_30321102 = "Siempreverde Ventisca Blanca",
  str_skill_desc_2002111 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2002112 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2002113 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_30021101 = "Convierte las <color=#00F6FF>2</color> casillas Amarillas más cercanas en Azul. Después de lanzar Granizada Invernal, el tiempo de reutilización de Ventisca Siempreverde aumenta en 1.",
  str_skill_desc_30021102 = "Convierte las <color=#00F6FF>2</color> casillas Verdes más cercanas a Azul. Después de lanzar Evergreen Whiteout, el tiempo de reutilización de Wintry Hailstorm aumenta en 1.",
  str_skill_desc_30021103 = "Convierte las <color=#00F6FF>3</color> casillas Amarillas más cercanas a Azul. Después de lanzar Granizada Invernal, el tiempo de reutilización de Ventisca Siempreverde aumenta en 1.",
  str_skill_desc_30021104 = "Convierte las <color=#00F6FF>3</color> casillas verdes más cercanas en azul. Después de lanzar Evergreen Whiteout, el tiempo de reutilización de Wintry Hailstorm aumenta en 1.",
  str_skill_desc_30021105 = "Convierte las <color=#00F6FF>4</color> casillas amarillas más cercanas a azul. Después de lanzar Granizo Invernal, el tiempo de reutilización de Ventisca Siempreverde aumenta en 1.",
  str_skill_desc_30021106 = "Convierte las <color=#00F6FF>4</color> casillas Verdes más cercanas a Azul. Después de lanzar Evergreen Whiteout, el tiempo de reutilización de Wintry Hailstorm aumenta en 1.",
  str_skill_desc_30321101 = "Convierte las <color=#00F6FF>2</color> casillas Amarillas más cercanas a Azul. Después de lanzar, la siguiente Habilidad Activa podrá convertir <color=#00F6FF>3</color> casillas, y el tiempo de espera de Evergreen Whiteout aumenta en 1.",
  str_skill_desc_30321102 = "Convierte las <color=#00F6FF>2</color> casillas verdes más cercanas en azul. Después de lanzar, la siguiente Habilidad Activa podrá convertir <color=#00F6FF>3</color> casillas, y el tiempo de reutilización de Wintry Hailstorm aumenta en 1.",
  str_skill_desc_30621103 = "Convierte las <color=#00F6FF>3</color> casillas amarillas más cercanas en azul. Después de lanzar la habilidad, el tiempo de reutilización de Evergreen Whiteout aumenta en +1. Si estas 2 Habilidades Activas no están listas cuando comienza la ronda, convierte <color=#00F6FF>1</color> casilla no azul más cercana al equipo en una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link> azul.",
  str_skill_desc_30621104 = "Convierte las <color=#00F6FF>3</color> casillas verdes más cercanas en azul. Después de lanzar la habilidad, el tiempo de reutilización de Wintry Hailstorm aumenta en +1. Si estas 2 Habilidades Activas no están listas cuando comienza la ronda, convierte <color=#00F6FF>1</color> casilla no azul más cercana al equipo en una <color=#00F6FF>Azul</color> <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link>.",
  str_skill_passive_name_410211 = "Remediación Nevada",
  str_skill_passive_name_420211 = "Remediación Nevada",
  str_skill_passive_name_430211 = "Remediación Nevada",
  str_skill_passive_desc_410211 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>50%</color> de daño básico por golpe. Después de cada <color=#00F6FF>7</color> ataques normales, Zarya restaura PS igual a <color=#00F6FF>{1}</color> de su ATQ para el equipo.",
  str_skill_passive_desc_420211 = "Los ataques normales se convierten en ataques combinados de 2 que infligen <color=#00F6FF>50%</color> de daño básico por golpe. Después de cada <color=#00F6FF>7</color> ataques normales, Zarya restaura HP igual a <color=#00F6FF>{1}</color> de su ATK para el equipo. Al ingresar a Aurora Time, ella restaura instantáneamente HP igual a <color=#00F6FF>100%</color> de su ATK para el equipo.",
  str_skill_passive_desc_430211 = "Los ataques normales se pueden lanzar en diagonal. Los ataques normales contra enemigos en forma de cruz se convierten en ataques combinados de 2 que infligen <color=#00F6FF>50%</color> de daño básico por golpe. Después de cada <color=#00F6FF>7</color> ataques normales, Zarya restaura HP igual a <color=#00F6FF>{1}</color> de su ATK para el equipo. Al ingresar a Aurora Time, ella restaura instantáneamente HP igual a <color=#00F6FF>100%</color> de su ATK para el equipo.",
  str_skill_upgrade_desc_16021113 = "Mejora Habilidad Activa: Aumenta el recuento de conversión de casilla a <color=#FFFF00>3</color>.",
  str_skill_upgrade_desc_16021116 = "Mejora Habilidad Activa: Si estas 2 Habilidades Activas <color=#00F6FF>no están listas</color> cuando comienza la ronda, convierte 1 casilla no azul más cercana al equipo en una Casilla Oscura azul.",
  str_skill_name_200350101 = "Terremoto",
  str_skill_name_200350102 = "Golpe doloroso",
  str_skill_name_200350103 = "Aplastacráneos",
  str_skill_name_200350104 = "Lamedura de sangre",
  str_skill_desc_200350101 = "Rimebeast golpea el suelo, infligiendo múltiples instancias de daño a los enemigos dentro de una forma de cruz hasta el alcance máximo y empujándolos a la mayor distancia posible.",
  str_skill_desc_200350102 = "Cuando los enemigos están posicionados dentro de 1 grupo circundante, Rimebeast les inflige daño y los empuja hacia atrás una casilla.",
  str_skill_desc_200350103 = "Si los enemigos están dentro de un rango específico alrededor de Rimebeast y no hay obstáculos en el área en forma de cruz, Rimebeast se acerca rápidamente a ellos y realiza un golpe poderoso, causando daño. Los enemigos en el área central sufrirán más daño y quedarán aturdidos.",
  str_skill_desc_200350104 = "Rimebeast recuperará su HP cuando no haya enemigos cerca.",
  str_skill_name_200360102 = "Espectro Carmesí - Persecución",
  str_skill_desc_200360102 = "Se teletransporta al equipo, infligiendo múltiples golpes dañinos a las unidades dentro de 1 casilla en frente y haciéndolas retroceder. Cuanto más lejos se teletransporte, menos ataques lanzará.",
  str_skill_name_290213101 = "Ruinas Eternas",
  str_skill_name_290213102 = "Juicio del guardián",
  str_skill_name_290213103 = "Amenaza detectada",
  str_skill_desc_290213101 = "Se teletransporta 1 vez mientras también inflige daño. Después de esto, convierte 3 casillas aleatorias dentro de 1 cúmulo circundante del equipo en casillas verdes.",
  str_skill_desc_290213102 = "Se teletransporta 1 vez mientras también inflige daño. Después de esto, convierte 3 casillas aleatorias dentro de 1 cúmulo circundante del equipo en casillas amarillas.",
  str_skill_desc_290213103 = "Absorbe energía de las losetas azules dentro de 2 grupos circundantes antes de atacar (cuantas más losetas se absorban, mayor será el daño).",
  str_skill_desc_200270201 = "Restaura HP para el Señalero de Illumina y convierte una parte del Bruise acumulado en HP.",
  str_skill_desc_200280201 = "Invoca a 2 Soldados Illumina en el campo de batalla.",
  str_skill_desc_200280202 = "Invoca 1 Soldado Illumina y 1 Sargento Illumina en el campo de batalla.",
  str_skill_desc_200280301 = "Invoca 2 Lanzallamas Illumina al campo de batalla.",
  str_skill_desc_200280302 = "Invoca 1 Lanzallamas Illumina y 1 Sargento Illumina en el campo de batalla.",
  str_skill_name_290280111 = "Sanki - Corte cruzado",
  str_skill_desc_290280111 = "Sanki se acerca al objetivo, lanzando un golpe arrollador con la Espada Sakae para causar daño.",
  str_skill_name_290280121 = "Sanki - Frenesí de Espada",
  str_skill_desc_290280121 = "Desata un frenético torbellino de golpes de espada en su lugar, infligiendo daño a los objetivos dentro del alcance.",
  str_skill_name_290280131 = "Sanki - Estocada Colmillo",
  str_skill_desc_290280131 = "Siguiendo la guía de la Espada Sakae, se lanza hacia el lado del objetivo, infligiendo daño en dos ocasiones.",
  str_skill_name_290280141 = "Sanki - Lanzamiento Cuádruple de Espadas",
  str_skill_desc_290280141 = "Antes de actuar, Sanki libera Espadas Sakae en cuatro direcciones, que infligen daño a los objetivos en sus trayectorias.",
  str_skill_name_290280151 = "Sanki - Recuerdo de la Espada",
  str_skill_desc_290280151 = "Antes de actuar, Sanki recupera todas las Espadas Sakae en el campo, las cuales infligen daño a los objetivos a lo largo de sus trayectorias.",
  str_skill_name_290280112 = "Corte transversal",
  str_skill_desc_290280112 = "Se acerca al Eclipsite más cercano y balancea la Espada Sakae horizontalmente, causando un enorme daño.",
  str_skill_name_290280122 = "Frenesí",
  str_skill_desc_290280122 = "Avanza hacia un enjambre de Eclipsites y lanza un torbellino frenético de cuchillas, infligiendo daño a todos los Eclipsites dentro de un cierto alcance.",
  str_skill_name_700110233 = "Abandonado: Corazón de León Golpe",
  str_skill_name_700110234 = "Forsaken: Puñetazo sobrealimentado",
  str_skill_name_700110235 = "Abandonado: Absorción de turbina",
  str_skill_desc_700110233 = "Se mueve y luego ataca a los objetivos cercanos.",
  str_skill_desc_700110234 = "Lanza puñetazos para infligir daño a 12 casillas en forma de diamante.",
  str_skill_desc_700110235 = "Atrae a los enemigos cerca y lanza un golpe devastador.",
  str_skill_name_700110413 = "Abandonado: Dios del Trueno",
  str_skill_name_700110414 = "Abandonados: Poder Justo",
  str_skill_name_700110415 = "Abandonado: Trueno Imperial",
  str_skill_desc_700110413 = "Se mueve y luego ataca a los objetivos cercanos.",
  str_skill_desc_700110414 = "Se mueve y luego invoca truenos que golpean 16 casillas en forma radial, infligiendo daño a los enemigos atrapados en el rango.",
  str_skill_desc_700110415 = "Inflige daño una vez a todos los enemigos en el campo de batalla y daño adicional equivalente al 10% del PS actual.",
  str_skill_desc_700110416 = "Se mueve y luego invoca truenos que golpean 16 casillas en forma radial, infligiendo daño a los enemigos atrapados en el rango.",
  str_skill_desc_700110417 = "Inflige daño una vez a todos los enemigos en el campo de batalla, y daño adicional equivalente al 15% del PS actual.",
  str_skill_name_111807112 = "Susurro del Pergamino",
  str_skill_desc_111807112 = "Aumenta tanto ATK como DEF al obtenerlo.",
  str_skill_name_111807113 = "Colector de pergaminos",
  str_skill_desc_111807113 = "Recupera rollos de pergamino encontrados en el campo de batalla.",
  str_skill_name_111807111 = "Invocador de Pergaminos",
  str_skill_desc_111807111 = "Invoca 3 rollos de pergamino en posiciones aleatorias en el campo de batalla.",
  str_skill_name_111807212 = "Invocador de Pergaminos",
  str_skill_desc_111807212 = "Convoca 5 rollos de pergamino en posiciones aleatorias en el campo de batalla.",
  str_skill_name_2002131 = "Amenaza detectada",
  str_skill_name_2102131 = "Amenaza detectada",
  str_skill_desc_2002131 = "Inflige un <color=#00F6FF>{1}%</color> de daño al enemigo más cercano, que obtiene un bono de daño adicional basado en el conteo de Chain Combo.",
  str_skill_desc_2102131 = "Inflige 3 instancias de daño al enemigo más cercano, cada una igual al 30% del daño original. El daño recibe un bono basado en la cantidad de ataques normales lanzados por el lanzador en esta ronda.",
  str_skill_name_300213 = "Control de área",
  str_skill_desc_300213 = "Selecciona 1 mosaico, desactiva temporalmente su elemento y genera <color=#00F6FF>un dominio cuadrado de 25 mosaicos</color> centrado en el mosaico seleccionado. Durante los siguientes <color=#00F6FF>15 segundos</color>, puedes tocar continuamente para intercambiar los elementos de los mosaicos adyacentes. El mosaico seleccionado se convertirá en <color=#00F6FF>Amarillo</color> cuando termine la cuenta atrás. Solo se puede lanzar 1 vez durante toda la batalla.",
  str_skill_name_302213 = "Control de área",
  str_skill_desc_302213 = "Selecciona 1 mosaico, deshabilita temporalmente su elemento y genera <color=#00F6FF>un dominio cuadrado de 25 mosaicos</color> centrado en el mosaico seleccionado. Durante los siguientes <color=#00F6FF>15 segundos</color>, puedes tocar continuamente para intercambiar los elementos de los mosaicos adyacentes. El mosaico seleccionado se convertirá en <color=#00F6FF>amarillo</color> cuando finalice la cuenta atrás. Otorga un uso al entrar en la batalla/en la 2ª ola.",
  str_skill_name_305213 = "Control de área",
  str_skill_desc_305213 = "Selecciona 1 mosaico, desactiva temporalmente su elemento y genera <color=#00F6FF>un dominio cuadrado de 25 mosaicos</color> centrado en el mosaico seleccionado. Durante los siguientes <color=#00F6FF>15 segundos</color>, puedes tocar continuamente para intercambiar los elementos de los mosaicos adyacentes. El mosaico seleccionado se convertirá en <color=#00F6FF>amarillo</color> cuando termine la cuenta regresiva. Otorga un lanzamiento al entrar en la batalla/la 2ª ola/la 7ª ronda.",
  str_skill_passive_name_410213 = "Hora de Erupción",
  str_skill_passive_desc_410213 = "Cuando el conteo de combos alcance <color=#00F6FF>{1}</color>, el Chain Combo actual lanza 3 instancias de daño, cada una igual al 30% del daño original. El daño recibe un bono basado en la cantidad de ataques normales realizados por el lanzador en esta ronda.",
  str_skill_passive_name_420213 = "Hora de Erupción",
  str_skill_passive_desc_420213 = "Cuando el conteo de combos alcanza <color=#00F6FF>{1}</color>, el Combo en Cadena actual lanza 3 instancias de daño, cada una igual al 30% del daño original. El daño obtiene un bono basado en la cantidad de ataques normales realizados por el lanzador en esta ronda y se puede desatar <color=#00F6FF>independientemente del elemento de las casillas enlazadas</color>.",
  str_skill_passive_name_430213 = "Hora de Erupción",
  str_skill_passive_desc_430213 = "Cuando el conteo de combos alcanza <color=#00F6FF>{1}</color>, el Combo en cadena actual lanza 3 instancias de daño, cada una igual al 30% del daño original. El daño obtiene un bono basado en la cantidad de ataques normales realizados por el lanzador en esta ronda y se puede desatar <color=#00F6FF>independientemente del elemento de las casillas enlazadas</color>. Cuando se agregan nuevas casillas a la cadena, la enésima casilla de esta cadena se convertirá en amarilla, siendo N el número de rondas restantes.",
  str_skill_upgrade_desc_15021312 = "Mejora de Habilidad Activa: Otorga un lanzamiento al entrar en la 2ª ola.",
  str_skill_upgrade_desc_15021315 = "Mejora de Habilidad Activa: Otorga un lanzamiento al entrar en la 7ª ronda.",
  str_skill_name_53520212 = "Convocar",
  str_skill_desc_53520212 = "Ataca primero a los Aurorianos si están cerca; si no, invoca más Lumopolis Pikers para obtener ayuda en combate.",
  str_skill_name_53520213 = "Animar",
  str_skill_desc_53520213 = "Ataca primero a los Aurorianos si están presentes en su cercanía; si no, inspira a los Soldados de Lumopolis cercanos, mejorando su ATK.",
  str_skill_name_53520411 = "Amenaza detectada",
  str_skill_desc_53520411 = "Absorbe energía de las losetas azules dentro de 2 grupos circundantes antes de infligir daño a los enemigos. Cuantas más losetas absorbidas, mayor será el daño.",
  str_skill_name_53520412 = "Amenaza detectada",
  str_skill_desc_53520412 = "Absorbe energía de las casillas rojas dentro de 2 grupos circundantes antes de infligir daño a los enemigos. Cuantas más casillas se absorban, mayor será el daño.",
  str_skill_name_53520413 = "Amenaza detectada",
  str_skill_desc_53520413 = "Absorbe energía de las losetas verdes dentro de 2 grupos circundantes antes de infligir daño a los enemigos. Cuantas más losetas se absorban, mayor será el daño.",
  str_skill_name_5352031 = "Explosión Fatal",
  str_skill_desc_5352031 = "Explota cada cierto tiempo, infligiendo daño a todas las unidades en el campo de batalla.",
  str_skill_name_29089011 = "Mazo del juez principal",
  str_skill_name_29089012 = "Veredicto del juez principal",
  str_skill_name_29089014 = "Mazo del juez principal",
  str_skill_desc_29089011 = "Lanza luz sagrada hacia donde estaba ubicado el objetivo en la ronda anterior, infligiendo daño a los objetivos en el camino y en las casillas adyacentes. El daño aumenta según las acumulaciones de Prejuicio del objetivo.",
  str_skill_desc_29089012 = "Bloquea la posición del objetivo e inflige un daño severo. El daño aumenta según las acumulaciones de Prejuicio del objetivo.",
  str_skill_desc_29089014 = "Lanza luz sagrada hacia donde estaba ubicado el objetivo en la ronda anterior, infligiendo daño a los objetivos en el camino y en las casillas adyacentes. El daño aumenta según las acumulaciones de Prejuicio del objetivo. Invoca una Estatua de Jurado en una ubicación fija.",
  str_skill_name_29089021 = "Mazo del juez principal",
  str_skill_desc_29089021 = "Lanza luz sagrada hacia donde estaba ubicado el objetivo en la ronda anterior, infligiendo daño a los objetivos en el camino y en las casillas adyacentes. El daño aumenta según las acumulaciones de Prejuicio del objetivo.",
  str_skill_name_290580101 = "Impacto del caos",
  str_skill_name_290580102 = "Toque Arcano",
  str_skill_name_290580103 = "Marcha a la destrucción",
  str_skill_name_290580104 = "Fin del Destino",
  str_skill_desc_290580101 = "Inflige daño a todos los objetivos en forma de abanico y los hace retroceder a la mayor distancia posible.",
  str_skill_desc_290580102 = "Se teletransporta una vez e inflige daño al jugador, luego lo empuja hacia atrás 2 casillas.",
  str_skill_desc_290580103 = "Marca 2 cúmulos circundantes alrededor del objetivo y, al comienzo del turno de los monstruos, desata un daño severo en el área marcada y empuja a los objetivos hacia atrás 3 casillas.",
  str_skill_desc_290580104 = "Entra en un estado de carga; inflige un enorme daño al jugador si no se mueve o es empujado hacia atrás al comienzo de la ronda de los enemigos.",
  str_skill_desc_2905801011 = "Inflige daño a todos los objetivos dentro de una forma de abanico.",
  str_skill_desc_2905801021 = "Se teletransporta una vez e inflige daño al jugador.",
  str_skill_desc_2905801031 = "Marca 2 grupos circundantes alrededor del objetivo y desata un daño severo en el área marcada al comienzo de la ronda de los enemigos.",
  str_skill_desc_2905801022 = "Se teletransporta una vez, inflige daño al jugador y lo silencia.",
  str_skill_name_2001871 = "Destino en una Pincelada",
  str_skill_name_2001872 = "Destino en una Pincelada",
  str_skill_name_2001873 = "Destino en una Pincelada",
  str_skill_name_3001871 = "Juicio hexagramático",
  str_skill_name_3051871 = "Juicio hexagramático",
  str_skill_passive_name_410187 = "Acto de Todas las Cosas",
  str_skill_passive_name_420187 = "Acto de Todas las Cosas",
  str_skill_passive_name_430187 = "Acto de Todas las Cosas",
  str_skill_desc_2001871 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2001872 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 3 enemigos más cercanos.",
  str_skill_desc_2001873 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 4 enemigos más cercanos.",
  str_skill_desc_3001871 = "Inflige aleatoriamente <color=#00F6FF>90%</color> de daño <color=#00F6FF>6</color> veces a enemigos dentro de <color=#00F6FF>13 casillas en forma de diamante</color> centradas en 1 casilla seleccionada.",
  str_skill_desc_3051871 = "Inflige aleatoriamente <color=#00F6FF>90%</color> de daño <color=#00F6FF>8</color> veces a enemigos dentro de <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado.",
  str_skill_passive_desc_410187 = "Si no hay enemigos dentro de <color=#00F6FF>1 cúmulo circundante</color>, cada instancia del Combo en cadena tiene una probabilidad del <color=#00F6FF>25%</color> de infligir <color=#00F6FF>{1}×</color> de daño.",
  str_skill_passive_desc_420187 = "Si no hay enemigos dentro de <color=#00F6FF>1 grupo circundante</color>, cada instancia de la Habilidad Activa y Combo en Cadena tiene una probabilidad del <color=#00F6FF>25%</color> de infligir <color=#00F6FF>{1}×</color> de daño.",
