  str_skill_passive_desc_410215 = "Cuando Isa realiza Ataques Normales en <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link>, infligen <color=#00F6FF>{1}</color> de daño 3 veces.",
  str_skill_passive_desc_420215 = "Cuando Isa lanza ataques normales en <link=\"30093\"><#FFAE07><u>Azulejos oscuros</u></color></link>, infligen <color=#00F6FF>{1}</color> de daño 3 veces. Después de que Isa dañe al mismo enemigo <color=#00F6FF>7 veces</color> con su ataque normal, inflige daño adicional igual al <color=#00F6FF>100%</color> de su ATK.",
  str_skill_passive_desc_430215 = "Cuando Isa lanza ataques normales en <link=\"30093\"><#FFAE07><u>Azulejos Oscuros</u></color></link>, infligen <color=#00F6FF>{1}</color> de daño 3 veces. Después de que Isa cause daño al mismo enemigo <color=#00F6FF>7 veces</color> con su ataque normal y/o combo en cadena, inflige daño adicional igual al <color=#00F6FF>100%</color> de su ATK. Golpear a un objetivo con su habilidad activa también activará daño adicional 1 vez.",
  str_skill_passive_desc_425215 = "Cuando Isa lanza ataques normales en <link=\"30093\"><#FFAE07><u>Azulejos oscuros</u></color></link>, infligen <color=#00F6FF>{1}</color> de daño 3 veces. Después de que Isa cause daño al mismo enemigo <color=#00F6FF>7 veces</color> con su ataque normal, inflige daño adicional igual al <color=#00F6FF>150%</color> de su ATK.",
  str_skill_passive_desc_435215 = "Cuando Isa lanza ataques normales en <link=\"30093\"><#FFAE07><u>Azulejos Oscuros</u></color></link>, infligen <color=#00F6FF>{1}</color> de daño 3 veces. Después de que Isa dañe al mismo enemigo <color=#00F6FF>7 veces</color> con su ataque normal y/o combo en cadena, inflige daño adicional igual al <color=#00F6FF>150%</color> de su ATK. Golpear a un objetivo con su habilidad activa también activará daño adicional 1 vez.",
