  str_skill_name_3402141 = "Baile de Mariposas",
  str_skill_name_3462141 = "Baile de Mariposas",
  str_skill_desc_2002141 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2002142 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 16 casillas en forma radial </color>.",
  str_skill_desc_2002143 = "ofertas <color=#00F6FF>{1}%</color> daño <color=#00F6FF>en forma radial al rango máximo</color>.",
  str_skill_desc_2202141 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>. Inflige <color=#00F6FF>1</color> pila de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2202142 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color>. Inflige <color=#00F6FF>1</color> pila de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2202143 = "Inflige un <color=#00F6FF>{1}%</color> de daño <color=#00F6FF>en forma radial hasta el alcance máximo</color>. Inflige <color=#00F6FF>1</color> pila de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2302141 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>. Inflige <color=#00F6FF>1</color> pila de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2302142 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color>. Inflige <color=#00F6FF>1</color> pila de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2302143 = "Inflige un <color=#00F6FF>{1}%</color> de daño <color=#00F6FF>en forma radial hasta el alcance máximo</color>. Inflige <color=#00F6FF>1</color> pila de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2402141 = "Inflige <color=#00F6FF>145%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>. Inflige <color=#00F6FF>2</color> acumulaciones de Inmersión en todos los objetivos dentro del alcance.",
  str_skill_desc_2402142 = "Inflige un <color=#00F6FF>160%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color>. Inflige <color=#00F6FF>2</color> acumulaciones de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_2402143 = "Inflige un <color=#00F6FF>165%</color> de daño <color=#00F6FF>en forma radial hasta el alcance máximo</color>. Inflige <color=#00F6FF>2</color> pilas de Inmersión a todos los objetivos dentro del alcance.",
  str_skill_desc_3002141 = "Convierte 1 casilla seleccionada en una <link=\"30093\"><#FFAE07><u>Casilla Oscura Azul</u></color></link> y convierte las <color=#00F6FF>3</color> casillas azules más cercanas a esta casilla en Casillas Oscuras Azules.",
  str_skill_desc_3062141 = "Convierte 1 casilla seleccionada en una <link=\"30093\"><#FFAE07><u>Casilla Azul Oscura</u></color></link> y convierte las <color=#00F6FF>5</color> casillas azules más cercanas a esta casilla en Casillas Azules Oscuras.",
  str_skill_passive_name_410214 = "Metástasis venenosa",
  str_skill_passive_desc_410214 = "Cada vez que pases por una Casilla Oscura, inflige <link=\"30094\"><#FFAE07><u>Inmersión</u></color></link> en <color=#00F6FF>12 casillas en forma de diamante</color>. Al inicio de la ronda enemiga, cada pila de Inmersión inflige daño igual a <color=#00F6FF>{1}</color> del ATK al objetivo.",
  str_skill_passive_name_430214 = "Metástasis venenosa",
  str_skill_passive_desc_430214 = "Cada vez que pases por una Casilla Oscura, inflige <link=\"30094\"><#FFAE07><u>Inmersión</u></color></link> en <color=#00F6FF>12 casillas en forma de diamante</color>. Al comienzo de la ronda enemiga, cada pila de Inmersión inflige daño igual a <color=#00F6FF>{1}</color> de ATK al objetivo. La Inmersión inflige daño que ignora la DEF a los enemigos golpeados por un Combo en Cadena en esta ronda.",
  str_skill_upgrade_desc_16021413 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16021416 = "Mejora de Habilidad Activa: Convierte <color=#FFFF00>5</color> casillas azules más cercanas a la casilla seleccionada en casillas azules oscuras.",
  str_skill_upgrade_refine_desc_16021411 = "Mejora de habilidades de equipo: Cada acumulación de Inmersión inflige daño igual al <color=#00F6FF>40%</color> del ATK de Rebecca al objetivo.",
  str_skill_upgrade_refine_desc_16021412 = "Mejora del Combo en Cadena: El Combo en Cadena inflige <color=#00F6FF>2</color> acumulaciones de Inmersión en todos los objetivos dentro del alcance.",
  str_skill_upgrade_refine_desc_16021413 = "Mejora de habilidad activa: Al lanzar la Habilidad Activa, se provoca daño 1 vez en todos los objetivos con Inmersión, infligiendo el doble de daño.",
  str_skill_passive_desc_440214 = "Cada vez que pases por una Casilla Oscura, inflige <link=\"30094\"><#FFAE07><u>Inmersión</u></color></link> en <color=#00F6FF>12 casillas en forma de diamante</color>. Al inicio de la ronda enemiga, cada pila de Inmersión inflige daño igual al <color=#00F6FF>40%</color> del ATK al objetivo. La Inmersión inflige daño que ignora la DEF a los enemigos golpeados por un Combo en Cadena en esta ronda.",
  str_skill_desc_3402141 = "Convierte 1 mosaico seleccionado en un <link=\"30093\"><#FFAE07><u>Mosaico Azul Oscuro</u></color></link> y convierte los <color=#00F6FF>3</color> mosaicos azules más cercanos a este en Mosaicos Azules Oscuros, luego provoca daño 1 vez en todos los objetivos en el campo con Inmersión, infligiendo el doble de daño.",
  str_skill_desc_3462141 = "Convierte 1 casilla seleccionada en un <link=\"30093\"><#FFAE07><u>Mosaico Azul Oscuro</u></color></link> y convierte las <color=#00F6FF>5</color> casillas azules más cercanas a esta casilla en Mosaicos Azules Oscuros, luego provoca daño 1 vez en todos los objetivos en el campo con Inmersión, infligiendo el doble de daño.",
