  str_skill_name_290910103 = "Mariposa venenosa",
  str_skill_name_290910104 = "Embestida de Mariposas",
  str_skill_desc_290910102 = "Se mueve y luego ataca a los enemigos dentro de 2 casillas en forma de cruz, infligiéndoles 2 acumulaciones de Fusión. Al comienzo de cada ronda, cada acumulación de Fusión inflige daño basado en un porcentaje del ATK de Rebecca Venomswamp.",
  str_skill_desc_290910103 = "Se aleja del objetivo, luego inflige daño e impone 1 acumulación de Fusión. Al comienzo de cada ronda, cada acumulación de Fusión inflige daño basado en un porcentaje del ATK de Rebecca Venomswamp.",
  str_skill_desc_290910104 = "Después de moverse, inflige daño dentro de un alcance fijo, aplica 3 pilas de Fusión e invoca aleatoriamente varias Marcas de Veneno dentro del rango.",
  str_skill_name_200390101 = "Golpe Mecánico",
  str_skill_desc_200390101 = "Ataca al enemigo más cercano. Si tiene menos del 40% de HP, recupera un cierto porcentaje de HP después de alejarse.",
  str_skill_name_200390102 = "Ataque curativo",
  str_skill_desc_200390102 = "Recupera cierto porcentaje de HP.",
  str_skill_name_200410101 = "Asesinato",
  str_skill_desc_200410101 = "Ataca al objetivo 2 veces después de moverse y luego retrocede hasta 2 casillas. Si no hay objetivos dentro del alcance, aumenta ACT en la siguiente ronda.",
  str_skill_name_9997042 = "Quemador flotante",
