  str_skill_name_200140111 = "Tentaclaw - Prevención de daños",
  str_skill_desc_200140111 = "El daño sostenido de Tentaclaw se pasa a Kittypus. Pero antes de que un Aurorian libere el Combo de Cadena, el tentaclaw se enrosca para evitar ataques.",
  str_skill_name_5000591 = "Repeler Goldor",
  str_skill_desc_5000591 = "Inflige daño y hace retroceder a todos los objetivos una vez.",
  str_skill_name_5000592 = "Purificando Goldor",
  str_skill_desc_5000592 = "Inflige daño a todos los objetivos frente a él una vez.",
  str_skill_name_5000593 = "Frenesí de huida",
  str_skill_desc_5000593 = "Después de que un auroriano lance una Habilidad Activa, las fichas amarillas aleatorias se convertirán en fichas rojas mientras se mueven.",
  str_skill_name_5000594 = "Calidez compartida",
  str_skill_desc_5000594 = "Siempre te acercarás a Goldor sin importar dónde estés.",
  str_skill_name_29092001 = "Pinza desgarradora",
  str_skill_desc_29092001 = "Stinger inflige daño a los objetivos dentro de 1 cúmulo circundante de sí mismo 2 veces e inflige efectos de Sangrado.",
  str_skill_desc_290920011 = "Stinger inflige daño a los objetivos dentro de 1 cúmulo circundante de sí mismo 2 veces e inflige Sangrado y efectos de No Curación.",
  str_skill_name_29092002 = "Choque montañoso",
  str_skill_desc_29092002 = "Stinger selecciona 1 dirección donde un jugador está en un área en forma de cruz, se lanza hacia el borde del campo o el obstáculo más cercano y luego derriba a todos los objetivos a lo largo de su camino, infligiendo daño adicional a los objetivos dentro de 1 casilla a ambos lados de su trayectoria e infligiéndoles Sangrado.",
  str_skill_name_29092003 = "Inmolar",
  str_skill_desc_29092003 = "Stinger dispara un rayo de Energía desde su cola, infligiendo un enorme daño al objetivo 1 vez.",
  str_skill_name_29092004 = "Empuje cargado",
  str_skill_desc_29092004 = "Stinger salta hacia atrás 1 casilla, infligiendo daño a los objetivos frente a él e infligiéndoles efectos de Sangrado y Veneno.",
  str_skill_name_29092005 = "Estampida desenfrenada",
  str_skill_desc_29092005 = "Stinger avanza hacia adelante horizontal y verticalmente de manera sucesiva, infligiendo daño a los objetivos frente a él e infligiéndoles efectos de Sangrado y Veneno.",
  str_skill_name_29092006 = "Reflejo de espejo",
  str_skill_desc_29092006 = "Stinger dispara rayos a las mariposas de espejo, formando un camino triangular con la luz que reflejan e infligiendo daño a todo en su camino.",
  str_skill_name_2002161 = "Tirón de sombrilla",
  str_skill_name_2002162 = "Tirón de sombrilla",
