  str_skill_name_300216 = "Destello de rayo",
  str_skill_name_303216 = "Destello de rayo",
  str_skill_passive_name_410216 = "Perímetro de la libélula",
  str_skill_passive_name_430216 = "Perímetro de la libélula",
  str_skill_desc_2002161 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2002162 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 3 enemigos más cercanos.",
  str_skill_desc_2002163 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 4 enemigos más cercanos.",
  str_skill_desc_2202161 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos, luego inflige daño una vez más a 1 enemigo aleatorio dentro de un Array de Trueno Cuadrado.",
  str_skill_desc_2202162 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 3 enemigos más cercanos, luego inflige daño una vez más a 1 enemigo aleatorio dentro de un Arreglo Cuadrado de Trueno.",
  str_skill_desc_2202163 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 4 enemigos más cercanos, luego inflige daño una vez más a 1 enemigo aleatorio dentro de un Array de Trueno Cuadrado.",
  str_skill_desc_300216 = "Consume 3 <link=\"30095\"><#FFAE07><u>Piezas de Repuesto</u></color></link> para seleccionar cualquier casilla y generar un Arreglo Cuadrado de Truenos dentro de <color=#00F6FF>9 casillas en forma cuadrada</color> que dura <color=#00F6FF>2</color> rondas. El ataque normal de Xuan Ji <color=#00F6FF>puede lanzarse en diagonal</color> dentro de un Arreglo Cuadrado de Truenos.",
  str_skill_desc_303216 = "Consume 3 <link=\"30095\"><#FFAE07><u>Piezas de Repuesto</u></color></link> para seleccionar cualquier casilla y generar un Arreglo Cuadrado de Truenos dentro de <color=#00F6FF>25 casillas en forma cuadrada</color> que dura <color=#00F6FF>3</color> rondas. El ataque normal de Xuan Ji <color=#00F6FF>puede lanzarse en diagonal</color> dentro de un Arreglo Cuadrado de Truenos.",
  str_skill_passive_desc_410216 = "Aumenta el daño de Xuan Ji en una Matriz Cuadrada de Trueno en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416216 = "Aumenta el daño de Xuan Ji en un Arreglo de Trueno Cuadrado en <color=#00F6FF>{1}</color>. Su daño se incrementa en <color=#00F6FF>5%</color> por cada Arreglo de Trueno Cuadrado adicional en el campo. Si Xuan Ji está dentro de un Arreglo de Trueno Cuadrado al finalizar la ronda, obtiene 1 Pieza de Repuesto.",
  str_skill_passive_desc_430216 = "Aumenta el daño de Xuan Ji en una Matriz de Trueno Cuadrada en <color=#00F6FF>{1}</color>. Siempre que Xuan Ji esté dentro de una Matriz de Trueno Cuadrada después de lanzar su Combo en Cadena, su ATK básico aumenta en <color=#00F6FF>4%</color>, acumulándose hasta 5 veces. Si no está dentro de una Matriz de Trueno Cuadrada cuando termina la ronda, las acumulaciones de este efecto se reducen a la mitad.",
  str_skill_passive_desc_436216 = "Aumenta el daño de Xuan Ji en una Matriz de Trueno Cuadrada en <color=#00F6FF>{1}</color>. Su daño se incrementa en <color=#00F6FF>5%</color> por cada Matriz de Trueno Cuadrada adicional en el campo. Si Xuan Ji está dentro de una Matriz de Trueno Cuadrada cuando termina la ronda, obtiene 1 Pieza de Repuesto. Siempre que Xuan Ji esté dentro de una Matriz de Trueno Cuadrada después de lanzar su Chain Combo, su ATK básico aumenta en <color=#00F6FF>4%</color>, acumulándose hasta 5 veces. Si no está dentro de una Matriz de Trueno Cuadrada cuando termina la ronda, las acumulaciones de este efecto se reducen a la mitad.",
  str_skill_upgrade_desc_16021613 = "Mejora de Habilidad Activa: Amplía el área del Array de Trueno Cuadrado a <color=#00F6FF>25 casillas en forma de cuadrado</color>. Dura <color=#00F6FF>3</color> rondas.",
  str_skill_upgrade_desc_16021616 = "Mejora de habilidades de equipo: el daño de Xuan Ji se incrementa aún más en un <color=#00F6FF>5%</color> por cada Cuadrado de Matriz de Trueno adicional en el campo. Si Xuan Ji está dentro de un Cuadrado de Matriz de Trueno cuando termina la ronda, ella gana 1 Pieza de Repuesto.",
  str_skill_name_53820323 = "Explota cuando los Aurorianos se acercan. Si se deja solo, explotará después de un cierto número de rondas y generará varias llamas a su alrededor.",
  str_skill_name_200400103 = "Fuego Abdominal",
  str_skill_name_200400104 = "Fuego Abdominal",
  str_skill_desc_200400103 = "Se mueve lateralmente y escupe llamas, causando daño a los enemigos frente a él. Se detiene de moverse cuando encuentra obstáculos.",
  str_skill_desc_200400104 = "Se mueve lateralmente y escupe llamas, causando daño a los enemigos frente a él. Se detiene de moverse cuando encuentra obstáculos.",
  str_skill_name_290570123 = "Mudbundle: Devorador",
  str_skill_desc_290570123 = "Mudbundle emerge del centro del gran pantano, devorando todo e infligiendo daño a los aurorianos.",
  str_skill_name_290620102 = "Cortador Espacial: Latitud",
  str_skill_desc_290620102 = "Vilanor se precipita y asesta un golpe, causando daño y lanzando un Muro Prohibido de 3 casillas de largo horizontalmente junto a los Aurorianos y se teletransporta a una nueva ubicación.",
  str_skill_name_290620104 = "Cortador Espacial: Longitud",
  str_skill_desc_290620104 = "Vilanor se apresura y corta, infligiendo daño y lanzando un Muro Prohibido de 3 casillas de longitud verticalmente al lado de los Aurorianos y se teletransporta a una nueva ubicación.",
  str_skill_name_290620106 = "Mantente Alejado",
  str_skill_desc_290620106 = "Vilanor inflige daño a los enemigos dentro de 1 grupo circundante y los empuja hacia la ubicación más lejana posible, luego lanza una Pared Prohibida en el borde exterior de los mosaicos dentro de 1 grupo circundante.",
  str_skill_name_800400011 = "Trampa de Exorcismo",
  str_skill_desc_800400011 = "Al pisar una Trampa de Exorcismo, se eliminarán todas las Paredes Prohibidas en el campo.",
  str_skill_desc_2900273 = "Inflige daño a los Aurorianos en cualquier lugar del campo de batalla y convoca a Goldor.",
  str_skill_desc_2000303 = "Paga Oro para recuperar el PS de Goldor Maldito cuando está dentro de 1 cúmulo circundante de él.",
  str_skill_desc_2000304 = "Cuando está dentro de 1 cúmulo circundante de Istvan, paga Oro para recuperar su PS.",
  str_skill_desc_200381101 = "Aumenta el rango de movimiento, luego se acerca al objetivo e inflige daño 2 veces. Este movimiento no se ve obstaculizado por obstáculos.",
  str_skill_desc_200411101 = "Ataca al objetivo 2 veces después de moverse, derribando al objetivo y dejando una bomba, luego se retira hasta 3 casillas. Si no hay objetivos dentro del rango, aumenta ACT en la próxima ronda.",
  str_skill_desc_200371101 = "Inflige daño a los enemigos dentro de un rango de 3 casillas en forma de cruz, los derriba y deja una bomba donde estaban antes de ser derribados.",
  str_skill_upgrade_desc_16021913 = "Mejora de Habilidad Activa: Obtén <color=#00F6FF>5</color> Dotaciones de Sombra al entrar en batalla.\nMejora de Habilidad de Equipo: Amplía el rango de selección de Movimiento de Ajedrez a 2 grupos circundantes.",
  str_skill_upgrade_desc_16021916 = "Obtén Nueva Habilidad Activa: Selecciona cualquier <color=#00F6FF>2</color> casillas e intercambia las Casillas Oscuras en estas 2 casillas. Si hay una Pieza de Sombra en una casilla seleccionada, la Pieza de Sombra también se cambiará a la otra casilla.",
  str_skill_name_2002191 = "Garras ardientes",
  str_skill_name_2002192 = "Garras ardientes",
  str_skill_name_2002193 = "Garras ardientes",
  str_skill_desc_2002191 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 4 enemigos más cercanos dentro de <color=#00F6FF> 2 cúmulos circundantes </color>.",
  str_skill_desc_2002192 = "ofertas <color=#00F6FF>{1}%</color> daño a los 4 enemigos más cercanos dentro <color=#00F6FF>3 grupos circundantes</color>.",
  str_skill_desc_2002193 = "ofertas <color=#00F6FF>{1}%</color> daño a los 4 enemigos más cercanos dentro <color=#00F6FF>4 círculos circundantes</color>.",
  str_skill_name_3002191 = "Enroque Sombra",
  str_skill_name_3302191 = "Enroque Sombra",
  str_skill_name_3032191 = "Enroque Sombra",
  str_skill_name_3332191 = "Enroque Sombra",
  str_skill_name_3062191 = "Transferencia de sombra",
  str_skill_desc_3002191 = "Consume <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>Dotaciones de Sombra</u></color></link> y selecciona <color=#00F6FF>un aliado</color> para que pueda <color=#00F6FF>lanzar su Combo en Cadena 1 vez más</color> en esta ronda (este efecto no se acumula). Al lanzar el Combo en Cadena adicional, el ATQ del aliado será igual al <color=#00F6FF>100%</color> del ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith no lanzará un Combo en Cadena en esta ronda. Cada vez que se lanza la Habilidad Activa en el mismo aliado en esta batalla, +1 costo de Dotación de Sombra.",
  str_skill_desc_3302191 = "Consume <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>Dotaciones de Sombra</u></color></link> y selecciona <color=#00F6FF>un aliado</color> para que pueda <color=#00F6FF>lanzar su Combo en Cadena 1 vez más</color> en esta ronda (este efecto no se acumula). Al lanzar el Combo en Cadena adicional, el ATQ del aliado será igual al <color=#00F6FF>100%</color> del ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith no lanzará un Combo en Cadena en esta ronda. Alternativamente, consume <color=#00F6FF>2</color> Dones de Sombra para seleccionar una Pieza de Sombra en el campo y lanzar la Habilidad Activa, que hace que la Pieza de Sombra lance un Combo en Cadena en lugar de Istvan: Médula Cicatrizada en esta ronda, y el daño final se incrementará en <color=#00F6FF>50%</color>. El costo del Don de Sombra siempre será 2 cuando se lance esto en la Pieza de Sombra. Cada vez que la Habilidad Activa se lanza sobre el mismo aliado en esta batalla, +1 costo de Don de Sombra.",
  str_skill_desc_3032191 = "Consume <color=#00F6FF>2</color> <link=\"30097\"><#FFAE07><u>Dotaciones de Sombra</u></color></link> y selecciona <color=#00F6FF>un aliado</color> para que pueda <color=#00F6FF>lanzar su Combo en Cadena 1 vez más</color> en esta ronda (este efecto no se acumula). Al lanzar el Combo en Cadena adicional, el ATQ del aliado será igual al <color=#00F6FF>100%</color> del ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith no lanzará un Combo en Cadena en esta ronda. Cada vez que se lanza la Habilidad Activa en el mismo aliado en esta batalla, +1 costo de Dotación de Sombra.",
  str_skill_desc_3332191 = "Consume <color=#00F6FF>2</color> <link=\"30097\"><#FFAE07><u>Dotaciones de Sombra</u></color></link> y selecciona <color=#00F6FF>un aliado</color> para que pueda <color=#00F6FF>lanzar su Combo en Cadena 1 vez más</color> en esta ronda (este efecto no se acumula). Al lanzar el Combo en Cadena adicional, el ATQ del aliado será igual al <color=#00F6FF>100%</color> del ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith no lanzará un Combo en Cadena en esta ronda. Alternativamente, consume <color=#00F6FF>2</color> Dones de Sombra para seleccionar una Pieza de Sombra en el campo y lanzar la Habilidad Activa, que hace que la Pieza de Sombra lance un Combo en Cadena en lugar de Istvan: Médula Cicatrizada en esta ronda, y el daño final se incrementará en <color=#00F6FF>50%</color>. El costo del Don de Sombra siempre será 2 cuando se lance esto en la Pieza de Sombra. Cada vez que la Habilidad Activa se lanza sobre el mismo aliado en esta batalla, +1 costo de Don de Sombra.",
  str_skill_desc_3062191 = "Selecciona cualquier <color=#00F6FF>2</color> mosaicos e intercambia los mosaicos oscuros en estos 2 mosaicos. Si hay una pieza de sombra en un mosaico seleccionado, la pieza de sombra también se cambiará al otro mosaico.",
  str_skill_passive_name_410219 = "Promoción de sombras",
  str_skill_passive_name_420219 = "Promoción de sombras",
  str_skill_passive_name_403219 = "Promoción de sombras",
  str_skill_passive_name_423219 = "Promoción de sombras",
  str_skill_passive_desc_410219 = "Al entrar en batalla, Istvan: Scarred Pith invoca 1 Pieza de Sombra cerca de los Aurorianos que pueden lanzar habilidades.\nMovimiento de Ajedrez: Se teletransporta a una casilla transitable dentro de <color=#00F6FF>12 casillas en forma de diamante</color> e inflige <color=#00F6FF>{1}</color> de daño a los 4 enemigos más cercanos dentro de <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_passive_desc_420219 = "Al entrar en batalla, Istvan: Scarred Pith invoca 1 Pieza de Sombra cerca de los Aurorianos que pueden lanzar habilidades. Cuando termina la ronda, la Pieza de Sombra genera una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link> debajo de ella.\nMovimiento de Ajedrez: Se teletransporta a una casilla transitable dentro de <color=#00F6FF>12 casillas en forma de diamante</color> e inflige <color=#00F6FF>{1}</color> de daño a los 4 enemigos más cercanos dentro de <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_passive_desc_403219 = "Al entrar en batalla, Istvan: Scarred Pith invoca 1 Pieza de Sombra cerca de los Aurorianos que pueden lanzar habilidades.\nMovimiento de Ajedrez: Se teletransporta a una casilla transitable dentro de <color=#00F6FF>2 cúmulos circundantes</color> e inflige <color=#00F6FF>{1}</color> daño a los 4 enemigos más cercanos dentro de <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_passive_desc_423219 = "Al entrar en batalla, Istvan: Scarred Pith invoca 1 Pieza de Sombra cerca de los Aurorianos que pueden lanzar habilidades. Cuando termina la ronda, la Pieza de Sombra genera una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link> debajo de ella.\nMovimiento de Ajedrez: Se teletransporta a una casilla transitable dentro de <color=#00F6FF>2 grupos circundantes</color> e inflige <color=#00F6FF>{1}</color> de daño a los 4 enemigos más cercanos dentro de <color=#00F6FF>2 grupos circundantes</color>.",
