  str_skill_name_3022201 = "Exposición completa",
  str_skill_desc_20022011 = "Inflige <color=#00F6FF>125%</color> de daño 2 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002202 = "ofertas <color=#00F6FF>130%</color> daño 3 veces, asignado aleatoriamente a los enemigos dentro <color=#00F6FF>3 grupos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002203 = "Inflige <color=#00F6FF>135%</color> de daño 4 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_3002201 = "Convierte las <color=#00F6FF>2</color> casillas Amarillas más cercanas en casillas Azules Oscuras.",
  str_skill_desc_3002202 = "Convierte <color=#00F6FF>2</color> casillas amarillas más cercanas en Casillas Azules Oscuras. Si la Habilidad Activa estuvo lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_3052201 = "Convierte las <color=#00F6FF>3</color> casillas amarillas más cercanas en casillas azules oscuras. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_desc_3052202 = "Convierte las <color=#00F6FF>3</color> casillas amarillas más cercanas en casillas azules oscuras. Si la Habilidad Activa está lista en la última ronda, aumenta el conteo de conversión de casillas por <color=#00F6FF>+1</color> en esta ronda.",
  str_skill_passive_name_410220 = "Reflejos caleidoscópicos",
  str_skill_passive_name_420220 = "Reflejos caleidoscópicos",
  str_skill_passive_name_430220 = "Reflejos caleidoscópicos",
  str_skill_passive_desc_410220 = "Al inicio de cada ronda, inflige <color=#00F6FF>Valoración</color> al objetivo más lejano en el campo durante 1 ronda. Cada vez que un objetivo con Valoración es golpeado por 1 habilidad de Combo en Cadena de objetivo único, se lanza 1 ataque adicional al objetivo, infligiendo daño igual a <color=#00F6FF>{1}</color> del ATQ de Vergil.",
  str_skill_passive_desc_420220 = "Al inicio de cada ronda, inflige <color=#00F6FF>Evaluación</color> al objetivo más lejano en el campo durante 1 ronda. Al entrar en la Hora de Aurora, tiene efecto 1 vez adicional. Cada vez que un objetivo con Evaluación es golpeado por 1 habilidad de Combo en Cadena de objetivo único, se lanza 1 ataque extra al objetivo, causando daño igual al <color=#00F6FF>{1}</color> del ATQ de Vergil.",
  str_skill_passive_desc_430220 = "Al inicio de cada ronda, inflige <color=#00F6FF>Evaluación</color> al objetivo más lejano en el campo durante 1 ronda. Al entrar en Hora de Aurora, tiene efecto 1 vez adicional. Cada vez que un objetivo con Evaluación es golpeado por 1 habilidad de Combo en Cadena de objetivo único, se lanza 1 ataque extra al objetivo, causando daño igual a <color=#00F6FF>{1}</color> del ATQ de Vergil. Cuando el objetivo es golpeado por el Combo en Cadena de Vergil, este daño adicional se duplica.",
  str_skill_upgrade_desc_15022012 = "Mejora Habilidad Activa: Si la Habilidad Activa estaba lista en la última ronda, convierte 1 casilla amarilla adicional en una Casilla Azul Oscuro en esta ronda.",
  str_skill_upgrade_desc_15022015 = "Mejora Habilidad Activa: Aumenta el número de casillas convertidas en Casillas Azules Oscuras en 1.",
