  str_skill_passive_name_436218 = "Sobre el Capital",
  str_skill_desc_2002181 = "Inflige <color=#00F6FF>150%</color> de daño a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> 3 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002182 = "Inflige <color=#00F6FF>155%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 4 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002183 = "Inflige <color=#00F6FF>165%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 5 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002184 = "Inflige <color=#00F6FF>150%</color> de daño a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> 3 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Inflige daño 1 vez adicional al objetivo más lejano.",
  str_skill_desc_2002185 = "Inflige <color=#00F6FF>155%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 4 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Inflige daño 1 vez adicional al objetivo más lejano.",
  str_skill_desc_2002186 = "Inflige <color=#00F6FF>165%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 5 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Inflige daño 1 vez adicional al objetivo más lejano.",
  str_skill_desc_2202181 = "Inflige <color=#00F6FF>150%</color> de daño a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> 3 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Por cada mosaico oscuro que se atraviesa al conectar mosaicos esta vez, el rango del Combo de Cadena se expande en 1 cúmulo circundante.",
  str_skill_desc_2202182 = "Inflige <color=#00F6FF>155%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 4 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Por cada mosaico oscuro que se atraviesa al conectar mosaicos esta vez, el rango del Combo en cadena se expande en 1 cúmulo circundante.",
  str_skill_desc_2202183 = "Inflige <color=#00F6FF>165%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 5 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Por cada mosaico oscuro que se atraviesa al conectar mosaicos esta vez, el rango del Combo en cadena se expande en 1 cúmulo circundante.",
  str_skill_desc_2202184 = "Inflige <color=#00F6FF>150%</color> de daño a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> 3 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo. Por cada ficha oscura que se pasa al conectar fichas esta vez, el rango del Chain Combo se expande en 1 cúmulo circundante.",
  str_skill_desc_2202185 = "Inflige <color=#00F6FF>155%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 4 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo. Por cada ficha oscura que se pasa al conectar fichas esta vez, el rango del Chain Combo se expande en 1 cúmulo circundante.",
  str_skill_desc_2202186 = "Inflige <color=#00F6FF>165%</color> de daño a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> 5 veces en un orden fijo. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad. Inflige daño 1 vez adicional al objetivo más lejano. Este daño adicional no se reducirá a la mitad al infligir daño al mismo objetivo. Por cada mosaico oscuro que se pasa al conectar mosaicos esta vez, el rango del Combo de Cadena se expande en 1 cúmulo circundante.",
  str_skill_desc_3002181 = "Convierte 1 casilla seleccionada en una <link=\"30093\"><#FFAE07><u>Casilla Oscura Azul</u></color></link> e inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color>.",
  str_skill_desc_30021811 = "Convierte 1 casilla seleccionada en un <link=\"30093\"><#FFAE07><u>Azulejo Oscuro</u></color></link> Azul e inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color>.",
  str_skill_desc_3402181 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color> centradas en 1 casilla seleccionada.",
  str_skill_desc_3412181 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centrado en 1 casilla seleccionada.",
  str_skill_desc_3402182 = "Convierte 1 casilla seleccionada en una <link=\"30093\"><#FFAE07><u>Casilla Oscura Azul</u></color></link> e inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color>. Por cada 5 puntos de Capital, obtiene 1 Capital adicional como dividendo.",
  str_skill_desc_3412182 = "Convierte 1 mosaico seleccionado en un <link=\"30093\"><#FFAE07><u>Mosaico Oscuro Azul</u></color></link> e inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color>. Por cada 5 puntos de Capital, obtiene 1 Capital adicional como dividendo.",
  str_skill_desc_30021812 = "Convierte 1 casilla seleccionada en una <link=\"30093\"><#FFAE07><u>Casilla Oscura Azul</u></color></link> e inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color>.",
  str_skill_desc_300218112 = "Convierte 1 mosaico seleccionado en un <link=\"30093\"><#FFAE07><u>Azulejo Oscuro</u></color></link> Azul e inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>13 fichas en forma de diamante</color>.",
  str_skill_desc_34021812 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Inflige un <color=#00F6FF>150%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color> centradas en 1 casilla seleccionada.",
  str_skill_desc_34121812 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrados en 1 mosaico seleccionado.",
  str_skill_desc_34021822 = "Convierte 1 casilla seleccionada en una <link=\"30093\"><#FFAE07><u>Casilla Oscura Azul</u></color></link> e inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>5 casillas en forma de cruz</color>. Por cada 5 puntos de Capital, obtiene 1 Capital adicional como dividendo.",
  str_skill_desc_34121822 = "Convierte 1 mosaico seleccionado en un <link=\"30093\"><#FFAE07><u>Mosaico Oscuro Azul</u></color></link> e inflige <color=#00F6FF>150%</color> de daño a <color=#00F6FF>13 fichas en forma de diamante</color>. Por cada 5 puntos de Capital, obtén 1 Capital adicional como dividendo.",
  str_skill_passive_desc_410218 = "Sheol comienza la batalla con <link=\"510218\"><#FFAE07><u>Estrategia de Inversión</u></color></link> y puede acumular Capital para seleccionar estrategias de inversión y ganar habilidades de combate correspondientes. (Alcanza el Nivel de Equipo Lv. 3/6/10 para desbloquear las estrategias de inversión \"Impulsado por la Niebla\", \"Riqueza aplastante\" y \"Golpe de Capital.\")",
  str_skill_passive_desc_413218 = "Sheol comienza la batalla con <link=\"513218\"><#FFAE07><u>Estrategia de Inversión</u></color></link> y puede acumular Capital para seleccionar estrategias de inversión y ganar habilidades de combate correspondientes. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (Alcanza el nivel de equipo Lv. 3/6/10 para desbloquear las estrategias de inversión \"Impulsado por la Niebla\", \"Riqueza aplastante\" y \"Golpe de Capital\").",
  str_skill_passive_desc_416218 = "Sheol comienza la batalla con <link=\"516218\"><#FFAE07><u>Estrategia de Inversión</u></color></link> y puede acumular Capital para seleccionar estrategias de inversión y ganar habilidades de combate correspondientes. Sheol comienza la batalla con 5 Capital. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (Alcanza el nivel de equipo Lv. 3/6/10 para desbloquear las estrategias de inversión \"Impulsado por la Niebla\", \"Riqueza aplastante\" y \"Golpe de Capital\").",
  str_skill_passive_desc_430218 = "Sheol comienza la batalla con <link=\"530218\"><#FFAE07><u>Estrategia de Inversión</u></color></link> y puede acumular Capital para seleccionar estrategias de inversión y obtener habilidades de combate correspondientes. Después de completar la primera ronda de inversión, puede hacer una segunda ronda de inversión para obtener habilidades de combate que no tenía en la primera ronda de inversión. (Alcanza el nivel de equipo Lv. 3/6/10 para desbloquear las estrategias de inversión \"Impulsado por la Niebla\", \"Riqueza aplastante\" y \"Golpe de Capital\").",
  str_skill_passive_desc_433218 = "Sheol comienza la batalla con <link=\"533218\"><#FFAE07><u>Estrategia de inversión</u></color></link> y puede acumular Capital para seleccionar estrategias de inversión y obtener habilidades de combate correspondientes. Después de completar la primera ronda de inversión, puede hacer una segunda ronda de inversión para obtener habilidades de combate que no tenía en la primera ronda de inversión. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (Alcanza el Nivel de Equipamiento Nvl. 3/6/10 para desbloquear las estrategias de inversión \"Impulsado por la Niebla\", \"Riqueza Aplastante\" y \"Golpe de Capital\".)",
  str_skill_passive_desc_436218 = "Sheol comienza la batalla con <link=\"536218\"><#FFAE07><u>Estrategia de Inversión</u></color></link> y puede acumular Capital para seleccionar estrategias de inversión y obtener habilidades de combate correspondientes. Después de completar la primera ronda de inversión, puede hacer una segunda ronda de inversión para obtener habilidades de combate que no tenía en la primera ronda de inversión. Sheol comienza la batalla con 5 Capital. Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (Alcanza el Nivel de Equipamiento Lv. 3/6/10 para desbloquear las estrategias de inversión \"Impulsado por la Niebla\", \"Riqueza Aplastante\" y \"Golpe de Capital\".)",
  str_skill_upgrade_desc_16021813 = "Mejora de habilidades de equipo: Cada punto de Capital ganado después de completar la segunda ronda de inversión aumenta el ATK de Sheol en un 1%, hasta 40 puntos. (se desbloquea en Ascensión III)",
  str_skill_upgrade_desc_16021816 = "Sheol comienza la batalla con 5 Capital. Por cada 5 puntos de Capital que tiene al lanzar su Habilidad Activa, gana 1 Capital adicional como dividendo.",
  str_skill_name_53920111 = "Ataque Normal",
  str_skill_desc_53920111 = "Ataca a los enemigos con un Ataque Normal después de moverse, infligiendo mucho daño a ellos.",
  str_skill_desc_53920112 = "Inflige daño a los enemigos dentro de 2 grupos circundantes después de moverse.",
  str_skill_desc_53920214 = "Después de que el equipo pasa por una Casilla Oscura, Sheol inflige daño a los enemigos dentro de 2 grupos circundantes 2 veces.",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>Nueva variante de habilidad activa</color>: <color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. La habilidad activa solo inflige daño y no genera ninguna Baldosa Oscura Azul.",
  str_skill_upgrade_refine_desc_16021812 = "Mejora Habilidad Activa: Aumenta el daño de la Habilidad Activa en un <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16021813 = "Mejora de habilidades de equipo: Reduce el costo en puntos de capital de la segunda ronda de inversión en 1 punto.",
  str_skill_name_70011191 = "Abandonado: Devorar - Saludable",
  str_skill_desc_70011191 = "Cuando los objetivos están dentro del alcance, los aurorianos y los fantasmas dentro de dos grupos en la dirección de avance son devorados. Los Aurorianos reciben daño y luego son escupidos hacia el borde del tablero.",
  str_skill_name_70011192 = "Abandonado: Devorar - Destruir",
  str_skill_desc_70011192 = "Inflige una gran cantidad de daño a los objetivos cuando están dentro del alcance, y cualquier fantasma que rodee a los objetivos se elimina al instante.",
  str_skill_name_70011193 = "Renegados: Devorar - Ejército Fantasma",
  str_skill_desc_70011193 = "Cuando el objetivo está dentro del alcance, se invoca una gran cantidad de fantasmas y se mejoran todos los fantasmas en el campo de batalla.",
  str_skill_name_70011195 = "Abandonado: Devorar - Saludable",
  str_skill_desc_70011195 = "Cuando los objetivos están dentro del alcance, los aurorianos y los fantasmas dentro de dos grupos en la dirección de avance son devorados, infligiendo daño verdadero a los aurorianos. Cuantos más fantasmas se devoran, mayor es el daño infligido. Luego, los Aurorianos son escupidos hacia el borde del tablero.",
  str_skill_name_200440103 = "Golpe Aplastante",
  str_skill_name_200450103 = "Bombardeo de explosión",
  str_skill_name_200460103 = "Embestida Armada",
  str_skill_name_200460104 = "Aniquilación total",
  str_skill_desc_200440103 = "Blande el arma para infligir daño a los Aurorianos.",
  str_skill_desc_200450103 = "Inflige daño a los Aurorianos en forma de cruz hasta el alcance máximo.",
  str_skill_desc_200460103 = "Inflige daño a los Aurorianos después de moverse.",
  str_skill_desc_200460104 = "Lanza un ataque penetrante en la dirección de los Aurorianos después de moverse, infligiendo daño tanto a enemigos como a aliados, luego pierde una cierta cantidad de HP.",
  str_skill_name_8004003 = "Explota cuando los Aurorianos se acercan a él. Si se deja solo, explotará después de un cierto número de rondas y generará una Pared Prohibida de 1 casilla a su alrededor.",
  str_skill_desc_8004039 = "Aumento de daño en esta ronda: Espadas Aterradoras usa las espadas para atacar objetivos dentro del rango 2 veces, causando un daño extremadamente alto.",
  str_skill_name_8004039 = "Doble cuchillada+",
  str_skill_desc_8004055 = "Vilanor se precipita y asesta un golpe, causando daño y lanzando un Muro Prohibido de 5 casillas de largo horizontalmente junto a los Aurorianos. Luego se teletransporta a una nueva ubicación.",
  str_skill_desc_8004057 = "Vilanor se precipita y asesta un golpe, infligiendo daño y lanzando un Muro Prohibido de 5 casillas de longitud verticalmente junto a los Aurorianos, luego se teletransporta a una nueva ubicación.",
  str_skill_desc_8004051 = "Vilanor se apresura y corta, infligiendo daño y lanzando un Muro Prohibido de 3 casillas de largo horizontalmente junto a los Aurorianos, luego se teletransporta a su ubicación original.",
  str_skill_desc_8004053 = "Vilanor se precipita y corta, infligiendo daño y lanzando un Muro Prohibido de 3 casillas de longitud verticalmente junto a los Aurorianos, luego se teletransporta a su ubicación original.",
  str_skill_name_8004012 = "Invocar Avispón Oscuro Vinesmark+",
  str_skill_desc_8004012 = "Invoca 1 Darkwasp y 1 Vinesmark a la batalla en cada ronda.",
  str_skill_desc_8004022 = "Después de pisar una Trampa de Exorcismo, a partir de la siguiente ronda, las Paredes Prohibidas alrededor de los Aurorianos se expanden nuevamente a 3 grupos circundantes.",
  str_skill_desc_8004040 = "Al pisar una Trampa de Exorcismo, se invocarán Muros Prohibidos alrededor de los enemigos.",
  str_skill_desc_8004050 = "Al pisar una Trampa de Exorcismo, se eliminarán todas las Paredes Prohibidas dentro de 2 grupos circundantes.",
  str_skill_name_290640101 = "Pisotear",
  str_skill_name_290640102 = "Salida Eficiente",
  str_skill_name_290640103 = "Reemplazo de Componentes",
  str_skill_desc_290640101 = "Consume un cierto porcentaje de su propio HP y todas las pilas de Armadura Mecánica después de moverse para atacar a los objetivos dentro de 2 casillas frente a sí mismo. Si el objetivo está al lado de Blaugm, lo derriba 1 casilla. Después de atacar, restaura su propio HP en función del número de pilas de Armadura Mecánica consumidas.",
  str_skill_desc_290640102 = "Inflige daño a todos los objetivos dentro de una forma de abanico. Cuanto más cerca esté el objetivo, mayor será el daño infligido.",
  str_skill_desc_290640103 = "Blaugm se potencia, aumentando permanentemente su ATK, DEF y HP máximo, y gana un cierto número de acumulaciones de Armadura Mecánica.",
  str_skill_name_29063011 = "Velocidad del viento opresiva",
  str_skill_name_29063012 = "Apunta a la ubicación de los Aurorianos y se lanza hacia el borde del tablero, infligiendo daño a todos los enemigos dentro del alcance en el camino.",
  str_skill_name_29063013 = "Modificación Corporal",
  str_skill_desc_29063011 = "Se mueve hacia los Aurorianos e inflige daño a los enemigos dentro de 2 casillas al frente de sí mismo.",
  str_skill_desc_29063012 = "Golpe de datos",
  str_skill_desc_29063013 = "Ulysses usa el Prototipo de Guardián para infligir daño a los Aurorianos en cualquier lugar del campo de batalla.",
  str_skill_name_2002211 = "Erupción Binaria",
  str_skill_name_2002212 = "Erupción Binaria",
  str_skill_name_2002213 = "Erupción Binaria",
  str_skill_desc_2002211 = "Bool inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2002212 = "Bool inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color>.",
  str_skill_desc_2002213 = "Bool inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>24 casillas en forma radial</color>.",
  str_skill_name_300221 = "Tarifa de muerte",
  str_skill_name_306221 = "Tarifa de muerte",
  str_skill_name_320221 = "Tarifa de muerte",
  str_skill_name_326221 = "Tarifa de muerte",
  str_skill_name_340221 = "Tarifa de muerte",
  str_skill_name_346221 = "Tarifa de muerte",
  str_skill_desc_300221 = "Elige cualquier casilla, luego selecciona 3 casillas dentro de <color=#00F6FF>1 grupo circundante</color> alrededor para convertirlas en <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link>. Bool inflige <color=#00F6FF>{1}%</color> de daño a esta área.",
  str_skill_desc_306221 = "Elige cualquier 1 mosaico, luego selecciona 4 mosaicos dentro de <color=#00F6FF>12 mosaicos en forma de diamante</color> alrededor de él para convertirlos en <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>. Bool inflige <color=#00F6FF>{1}%</color> de daño a esta área.",
  str_skill_desc_320221 = "Elige cualquier casilla, luego selecciona 3 casillas dentro de <color=#00F6FF>1 grupo circundante</color> alrededor de ella para convertirlas en <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link>. Bool inflige <color=#00F6FF>{1}%</color> de daño a esta área. Gana 1 punto de cálculo cada vez que se inflige daño.",
  str_skill_desc_326221 = "Elige cualquier 1 mosaico, luego selecciona 4 mosaicos dentro de <color=#00F6FF>12 mosaicos en forma de diamante</color> alrededor de él para convertirlos en <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>. Bool inflige <color=#00F6FF>{1}%</color> de daño a esta área. Gana 1 punto de cálculo cada vez que se inflige daño.",
  str_skill_desc_340221 = "Elige cualquier mosaico, luego selecciona 3 mosaicos dentro de <color=#00F6FF>1 grupo circundante</color> alrededor de él para convertirlos en <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>. Bool inflige <color=#00F6FF>250%</color> de daño a esta área. Gana 1 punto de cálculo cada vez que se inflige daño.",
  str_skill_desc_346221 = "Elige cualquier mosaico, luego selecciona 4 mosaicos dentro de <color=#00F6FF>12 mosaicos en forma de diamante</color> alrededor de él para convertirlos en <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>. Bool inflige <color=#00F6FF>250%</color> de daño a esta área. Gana 1 punto de cálculo cada vez que se inflige daño.",
  str_skill_passive_name_410221 = "Números Mágicos Nanométricos",
  str_skill_passive_name_430221 = "Números Mágicos Nanométricos",
  str_skill_passive_name_440221 = "Números Mágicos Nanométricos",
  str_skill_passive_name_443221 = "Números Mágicos Nanométricos",
  str_skill_passive_desc_410221 = "Gana 1 punto de cálculo cada vez que pasa por una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link>. Cada punto de cálculo aumenta el daño de Bool en <color=#00F6FF>{1}</color>, y la mitad de los puntos de cálculo se retendrán al final de la ronda.",
  str_skill_passive_desc_430221 = "Gana 1 punto de cálculo cada vez que pasa por un <link=\"30093\"><#FFAE07><u>Mosaico Oscuro</u></color></link>. Cada punto de cálculo aumenta el daño de Bool en <color=#00F6FF>{1}</color>, y la mitad de los puntos de cálculo se mantendrán al final de la ronda. Si hay no menos de <color=#00F6FF>3</color> puntos de cálculo después de que termina la acción de Bool, Bool inflige un <color=#00F6FF>100%</color> de daño adicional al enemigo que ha recibido daño más veces de él.",
  str_skill_passive_desc_440221 = "Gana 1 punto de cálculo cada vez que pasa por un <link=\"30093\"><#FFAE07><u>Mosaico Oscuro</u></color></link>. Cada punto de cálculo aumenta el daño de Bool en <color=#00F6FF>6%</color>, y la mitad de los puntos de cálculo se conservarán al final de la ronda. Si hay no menos de <color=#00F6FF>3</color> puntos de cálculo después de que termina la acción de Bool, Bool inflige un daño adicional del <color=#00F6FF>100%</color> al enemigo que ha recibido más veces daño de él.",
  str_skill_passive_desc_443221 = "Gana 1 punto de cálculo cada vez que pasa por un <link=\"30093\"><#FFAE07><u>Mosaico Oscuro</u></color></link>. Cada punto de cálculo aumenta el daño de Bool en <color=#00F6FF>6%</color>, y la mitad de los puntos de cálculo se conservarán al final de la ronda. Si hay no menos de <color=#00F6FF>3</color> puntos de cálculo después de que termina la acción de Bool, Bool inflige un daño adicional del <color=#00F6FF>120%</color> al enemigo que ha recibido más daño de él.",
  str_skill_upgrade_refine_desc_16022111 = "Mejora de Habilidad de Equipo: Cada punto de cálculo aumenta el daño de Bool en un <color=#00F6FF>6%</color>.",
  str_skill_upgrade_refine_desc_16022112 = "Mejora de Habilidad Activa: Aumenta el factor de daño en un <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16022113 = "Mejora de habilidades de equipo: Aumenta el daño adicional infligido por Bool a <color=#00F6FF>120%</color>.",
  str_skill_upgrade_desc_16022113 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16022116 = "Mejora Habilidad Activa: El rango se expande a 13 casillas en forma de diamante, y el número de casillas que se pueden seleccionar aumenta a 4.",
  str_skill_name_802401 = "Talento: Rompecielos",
  str_skill_name_802402 = "Habilidad: Borrar",
  str_skill_name_802403 = "Habilidad: Vitalización",
  str_skill_name_802404 = "Habilidad: Terremoto",
  str_skill_name_802405 = "Habilidad: Desorientar",
  str_skill_desc_802401 = "Este pedazo de metal puede doblar la tela del espacio y transportar a los aurorianos a cualquier casilla que se pueda atravesar.",
  str_skill_desc_802402 = "Los restos de un deslizamiento de lodo que destruyó una ciudad. Puede eliminar Rocas o Muros Prohibidos de cualquier casilla.",
  str_skill_desc_802403 = "Una gota de rocío dejada por las estrellas en movimiento. Al usar esto, los puntos de fuerza de Aurorian aumentan en 7.",
  str_skill_desc_802404 = "Un arma de pólvora del misterioso este. Empuja a todos los enemigos dentro de 1 cúmulo circundante a la mayor distancia e inflige daño a ellos.",
  str_skill_desc_802405 = "Las hierbas pueden usarse para salvar a las personas o para envenenarlas. Aturde al objetivo durante 1 ronda.",
  str_skill_desc_80240131 = "Invoca 3 runas de Geist sombrío a la vez, cada una de las cuales se convierte en un Geist sombrío con habilidad de curación después de 3 rondas.",
  str_skill_desc_8024441 = "Murkmite ataca a los objetivos dentro del alcance y reduce los puntos de fuerza de los objetivos en 2.",
  str_skill_name_802431111 = "Malvado Voluntad: La Llamada",
  str_skill_desc_802431111 = "Invoca a algunos enemigos en el área cercana para apoyarlo.",
  str_skill_desc_8024150 = "El coleccionista inflige el 30% de los PS máx. en daño a los enemigos adyacentes. Cuesta 5 puntos de fuerza.",
  str_skill_desc_8024151 = "El coleccionista se encarga de la autoreparación para regenerar el 25% del PS máx. Cuesta 3 puntos de fuerza.",
  str_skill_desc_8024152 = "El colector irradia partículas de energía, formando 3 capas de escudo que pueden resistir el daño. Cuesta 1 punto de fuerza.",
  str_skill_name_80242801 = "Trampa de jaula",
  str_skill_desc_80242801 = "Una jaula robusta, aparentemente irrompible. El enemigo dentro puede transferir una proporción del daño que recibe al enemigo central. Consume 3 puntos de fuerza para liberar al enemigo de la jaula.",
  str_skill_upgrade_desc_16022313 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16022316 = "Mejora de Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00>1</color> ronda. Aumenta el número de Casillas Oscuras generadas a 5.",
  str_skill_name_2002231 = "Danza del Dragón Bendito",
  str_skill_name_2002232 = "Danza del Dragón Bendito",
  str_skill_name_2002233 = "Danza del Dragón Bendito",
  str_skill_name_3002231 = "Gracia divina del trueno",
  str_skill_name_3062231 = "Gracia divina del trueno",
  str_skill_passive_name_410223 = "Campanillas de escamas de dragón",
  str_skill_passive_name_420223 = "Campanillas de escamas de dragón",
  str_skill_passive_name_430223 = "Campanillas de escamas de dragón",
  str_skill_desc_2002231 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_2002232 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2002233 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>24 casillas en forma de diamante</color>.",
  str_skill_desc_3002231 = "Selecciona 1 de 8 direcciones y convierte <color=#00F6FF>todos los mosaicos</color> en esa línea a amarillo, priorizando la creación de <color=#00F6FF>3</color> <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link> en la dirección elegida.",
  str_skill_desc_3062231 = "Selecciona 1 de 8 direcciones y convierte <color=#00F6FF>todos los mosaicos</color> en esa línea a amarillo, priorizando la creación de <color=#00F6FF>5</color> <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link> en la dirección elegida.",
  str_skill_passive_desc_410223 = "Los ataques normales de Chen'ni apuntan al enemigo con la mayor diferencia en el porcentaje de PS del equipo, infligiendo daño igual al <color=#00F6FF>{1}</color> del ATQ promedio del equipo.",
  str_skill_passive_desc_420223 = "Los ataques normales de Chen'ni apuntan al enemigo con la mayor diferencia en el porcentaje de HP del equipo, infligiendo daño igual a <color=#00F6FF>{1}</color> del ATK promedio del equipo. Provoca <color=#00F6FF>1.5×</color> daño cada vez que pasa por un <link=\"30093\"><#FFAE07><u>Azulejo Oscuro</u></color></link>.",
  str_skill_passive_desc_430223 = "Los ataques normales de Chen'ni apuntan al enemigo con la mayor diferencia de porcentaje de HP del equipo, infligiendo daño igual a <color=#00F6FF>{1}</color> del ATK promedio del equipo. Provoca <color=#00F6FF>1.5×</color> daño cada vez que pasa por un <link=\"30093\"><#FFAE07><u>Azulejo Oscuro</u></color></link>. Cuanto mayor es la diferencia de porcentaje de HP entre el objetivo y el equipo, mayor es el daño, con un aumento máximo de <color=#00F6FF>50%</color>.",
  str_skill_name_70011211 = "Abandonado: Fuerza Dominante",
  str_skill_name_70011212 = "Abandonado: Olas Furiosas",
  str_skill_upgrade_desc_15022412 = "Cambia la Habilidad Activa a <color=#FFFF00>Ataque preventivo</color>, disponible al entrar en combate. Obtiene 10 Llamas del Guardián Demoníaco al comienzo de la batalla.",
  str_skill_upgrade_desc_15022415 = "Mejora de habilidades de equipo: Gana una Llama Guardiana Demoníaca cada vez que pasa por mosaicos de cualquier elemento.",
  str_skill_name_2002241 = "Llama Marcial",
  str_skill_name_2002242 = "Llama Marcial",
  str_skill_name_2002243 = "Llama Marcial",
  str_skill_name_300224 = "Granada Sorpresa",
  str_skill_name_3002241 = "Variante I de Granada Sorpresa",
  str_skill_name_3002242 = "Variante de Granada Sorpresa II",
  str_skill_passive_name_410224 = "Esfuerzo Conjunto",
  str_skill_passive_name_412224 = "Esfuerzo Conjunto",
  str_skill_passive_name_415224 = "Esfuerzo Conjunto",
  str_skill_desc_2002241 = "Lanza a Ah Ding, infligiendo un <color=#00F6FF>{1}%</color> de daño a la casilla más cercana del enemigo más próximo.",
  str_skill_desc_2002242 = "Lanza a Ah Ding, infligiendo <color=#00F6FF>{1}%</color> de daño a la casilla más cercana del enemigo más cercano y un 30% de daño de salpicadura a <color=#00F6FF>4 casillas circundantes en forma de cruz</color>.",
  str_skill_desc_2002243 = "Lanza a Ah Ding, infligiendo un <color=#00F6FF>{1}%</color> de daño a la casilla más cercana del enemigo más próximo y un 30% de daño de salpicadura a <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_300224 = "Selecciona una casilla para centrar el Combo en Cadena y reduce el requisito de activación del Combo en Cadena en 3, aplicable solo a esta ronda.",
  str_skill_desc_3002241 = "<color=#FFFF00>Después de lanzar, reduce el enfriamiento de habilidad en 1</color>, y si no se desata un Combo en Cadena en esta ronda, los ataques normales pueden lanzarse en diagonal. Gana 2 Llamas Guardianas de Demonio con cada ataque normal.",
  str_skill_desc_3002242 = "<color=#FFFF00>Después de lanzar, aumenta el enfriamiento de habilidad en 1</color>. Selecciona una ficha para centrar el Combo en Cadena de esta ronda, luego inflige un <color=#00F6FF>100%</color> de daño. Cada Llama Guardiana Demoníaca aumenta el daño en un 10%. Reduce el requisito de activación del Combo en Cadena en 3 para esta ronda y obtiene un efecto de retroceso adicional.",
  str_skill_passive_desc_410224 = "Gana 1 Llama Guardiana Demoníaca por cada casilla roja atravesada. Cada Llama aumenta el daño del siguiente Combo en Cadena en <color=#00F6FF>{1}</color>, que se reinicia después de que se libera el Combo en Cadena.",
  str_skill_passive_desc_412224 = "Gana 1 Llama Guardiana Diablillo por cada casilla roja recorrida. Cada Llama aumenta el daño del siguiente Combo en Cadena en <color=#00F6FF>{1}</color>, que se reinicia después de que se libera el Combo en Cadena. Obtiene 10 Llamas Guardianas Diablillo al comienzo de la batalla.",
  str_skill_passive_desc_415224 = "Gana 1 Llama Guardiana Demoníaca por cada ficha recorrida. Cada Llama aumenta el daño del siguiente Combo en Cadena en <color=#00F6FF>{1}</color>, que se reinicia después de que se libera el Combo en Cadena. Obtiene 10 Llamas Guardianas Demoníacas al inicio de la batalla.",
  str_skill_desc_9997040 = "Convierte cualquier 2 fichas seleccionadas en fichas cromáticas, ganando 1 energía por cada ficha eliminada. Obtiene 1 oportunidad de uso después de acumular 60 energías; se pueden almacenar hasta 2 oportunidades.",
  str_skill_desc_9997041 = "Selecciona un área de 3×3 y elimina todas las losetas azules dentro de ella, ganando 1 energía por cada loseta eliminada. Obtiene 1 oportunidad de uso después de acumular 50 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_9997042 = "Selecciona un área de 3×3 y elimina todas las fichas rojas dentro de ella, ganando 1 energía por cada ficha eliminada. Obtiene 1 oportunidad de uso después de acumular 50 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_9997043 = "Selecciona un área de 3x3 y elimina todos los mosaicos verdes dentro de ella, ganando 1 energía por cada mosaico eliminado. Obtiene 1 oportunidad de uso después de acumular 50 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_9997044 = "Selecciona un área de 3×3 y elimina todas las fichas amarillas dentro de ella, ganando 1 energía por cada ficha eliminada. Obtiene 1 oportunidad de uso después de acumular 50 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_9997045 = "Restablece todas las casillas en el campo, ganando 1 energía por cada casilla eliminada. Obtiene 1 oportunidad de uso después de acumular 80 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_9997046 = "Selecciona 1 color y reinicia todos los mosaicos de este color en el campo, ganando 1 energía por cada mosaico eliminado. Obtiene 1 oportunidad de uso después de acumular 80 energías; se pueden almacenar hasta 2 oportunidades.",
  str_skill_desc_9997047 = "Selecciona 1 mosaico y elimina los 4 mosaicos más cercanos del mismo color. Gana 1 energía por cada mosaico eliminado. Obtiene 1 oportunidad de uso después de acumular 60 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_name_5066101 = "Kaleidogema",
  str_skill_desc_5066101 = "Convierte todos los mosaicos en el campo a mosaicos cromáticos.",
  str_skill_name_5060801 = "Quiebra paredes",
  str_skill_desc_5060801 = "Consume 2 rondas para lanzar instantáneamente una habilidad de apoyo de facción de nivel 2. Solo se puede usar una vez en cada ronda.",
  str_skill_name_20047011 = "Golpe de transbordador",
  str_skill_desc_20047011 = "Después de moverse, ataca a un objetivo en 4 casillas circundantes en forma de cruz, luego pasa a través del objetivo a una casilla a su alrededor, priorizando la casilla directamente detrás del objetivo.",
  str_skill_name_5412015 = "Invocación: Necrófago Sombrío",
  str_skill_desc_5412015 = "Invoca Gloom Ghouls a la batalla en cada ronda.",
  str_skill_name_9997040 = "Espada de resplandor",
  str_skill_name_9997046 = "Escudo de resplandor",
  str_skill_name_9997047 = "Lanza de Resplandor",
  str_skill_desc_5064701 = "Selecciona un área de 5x5 y elimina todas las casillas azules dentro de ella, ganando 1 energía por cada casilla eliminada. Obtiene 1 oportunidad de uso después de acumular 40 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_5064702 = "Selecciona un área de 5x5 y elimina todas las casillas rojas dentro de ella, ganando 1 energía por cada casilla eliminada. Obtiene 1 oportunidad de uso después de acumular 40 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_5064703 = "Selecciona un área de 5x5 y elimina todas las fichas verdes dentro de ella, ganando 1 energía por cada ficha eliminada. Obtiene 1 oportunidad de uso después de acumular 40 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_desc_5064704 = "Selecciona un área de 5x5 y elimina todas las fichas amarillas dentro de ella, ganando 1 energía por cada ficha eliminada. Obtiene 1 oportunidad de uso después de acumular 40 energías; se pueden almacenar hasta 3 oportunidades.",
  str_skill_name_5411002 = "Danza del Dragón Bendito",
  str_skill_desc_5411002 = "Inflige daño a 24 mosaicos en forma de diamante.",
  str_skill_name_5411003 = "Invocación: Fiendling",
  str_skill_desc_5411003 = "Invoca 2 Fiendling: Ratas al campo de batalla.",
  str_skill_desc_5411012 = "Nozard acumula fuerza para la inminente Marea Creciente, convocando a varios Gloom Ghouls frente a él.",
  str_skill_desc_5411020 = "Gertzurde convoca al azar a 4 Siervos de Gertzurde inmóviles al campo.",
  str_skill_desc_5411021 = "Gertzurde ataca a los objetivos dentro del área de efecto y aplica 1 Marca de Penetrabilidad. Cuantas más marcas haya, menor será la DEF del objetivo. También convoca a 2 sirvientes de Gertzurde.",
  str_skill_desc_5411022 = "Gertzurde ruge y aplica 2 Marcas de Penetrabilidad a los objetivos dentro del área de efecto. Cuantas más marcas haya, menor será la DEF del objetivo. También convoca a 2 sirvientes de Gertzurde.",
  str_skill_desc_5411023 = "Gertzurde detona las Marcas de Penetrabilidad en los objetivos para infligir un daño masivo. Cuantas más marcas tenga un objetivo, más daño recibirá. También convoca a 2 sirvientes de Gertzurde.",
  str_skill_desc_5411025 = "Gertzurde convoca al azar a 4 Siervos de Gertzurde inmóviles al campo.",
  str_skill_desc_5411026 = "Gertzurde ataca frenéticamente a los objetivos dentro del área de efecto 2 veces y aplica 2 Marcas de Penetrabilidad. Cuantas más marcas haya, menor será la DEF del objetivo. También convoca a 2 sirvientes de Gertzurde.",
  str_skill_desc_5411027 = "Gertzurde emite su rugido final y aplica 3 Marcas de Penetrabilidad a los objetivos dentro del área de efecto. Cuantas más marcas haya, menor será la DEF del objetivo. También convoca a 2 sirvientes de Gertzurde.",
  str_skill_desc_5411004 = "Invoca una Trampa de Jaula.",
  str_skill_name_5411031 = "Unir",
  str_skill_desc_5411031 = "La línea entre la realidad y la fantasía se desdibuja en este reino ilusorio...",
  str_skill_name_5064701 = "Congelador flotante",
  str_skill_name_5064702 = "Quemador flotante",
  str_skill_name_5064703 = "Ira del Bosque Flotante",
  str_skill_name_5064704 = "Trueno flotante",
  str_skill_name_5065501 = "Trampa de aumento de daño",
  str_skill_name_5065601 = "Tarro de Caramelo Energético",
  str_skill_name_5065801 = "Energizador móvil",
  str_skill_desc_5065501 = "Después de la eliminación, el daño de Chain Combo aumenta en un 35% esta ronda.",
  str_skill_desc_5065601 = "Después de la eliminación, otorga 1 oportunidad de uso para un equipo especial de Caelestite aleatorio.",
  str_skill_desc_5065801 = "Después de la eliminación, otorga 3 rondas extra.",
  str_skill_name_29093013 = "Paso de Año Nuevo",
  str_skill_desc_29093013 = "Nian salta hacia adelante 3 casillas, infligiendo daño a 1 grupo circundante de la casilla de aterrizaje y repeliendo a los enemigos dentro del alcance hacia ambos lados. Si Nian llega a la puerta, la puerta será destruida, permitiendo a Nian entrar.",
  str_skill_name_7001125103 = "Abandonado: Aullido Enojado",
  str_skill_desc_7001125103 = "Forsaken: Cerritus inflige daño a todos los Aurorianos en el campo, aumenta su propio ACT y convoca guijarros.",
  str_skill_name_7001125104 = "Abandonado: Golpe devastador",
  str_skill_desc_7001125104 = "Abandonado: Cerritus genera fichas debilitadas y carga contra los aurorianos, derribándolos y destruyendo guijarros en su camino.",
  str_skill_name_7001125105 = "Abandonado: Terremoto devastador",
  str_skill_desc_7001125105 = "Abandonado: Cerritus golpea las 2 fichas que tiene delante después de moverse, inflige un daño enorme y genera fichas debilitadas.",
  str_skill_name_7001126103 = "Abandonado: Desata la Negatividad",
  str_skill_desc_7001126103 = "Forsaken: Chandra se aleja de los Aurorianos y luego inflige daño a los Aurorianos dentro de 2 cúmulos circundantes.",
  str_skill_name_7001126104 = "Abandonado: Proyecto de Emociones Negativas",
  str_skill_desc_7001126104 = "Abandonado: Chandra inflige daño a todos los Aurorianos en el campo.",
  str_skill_name_80150311 = "Roca",
  str_skill_desc_80150311 = "La Roca ha obstruido el camino aquí durante mucho tiempo. Consume 2 Puntos de Fuerza para eliminarla.",
  str_skill_name_290940103 = "Lanza de Fuego Sombrío",
  str_skill_desc_290940103 = "Ira inflige daño a los Aurorianos y genera Fuego Sombra en las fichas más externas del campo hasta el alcance máximo en el área en forma de cruz centrada alrededor de los Aurorianos.",
  str_skill_name_290940104 = "Explosión ardiente",
  str_skill_desc_290940104 = "Ira inflige daño a los Aurorianos dentro de 2 grupos circundantes de sí mismo.",
  str_skill_name_290940105 = "Meteor iracundo",
  str_skill_desc_290940105 = "Ira invoca meteoritos para golpear la posición donde estaban los Aurorianos en la ronda anterior, causando daño letal y destruyendo la casilla, dejando atrás 4 casillas rotas en forma de cruz.",
  str_skill_name_200480103 = "Sombra de fuego del infierno",
  str_skill_desc_200480103 = "Shadowfire inflige daño a los Aurorianos dentro del alcance y se teletransporta al lado opuesto del campo. Si no puede atacar a los jugadores, se teletransporta en sentido horario a lo largo del grupo más externo del campo, moviéndose 2 casillas.",
  str_skill_name_300226 = "Es un mundo de rana",
  str_skill_name_200226 = "Todos saluden a la Rana",
  str_skill_passive_name_400226 = "Una Sinfonía Ribbitante",
  str_skill_desc_300226 = "Dentro de los sueños, el Príncipe Lilypad tiene el poder de calmar los volcanes en erupción y reparar las grietas negras en el cielo. En el mundo real, aspira a curar a sus compañeros con su ternura... ¿Qué hace en realidad, preguntas? ¡Te llena de ternura!",
  str_skill_desc_200226 = "El croar resuelto del Príncipe Lilypad resuena en todo Astra. ¿Qué hace realmente, preguntas? ¡Te baña de ternura!",
  str_skill_passive_desc_400226 = "El croar de una rana es el latido del corazón de la naturaleza, el aliento de Astra, un rayo de luz en la oscuridad infinita. ¿Puedes oírlo? ¡Está invitando a todos a unirse a esta gran celebración cantando un himno juntos! ¿Qué hace realmente, preguntas? ¡Hacer que todos croen, por supuesto!",
  str_skill_name_54350081 = "Guardián del Cañón Salva",
  str_skill_desc_54350081 = "¡Es el deber de un cañón de salva proteger al rey! Saldrán del campo de batalla después del Combo en Cadena de los Aurorians.",
  str_skill_upgrade_desc_16022513 = "Mejora de habilidad activa: Cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate. Inflige 1 punto débil extra a los enemigos dentro del rango.",
  str_skill_upgrade_desc_16022516 = "Mejora de habilidades de equipo: Al pasar por un <link=\"30093\"><#FFAE07><u>Mosaico Oscuro</u></color></link>, hay un 50% de probabilidad de infligir 1 punto débil adicional.",
  str_skill_name_2002251 = "Cielos Desmoronándose",
  str_skill_name_2002252 = "Cielos Desmoronándose",
