  str_skill_passive_name_4402253 = "Trueno y Cielo, Como Uno Solo",
  str_skill_passive_name_4462253 = "Trueno y Cielo, Como Uno Solo",
  str_skill_desc_2002251 = "Inflige un <color=#00F6FF>{1}%</color> de daño en una columna a lo largo del camino hacia el enemigo más cercano.",
  str_skill_desc_2002252 = "Inflige <color=#00F6FF>{1}%</color> de daño en una columna y a las casillas adyacentes a lo largo del camino hacia el enemigo más cercano.",
  str_skill_desc_2002253 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy.",
  str_skill_desc_2102251 = "Inflige <color=#00F6FF>{1}%</color> de daño en una columna en el camino hacia el enemigo más cercano. También rompe 1 punto débil en esa dirección.",
  str_skill_desc_2102252 = "Inflige <color=#00F6FF>{1}%</color> de daño en una columna y a las casillas adyacentes en el camino hacia el enemigo más cercano. También rompe 1 punto débil en esa dirección.",
  str_skill_desc_2102253 = "Inflige <color=#00F6FF>{1}%</color> de daño en una columna y a las casillas adyacentes en el camino hacia el enemigo más cercano. También rompe hasta 2 puntos débiles en esa dirección.",
  str_skill_desc_2302251 = "Deals <color=#00F6FF>{1}%</color> damage in a column along the path towards the nearest enemy. Also breaks 1 weak spot in that direction.",
  str_skill_desc_2302252 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy. Also breaks 1 weak spot in that direction.",
  str_skill_desc_2302253 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy. Also breaks up to 2 weak spots in that direction.",
  str_skill_desc_300225 = "Apunta a 1 casilla e inflige <color=#00F6FF>{1}%</color> de daño en forma de cono en esa dirección.",
  str_skill_desc_303225 = "Targets 1 tile and deals <color=#00F6FF>{1}%</color> damage in a cone shape in that direction.",
  str_skill_desc_320225 = "Apunta a 1 casilla e inflige <color=#00F6FF>{1}%</color> de daño en forma de cono en esa dirección. También inflige 1 punto débil a todos los enemigos dentro del rango del ataque.",
  str_skill_desc_323225 = "Apunta a 1 casilla e inflige un <color=#00F6FF>{1}%</color> de daño en forma de cono en esa dirección. También inflige 2 puntos débiles a todos los enemigos dentro del rango del ataque.",
  str_skill_desc_340225 = "Apunta a 1 casilla e inflige <color=#00F6FF>250%</color> de daño en forma de cono en esa dirección. También inflige 1 punto débil a todos los enemigos dentro del rango del ataque.",
  str_skill_desc_343225 = "Apunta a 1 casilla e inflige <color=#00F6FF>250%</color> de daño en forma de cono en esa dirección. También inflige 2 puntos débiles a todos los enemigos dentro del rango del ataque.",
  str_skill_passive_desc_410225 = "Al pasar por <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>, Tiare infligirá 1 punto débil al enemigo con más PS en el campo en la dirección más cercana a ella. Cada vez que el Ataque Normal o Combo en Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en <color=#00F6FF>{1}</color> de daño. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá un daño adicional de la mitad del daño de ruptura.",
  str_skill_passive_desc_416225 = "Al pasar por <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>, Tiare infligirá 1 punto débil (con un 50% de probabilidad de 1 punto débil extra) al enemigo con la mayor HP en el campo en la dirección más cercana a ella. Siempre que el Ataque Normal o Combo en Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en <color=#00F6FF>{1}</color> de daño. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá un daño adicional equivalente a la mitad del daño de ruptura.",
  str_skill_passive_desc_430225 = "Al pasar por <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link>, Tiare infligirá 1 punto débil al enemigo con más HP en el campo en la dirección más cercana a ella. Cada vez que el Ataque Normal o Combo en Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>Daño de Salpicadura</u></color></link> y <color=#00F6FF>{2}</color> de daño al rango de salpicadura. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá la mitad adicional del daño de ruptura.",
  str_skill_passive_desc_436225 = "Al pasar por <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>, Tiare infligirá 1 punto débil (con un 50% de probabilidad de 1 punto débil extra) al enemigo con más HP en el campo en la dirección más cercana a ella. Siempre que el Ataque Normal o Combo de Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>Daño de Salpicadura</u></color></link> y <color=#00F6FF>{2}</color> de daño al rango de salpicadura. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá la mitad adicional del daño de ruptura.",
  str_skill_passive_desc_440225 = "Al pasar por <link=\"30093\"><#FFAE07><u>Mosaicos Oscuros</u></color></link>, Tiare infligirá 1 punto débil al enemigo con más HP en el campo en la dirección más cercana a ella. Cada vez que el Ataque Normal o Combo de Cadena de Tiare golpea en esa dirección, los puntos débiles se romperán, resultando en <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Daño de Salpicadura</u></color></link> y <color=#00F6FF>100%</color> de daño al rango de salpicadura. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá la mitad adicional del daño de ruptura.",
  str_skill_passive_desc_446225 = "Al pasar por <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link>, Tiare infligirá 1 punto débil (con un 50% de probabilidad de 1 punto débil extra) al enemigo con más HP en el campo en la dirección más cercana a ella. Siempre que el Ataque Normal o Combo en Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en <color=#00F6FF>230%</color> de <link=\"30015\"><#FFAE07><u>Daño de Salpicadura</u></color></link> y <color=#00F6FF>100%</color> de daño al rango de salpicadura. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá la mitad adicional del daño de ruptura.",
  str_skill_passive_desc_4402253 = "Al pasar por <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link> o al entrar en la Hora de Aurora, Tiare infligirá 1 punto débil al enemigo con más PS en el campo en la dirección más cercana a ella. Cada vez que el Ataque Normal o Combo en Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en un <color=#00F6FF>230%</color> de <link=\"30015\"><#FFAE07><u>Daño de Salpicadura</u></color></link> y un <color=#00F6FF>100%</color> de daño al rango de salpicadura. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá un daño adicional equivalente a la mitad del daño de ruptura.",
  str_skill_passive_desc_4462253 = "Al pasar por <link=\"30093\"><#FFAE07><u>Casillas Oscuras</u></color></link> o al entrar en la Hora de Aurora, Tiare infligirá 1 punto débil (con un 50% de probabilidad de 1 punto débil extra) al enemigo con más PS en el campo en la dirección más cercana a ella. Cada vez que el Ataque Normal o Combo en Cadena de Tiare golpee en esa dirección, los puntos débiles se romperán, resultando en un <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Daño de Salpicadura</u></color></link> y un <color=#00F6FF>100%</color> de daño al rango de salpicadura. Cuando un enemigo muere, su punto débil se transfiere al enemigo más cercano. Cuando un enemigo está rodeado de puntos débiles, se infligirá un daño adicional equivalente a la mitad del daño de ruptura.",
  str_skill_upgrade_refine_desc_16022511 = "Mejora de habilidades de equipo: Aumenta el daño causado al romper puntos débiles en un <color=#00F6FF>230%</color>.",
  str_skill_upgrade_refine_desc_16022512 = "Mejora de habilidad activa: Aumenta el factor de daño de la habilidad en un <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16022513 = "Mejora de Habilidad de Equipo: Al entrar en la Hora de Aurora, inflige 1 punto débil al enemigo con mayor PS en la dirección más cercana.",
  str_skill_desc_70011272 = "La energía del Caracalune se desborda e inflige daño a 4 columnas y filas.",
  str_skill_desc_70011273 = "El Caracalune se convierte en un Plenalune, inflige daño a los objetivos dentro del área de ataque y se mueve al otro lado del campo. Después de moverse, bloquea las casillas dentro de 1 cúmulo circundante. Las casillas bloqueadas no se pueden convertir.",
  str_skill_name_290501142 = "Abandonado: Presa",
  str_skill_name_290501143 = "Abandonado: Caza",
  str_skill_name_290501144 = "Abandonado: Rally",
  str_skill_desc_290501142 = "La Reina Araña Queen se abalanza sobre su presa, tiende una telaraña para bloquear mosaicos y daña a los aurorianos. Los mosaicos bloqueados vuelven a su estado original después de 1 ronda.",
  str_skill_desc_290501143 = "La Reina Araña teje una telaraña para bloquear las casillas alrededor de los Aurorianos, luego convoca a sus crías para que se abalancen sobre ellos y les hagan daño. Las fichas bloqueadas vuelven a su estado original después de 1 ronda.",
  str_skill_desc_290501144 = "La Reina Araña convoca a sus crías para tejer telas de araña, bloqueando una gran cantidad de fichas. Las fichas bloqueadas vuelven a su estado original después de 1 ronda.",
  str_skill_desc_9011062 = "-1 rondas de habilidad para el Aurorian con el enfriamiento actual más alto.",
  str_skill_name_290420209 = "Guadaña",
  str_skill_desc_290420209 = "El Fantasma Dreamwalker se mueve e inflige daño a los objetivos en frente.",
  str_skill_desc_510233 = "Todas las rondas de habilidad de los Aurorians desplegados -2.",
  str_skill_desc_520233 = "Termina el enfriamiento de habilidad para un Aurorian aleatorio.",
  str_skill_desc_530233 = "Finaliza el tiempo de reutilización de habilidades para todos los Aurorianos desplegados.",
  str_skill_desc_292600105 = "La afligida Eve gana un número sustancial de acumulaciones de Darkflow, obteniendo el efecto de Asalto basado en el número de acumulaciones. Cada vez que es atacada, las acumulaciones de Darkflow disminuyen.",
  str_skill_desc_292600106 = "El lamento Eve se fija en el objetivo y causa daño.",
  str_skill_desc_20060012 = "Otorga una bonificación de DEF para Grieving Eve.",
  str_skill_name_200490101 = "Bruma",
  str_skill_desc_200490101 = "Haze se mueve hacia los Aurorianos.",
  str_skill_name_290950105 = "Granizo de Plaga",
  str_skill_name_290950106 = "Tormenta de plaga",
  str_skill_name_290950107 = "Granizo de Plaga",
  str_skill_name_290950108 = "Tormenta de plaga",
  str_skill_name_290950109 = "Aplastamiento de Plaga",
  str_skill_desc_290950105 = "Zanahoria: La Plaga inflige múltiples instancias de daño a los aurorianos. Cuanto más bajo es el HP de los aurorianos, más daño se inflige.",
  str_skill_desc_290950106 = "Zanahoria: Blight gira a alta velocidad, infligiendo múltiples instancias de daño a los objetivos a su alrededor. Cada vez que inflige daño, hay una posibilidad de repeler a los aurorianos 1 mosaico en la dirección antihoraria o hacia afuera. Cada golpe exitoso reduce el daño del siguiente golpe.",
  str_skill_desc_290950107 = "Zanahoria: La Plaga inflige múltiples instancias de daño a los aurorianos. Cuanto más bajo es el HP de los aurorianos, más daño se inflige.",
  str_skill_desc_290950108 = "Si los Aurorianos no están dentro del alcance de Blight Crush, Carrot: Blight gira a alta velocidad, infligiendo múltiples instancias de daño a los objetivos a su alrededor. Cada vez que inflige daño, hay una posibilidad de repeler a los Aurorianos 1 casilla en la dirección antihoraria o hacia afuera. Cada golpe exitoso reduce el daño del siguiente golpe.",
  str_skill_desc_290950109 = "Si los Aurorianos están dentro del alcance de Blight Crush, Carrot: Blight los aplasta con una zanahoria gigante, causándoles daño y repeliéndolos 2 casillas.",
  str_skill_name_80060401 = "Espigas de Contradicción",
  str_skill_desc_80060401 = "Inflige un daño considerable al final de cada ronda a cualquier monstruo atrapado en las púas e inflige 1 pila de Sangrado. Estas púas parecen familiares, pero esta vez no te harán daño.",
  str_skill_name_80060501 = "Invocar Slasher",
  str_skill_name_80060502 = "Invocar Investigador",
  str_skill_name_80060503 = "Invocación: Siphorb",
  str_skill_desc_80060501 = "¡Invoca a un Slasher al campo de batalla!",
  str_skill_desc_80060502 = "¡Invoca a un Probador al campo de batalla!",
  str_skill_desc_80060503 = "¡Invoca un Siphorb al campo de batalla!",
  str_skill_desc_800637101 = "Desata disparos precisos, sigilosos y hábiles que infligen daño en forma de cruz hasta el alcance máximo.",
  str_skill_desc_800638101 = "Inflige daño a su objetivo dos veces después de usar su increíble agilidad para alejarse del enemigo.",
  str_skill_desc_80062201 = "Recuperación de Punto de Fuerza del Equipo por ronda +1.",
