  str_skill_name_20022732 = "Eagleeye Lock-On",
  str_skill_name_2202271 = "Eagleeye Lock-On",
  str_skill_name_2202272 = "Eagleeye Lock-On",
  str_skill_name_2202273 = "Eagleeye Lock-On",
  str_skill_name_3002271 = "Reconocimiento de muerte",
  str_skill_name_3032271 = "Death Recon",
  str_skill_name_3002272 = "Reconocimiento de Muerte: Exhausto",
  str_skill_name_3032272 = "Death Recon: Exhausted",
  str_skill_name_3062272 = "Death Recon: Exhausted",
  str_skill_name_3062271 = "Death Recon",
  str_skill_desc_2002271 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2002272 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2002273 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_20022712 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos. Esto se puede lanzar mientras estás agotado, pero infligirá 1 acumulación de Garra de Águila en lugar de causar daño.",
  str_skill_desc_20022722 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos. Esto se puede lanzar mientras estás agotado, pero infligirá 2 acumulaciones de Garra de Águila en lugar de causar daño.",
  str_skill_desc_20022732 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos. Esto se puede lanzar mientras estás agotado, pero infligirá 3 acumulaciones de Garra de Águila en lugar de causar daño.",
  str_skill_desc_2202271 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos. Esto se puede lanzar mientras estás agotado, pero infligirá 1 acumulación de Garra de Águila en lugar de causar daño.",
  str_skill_desc_2202272 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos. Esto se puede lanzar mientras estás agotado, pero infligirá 2 acumulaciones de Garra de Águila en lugar de causar daño.",
  str_skill_desc_2202273 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 2 enemigos más cercanos. Esto se puede lanzar mientras estás agotado, pero infligirá 3 acumulaciones de Garra de Águila en lugar de causar daño.",
  str_skill_desc_3002271 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas a amarillas, y genera una Casilla Oscura en <color=#00F6FF>1</color> de estas casillas al azar.\nLa Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Después de lanzarla, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos en Cadena. Agotada se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3032271 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas a amarillas, y genera una Casilla Oscura en <color=#00F6FF>1</color> de estas casillas al azar.\nLa Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Aumenta el conteo de conversión de casillas en <color=#00F6FF>2</color> y genera <color=#00F6FF>1</color> Casilla Oscura adicional. Después de lanzar, el tiempo de enfriamiento de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos en Cadena. Agotada se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3062271 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas a amarillas, y genera Casillas Oscuras en <color=#00F6FF>2</color> de estas casillas al azar.\nLa Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Aumenta el conteo de conversión de casillas por <color=#00F6FF>2</color> y genera <color=#00F6FF>1</color> Casilla Oscura adicional. Después de lanzar, el tiempo de enfriamiento de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos de Cadena. Agotada se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3002272 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas en amarillas, y genera una Casilla Oscura en <color=#00F6FF>1</color> de estas casillas al azar.\nDespués de lanzar, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos en Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3032272 = "Convierte las <color=#00F6FF>5</color> casillas no amarillas más cercanas a amarillas, y genera Casillas Oscuras en <color=#00F6FF>2</color> de estas casillas al azar.\nDespués de lanzar, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos de Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3062272 = "Convierte las <color=#00F6FF>5</color> casillas no amarillas más cercanas a amarillas, y genera Casillas Oscuras en <color=#00F6FF>3</color> de estas casillas al azar.\nDespués de lanzar, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos de Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_passive_name_410227 = "Formación Holográfica",
  str_skill_passive_name_420227 = "Holographic Formation",
  str_skill_passive_name_430227 = "Holographic Formation",
  str_skill_passive_desc_410227 = "Inflige <color=#00F6FF>3</color> pilas de Garra de Águila al objetivo más cercano al pasar por una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link>. Al inicio de la ronda del enemigo, inflige daño igual a <color=#00F6FF>{1}</color> del ATK actual de Rachel una vez por cada pila de Garra de Águila. El número de pilas se reduce a la mitad cuando termina la ronda. Si el objetivo es asesinado, la mitad de las pilas de Garra de Águila se transferirán al enemigo más cercano.",
  str_skill_passive_desc_420227 = "Inflicts <color=#00F6FF>3</color> Eagle Talon stacks on the nearest target when passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. At the start of the enemy's round, deals damage equal to <color=#00F6FF>{1}</color> of Rachel's current ATK once for each Eagle Talon stack. The number of stacks is halved when the round ends. If the target is killed, half the Eagle Talon stacks will transfer to the nearest enemy.",
  str_skill_passive_desc_430227 = "Inflige <color=#00F6FF>3</color> acumulaciones de Garra de Águila al objetivo más cercano al pasar por una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link>. Al inicio de la ronda del enemigo, inflige daño igual a <color=#00F6FF>{1}</color> del ATK actual de Rachel una vez por cada acumulación de Garra de Águila. El número de acumulaciones se reduce a la mitad cuando termina la ronda. Si el objetivo es asesinado, la mitad de las acumulaciones de Garra de Águila se transferirán al enemigo más cercano. Si Rachel está <color=#00F6FF>Agotada</color>, su ATK aumenta en <color=#00F6FF>3%</color> por cada casilla recorrida en una conexión.",
  str_skill_passive_desc_440227 = "Inflige <color=#00F6FF>3</color> acumulaciones de Garra de Águila al objetivo más cercano al pasar por una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link>. Al inicio de la ronda del enemigo, inflige daño igual al <color=#00F6FF>80%</color> del ATK actual de Rachel una vez por cada acumulación de Garra de Águila. El número de acumulaciones se reduce a la mitad cuando termina la ronda. Si el objetivo es asesinado, la mitad de las acumulaciones de Garra de Águila se transferirán al enemigo más cercano. Si Rachel está <color=#00F6FF>Agotada</color>, su ATK aumenta en un <color=#00F6FF>3%</color> por cada casilla recorrida en una conexión.",
  str_skill_passive_desc_460227 = "Inflige <color=#00F6FF>3</color> montones de Garra de Águila al objetivo más cercano al pasar por una <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link>. Al inicio de la ronda del enemigo, inflige daño igual al <color=#00F6FF>80%</color> del ATK actual de Rachel una vez por cada montón de Garra de Águila. El número de montones se reduce a la mitad cuando termina la ronda. Si el objetivo es asesinado, la mitad de los montones de Garra de Águila se transferirán al enemigo más cercano. Si Rachel está <color=#00F6FF>Agotada</color>, su ATK aumenta en un <color=#00F6FF>4%</color> por cada casilla recorrida en una conexión.",
  str_skill_desc_3502271 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas en amarillas, y genera una Casilla Oscura en <color=#00F6FF>1</color> de estas casillas al azar, luego inflige <color=#00F6FF>2</color> acumulaciones de Garra de Águila en el objetivo más cercano.\nLa Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Después de lanzarla, el tiempo de enfriamiento de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos en Cadena. Agotada se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3532271 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas en amarillas, y genera una Casilla Oscura en <color=#00F6FF>1</color> de estas casillas al azar, luego inflige <color=#00F6FF>2</color> acumulaciones de Garra de Águila en el objetivo más cercano.\nLa Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Aumenta el conteo de conversión de casillas por <color=#00F6FF>2</color> y genera <color=#00F6FF>1</color> Casilla Oscura adicional. Después de lanzar, el tiempo de enfriamiento de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos en Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista nuevamente.",
  str_skill_desc_3562271 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas en amarillas, y genera Casillas Oscuras en <color=#00F6FF>2</color> de estas casillas al azar, luego inflige <color=#00F6FF>2</color> acumulaciones de Garra de Águila en el objetivo más cercano.\nLa Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Aumenta el conteo de conversión de casillas en <color=#00F6FF>2</color> y genera <color=#00F6FF>1</color> Casilla Oscura adicional. Después de lanzar, el tiempo de enfriamiento de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos en Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3502272 = "Convierte las <color=#00F6FF>3</color> casillas no amarillas más cercanas a amarillas, y genera una Casilla Oscura en <color=#00F6FF>1</color> de estas casillas al azar, luego inflige <color=#00F6FF>2</color> acumulaciones de Garra de Águila en el objetivo más cercano.\nDespués de lanzar, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos de Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3532272 = "Convierte las <color=#00F6FF>5</color> casillas no amarillas más cercanas a amarillas, y genera Casillas Oscuras en <color=#00F6FF>2</color> de estas casillas al azar, luego inflige <color=#00F6FF>2</color> acumulaciones de Garra de Águila en el objetivo más cercano.\nDespués de lanzar, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos de Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista de nuevo.",
  str_skill_desc_3562272 = "Convierte las <color=#00F6FF>5</color> casillas no amarillas más cercanas a amarillas, y genera Casillas Oscuras en <color=#00F6FF>3</color> de estas casillas al azar, luego inflige <color=#00F6FF>2</color> acumulaciones de Garra de Águila en el objetivo más cercano.\nDespués de lanzar, el tiempo de reutilización de la Habilidad Activa aumenta en 1 ronda, y Rachel se vuelve <color=#00F6FF>Agotada</color>, lo que la hace incapaz de lanzar Ataques Normales o Combos de Cadena. El agotamiento se elimina cuando la Habilidad Activa está lista nuevamente.",
  str_skill_upgrade_desc_16022713 = "Mejora Habilidad Activa: La Habilidad Activa puede ser lanzada de nuevo antes de que esté lista. Aumenta el recuento de conversión de casilla en <color=#FFFF00>2</color> y genera <color=#FFFF00>1</color> Casilla Oscura adicional.",
  str_skill_upgrade_desc_16022716 = "Mejora Habilidad Activa: Aumenta el recuento de generación de Casillas Oscuras en <color=#FFFF00>1</color>.",
  str_skill_upgrade_refine_desc_16022711 = "Mejora de habilidades de equipo: Al inicio de la ronda del enemigo, inflige daño igual al <color=#00F6FF>80%</color> del ATK actual de Rachel una vez por cada acumulación de Eagle Talon.",
  str_skill_upgrade_refine_desc_16022712 = "Mejora de habilidad activa: después de lanzar, inflige <color=#00F6FF>2</color> pilas de Garra de Águila al objetivo más cercano.",
  str_skill_upgrade_refine_desc_16022713 = "Mejora de habilidades de equipo: Si Rachel está agotado, su ATK aumenta en <color=#00F6FF>4%</color> por cada mosaico atravesado en una conexión.",
  str_skill_upgrade_desc_15022812 = "Mejora de habilidad activa: cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate.\nEl secreto Razzle Dazzle <color=#FFFF00>Ataque preventivo</color> es válido para Ascensión I.",
  str_skill_upgrade_desc_15022815 = "Mejora de Habilidad Activa de Variety Blitz: Aumenta el número de casillas que puedes seleccionar en <color=#FFFF00>1</color>.",
  str_skill_desc_10071120 = "Lanza un rayo impactante hacia la ubicación del objetivo en la última ronda, lo que inflige daño a los objetivos en el camino del rayo y en la ubicación del objetivo.",
  str_skill_desc_10071130 = "Derriba a los objetivos en el rango al centro del campo de batalla.",
  str_skill_name_54550920 = "Tentaclaw - Prevención de daños",
  str_skill_desc_54550920 = "Cuando un Auroriano desata un combo en cadena, Tentaclaw retrae sus tentáculos para evitar ataques y absorbe la Ficha Mejorada en su ubicación.",
  str_skill_name_29097013 = "Ataque Normal",
  str_skill_desc_29097013 = "Inflige daño a los Aurorianos frente a él después de moverse.",
  str_skill_name_29097014 = "Fiebre de lava",
  str_skill_desc_29097014 = "Inflige daño a una gran área en forma de abanico en la dirección de los Aurorianos y genera Piedritas.",
  str_skill_name_29097015 = "Rugido abrasador",
  str_skill_desc_29097015 = "Inflige daño a pantalla completa 3 veces, empujando a los objetivos 1 casilla con cada golpe. El objetivo recibe aún más daño si no puede ser empujado hacia atrás.",
  str_skill_name_2002281 = "Dulce Emboscada",
  str_skill_name_2002282 = "Dulce Emboscada",
  str_skill_name_2002283 = "Dulce Emboscada",
  str_skill_desc_2002281 = "Zeta libera a Conan, quien busca al enemigo más cercano dentro de 12 fichas en forma de diamante. Explota al llegar al objetivo, repartiendo <color=#00F6FF>150%</color> de daño a 5 fichas en forma de cruz.",
  str_skill_desc_2002282 = "Zeta libera a Conan, quien busca al enemigo más cercano dentro de 24 fichas en forma de diamante. Explota al llegar al objetivo, repartiendo <color=#00F6FF>160%</color> de daño a 5 fichas en forma de cruz.",
  str_skill_desc_2002283 = "Zeta libera a Conan, quien busca al enemigo más cercano dentro de 24 fichas en forma de diamante. Explota al llegar al objetivo, causando <color=#00F6FF>160%</color> de daño a 5 fichas en forma de cruz.\nCuando Zeta lanza su Combo de Cadena de nivel 3, el rango de daño de Conan, invocado por su Habilidad Activa Secreta Razzle Dazzle, se expande a 1 grupo circundante.",
  str_skill_name_3002281 = "Bombardeo variado",
  str_skill_name_3052281 = "Bombardeo variado",
  str_skill_name_3102281 = "Bombardeo variado",
  str_skill_name_3152281 = "Bombardeo variado",
  str_skill_desc_3002281 = "Selecciona cualquier 3 mosaicos, luego reinicia sus colores y los purifica. Los mosaicos azules se mantendrán al reiniciar los mosaicos.",
  str_skill_desc_3052281 = "Selecciona cualquier 4 mosaicos, luego restablece sus colores y los purifica. Los mosaicos azules se conservarán al restablecer los mosaicos.",
  str_skill_desc_3102281 = "Selecciona cualquier 3 casillas, registra sus colores en el <link=\"30100\"><#FFAE07><u>Tablero de Colores</u></color></link>, luego reinicia sus colores y los purifica. Las casillas azules se mantendrán al reiniciar las casillas.",
  str_skill_desc_3152281 = "Selecciona cualquier 4 casillas, registra sus colores en el <link=\"30100\"><#FFAE07><u>Tablero de Colores</u></color></link>, luego reinicia sus colores y los purifica. Las casillas azules se mantendrán al reiniciar las casillas.",
  str_skill_name_3002282 = "Secreto Razzle Dazzle",
  str_skill_desc_3002282 = "Utiliza todos los colores en el llenado <link=\"30100\"><#FFAE07><u>Tablero de Color</u></color></link> para invocar a Conan en 1 mosaico transitable. Cuando Zeta lanza su Combo de Cadena por primera vez en esta ronda, Conan también buscará enemigos y los atacará.",
  str_skill_passive_name_410228 = "Rainbow Dinamita",
  str_skill_passive_name_420228 = "Rainbow Dinamita",
  str_skill_passive_name_430228 = "Rainbow Dinamita",
  str_skill_passive_desc_410228 = "Zeta obtiene la Habilidad Activa Secreta Razzle Dazzle y el <link=\"30100\"><#FFAE07><u>Tablero de Colores</u></color></link>. Conan, que es invocado por Secret Razzle Dazzle, <color=#00F6FF>buscará enemigos a su alrededor y los atacará</color> cuando Zeta lance su Combo en Cadena. Su radio de búsqueda es el <color=#00F6FF>mismo</color> que el rango del Combo en Cadena lanzado por Zeta, y él inflige un daño igual a <color=#00F6FF>{1}</color> del daño infligido por el Combo en Cadena de Zeta.",
  str_skill_passive_desc_420228 = "Zeta obtiene la Habilidad Activa Secret Razzle Dazzle y el <link=\"30100\"><#FFAE07><u>Tablero de Colores</u></color></link>. Conan, que es convocado por Secret Razzle Dazzle, <color=#00F6FF>buscará enemigos a su alrededor y los atacará</color> cuando Zeta lance su Combo de Cadena. Su radio de búsqueda es el <color=#00F6FF>mismo</color> que el rango del Combo de Cadena lanzado por Zeta, y él inflige daño igual a <color=#00F6FF>{1}</color> del daño infligido por el Combo de Cadena de Zeta. Cuando Zeta lanza su Combo de Cadena de nivel 3, el rango de daño de Conan se expande <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_desc_430228 = "Zeta obtiene la habilidad activa Secret Razzle Dazzle y el <link=\"30100\"><#FFAE07><u>Tablero de Colores</u></color></link>. Conan, que es convocado por Secret Razzle Dazzle, <color=#00F6FF>buscará enemigos a su alrededor y los atacará</color> cuando Zeta lance su Combo en Cadena. Su radio de búsqueda es el <color=#00F6FF>mismo</color> que el rango del Combo en Cadena de Zeta, y él inflige daño igual a <color=#00F6FF>{1}</color> del daño infligido por el Combo en Cadena de Zeta. Cuando Zeta lanza su Combo en Cadena de nivel 3, el rango de daño de Conan se expande <color=#00F6FF>1 grupo circundante</color>. Cada vez que el Tablero de Color se llena, restaura PS igual al <color=#00F6FF>12%</color> del PS máximo de Zeta para el equipo.",
  str_skill_name_2002291 = "¡Salida encontrada!",
  str_skill_name_2002292 = "Exit Found!",
  str_skill_name_2002293 = "Exit Found!",
  str_skill_name_3002291 = "¡Todo Despejado!",
  str_skill_name_3202291 = "All Clear!",
  str_skill_name_3302291 = "All Clear!",
  str_skill_name_3232291 = "All Clear!",
  str_skill_name_3262291 = "All Clear!",
  str_skill_name_3332291 = "All Clear!",
  str_skill_name_3362291 = "All Clear!",
  str_skill_passive_name_4002291 = "¡No te quedes sin batería!",
  str_skill_desc_2002291 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos.",
  str_skill_desc_2002292 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 3 enemigos más cercanos.",
  str_skill_desc_2002293 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 4 enemigos más cercanos.",
  str_skill_desc_2202291 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 2 enemigos más cercanos e inflige 1 pila de Quemado.",
  str_skill_desc_2202292 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 3 enemigos más cercanos e inflige 1 pila de Quemado.",
  str_skill_desc_2202293 = "Inflige un <color=#00F6FF>{1}% </color> de daño a los 4 enemigos más cercanos e inflige 1 pila de Quemado.",
  str_skill_desc_3002291 = "Batia comienza la batalla con <link=\"30110\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en la Siguiente Cola se convertirá en casillas rojas.",
  str_skill_desc_3202291 = "Batia comienza la batalla con <link=\"30111\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en Siguiente Cola se convertirá en casillas rojas. Cada casilla roja atravesada le otorga <color=#00F6FF>1</color> Energía. Consume <color=#00F6FF>5</color> Energía para aleatorizar el bloque. Cada intento de aleatorización costará <color=#00F6FF>5</color> Energía adicional hasta el próximo uso de su Habilidad Activa.",
  str_skill_desc_3232291 = "Batia comienza la batalla con <link=\"30112\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en Siguiente Cola se convertirá en casillas rojas. Siguiente Cola comienza con <color=#00F6FF>10</color> de Energía, y cada casilla roja atravesada le otorga <color=#00F6FF>1</color> de Energía. Consume <color=#00F6FF>5</color> de Energía para aleatorizar el bloque. Cada intento de aleatorización costará <color=#00F6FF>5</color> de Energía adicional hasta el próximo uso de su Habilidad Activa.",
  str_skill_desc_3262291 = "Batia comienza la batalla con <link=\"30113\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en Siguiente Cola se convertirá en casillas rojas. Siguiente Cola comienza con <color=#00F6FF>10</color> de Energía, y cada casilla roja atravesada le otorga <color=#00F6FF>1</color> de Energía. Consume <color=#00F6FF>5</color> de Energía para aleatorizar el bloque.",
  str_skill_desc_3302291 = "Batia comienza la batalla con <link=\"30114\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en Siguiente Cola se convertirá en casillas rojas. Cada casilla roja atravesada le otorga <color=#00F6FF>1</color> Energía. Consume <color=#00F6FF>5</color> Energía para aleatorizar el bloque. Cada intento de aleatorización costará <color=#00F6FF>5</color> de Energía adicional hasta el próximo uso de su Habilidad Activa. Bloquee el bloque en la Siguiente Cola para evitar que se aleatorice. Mientras está bloqueado, cada aleatorización mejora el bloque actual. Por cada mejora, la Habilidad Activa también generará un Mosaico Oscuro en una ubicación aleatoria.",
  str_skill_desc_3332291 = "Batia comienza la batalla con <link=\"30115\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en Siguiente Cola se convertirá en casillas rojas. Siguiente Cola comienza con <color=#00F6FF>10</color> de Energía, y cada casilla roja atravesada le otorga <color=#00F6FF>1</color> de Energía. Consume <color=#00F6FF>5</color> Energía para aleatorizar el bloque. Cada intento de aleatorización costará <color=#00F6FF>5</color> de Energía adicional hasta el próximo uso de su Habilidad Activa. Bloquee el bloque en la Siguiente Cola para evitar que se aleatorice. Mientras está bloqueado, cada aleatorización mejora el bloque actual. Por cada mejora, la Habilidad Activa también generará una Casilla Oscura en una ubicación aleatoria.",
  str_skill_desc_3362291 = "Batia comienza la batalla con <link=\"30116\"><#FFAE07><u>Siguiente Cola</u></color></link>. Selecciona 1 casilla, y el área que coincide con el bloque mostrado en Siguiente Cola se convertirá en casillas rojas. Siguiente Cola comienza con <color=#00F6FF>10</color> de Energía, y cada casilla roja atravesada le otorga <color=#00F6FF>1</color> de Energía. Consume <color=#00F6FF>5</color> Energía para aleatorizar el bloque. Bloquee el bloque en la siguiente cola para evitar que se aleatorice. Mientras está bloqueado, cada aleatorización mejora el bloque actual. Para cada mejora, la Habilidad Activa también generará una Ficha Oscura en una ubicación aleatoria.",
  str_skill_passive_desc_4002291 = "El equipo inflige <color=#00F6FF>Enflame</color> a los objetivos en lugar de Quemar. Cada pila inflige <color=#00F6FF>{1}</color> del ATK promedio del equipo a los objetivos. Cuanto mayor es la HP de un objetivo, mayor es el daño, hasta un bono del 100%. Se acumula hasta 5 veces y dura 2 rondas. Inflige <color=#00F6FF>1</color> pila de Enflame al objetivo más cercano por cada <link=\"30093\"><#FFAE07><u>Casilla Oscura</u></color></link> atravesada.",
  str_skill_upgrade_desc_16022913 = "Mejora de habilidad activa: cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate. La siguiente cola comienza con 10 de energía (válido para Ascensión II).",
  str_skill_upgrade_desc_16022916 = "Mejora de Habilidad Activa: El costo de energía ya no aumenta al aleatorizar la Siguiente Cola (válido para Ascensión II).",
  str_skill_name_28002414 = "Opresión",
  str_skill_desc_28002414 = "Forsakin lanza un hechizo poderoso y derriba a los Aurorianos.",
  str_skill_name_28002415 = "Convocar",
  str_skill_desc_28002415 = "Forsakin convoca Eclipsites en ubicaciones aleatorias en el campo.",
  str_skill_name_1003003 = "Cierre",
  str_skill_desc_1003003 = "Shadowgeist convierte 1 mosaico aleatorio dentro de 1 grupo circundante en un Mosaico Bloqueado cada ronda.",
  str_skill_name_29102421 = "Quemar",
  str_skill_desc_29102421 = "Inflige daño a los Aurorianos dentro de las 4 columnas adelante y convoca llamas en ubicaciones aleatorias.",
  str_skill_name_29102422 = "Reino de Fuego",
  str_skill_desc_29102422 = "Desata llamas abrasadoras, infligiendo daño a todo el campo. Inflige daño adicional aumentado 1 vez a los objetivos dentro de las 3 filas en cada lado del campo.",
  str_skill_name_15017611 = "Tempestad australiana",
  str_skill_desc_15017611 = "Inflige daño varias veces a los Aurorianos dentro de 3 grupos circundantes basado en sus acumulaciones de Lanzas australianas. Cada instancia de daño inflige 1 Lanza Australis adicional en el objetivo. Si el objetivo no puede ser atacado, se inflige 3 acumulaciones de Lanzas australianas en sí misma.",
  str_skill_name_15017612 = "Resplandor boreal",
  str_skill_desc_15017612 = "Elimina las Lanzas australianas de los objetivos dentro de 2 grupos circundantes. Cada Lanza Australiana inflige un 20% de daño. Si el objetivo no puede ser atacado, se inflige 3 acumulaciones de Lanza Australiana sobre sí misma.",
  str_skill_name_15020011 = "Viene la oscuridad",
  str_skill_desc_15020011 = "Inflige daño a las unidades enemigas dentro de 3 cúmulos circundantes.",
  str_skill_name_15020012 = "Oda a las profundidades",
  str_skill_desc_15020012 = "Reúne a los Aurorianos y al Soldado Illumina hacia el centro en relación con ambas posiciones.",
  str_skill_name_547100101 = "Reinhardt Ataque Normal",
  str_skill_desc_547100101 = "Reinhardt se acerca a los enemigos y lanza ataques.",
  str_skill_name_547100102 = "Explosión de iluminación",
  str_skill_desc_547100102 = "Reinhardt inflige un gran daño a los enemigos.",
  str_skill_name_290980101 = "Malicia penetrante",
  str_skill_name_290980102 = "Juicio despreciado por el alma",
  str_skill_name_290980103 = "Grito de Blitztide",
  str_skill_name_290980104 = "Aliento de dragón convergente",
  str_skill_desc_290980101 = "Si hay enemigos dentro de un área en forma de X, les inflige daño y convoca unidades periféricas. De lo contrario, convoca unidades periféricas a su alrededor.",
  str_skill_desc_290980102 = "Si hay enemigos dentro de un área en forma de cruz, les inflige daño y convoca unidades periféricas. De lo contrario, convoca unidades periféricas alrededor de sí mismo.",
  str_skill_desc_290980103 = "Invoca unidades periféricas alrededor de sí mismo.",
  str_skill_desc_290980104 = "Inflige daño a todos los enemigos en el campo, empujándolos hacia atrás e invocando unidades periféricas a su alrededor.",
  str_skill_name_200510101 = "Mirada provocativa",
  str_skill_desc_200510101 = "Los Provocantes de la Periferia se acercan a los enemigos y lanzan ataques.",
  str_skill_name_290520111 = "Abandonado: Bombardeo feroz",
  str_skill_desc_290520111 = "Figerald se mueve hacia los aurorianos y causa mucho daño, luego se retira.",
  str_skill_name_290520112 = "Abandonado: El Asalto de Figerald",
  str_skill_desc_290520112 = "Figerald se mueve, luego inflige daño a todos los Aurorianos en el rango.",
  str_skill_name_290940113 = "Abandonado: Lanza de Shadowfire",
  str_skill_desc_290940113 = "Ira inflige daño equivalente al 40% del HP actual de los Aurorianos, aumenta el HP máximo del equipo en función del daño infligido y genera Sombras de fuego en las fichas más externas del tablero dentro de un alcance máximo en el área en forma de cruz centrada alrededor del Auroriano.",
  str_skill_name_290940114 = "Forsaken: Bombardeo ardiente",
  str_skill_desc_290940114 = "Ira inflige daño a los Aurorianos dentro de 2 grupos circundantes de sí mismo.",
  str_skill_name_290940115 = "Abandonado: Meteorito iracundo",
  str_skill_desc_290940115 = "Ira invoca meteoritos para golpear la posición donde estaban los Aurorianos en la ronda anterior, causando daño letal y destruyendo la casilla, dejando atrás 4 casillas rotas en forma de cruz.",
  str_skill_upgrade_refine_desc_17010711 = "Mejora de Habilidad Activa: Aumenta el daño del Combo en Cadena en <color=#00F6FF>25%</color> cuando está aumentado.",
  str_skill_upgrade_refine_desc_17010712 = "Mejora de la habilidad del equipamiento: Al comienzo de cada ronda, gana 1 Vis por cada enemigo dentro de <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_upgrade_refine_desc_17010713 = "Mejora de la habilidad del equipamiento: Gana 5 Vis al <color=#00F6FF>final de la ronda</color> (gana 1 Vis extra por cada <color=#00F6FF>15%</color> de PS perdido).",
  str_skill_desc_346107 = "Utiliza <color=#00F6FF>10</color> Vis para ingresar a un estado aumentado en esta ronda: Los ataques normales se pueden lanzar en diagonal. Aumenta el daño del Ataque Normal/Combo en Cadena en <color=#00F6FF>20%/25%</color> respectivamente (se puede acumular). Gana 2 Vis por cada enemigo eliminado mientras está aumentado.",
  str_skill_passive_desc_456107 = "Gana 10 Vis al comienzo de la batalla. Al inicio de cada ronda, gana <color=#00F6FF>1</color> Vis por cada enemigo dentro de <color=#00F6FF>1 grupo circundante</color>. Gana <color=#00F6FF>5</color> Vis al finalizar la ronda en un estado no aumentado y 1 Vis extra por cada 20% de PS perdido.",
  str_skill_passive_desc_466107 = "Obtiene 10 Vis al comienzo de la batalla. Al inicio de cada ronda, gana <color=#00F6FF>1</color> Vis por cada enemigo dentro de <color=#00F6FF>1 grupo circundante</color>. Gana <color=#00F6FF>5</color> Vis al final de la ronda y 1 Vis extra por cada 15% de PS perdido.",
  str_skill_upgrade_refine_desc_17010811 = "<color=#00F6FF> Variante I de Habilidad Activa </color>: Usa <color=#00F6FF>15</color> Vis para infligir <color=#00F6FF>480%</color> de daño a una casilla seleccionada. Cada lanzamiento aumenta el ATK básico en <color=#00F6FF>3%</color>. Se puede lanzar varias veces en cada ronda.",
  str_skill_upgrade_refine_desc_17010812 = "Mejora Habilidad Activa: Cada lanzamiento aumenta el daño final de la Habilidad Activa en un <color=#00F6FF>3%</color>.",
  str_skill_upgrade_refine_desc_17010813 = "Mejora Habilidad Activa: Inflige <color=#00F6FF>300%</color> de daño a objetivos con menos del <color=#00F6FF>10%</color> PS.",
  str_skill_name_366108 = "Tormenta de meteoritos",
  str_skill_name_33610801 = "Variante I de la tormenta de meteoritos",
  str_skill_name_36610801 = "Variante I de la tormenta de meteoritos",
  str_skill_desc_33610801 = "Utiliza <color=#00F6FF>15</color> Vis para infligir <color=#00F6FF>480%</color> de daño a una casilla seleccionada. Cada lanzamiento aumenta el ATK básico en <color=#00F6FF>3%</color>. Se puede lanzar varias veces en cada ronda.",
  str_skill_desc_356108 = "Utiliza <color=#00F6FF>10</color> Vis para infligir un <color=#00F6FF>240%</color> de daño a 1 casilla seleccionada e inflige un 50% <link=\"30015\"><#FFAE07><u>daño de Salpicadura</u></color></link> a <color=#00F6FF>4 casillas en forma de cruz</color> a su alrededor. Cada lanzamiento aumenta el ATK básico y el daño final de la habilidad activa en <color=#00F6FF>3%</color>. Se puede lanzar varias veces por ronda.",
  str_skill_desc_35610801 = "Utiliza <color=#00F6FF>15</color> Vis para infligir <color=#00F6FF>480%</color> de daño a una casilla seleccionada. Cada lanzamiento aumenta el ATK básico y el daño final de la Habilidad Activa en <color=#00F6FF>3%</color>. Se puede lanzar varias veces en cada ronda.",
  str_skill_desc_366108 = "Utiliza <color=#00F6FF>10</color> Vis para infligir un <color=#00F6FF>240%</color> de daño a 1 casilla seleccionada e inflige un 50% <link=\"30015\"><#FFAE07><u>daño de Salpicadura</u></color></link> a <color=#00F6FF>4 casillas en forma de cruz</color> a su alrededor. Cada lanzamiento aumenta el ATK básico y el daño final de la Habilidad Activa en <color=#00F6FF>3%</color>. Se puede lanzar varias veces por ronda. Inflige <color=#00F6FF>300%</color> de daño a objetivos con menos del <color=#00F6FF>10%</color> de HP.",
  str_skill_desc_36610801 = "Utiliza <color=#00F6FF>15</color> Vis para infligir <color=#00F6FF>480%</color> de daño a una casilla seleccionada. Cada lanzamiento aumenta el ATK básico y el daño final de la Habilidad Activa en <color=#00F6FF>3%</color>. Se puede lanzar varias veces en cada ronda. Inflige <color=#00F6FF>300%</color> de daño a los objetivos con menos del <color=#00F6FF>10%</color> de HP.",
  str_skill_upgrade_refine_desc_17010911 = "Mejora de Habilidad Activa: <color=#00F6FF>Selecciona 1 casilla en el campo</color> y los ataques pueden alcanzar <color=#00F6FF>objetivos detrás del equipo</color>.",
  str_skill_upgrade_refine_desc_17010912 = "Mejora de la habilidad del equipamiento: Obtiene <color=#00F6FF>1</color> Vis por los <color=#00F6FF>primeros 2</color> Ataques Normales lanzados en cada ronda y aumenta el daño infligido por estos ataques en un <color=#00F6FF>100%</color>.",
  str_skill_upgrade_refine_desc_17010913 = "Nueva Habilidad Activa: Usa <color=#00F6FF>10</color> Vis para aumentar los objetivos del Combo en Cadena en esta ronda en <color=#00F6FF>1</color> (se puede acumular).",
  str_skill_name_340109 = "Caza a la luz de la luna",
  str_skill_desc_340109 = "Cuesta <color=#00F6FF>10</color> Vis y elimina el Vis restante para seleccionar 1 casilla e infligir <color=#00F6FF><color=#00F6FF>150%</color></color> de daño a todos los enemigos en el camino entre el Auroriano y la casilla seleccionada, extendiéndose en ambas direcciones, así como a los enemigos en las casillas adyacentes. El daño final aumenta en <color=#00F6FF>8%</color> por cada 1 Vis eliminado.",
  str_skill_passive_desc_453109 = "Gana <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Obtiene <color=#00F6FF>1</color> Vis por los <color=#00F6FF>primeros 2</color> Ataques Normales en cada ronda y aumenta su daño en un <color=#00F6FF>100%</color>.",
  str_skill_name_360109 = "Persiguiendo Sombras Entre Árboles",
  str_skill_desc_360109 = "Utiliza <color=#00F6FF>10</color> Vis para aumentar el número de objetivos para el Combo en Cadena en esta ronda en <color=#00F6FF>1</color> (se puede acumular).",
  str_skill_upgrade_refine_desc_17011011 = "Mejora de habilidades de equipo: Los ataques normales tienen un <color=#00F6FF>35%</color> de probabilidad de golpear al enemigo más lejano con un rayo.",
  str_skill_upgrade_refine_desc_17011012 = "Mejora de la habilidad del equipamiento: Gana 1 Vis por cada golpe de rayo cuando posee menos de 5 Vis.",
  str_skill_upgrade_refine_desc_17011013 = "Mejora de Habilidad Activa: Obtiene 1 pila de Marca Requiem por cada golpe de rayo liberado, y todas las marcas se borrarán cuando se libere la habilidad activa. Aumenta el factor de daño para la habilidad activa en un 10% por cada pila de Marcas Requiem eliminadas.",
  str_skill_passive_desc_443110 = "Obtienes <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Ganas <color=#00F6FF>2</color> Vis extra al matar a un objetivo con una Habilidad Activa. Los ataques normales tienen un <color=#00F6FF>35%</color> de probabilidad de golpear al enemigo más lejano con un rayo.",
  str_skill_passive_desc_453110 = "Obtiene <color=#00F6FF>5</color> Vis al comienzo de cada ronda. Gana <color=#00F6FF>2</color> Vis extra al matar a un objetivo con una Habilidad Activa. Los Ataques Normales tienen un <color=#00F6FF>35%</color> de probabilidad de golpear al enemigo más lejano con un rayo. Gana 1 Vis por cada golpe de rayo cuando posee menos de 5 Vis.",
  str_skill_desc_366110 = "Cuesta <color=#00F6FF>10</color> Vis. Elimina el Vis restante y <link=\"30117\"><#FFAE07><u>Marcas de Requiem</u></color></link> para infligir <color=#00F6FF>150%</color> de daño a todos los enemigos. Por cada 1 Vis eliminado, el daño aumenta en un <color=#00F6FF>15%</color> e ignora <color=#00F6FF>1%</color> de DEF. Aumenta el factor de daño de la Habilidad Activa en <color=#00F6FF>10%</color> por cada acumulación de Marca de Requiem eliminada.",
  str_skill_upgrade_desc_16023013 = "Mejora de habilidades de equipo: Siempre que la cordura caiga por debajo o por encima de 50, el mosaico no rojo más cercano al equipo se convierte en un <color=#00F6FF>Mosaico Oscuro Rojo</color>.",
  str_skill_upgrade_desc_16023014 = "Mejora de habilidad activa y habilidades de equipo: Al infligir daño, incluye una pérdida adicional de <color=#00F6FF>4,000</color> HP del equipo.",
  str_skill_upgrade_desc_16023015 = "Mejora de habilidades de equipo: Victoria: El daño de Elegy a los enemigos con el Pacto del Señor aumenta a medida que disminuye el HP del equipo, alcanzando un máximo de <color=#00F6FF>15%</color> cuando el HP del equipo está al 50%.",
  str_skill_name_2002301 = "Prisión Escarlata",
  str_skill_name_2002302 = "Prisión Escarlata",
  str_skill_name_2002303 = "Prisión Escarlata",
