  str_skill_name_30423011 = "Gala de la Luna Sangrienta",
  str_skill_name_3002302 = "Ondulaciones bailando",
  str_skill_passive_name_4102301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4302301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4132301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4332301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4142301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4342301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4162301 = "Omnisciencia Benevolente",
  str_skill_passive_name_4362301 = "Omnisciencia Benevolente",
  str_skill_desc_2002301 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 3 enemigos más cercanos y el <color=#00F6FF>mismo daño</color> una vez a los enemigos con el Pacto del Señor.",
  str_skill_desc_2002302 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 3 enemigos más cercanos y el <color=#00F6FF>mismo daño</color> una vez a los enemigos con el Pacto del Señor.",
  str_skill_desc_2002303 = "Inflige un <color=#00F6FF>{1}%</color> de daño a los 3 enemigos más cercanos y el <color=#00F6FF>mismo daño</color> una vez a los enemigos con el Pacto del Señor.",
  str_skill_desc_3002301 = "Victoria: Elegy se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Ella consume 10 cordura para aplicar el <link=\"30118\"><#FFAE07><u>Pacto del Señor</u></color></link> a 1 objetivo y causar daño que ignora la DEF igual al <color=#00F6FF>200%</color> del HP perdido del equipo.",
  str_skill_desc_3042301 = "Victoria: Elegy se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Ella consume 10 cordura para aplicar el <link=\"30118\"><#FFAE07><u>Pacto del Señor</u></color></link> a 1 objetivo y causar daño que ignora DEF igual a <color=#00F6FF>200%</color> del HP perdido del equipo, con un extra de 4,000 puntos de HP perdido del equipo incluidos.",
  str_skill_desc_3002302 = "Intercambia los porcentajes actuales de HP y cordura del equipo. No se puede lanzar si la cordura es 0. Gana 1 lanzamiento al entrar en batalla.",
  str_skill_passive_desc_4102301 = "Al inicio de cada ronda o al pasar por una Casilla Oscura, inflige una vez daño que ignora la DEF igual a <color=#00F6FF>{1}</color> del PS perdido del equipo a los enemigos con el Pacto del Señor.",
  str_skill_passive_desc_4302301 = "Al inicio de cada ronda o al pasar por una Casilla Oscura, inflige una vez daño que ignora la DEF igual a <color=#00F6FF>{1}</color> del PS perdido del equipo a los enemigos con el Pacto del Señor. Victoria: Elegy restaura <color=#00F6FF>3%</color> de la cordura perdida cada vez que daña a tal enemigo (al menos 1 punto).",
  str_skill_passive_desc_4132301 = "Al comienzo de cada ronda o al pasar por una Baldosa Oscura, inflige una vez daño ignorando la DEF igual a <color=#00F6FF>{1}</color> del HP perdido del equipo a los enemigos con el Pacto del Señor. Siempre que la cordura cambie de 50 o más a menos de 50, o de menos de 50 a 50 o más, la baldosa no roja más cercana al equipo se convierte en una <color=#00F6FF>Baldosa Oscura Roja</color>.",
  str_skill_passive_desc_4332301 = "Al inicio de cada ronda o al pasar por una Casilla Oscura, inflige una vez daño que ignora DEF igual a <color=#00F6FF>{1}</color> del HP perdido del equipo a los enemigos con el Pacto del Señor. Victoria: Elegy restaura <color=#00F6FF>3%</color> de la Cordura perdida cada vez que daña a tal enemigo (al menos 1 punto). Cada vez que la Cordura cambia de 50 o más a menos de 50, o de menos de 50 a 50 o más, la casilla no Roja más cercana al equipo se convierte en una <color=#00F6FF>Casilla Oscura Roja</color>.",
  str_skill_passive_desc_4142301 = "Al comienzo de cada ronda o al pasar por una Baldosa Oscura, inflige daño una vez que ignora la DEF igual a <color=#00F6FF>{1}</color> del HP perdido del equipo a los enemigos con el Pacto del Señor, con un extra de <color=#00F6FF>4,000</color> puntos de HP perdido del equipo incluido. Siempre que la cordura cambia de 50 o más a menos de 50, o de menos de 50 a 50 o más, la baldosa no roja más cercana al equipo se convierte en una <color=#00F6FF>Baldosa Oscura Roja</color>.",
  str_skill_passive_desc_4342301 = "Al inicio de cada ronda o al pasar por una Casilla Oscura, inflige una vez daño que ignora DEF igual a <color=#00F6FF>{1}</color> del HP perdido del equipo a los enemigos con el Pacto del Señor. Victoria: Elegy restaura <color=#00F6FF>3%</color> de la Cordura perdida cada vez que daña a tal enemigo (al menos 1 punto). Cada vez que la Cordura cambia de 50 o más a menos de 50, o de menos de 50 a 50 o más, la casilla no Roja más cercana al equipo se convierte en una <color=#00F6FF>Casilla Oscura Roja</color>.",
  str_skill_passive_desc_4162301 = "Al inicio de cada ronda o al pasar por una Casilla Oscura, inflige una vez daño que ignora la DEF igual a <color=#00F6FF>{1}</color> del PS perdido del equipo a los enemigos con el Pacto del Señor, con un extra de <color=#00F6FF>4,000</color> puntos de PS perdido del equipo incluidos. Siempre que la cordura cambie de 50 o más a menos de 50, o de menos de 50 a 50 o más, la casilla no roja más cercana al equipo se convierte en una <color=#00F6FF>Casilla Oscura Roja</color>. Victoria: El daño de Elegy a los enemigos con el Pacto del Señor aumenta a medida que disminuye el HP del equipo, alcanzando un máximo de <color=#00F6FF>15%</color> cuando el HP del equipo está al 50%.",
  str_skill_passive_desc_4362301 = "Al inicio de cada ronda o al pasar por una Casilla Oscura, inflige una vez daño que ignora la DEF igual a <color=#00F6FF>{1}</color> del PS perdido del equipo a los enemigos con el Pacto del Señor. Victoria: Elegy restaura <color=#00F6FF>3%</color> de la cordura perdida cada vez que daña a tal enemigo (al menos 1 punto). Siempre que la cordura cambie de 50 o más a menos de 50, o de menos de 50 a 50 o más, la casilla no roja más cercana al equipo se convierte en una <color=#00F6FF>Casilla Oscura Roja</color>. Victoria: El daño de Elegy a los enemigos con el Pacto del Señor aumenta a medida que disminuye el HP del equipo, alcanzando un máximo de <color=#00F6FF>15%</color> cuando el HP del equipo está al 50%.",
  str_skill_upgrade_refine_desc_16023011 = "Mejora de Habilidad de Equipo: Aumenta el factor de daño a <color=#00F6FF>35%</color>.",
  str_skill_upgrade_refine_desc_16023012 = "Mejora del Combo en Cadena: Inflige un daño adicional del <color=#00F6FF>110%</color> contra enemigos con el Pacto del Señor.",
  str_skill_upgrade_refine_desc_16023013 = "Mejora de habilidad activa: Gana <color=#00F6FF>1</color> lanzamiento más.",
