  str_skill_desc_2502302 = "Inflige <color=#00F6FF>150%</color> de daño a los 3 enemigos más cercanos e inflige <color=#00F6FF>110%</color> del daño anterior una vez al enemigo con el Pacto del Señor.",
  str_skill_desc_2502303 = "Inflige <color=#00F6FF>165%</color> de daño a los 3 enemigos más cercanos e inflige <color=#00F6FF>110%</color> del daño anterior una vez al enemigo con el Pacto del Señor.",
