  str_skill_desc_2002311 = "Inflige <color=#00F6FF>130%</color> de daño 3 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002312 = "Inflige <color=#00F6FF>140%</color> de daño 4 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>2 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_2002313 = "Inflige <color=#00F6FF>150%</color> de daño 5 veces, asignado al azar a los enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color> de esta unidad. Cuando un objetivo recibe daño más de una vez, el daño a partir de la segunda vez se reduce a la mitad.",
  str_skill_desc_3002311 = "Wilhelm se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Elija cualquier mosaico y luego seleccione otro mosaico dentro de <color=#00F6FF>2 grupos circundantes</color> para generar un área rectangular. Convierte los mosaicos seleccionados en Mosaicos Oscuros Azules. Cada mosaico en el área utiliza <color=#00F6FF>2</color> cordura.",
  str_skill_desc_3032311 = "Wilhelm se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Elija cualquier mosaico y luego seleccione otro mosaico dentro de <color=#00F6FF>3 grupos circundantes</color> para generar un área rectangular. Convierte los mosaicos seleccionados en Mosaicos Oscuros Azules. Cada mosaico en el área usa <color=#00F6FF>2</color> cordura.",
  str_skill_desc_3202311 = "Wilhelm se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Elija cualquier mosaico y luego seleccione otro mosaico dentro de <color=#00F6FF>2 grupos circundantes</color> para generar un área rectangular. Convierte los mosaicos seleccionados en Mosaicos Oscuros Azules. Cada mosaico en el área usa <color=#00F6FF>2</color> cordura, y <color=#00F6FF>1</color> pila de Deslumbramiento de Sangre se inflige a todos los enemigos en el área. Se inflige una pila adicional si la cordura cae por debajo de <color=#00F6FF>50</color> después de lanzar.",
  str_skill_desc_3232311 = "Wilhelm se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Elija cualquier mosaico y luego seleccione otro mosaico dentro de <color=#00F6FF>3 grupos circundantes</color> para generar un área rectangular. Convierte los mosaicos seleccionados en Mosaicos Oscuros Azules. Cada mosaico en el área usa <color=#00F6FF>2</color> cordura, y <color=#00F6FF>1</color> pila de Deslumbramiento de Sangre se inflige a todos los enemigos en el área. Se inflige una pila adicional si la cordura cae por debajo de <color=#00F6FF>50</color> después de lanzar.",
  str_skill_desc_3302312 = "Restaura 20 de Cordura, pero reduce la Cordura Máxima en 20 después de lanzar. Se puede lanzar en sucesión hasta que la Cordura Máxima caiga a 0.",
  str_skill_passive_name_4002311 = "Entierro Nocturno",
  str_skill_passive_name_4062311 = "Entierro Nocturno",
  str_skill_passive_desc_4002311 = "Reemplaza el debuff de Miedo infligido por el equipo en el objetivo con <color=#00F6FF>Aturdimiento de Sangre</color>. Cada pila reduce la DEF del objetivo en <color=#00F6FF>{1}</color>, hasta 3 pilas, durando 2 rondas. Cada vez que se elimina una pila (incluyendo cuando el objetivo muere) o excede el límite, restaura 1 Cordura. El Combo en Cadena de Wilhelm aplica 1 pila de <color=#00F6FF>Aturdimiento de Sangre</color> cada vez que inflige daño.",
  str_skill_passive_desc_4062311 = "Reemplaza el debuff de Miedo infligido por el equipo en el objetivo con <color=#00F6FF>Aturdimiento de Sangre</color>. Cada pila reduce la DEF del objetivo en <color=#00F6FF>{1}</color>, hasta 3 pilas, durando 2 rondas. Cada vez que se elimina una pila (incluyendo cuando el objetivo muere) o excede el límite, restaura 2 de Cordura. El Combo en Cadena de Wilhelm aplica 1 pila de <color=#00F6FF>Aturdimiento de Sangre</color> cada vez que inflige daño.",
  str_skill_upgrade_desc_16023113 = "Mejora de habilidad activa: cambia la habilidad activa a <color=#FFFF00>Ataque preventivo</color>. Disponible al entrar en combate. Amplía el rango de selección del segundo mosaico a 3 grupos circundantes.",
  str_skill_upgrade_desc_16023116 = "Mejora de habilidad de equipo: Restaura 2 puntos de Cordura por cada acumulación de Aturdimiento de Sangre que desaparece o excede el límite.",
  str_skill_name_2002321 = "Bautismo sangriento",
