  str_skill_passive_name_4002321 = "Perdón Inebriante",
  str_skill_passive_name_4052321 = "Perdón Inebriante",
  str_skill_desc_2002321 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 12 casillas en forma de diamante </color> e inflige 1 pila de <link=\"10000\"><#FFAE07> <u> sangrado </u></color></link> durante 2 rondas.",
  str_skill_desc_2002322 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>16 casillas en forma radial</color> e inflige 1 pila de <link=\"10000\"><#FFAE07><u>Sangrado</u></color></link> por 2 rondas.",
  str_skill_desc_2002323 = "Inflige un <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF> 2 cúmulos circundantes </color> e inflige 1 pila de <link=\"10000\"><#FFAE07> <u> sangrado </u></color></link> durante 2 rondas.",
  str_skill_desc_3002321 = "Consume <color=#00F6FF>10%</color> del HP máximo del equipo para convertir <color=#00F6FF>1</color> ficha seleccionada en fichas oscuras. No se puede lanzar si el HP es insuficiente.",
  str_skill_desc_3202322 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Consume <color=#00F6FF>25%</color> del HP máximo del equipo para convertir <color=#00F6FF>2</color> fichas seleccionadas en fichas oscuras. No se puede lanzar si el HP es insuficiente.",
  str_skill_desc_3022321 = "Consume <color=#00F6FF>10%</color> del HP máximo del equipo para convertir <color=#00F6FF>1</color> ficha seleccionada en fichas oscuras. No se puede lanzar si el HP es insuficiente.",
  str_skill_desc_3222322 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Consume <color=#00F6FF>25%</color> del HP máximo del equipo para convertir <color=#00F6FF>2</color> fichas seleccionadas en fichas oscuras. No se puede lanzar si el HP es insuficiente.",
  str_skill_desc_3302321 = "Consume <color=#00F6FF>10%</color> del HP máximo del equipo para convertir <color=#00F6FF>1</color> ficha seleccionada en fichas oscuras. No se puede lanzar si HP es insuficiente. Si el HP del equipo está por debajo del <color=#00F6FF>30%</color> después de lanzar, convierte la primera ficha seleccionada en una ficha oscura roja.",
  str_skill_desc_3302322 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Consume <color=#00F6FF>25%</color> del HP máximo del equipo para convertir <color=#00F6FF>2</color> fichas seleccionadas en fichas oscuras. No se puede lanzar si el HP es insuficiente. Si el HP del equipo está por debajo del <color=#00F6FF>30%</color> después de lanzar, convierte la primera ficha seleccionada en una ficha oscura roja.",
  str_skill_desc_3322321 = "Consume <color=#00F6FF>10%</color> del HP máximo del equipo para convertir <color=#00F6FF>1</color> ficha seleccionada en fichas oscuras. No se puede lanzar si HP es insuficiente. Si el HP del equipo está por debajo del <color=#00F6FF>30%</color> después de lanzar, convierte la primera ficha seleccionada en una ficha oscura roja.",
  str_skill_desc_3322322 = "<color=#FFFF00>Enfriamiento de habilidad +1 después de lanzar</color>. Consume <color=#00F6FF>25%</color> del HP máximo del equipo para convertir <color=#00F6FF>2</color> fichas seleccionadas en fichas oscuras. No se puede lanzar si el HP es insuficiente. Si el HP del equipo está por debajo del <color=#00F6FF>30%</color> después de lanzar, convierte la primera ficha seleccionada en una ficha oscura roja.",
  str_skill_passive_desc_4002321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual a <color=#00F6FF>{1}</color> del ATQ de Nails: Rito Sagrado.",
  str_skill_passive_desc_4052321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual a <color=#00F6FF>{1}</color> del ATQ de Nails: Rito Sagrado. Considera la Bendición Carmesí como una casilla oscura al moverse a través de ella.",
  str_skill_passive_desc_4402321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual al <color=#00F6FF>110%</color> del ATQ de Nails: Rito Sagrado.",
  str_skill_passive_desc_4452321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual al <color=#00F6FF>110%</color> del ATQ de Nails: Rito Sagrado. Considera la Bendición Carmesí como una casilla oscura al moverse a través de ella.",
  str_skill_passive_desc_4502321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual al <color=#00F6FF>110%</color> del ATQ de Nails: Rito Sagrado y el <color=#00F6FF>5%</color> del PS perdido.",
  str_skill_passive_desc_4552321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual al <color=#00F6FF>110%</color> del ATQ de Nails: Rito Sagrado y el <color=#00F6FF>5%</color> del PS perdido. Considera la Bendición Carmesí como una casilla oscura al moverse a través de ella.",
  str_skill_passive_desc_4602321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color> y <color=#00F6FF>30%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual al <color=#00F6FF>110%</color> del ATQ de Nails: Rito Sagrado y el <color=#00F6FF>5%</color> del PS perdido.",
  str_skill_passive_desc_4652321 = "Cuando el porcentaje de PS actual cae por debajo del <color=#00F6FF>50%</color> y <color=#00F6FF>30%</color>, genera una Bendición Carmesí en la casilla roja transitable más cercana. Al pasar por ella, restaura PS igual al <color=#00F6FF>110%</color> del ATQ de Nails: Rito Sagrado y el <color=#00F6FF>5%</color> del PS perdido. Considera la Bendición Carmesí como una casilla oscura al moverse a través de ella.",
  str_skill_upgrade_desc_15023212 = "Mejora Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00> 1 </color> ronda.",
  str_skill_upgrade_desc_15023215 = "Mejora de habilidades de equipo: Considera la Bendición Carmesí como una Casilla Oscura al pasar por ella.",
  str_skill_upgrade_refine_desc_15023211 = "Mejora de habilidades de equipo: Restaura HP igual a <color=#00F6FF>110%</color> del ATK de Nails: Rito Sagrado al pasar por la Bendición Carmesí.",
  str_skill_upgrade_refine_desc_15023212 = "Mejora de habilidades de equipo: Además, restaura HP igual al <color=#00F6FF>5%</color> del HP perdido.",
  str_skill_upgrade_refine_desc_15023213 = "Mejora de habilidades de equipo: Cuando el porcentaje de HP actual cae por debajo del <color=#00F6FF>30%</color>, crea otra Bendición Carmesí en el mosaico rojo más cercano.",
