  str_skill_desc_240461 = "Inflige un <color=#00F6FF>120%</color> de daño a <color=#00F6FF>3</color> enemigos dentro de <color=#00F6FF>4 cúmulos circundantes</color> e inflige 1 pila de Risa, hasta 8 pilas. Cada pila aumenta el daño de Combo en cadena en un <color=#00F6FF>7%</color>.",
  str_skill_desc_240462 = "ofertas <color=#00F6FF>140%</color> daño a <color=#00F6FF>3</color> enemigos dentro <color=#00F6FF>4 grupos circundantes</color> e inflige 2 acumulaciones de Laughter, hasta 8 acumulaciones. Cada acumulación aumenta el daño de Chain Combo en <color=#00F6FF>7%</color>.",
  str_skill_desc_240463 = "Ofertas <color=#00F6FF>155%</color> daño a <color=#00F6FF>3</color> enemigos dentro <color=#00F6FF>4 grupos circundantes</color> e inflige 3 acumulaciones de Risa, hasta 8 acumulaciones. Cada acumulación aumenta el daño de Chain Combo en <color=#00F6FF>7%</color>.",
  str_skill_upgrade_refine_desc_13004612 = "Mejora del Combo en Cadena: Cada acumulación de Risa aumenta el daño del Combo en Cadena en un <color=#00F6FF>7%</color>.",
  str_skill_desc_300046 = "Coloca a Clucky en un mosaico seleccionado, luego atrae a <color=#00F6FF>todos</color> los enemigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> en enemigos con 5 acumulaciones de Risa durante 2 rondas.",
  str_skill_desc_302046 = "Coloca a Clucky en una casilla seleccionada, luego atrae a <color=#00F6FF>todos</color> los enemigos. Inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> en enemigos con 4 acumulaciones de Risa durante 2 rondas y <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link> en enemigos con 6 acumulaciones de Risa durante 1 ronda.",
  str_skill_desc_305046 = "Coloca a Clucky en un mosaico seleccionado, luego atrae a <color=#00F6FF>todos</color> los enemigos. Inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> en enemigos con 4 acumulaciones de Risa durante 2 rondas y <link=\"10004\"><#FFAE07><u>Parálisis</u></color></link> en enemigos con 6 acumulaciones de Risa durante <color=#00F6FF>1</color> ronda.",
