  str_skill_desc_2002372 = "Inflige <color=#00F6FF>170%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centradas en el enemigo más cercano dentro de <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2002373 = "Inflige <color=#00F6FF>180%</color> de daño a <color=#00F6FF>13 mosaicos en forma de diamante</color> centrado en el enemigo más cercano dentro de <color=#00F6FF>2 grupos circundantes</color>.",
  str_skill_desc_2302371 = "ofertas <color=#00F6FF>160%</color> daño a <color=#00F6FF>12 fichas en forma de diamante</color>.",
  str_skill_desc_2302372 = "Inflige <color=#00F6FF>170%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centradas en el enemigo más cercano dentro de <color=#00F6FF>12 casillas en forma de diamante</color>. Invoca una Burbuja Radiante en la ubicación del objetivo.",
  str_skill_desc_2302373 = "Inflige <color=#00F6FF>180%</color> de daño a <color=#00F6FF>13 casillas en forma de diamante</color> centradas en el enemigo más cercano dentro de <color=#00F6FF>2 grupos circundantes</color>. Invoca una Burbuja Radiante en la ubicación del objetivo.",
  str_skill_desc_3002371 = "Seleccione una casilla transitable de <color=#00F6FF>12 casillas en forma de diamante</color> como punto de partida, luego conecte cualquier número de <color=#00F6FF>casillas azules</color> ignorando todos los obstáculos. Se teletransporta instantáneamente al final de la conexión. Si hay un enemigo en la última casilla, inflige <color=#00F6FF>200%</color> de daño al objetivo antes de moverse a una casilla adyacente.",
  str_skill_desc_3032371 = "Seleccione una casilla transitable de <color=#00F6FF>12 fichas en forma de diamante</color> como punto de partida, luego conecte cualquier número de <color=#00F6FF>fichas azules</color> ignorando todos los obstáculos. Se teletransporta instantáneamente al final de la conexión. Si hay un enemigo en la última ficha, inflige <color=#00F6FF>300%</color> de daño al objetivo antes de moverse a una ficha adyacente.",
  str_skill_desc_3202371 = "Seleccione una casilla transitable de <color=#00F6FF>12 casillas en forma de diamante</color> como punto de partida, luego conecte cualquier número de <color=#00F6FF>casillas Azules, casillas Oscuras o casillas de Burbujas Radiantes</color> ignorando todos los obstáculos. Se teletransporta al final de la conexión. Si hay un enemigo en la última casilla, inflige <color=#00F6FF>200%</color> de daño al objetivo antes de moverse a una casilla adyacente.",
  str_skill_desc_3232371 = "Seleccione una casilla transitable de <color=#00F6FF>12 casillas en forma de diamante</color> como punto de partida, luego conecte cualquier número de <color=#00F6FF>casillas Azules, casillas Oscuras o casillas de Burbujas Radiantes</color> ignorando todos los obstáculos. Se teletransporta al final de la conexión. Si hay un enemigo en la última casilla, inflige <color=#00F6FF>300%</color> de daño al objetivo antes de moverse a una casilla adyacente.",
  str_skill_passive_name_4102371 = "Irreal",
  str_skill_passive_desc_4102371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>2</color> casillas transitables aleatorias que duran 3 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>{1}</color> de daño a 3 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_passive_name_4402371 = "Irreal",
  str_skill_passive_desc_4402371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>2</color> casillas transitables aleatorias que duran 3 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>140%</color> de daño a 3 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_passive_name_4502371 = "Irreal",
  str_skill_passive_desc_4502371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>2</color> casillas transitables aleatorias que duran 3 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>140%</color> de daño a 4 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_passive_name_4602371 = "Irreal",
  str_skill_passive_desc_4602371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>2</color> casillas transitables aleatorias que duran 3 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>140%</color> de daño a 4 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>. Obtén 1 Fuente de Ilusión al pasar por Casillas Oscuras o Burbujas Radiantes. Cada punto de Fuente de Ilusión aumenta el daño de Combo en Cadena en <color=#00F6FF>1%</color>.",
  str_skill_passive_name_4162371 = "Irreal",
  str_skill_passive_desc_4162371 = "Al comienzo de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>3</color> casillas transitables aleatorias que duran 5 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>{1}</color> de daño a 3 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_passive_name_4462371 = "Irreal",
  str_skill_passive_desc_4462371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>3</color> casillas transitables aleatorias que duran 5 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>140%</color> de daño a 3 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_passive_name_4562371 = "Irreal",
  str_skill_passive_desc_4562371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>3</color> casillas transitables aleatorias que duran 5 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>140%</color> de daño a 4 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>.",
  str_skill_passive_name_4662371 = "Irreal",
  str_skill_passive_desc_4662371 = "Al inicio de cada ronda, genera Burbujas Radiantes en <color=#00F6FF>3</color> casillas transitables aleatorias que duran 3 rondas. Al pasar por una Burbuja Radiante a través de casillas conectadas o Habilidades Activas, inflige <color=#00F6FF>140%</color> de daño a 4 enemigos dentro de <color=#00F6FF>3 cúmulos circundantes</color>. Obtén 1 Fuente de Ilusión al pasar por Casillas Oscuras o Burbujas Radiantes. Cada punto de Fuente de Ilusión aumenta el daño de Combo en Cadena en <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_16023711 = "Mejora de habilidades de equipo: aumenta el daño de Burbuja Radiante a <color=#00F6FF>140%</color>.",
  str_skill_upgrade_refine_desc_16023712 = "Mejora de habilidad de equipo: Las Burbujas Radiantes infligen daño a <color=#00F6FF>4</color> enemigos dentro del alcance.",
  str_skill_upgrade_refine_desc_16023713 = "Mejora de habilidades de equipo: Gana 1 Fuente de Ilusión al pasar por Mosaicos Oscuros o Burbujas Radiantes. Cada punto de Fuente de Ilusión aumenta el daño de Combo en cadena en <color=#00F6FF>1%</color>.",
  str_skill_upgrade_desc_16023713 = "Mejora de Habilidad Activa: Reduce el tiempo de enfriamiento de la habilidad en <color=#FFFF00>1</color> ronda. Si hay un enemigo en la última casilla, inflige <color=#FFFF00>300%</color> de daño.",
  str_skill_upgrade_desc_16023716 = "Mejora de habilidades de equipo: Las Burbujas Radiantes duran 5 rondas y generan 1 Burbuja Radiante adicional al inicio de cada ronda.",
  str_skill_name_291020103 = "Persecución varada",
  str_skill_name_291020104 = "Amor Desesperado",
  str_skill_name_291020105 = "Lamento de la Sirena",
  str_skill_desc_291020103 = "Inflige daño a los Aurorianos y convoca Cañones Salvo a su alrededor. Cuando el HP cae por debajo del 70%/40%, el número de Cañones Salvo convocados aumenta en 1 respectivamente.",
  str_skill_desc_291020104 = "Invoca una Solicitud en el mosaico más lejano de los Aurorianos dentro de 1 grupo circundante. Cuando el HP cae por debajo del 50%, el número de Solicitudes invocadas aumenta en 1.",
  str_skill_desc_291020105 = "Inflige daño creciente a los Aurorianos 3 veces y los empuja hacia el borde del campo.",
  str_skill_desc_291020113 = "Inflige daño a los Aurorianos e invoca Cañones Salvo a su alrededor.",
  str_skill_passive_desc_443173 = "Inflige inmediatamente <color=#00F6FF>85%</color> de daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>mosaicos mejorados</u></color></link> (incluyendo <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> acumulaciones de Marca Mortal y reduce <color=#00F6FF>1</color> acumulación por cada mosaico mejorado obtenido. Minos entra en el Estado Minotauro cuando se han eliminado todas las Marcas, aumentando su ATK básico en <color=#00F6FF>25%</color>, permitiendo que sus ataques normales golpeen las fichas diagonales, aumentando el daño de la Habilidad de Equipo a <color=#00F6FF>2.5</color> veces, y permitiendo que su Combo de Cadena cause daño normal al golpear el mismo objetivo de nuevo.",
  str_skill_passive_desc_453173 = "Inmediatamente inflige un <color=#00F6FF>85%</color> de daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>fichas mejoradas</u></color></link> (incluyendo <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> acumulaciones de la Marca Mortal y reduce <color=#00F6FF>1</color> acumulación por cada ficha mejorada obtenida. Minos entra en el Estado Minotauro cuando todas las Marcas han sido eliminadas, aumentando su ATK básico en un <color=#00F6FF>25%</color>, permitiendo que sus ataques normales golpeen las fichas diagonales, y aumentando el daño de la Habilidad de Equipo a <color=#00F6FF>2.5</color> veces. Reduce el requisito de activación del Combo en Cadena en <color=#00F6FF>1/2/3</color> y su daño ya no disminuye al golpear al mismo objetivo.",
  str_skill_passive_desc_463173 = "Inmediatamente inflige un <color=#00F6FF>85%</color> de daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>fichas mejoradas</u></color></link> (incluyendo <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> acumulaciones de la Marca Mortal y reduce <color=#00F6FF>1</color> acumulación por cada ficha mejorada obtenida. Minos entra en el Estado Minotauro cuando todas las Marcas han sido eliminadas, aumentando su ATK básico en un <color=#00F6FF>25%</color>, permitiendo que sus ataques normales golpeen las fichas diagonales, y aumentando el daño de la Habilidad de Equipo a <color=#00F6FF>2.5</color> veces. Reduce el requisito de activación del Combo en cadena en <color=#00F6FF>1/2/3</color> y su daño ya no disminuye al golpear al mismo objetivo. Aumenta el factor de daño de la Habilidad Activa a <color=#00F6FF>200%</color>.",
  str_skill_passive_desc_440173 = "Inmediatamente inflige un <color=#00F6FF>85%</color> de daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>fichas mejoradas</u></color></link> (incluyendo <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> acumulaciones de la Marca Mortal y reduce <color=#00F6FF>1</color> acumulación por cada ficha mejorada obtenida. Minos entra en el Estado Minotauro cuando se han eliminado todas las Marcas, aumentando su ATK básico en un <color=#00F6FF>20%</color>, permitiendo que sus ataques normales golpeen las fichas diagonales, aumentando el daño de la Habilidad de Equipo a <color=#00F6FF>2.5</color> veces, y el daño del Combo en Cadena ya no disminuye al golpear el mismo objetivo.",
  str_skill_passive_desc_450173 = "Inmediatamente inflige un <color=#00F6FF>85%</color> de daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>fichas mejoradas</u></color></link> (incluyendo <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> acumulaciones de la Marca Mortal y reduce <color=#00F6FF>1</color> acumulación por cada ficha mejorada obtenida. Minos entra en el Estado Minotauro cuando todas las Marcas han sido eliminadas, aumentando su ATK básico en un <color=#00F6FF>20%</color>, permitiendo que sus ataques normales golpeen las fichas diagonales, y aumentando el daño de la Habilidad de Equipo a <color=#00F6FF>2.5</color> veces. Reduce el requisito de activación del Combo en Cadena en <color=#00F6FF>1/2/3</color> y su daño ya no disminuye al golpear al mismo objetivo.",
  str_skill_passive_desc_460173 = "Inmediatamente inflige un <color=#00F6FF>85%</color> de daño a <color=#00F6FF>1</color> objetivo aleatorio en el campo cada vez que el equipo obtiene <link=\"20001\"><#FFAE07><u>fichas mejoradas</u></color></link> (incluyendo <link=\"30065\"><#FFAE07><u>absorción</u></color></link>). Comienza la batalla con <color=#00F6FF>33</color> acumulaciones de la Marca Mortal y reduce <color=#00F6FF>1</color> acumulación por cada ficha mejorada obtenida. Minos entra en el Estado Minotauro cuando todas las Marcas han sido eliminadas, aumentando su ATK básico en un <color=#00F6FF>20%</color>, permitiendo que sus ataques normales golpeen las fichas diagonales, y aumentando el daño de la Habilidad de Equipo a <color=#00F6FF>2.5</color> veces. Reduce el requisito de activación del Combo en cadena en <color=#00F6FF>1/2/3</color> y su daño ya no disminuye al golpear al mismo objetivo. Aumenta el factor de daño de la Habilidad Activa a <color=#00F6FF>200%</color>.",
  str_skill_upgrade_refine_desc_16017311 = "Mejora de habilidades de equipo: Aumenta el factor de daño al 85%.",
  str_skill_upgrade_refine_desc_16017312 = "Mejora de Habilidad de Equipo: Reduce el requisito de activación de Chain Combo en 1/2/3 en el estado Minotauro.",
  str_skill_upgrade_refine_desc_16017313 = "Mejora de Habilidad de Equipo: Aumenta el factor de daño de la Habilidad Activa al 200% en el Estado de Minotauro.",
  str_skill_upgrade_refine_desc_14016911 = "Mejora de Habilidad de Equipo: Aumenta el ATK básico de Sadie en <color=#00F6FF>33%</color>. Cada Punto de choque aumenta el factor de daño de la Habilidad Activa en <color=#00F6FF>22%</color>.",
  str_skill_upgrade_refine_desc_14016912 = "Mejora de habilidades de equipo: Gana 1 <color=#00F6FF>Punto de choque</color> al pasar por un mosaico oscuro.",
  str_skill_upgrade_refine_desc_14016913 = "Mejora de habilidad activa: amplía el rango de mosaicos seleccionables a <color=#00F6FF>1 grupo circundante</color>.",
  str_skill_passive_desc_440169 = "Aumenta el ATK básico de Sadie en <color=#00F6FF>33%</color>. Sadie reparte hasta <color=#00F6FF>3</color> ataques normales al conectar mosaicos, y el tercer ataque normal inflige el doble de daño. Después de 3 ataques, gana 1 <color=#00F6FF>Punto de choque</color> con el siguiente ataque normal. Cada Crash Point aumenta el factor de daño de la habilidad activa en <color=#00F6FF>22%</color>. Todos los Crash Points se borran después de usar la habilidad activa.",
  str_skill_passive_desc_450169 = "Aumenta el ATK básico de Sadie en <color=#00F6FF>33%</color>. Sadie reparte hasta <color=#00F6FF>3</color> ataques normales al conectar mosaicos, y el tercer ataque normal inflige el doble de daño. Después de 3 ataques, gana 1 <color=#00F6FF>Punto de choque</color> con el siguiente ataque normal. Cada Punto de choque aumenta el factor de daño de la habilidad activa en <color=#00F6FF>22%</color>. Todos los Puntos de choque se borran después de usar la habilidad activa. Gana 1 <color=#00F6FF>Punto de choque</color> adicional por cada mosaico oscuro atravesado.",
  str_skill_name_360169 = "Pelota voladora",
  str_skill_name_365169 = "Pelota voladora",
  str_skill_desc_360169 = "Ofrece <color=#00F6FF>300%</color> de daño a 1 enemigo dentro de un <color=#00F6FF>grupo circundante</color> y los derriba 2 fichas. Los enemigos bloqueados por <color=#00F6FF>obstáculos</color> mientras son derribados reciben un daño adicional del <color=#00F6FF>200%</color> y quedan <color=#00F6FF>aturdidos</color> durante 1 ronda. Si en cambio, es bloqueado por otro enemigo, ambos reciben daño y quedan aturdidos.",
  str_skill_desc_365169 = "Ofrece <color=#00F6FF>300%</color> de daño a 1 enemigo dentro de <color=#00F6FF>1 grupo circundante</color> y los derriba 3 fichas. Los enemigos bloqueados por <color=#00F6FF>obstáculos</color> mientras son derribados reciben un adicional <color=#00F6FF>200%</color> de daño y son <color=#00F6FF>aturdidos</color> por 1 ronda. Si es bloqueado por otro enemigo, ambos reciben daño y quedan aturdidos.",
  str_skill_name_20053011 = "Susurros de las profundidades del mar",
  str_skill_desc_20053011 = "Inflige daño a las unidades enemigas dentro de 1 grupo circundante.",
  str_skill_name_20054011 = "Tocar",
  str_skill_desc_20054011 = "Cuando hay un Aurorian dentro de 2 grupos de sí mismo, convoca a un Eclipsite cerca del objetivo para ayudarse a sí mismo.",
  str_skill_upgrade_desc_17023613 = "Mejora de Habilidad Activa: Gana 5 Vis al comienzo de cada ronda.",
  str_skill_upgrade_desc_17023616 = "Nueva Habilidad Activa: Puede ser lanzada para regresar al equipo mientras se está fuera del equipo, infligiendo un <color=#00F6FF>550%</color> de daño a las casillas en el camino.",
  str_skill_passive_name_4102361 = "Agitado",
  str_skill_name_2002361 = "El milagro de Czerny",
  str_skill_name_2002362 = "El milagro de Czerny",
  str_skill_name_2002363 = "El milagro de Czerny",
  str_skill_name_2002364 = "El milagro de Czerny",
  str_skill_name_3302361 = "Con Brio",
  str_skill_name_3302362 = "Estrellas que regresan",
  str_skill_desc_3302361 = "Obtiene <link=\"30125\"><#FFAE07><u>Vis</u></color></link> durante el combate. Al activar la habilidad, Claymore entra en un modo de combate único, permitiendo <link=\"30127\"><#FFAE07><u>conexiones de casillas</u></color></link> independientes. Después de la conexión, Claymore entra en el <link=\"30128\"><#FFAE07><u>estado fuera del equipo</u></color></link>, dejando una <link=\"30129\"><#FFAE07><u>imagen residual</u></color></link> en la última casilla conectada, que servirá como punto de partida para la próxima Habilidad Activa.",
  str_skill_desc_3332361 = "Obtiene <link=\"30126\"><#FFAE07><u>Vis</u></color></link> durante el combate. Al activar la habilidad, Claymore entra en un modo de combate único, permitiendo <link=\"30127\"><#FFAE07><u>conexiones de casillas</u></color></link> independientes. Después de la conexión, Claymore entra en el <link=\"30128\"><#FFAE07><u>estado fuera del equipo</u></color></link>, dejando una <link=\"30129\"><#FFAE07><u>imagen residual</u></color></link> en la última casilla conectada, que servirá como punto de partida para la próxima Habilidad Activa.",
  str_skill_desc_3302362 = "Puede ser lanzado para regresar al equipo mientras está en el estado fuera del equipo, infligiendo <color=#00F6FF>550%</color> de daño a las casillas en el camino.",
  str_skill_desc_2002361 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>4 fichas circundantes</color>.",
  str_skill_desc_2002362 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>. Obtiene 3 Vis si no está en el estado de equipo fuera de juego.",
  str_skill_desc_2002363 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>. Gana 4 Vis si no está en el estado de equipo de reserva.",
  str_skill_desc_2002364 = "Inflige un <color=#00F6FF>175%</color> de daño a <color=#00F6FF>2 cúmulos circundantes</color>. Obtiene 5 Vis si no está en el estado de equipo fuera.",
  str_skill_passive_desc_4102361 = "Claymore es un Auroriano <color=#00F6FF>no elemental</color> y tiene un Contrarresto Elemental del <color=#00F6FF>100%</color> al atacar o ser atacado. <color=#00F6FF>Claymore toma acción durante la batalla cuando es Capitán, pero solo participa como miembro del equipo cuando todas las casillas conectadas son casillas cromáticas.</color> Cada uso de una Habilidad Activa consume 1 Vis, otorgando a Claymore 1 pila de Poder Estelar. El Poder Estelar aumenta el daño en <color=#00F6FF>{1}</color>, hasta 99 pilas.",
  str_skill_passive_desc_4402361 = "Claymore es un Auroriano <color=#00F6FF>no elemental</color> y tiene un Contragolpe Elemental del <color=#00F6FF>100%</color> cuando ataca o es atacado. <color=#00F6FF>Claymore toma acción durante la batalla cuando es Capitán, pero solo participa como miembro del equipo cuando todas las casillas conectadas son casillas cromáticas.</color> Cada uso de una Habilidad Activa consume 1 Vis, otorgando a Claymore 1 pila de Poder Estelar. El Poder Estelar aumenta el daño en un <color=#00F6FF>1.1%</color>, hasta 99 pilas.",
  str_skill_passive_desc_4602361 = "Claymore es un Auroriano <color=#00F6FF>no elemental</color> y tiene un Contragolpe Elemental del <color=#00F6FF>100%</color> al atacar o ser atacado. <color=#00F6FF>Claymore toma acción durante la batalla cuando es Capitán, pero solo participa como miembro del equipo cuando todas las casillas conectadas son casillas cromáticas.</color> Cada uso de una Habilidad Activa consume 1 Vis, otorgando a Claymore 2 acumulaciones de Poder Estelar. El Poder Estelar aumenta el daño en un <color=#00F6FF>1.1%</color>, hasta 99 acumulaciones.",
  str_skill_upgrade_refine_desc_17023611 = "Mejora de habilidades de equipo: Aumenta el factor a <color=#00F6FF>1.1%</color>.",
  str_skill_upgrade_refine_desc_17023612 = "Nuevo Combo en Cadena de nivel <color=#00F6FF>4</color>: Requiere 12 fichas conectadas. Inflige un 175% de daño a 2 grupos circundantes. Gana 5 Vis si no está en el estado de equipo de reserva.",
  str_skill_upgrade_refine_desc_17023613 = "Mejora de habilidades de equipo: <color=#00F6FF>Dobla</color> las acumulaciones de Poder Estelar ganadas.",
  str_skill_upgrade_desc_16023813 = "Mejora Habilidad Activa: Cambia la Habilidad Activa a <color=#FFFF00> ataque preventivo </color>. Disponible al entrar en combate.",
  str_skill_upgrade_desc_16023816 = "Mejora de habilidad activa: aumenta el número de fichas que puedes seleccionar en <color=#00F6FF>1</color>.",
  str_skill_name_2002381 = "Borde Celestial",
  str_skill_desc_2002381 = "Lanza una cuchilla de pluma al <color=#00F6FF>enemigo más cercano</color>, infligiendo un 170% de daño, que luego rebota al siguiente <color=#00F6FF>enemigo más cercano</color>. Por cada grupo entre objetivos, el daño final aumenta en un 10%, hasta un 50%. El daño se incrementa aún más en función del conteo de Combo en Cadena.",
  str_skill_name_3002381 = "Mensaje Revelador",
  str_skill_name_3062381 = "Mensaje Revelador",
  str_skill_name_3302381 = "Mensaje Revelador Variante I",
  str_skill_name_3362381 = "Revelatory Message Variant I",
  str_skill_desc_3002381 = "Convierte cualquier <color=#00F6FF>5</color> casillas seleccionadas en casillas mejoradas.",
  str_skill_desc_3062381 = "Convierte cualquier <color=#00F6FF>6</color> casillas seleccionadas en casillas mejoradas.",
  str_skill_desc_3302381 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Convierte cualquier <color=#00F6FF>3</color> casillas seleccionadas en casillas mejoradas.",
  str_skill_desc_3362381 = "<color=#FFFF00>Enfriamiento de habilidad -1 después de lanzar</color>. Convierte cualquier <color=#00F6FF>4</color> casillas seleccionadas en casillas mejoradas.",
  str_skill_passive_name_4102381 = "Luz de estrella heredada",
  str_skill_passive_name_4162381 = "Luz de estrella heredada",
  str_skill_passive_desc_4102381 = "Obtén <color=#00F6FF>1 Marca de Luz Estelar</color> por <color=#00F6FF>cada casilla mejorada</color> obtenida. Los Combos en Cadena consumen <color=#00F6FF>un tercio</color> de las Marcas de Luz Estelar, añadiendo <color=#00F6FF>{1}%</color> del ATQ promedio del equipo como daño extra por pila.",
  str_skill_passive_desc_4162381 = "Obtén <color=#00F6FF>1 Marca de Luz Estelar</color> por <color=#00F6FF>cada casilla mejorada</color> obtenida. Los Combos en Cadena consumen <color=#00F6FF>un tercio</color> de las Marcas de Luz Estelar, añadiendo <color=#00F6FF>{1}</color> del ATQ medio del equipo como daño extra por pila. Cada casilla mejorada obtenida en una sola ronda reduce el requisito de activación del Combo en Cadena en 1.",
  str_skill_upgrade_refine_desc_15017611 = "Mejora de habilidad de equipo: Cada <color=#00F6FF>4</color> ataques normales, Beretta perfora su objetivo actual con 1 Lanza Australis.",
  str_skill_upgrade_refine_desc_15017612 = "Mejora de habilidad activa: Cada Lanza Australis inflige <color=#00F6FF>100%</color> daño al objetivo.",
  str_skill_upgrade_refine_desc_15017613 = "Mejora de habilidad activa: Cada Lanza Australis recupera <color=#00F6FF>15%–22.5%</color> del daño infligido como HP cuando daña al objetivo.",
  str_skill_passive_desc_4401761 = "Cada <color=#00F6FF>4</color> ataques normales, Beretta perfora su objetivo actual con <color=#00F6FF>1</color> <color=#00F6FF>Lanza Australis</color>.",
  str_skill_passive_desc_4451761 = "Every <color=#00F6FF>4</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_desc_3501761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. Ofertas <color=#00F6FF>100%</color> daño y recupera HP por <color=#00F6FF>10%–15%</color> del daño infligido de esta manera por cada Lanza Australis sacada. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3521761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Ofertas <color=#00F6FF>100%</color> daño y recupera HP por <color=#00F6FF>10%–15%</color> del daño infligido de esta manera por cada Lanza Australis sacada. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3551761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Ofertas <color=#00F6FF>100%–120%</color> daño y recupera HP por <color=#00F6FF>10%–15% de</color> el daño infligido de esta manera por cada <color=#00F6FF>Lanza Australis</color> sacada. Cuanto menor sea el HP actual del objetivo, mayor será el factor de daño. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3601761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>2 grupos circundantes</color>. Ofertas <color=#00F6FF>100%</color> daño y recupera HP por <color=#00F6FF>15%–22.5%</color> del daño infligido de esta manera por cada Lanza Australis sacada. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3621761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Ofertas <color=#00F6FF>100%</color> daño y recupera HP por <color=#00F6FF>15%–22.5%</color> del daño infligido de esta manera por cada Lanza Australis sacada. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_desc_3651761 = "Saca <color=#00F6FF>Lanzas australianas</color> de todos los enemigos dentro <color=#00F6FF>3 grupos circundantes</color>. Ofertas <color=#00F6FF>100%–120%</color> daño y recupera HP por <color=#00F6FF>15%–22.5% de</color> el daño infligido de esta manera por cada <color=#00F6FF>Lanza Australis</color> sacada. Cuanto menor sea el HP actual del objetivo, mayor será el factor de daño. Cuanto menor sea el HP del equipo, mayor será el factor de recuperación.",
  str_skill_name_3501821 = "Constricción de Serpiente Variante I",
  str_skill_name_3601821 = "Constricción de serpiente Variante II",
  str_skill_desc_3501821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Selects 1 tile and deals <color=#00F6FF>400%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_desc_3601821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Triggers the Equipment Skill: Moonglow Relict Arts, dealing <color=#00F6FF>300%</color> damage to <color=#00F6FF>all</color> enemies.",
  str_skill_upgrade_refine_desc_16018211 = "Mejora de habilidad activa: aumenta el factor de daño a 400%.",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>New Active Skill Variant I</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Selects 1 tile and deals 400% damage to 13 tiles in a diamond shape. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>New Active Skill Variant II</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Triggers the Equipment Skill: Moonglow Relict Arts, dealing 300% damage to all enemies.",
  str_skill_desc_3401821 = "La habilidad activa se puede desatar cuando <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Bengalas de serpiente</u></color></link> están encendidos. Selecciona 1 ficha y reparte <color=#00F6FF>400%</color> daño a <color=#00F6FF>13 fichas en forma de diamante</color>. Todas las bengalas de serpiente se extinguirán después de usar la habilidad activa.",
  str_skill_upgrade_desc_16024113 = "Mejora de habilidad activa: Reduce el tiempo de enfriamiento de la Habilidad Activa en <color=#00F6FF>1</color> ronda y aumenta el factor de daño en <color=#00F6FF>50%</color>.",
  str_skill_upgrade_desc_16024116 = "Nueva variante de habilidad activa: <color=#00F6FF>Duplica</color> el consumo de cordura y el daño infligido. Genera hasta <color=#00F6FF>3</color> Casillas Oscuras.",
  str_skill_name_2002411 = "Explosión desenfrenada",
  str_skill_name_2002412 = "Explosión desenfrenada",
  str_skill_name_2002413 = "Explosión desenfrenada",
  str_skill_name_2302411 = "Explosión desenfrenada",
  str_skill_name_2302412 = "Explosión desenfrenada",
  str_skill_name_2302413 = "Explosión desenfrenada",
  str_skill_name_3002411 = "Danza frenética",
  str_skill_name_3032411 = "Danza frenética",
  str_skill_name_3062411 = "Danza frenética Variante I",
  str_skill_desc_2002411 = "Inflige un <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 cúmulo circundante</color>.",
  str_skill_desc_2002412 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>.",
  str_skill_desc_2002413 = "Inflige <color=#00F6FF>{1}% </color> de daño a <color=#00F6FF>2 cúmulos circundantes</color>.",
  str_skill_desc_2302411 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>1 grupo circundante</color>. <link=\"30124\"><#FFAE07><u>Absorbe</u></color></link> las losetas oscuras dentro de las 4 losetas circundantes.",
  str_skill_desc_2302412 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>12 casillas en forma de diamante</color>. <link=\"30124\"><#FFAE07><u>Absorbe</u></color></link> las casillas oscuras dentro de 1 cúmulo circundante.",
  str_skill_desc_2302413 = "Inflige <color=#00F6FF>{1}%</color> de daño a <color=#00F6FF>2 grupos circundantes</color>. <link=\"30124\"><#FFAE07><u>Absorbe</u></color></link> las casillas oscuras dentro de las 12 casillas circundantes en forma de diamante.",
  str_skill_desc_3002411 = "Pepita se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Consume <color=#00F6FF>15</color> puntos de cordura para infligir 150% de DAÑO a un enemigo seleccionado, generando 1 casilla oscura debajo del objetivo.",
  str_skill_desc_3032411 = "Pepita se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Consume <color=#00F6FF>15</color> puntos de cordura para infligir 200% de DAÑO a un enemigo seleccionado, generando 1 casilla oscura debajo del objetivo.",
  str_skill_desc_3062411 = "Pepita se une a la batalla con el <link=\"30039\"><#FFAE07><u>Sistema de cordura</u></color></link>. Consume <color=#00F6FF>30</color> puntos de cordura para infligir un 400% de DAÑO a un enemigo seleccionado, generando hasta 3 casillas oscuras al azar debajo del objetivo.",
  str_skill_passive_name_4102411 = "Llamas En llamas",
  str_skill_passive_name_4202411 = "Llamas En llamas",
  str_skill_passive_desc_4102411 = "Cada vez que Pepita adquiere una casilla oscura, gana <color=#00F6FF>1</color> pila de Llama del Corazón, hasta <color=#00F6FF>7</color> pilas. El Capitán actual consume 1 pila de Llama del Corazón con cada ataque normal, aumentando su daño final en <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_4202411 = "Cada vez que Pepita adquiere un Mosaico Oscuro, gana <color=#00F6FF>1</color> Llama del Corazón, hasta <color=#00F6FF>7</color>. El Capitán actual consume 1 Llama del Corazón con cada ataque normal, aumentando su daño final en <color=#00F6FF>{1}</color>. Al comienzo de cada ronda, se generan aleatoriamente <color=#00F6FF>2</color> Mosaicos Oscuros debajo de los enemigos en el campo.",
